package com.anvil;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ClogTaskModelTest
{
	private static PluginConfigResponse.TrackedDrop drop(int id, String label, int cur, int req, Integer... items)
	{
		PluginConfigResponse.TrackedDrop d = new PluginConfigResponse.TrackedDrop();
		d.tileId = id;
		d.label = label;
		d.currentAmount = cur;
		d.requiredAmount = req;
		d.itemIds = new ArrayList<>();
		for (Integer it : items)
		{
			d.itemIds.add(it);
		}
		return d;
	}

	private static PluginConfigResponse.TrackedStat stat(int id, String label, int cur, int goal)
	{
		PluginConfigResponse.TrackedStat s = new PluginConfigResponse.TrackedStat();
		s.tileId = id;
		s.label = label;
		s.currentAmount = cur;
		s.goalAmount = goal;
		return s;
	}

	@Test
	public void multiTagCategoriesSplitAndFilter()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Zuk cape", ClogTaskModel.Type.DROP, 0, 1, -1, 5, null, "Inferno, PvM"));
		rows.add(new ClogTaskModel.TaskRow(2, "99 Slayer", ClogTaskModel.Type.STAT, 0, 1, -1, 5, null, "Skilling"));
		rows.add(new ClogTaskModel.TaskRow(3, "Nex drop", ClogTaskModel.Type.DROP, 0, 1, -1, 5, null, "pvm"));

		// Each tag contributes to the dropdown once, case-insensitively deduped.
		List<String> cats = ClogTaskModel.categories(rows);
		assertEquals(3, cats.size());
		assertTrue(cats.contains("Inferno"));
		assertTrue(cats.contains("Skilling"));
		// "PvM" (first seen) wins over the later "pvm".
		assertTrue(cats.contains("PvM"));

		// Filtering by one tag matches every tile carrying it, whatever its other tags.
		List<ClogTaskModel.TaskRow> pvm = ClogTaskModel.filter(
			rows, ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, "", "PvM");
		assertEquals(2, pvm.size());
		List<ClogTaskModel.TaskRow> inferno = ClogTaskModel.filter(
			rows, ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, "", "Inferno");
		assertEquals(1, inferno.size());
		assertEquals(1, inferno.get(0).tileId);
	}

	@Test
	public void statusDerivation()
	{
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 5));
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, ClogTaskModel.statusOf(2, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(5, 5));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(7, 5));
		// Untargeted tile (goal <= 0): any progress completes it.
		assertEquals(ClogTaskModel.Status.NOT_STARTED, ClogTaskModel.statusOf(0, 0));
		assertEquals(ClogTaskModel.Status.COMPLETED, ClogTaskModel.statusOf(1, 0));
	}

	@Test
	public void buildIsNullSafe()
	{
		assertTrue(ClogTaskModel.build(null).isEmpty());
		assertTrue(ClogTaskModel.build(new PluginConfigResponse()).isEmpty());
	}

	@Test
	public void buildMergesDropsAndStatsWithIcons()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.trackedDrops = new ArrayList<>();
		cfg.trackedDrops.add(drop(1, "Zulrah unique", 3, 5, 12921, 12922));
		cfg.trackedStats = new ArrayList<>();
		cfg.trackedStats.add(stat(2, "Mining XP", 100, 100));

		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.build(cfg);
		assertEquals(2, rows.size());

		ClogTaskModel.TaskRow dropRow = rows.get(0);
		assertEquals(ClogTaskModel.Type.DROP, dropRow.type);
		assertEquals(12921, dropRow.itemId); // first tracked item id
		assertEquals(ClogTaskModel.Status.IN_PROGRESS, dropRow.status);

		ClogTaskModel.TaskRow statRow = rows.get(1);
		assertEquals(ClogTaskModel.Type.STAT, statRow.type);
		assertEquals(-1, statRow.itemId); // no inventory icon for stat tiles
		assertTrue(statRow.isCompleted());
	}

	@Test
	public void filterByStatusAndType()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Done drop", ClogTaskModel.Type.DROP, 5, 5, 100));
		rows.add(new ClogTaskModel.TaskRow(2, "Partial drop", ClogTaskModel.Type.DROP, 1, 5, 101));
		rows.add(new ClogTaskModel.TaskRow(3, "Fresh stat", ClogTaskModel.Type.STAT, 0, 10, -1));

		List<ClogTaskModel.TaskRow> completed = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.COMPLETED, ClogTaskModel.TypeFilter.ALL, null);
		assertEquals(1, completed.size());
		assertEquals(1, completed.get(0).tileId);

		// A bare STAT row classifies as the SKILL kind (the legacy constructor's default for stats).
		List<ClogTaskModel.TaskRow> stats = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.SKILL, null);
		assertEquals(1, stats.size());
		assertEquals(3, stats.get(0).tileId);
	}

	@Test
	public void buildClassifiesEveryKind()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();

		cfg.trackedDrops = new ArrayList<>();
		// Simple drop pool → DROP.
		cfg.trackedDrops.add(drop(1, "Dragon warhammer", 0, 1, 13576));
		// Per-item requirement list → COLLECTION.
		PluginConfigResponse.TrackedDrop coll = drop(2, "Void set", 0, 1, 11665);
		coll.itemRequirements = new ArrayList<>();
		PluginConfigResponse.ItemRequirement req = new PluginConfigResponse.ItemRequirement();
		req.itemId = 11665;
		req.requiredAmount = 1;
		coll.itemRequirements.add(req);
		cfg.trackedDrops.add(coll);

		cfg.trackedStats = new ArrayList<>();
		PluginConfigResponse.TrackedStat skill = stat(3, "Agility XP", 0, 100);
		skill.statType = "skill";
		cfg.trackedStats.add(skill);
		PluginConfigResponse.TrackedStat boss = stat(4, "Zulrah KC", 0, 100);
		boss.statType = "boss";
		cfg.trackedStats.add(boss);

		cfg.trackedKills = new ArrayList<>();
		PluginConfigResponse.TrackedKill kill = new PluginConfigResponse.TrackedKill();
		kill.tileId = 5;
		kill.label = "Kill 10 chickens";
		kill.requiredAmount = 10;
		kill.currentAmount = 4;
		cfg.trackedKills.add(kill);

		cfg.trackedTimed = new ArrayList<>();
		PluginConfigResponse.TrackedTimed timed = new PluginConfigResponse.TrackedTimed();
		timed.tileId = 6;
		timed.label = "Sub-30 Inferno";
		timed.completed = true;
		cfg.trackedTimed.add(timed);

		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.build(cfg);
		assertEquals(6, rows.size());
		assertEquals(ClogTaskModel.Kind.DROP, kindOf(rows, 1));
		assertEquals(ClogTaskModel.Kind.COLLECTION, kindOf(rows, 2));
		assertEquals(ClogTaskModel.Kind.SKILL, kindOf(rows, 3));
		assertEquals(ClogTaskModel.Kind.BOSS, kindOf(rows, 4));
		assertEquals(ClogTaskModel.Kind.KILL, kindOf(rows, 5));
		assertEquals(ClogTaskModel.Kind.TIMED, kindOf(rows, 6));
		// The timed tile carries its completed flag through.
		assertTrue(rowOf(rows, 6).isCompleted());

		// Type filter narrows to a single kind.
		List<ClogTaskModel.TaskRow> kills = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.KILL, null);
		assertEquals(1, kills.size());
		assertEquals(5, kills.get(0).tileId);
	}

	@Test
	public void tierKeyMatchesDefaultBands()
	{
		List<PluginConfigResponse.TierBand> bands = ClogTaskModel.defaultTierBands();
		assertEquals("troll", ClogTaskModel.tierKeyOf(10, bands));
		assertEquals("easy", ClogTaskModel.tierKeyOf(50, bands));
		assertEquals("medium", ClogTaskModel.tierKeyOf(250, bands));
		assertEquals("hard", ClogTaskModel.tierKeyOf(400, bands));
		assertEquals("ultra", ClogTaskModel.tierKeyOf(800, bands));
	}

	@Test
	public void tierKeyHonoursCustomDynamicBands()
	{
		List<PluginConfigResponse.TierBand> bands = new ArrayList<>();
		bands.add(band("baby", "Baby", 0));
		bands.add(band("spicy", "Spicy", 200));
		bands.add(band("death", "Death", 600));
		assertEquals("baby", ClogTaskModel.tierKeyOf(50, bands));
		assertEquals("spicy", ClogTaskModel.tierKeyOf(200, bands));
		assertEquals("spicy", ClogTaskModel.tierKeyOf(599, bands));
		assertEquals("death", ClogTaskModel.tierKeyOf(600, bands));
		assertEquals("Death", ClogTaskModel.tierLabel("death", bands));
		// Empty/missing served bands fall back to the baked-in defaults.
		assertEquals(ClogTaskModel.defaultTierBands().size(), ClogTaskModel.tierBandsOrDefault(null).size());
	}

	@Test
	public void filterByTier()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Troll", ClogTaskModel.Type.DROP, 0, 1, 100, 10));
		rows.add(new ClogTaskModel.TaskRow(2, "Ultra", ClogTaskModel.Type.DROP, 0, 1, 101, 800));

		List<PluginConfigResponse.TierBand> bands = ClogTaskModel.defaultTierBands();
		List<ClogTaskModel.TaskRow> ultra = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, null, null, "ultra", bands);
		assertEquals(1, ultra.size());
		assertEquals(2, ultra.get(0).tileId);
	}

	private static PluginConfigResponse.TierBand band(String key, String label, int min)
	{
		PluginConfigResponse.TierBand b = new PluginConfigResponse.TierBand();
		b.key = key;
		b.label = label;
		b.min = min;
		return b;
	}

	private static ClogTaskModel.TaskRow rowOf(List<ClogTaskModel.TaskRow> rows, int tileId)
	{
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (r.tileId == tileId)
			{
				return r;
			}
		}
		throw new AssertionError("no row " + tileId);
	}

	private static ClogTaskModel.Kind kindOf(List<ClogTaskModel.TaskRow> rows, int tileId)
	{
		return rowOf(rows, tileId).kind;
	}

	@Test
	public void filterBySearchIsCaseInsensitive()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Vorkath head", ClogTaskModel.Type.DROP, 0, 1, 100));
		rows.add(new ClogTaskModel.TaskRow(2, "Zulrah scales", ClogTaskModel.Type.DROP, 0, 1, 101));

		List<ClogTaskModel.TaskRow> hit = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, "VORK");
		assertEquals(1, hit.size());
		assertEquals(1, hit.get(0).tileId);
	}

	@Test
	public void filterSortsIncompleteFirstThenLabel()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "Zeta done", ClogTaskModel.Type.DROP, 1, 1, 100));
		rows.add(new ClogTaskModel.TaskRow(2, "Beta open", ClogTaskModel.Type.DROP, 0, 1, 101));
		rows.add(new ClogTaskModel.TaskRow(3, "Alpha progress", ClogTaskModel.Type.DROP, 1, 2, 102));

		List<ClogTaskModel.TaskRow> sorted = ClogTaskModel.filter(rows,
			ClogTaskModel.StatusFilter.ALL, ClogTaskModel.TypeFilter.ALL, null);
		// IN_PROGRESS first, then NOT_STARTED, then COMPLETED.
		assertEquals(3, sorted.get(0).tileId); // Alpha progress (in progress)
		assertEquals(2, sorted.get(1).tileId); // Beta open (not started)
		assertEquals(1, sorted.get(2).tileId); // Zeta done (completed)
	}

	@Test
	public void completedCount()
	{
		List<ClogTaskModel.TaskRow> rows = new ArrayList<>();
		rows.add(new ClogTaskModel.TaskRow(1, "a", ClogTaskModel.Type.DROP, 5, 5, 100));
		rows.add(new ClogTaskModel.TaskRow(2, "b", ClogTaskModel.Type.DROP, 1, 5, 101));
		assertEquals(1, ClogTaskModel.completedCount(rows));
		assertFalse(rows.get(1).isCompleted());
	}

	// ---- Collection set modes (mirrors the site's lib/collectionSets) ------------------------------

	private static PluginConfigResponse.ItemRequirement req(String name, int have, String group, int groupRequire)
	{
		PluginConfigResponse.ItemRequirement r = new PluginConfigResponse.ItemRequirement();
		r.name = name;
		r.requiredAmount = 1;
		r.currentAmount = have;
		r.group = group;
		r.groupRequire = groupRequire;
		return r;
	}

	@Test
	public void flatCollectionNeedsEveryItem()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Bandos chestplate", 1, null, 0));
		reqs.add(req("Bandos tassets", 0, null, 0));
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, null));
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, null));
	}

	@Test
	public void anyModeReportsTheClosestSetAndCompletesOnOne()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Dharok's helm", 1, "Dharok", 0));
		reqs.add(req("Dharok's greataxe", 0, "Dharok", 0));
		reqs.add(req("Guthan's helm", 0, "Guthan", 0));
		reqs.add(req("Guthan's warspear", 0, "Guthan", 0));
		// Closest set, not the sum across sets.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "any"));
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, "any"));
	}

	@Test
	public void allModeNeedsEverySetAndOneSourceCannotFinishIt()
	{
		// One unique from each of three bosses.
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		for (String boss : new String[]{ "Duke", "Leviathan", "Whisperer" })
		{
			reqs.add(req(boss + " a", 0, boss, 1));
			reqs.add(req(boss + " b", 0, boss, 1));
		}
		assertArrayEquals(new int[]{ 0, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "all"));

		// Both Duke uniques is still ONE source — capped at what that set needs.
		reqs.get(0).currentAmount = 1;
		reqs.get(1).currentAmount = 1;
		assertArrayEquals(new int[]{ 1, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "all"));

		// The same board under the old OR-ed reading would have read as complete.
		assertEquals(1, ClogTaskModel.collectionProgress(reqs, "any")[2]);

		reqs.get(2).currentAmount = 1; // Leviathan
		reqs.get(4).currentAmount = 1; // Whisperer
		assertArrayEquals(new int[]{ 3, 3, 1 }, ClogTaskModel.collectionProgress(reqs, "all"));
	}

	@Test
	public void partialSetsNeedOnlyTheirRequireCount()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			reqs.add(req("Megarare " + i, i < 2 ? 1 : 0, "Rares", 3));
		}
		assertArrayEquals(new int[]{ 2, 3, 0 }, ClogTaskModel.collectionProgress(reqs, "any"));
		reqs.get(2).currentAmount = 1;
		assertArrayEquals(new int[]{ 3, 3, 1 }, ClogTaskModel.collectionProgress(reqs, "any"));
	}

	@Test
	public void ungroupedItemsStayRequiredAlongsideTheSets()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Scythe of vitur", 0, null, 0));
		reqs.add(req("Duke unique", 1, "Duke", 1));
		// The set is satisfied, the always-required item isn't.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "all"));
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "any"));
	}

	@Test
	public void anOlderServerSendingNoModeKeepsTheLegacyReading()
	{
		// No groupMode and no groupRequire — OR-ed full sets, exactly as before set modes existed.
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("Ahrim's hood", 1, "Ahrim", 0));
		reqs.add(req("Ahrim's staff", 1, "Ahrim", 0));
		reqs.add(req("Karil's coif", 0, "Karil", 0));
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs));
	}

	@Test
	public void setNamesGroupCaseInsensitively()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("a", 1, "Duke", 1));
		reqs.add(req("b", 0, "duke", 1));
		reqs.add(req("c", 0, "Leviathan", 1));
		// Two sets, not three — and Duke's is already satisfied.
		assertArrayEquals(new int[]{ 1, 2, 0 }, ClogTaskModel.collectionProgress(reqs, "all"));
	}

	@Test
	public void aStaleRequireLargerThanItsSetStaysSatisfiable()
	{
		List<PluginConfigResponse.ItemRequirement> reqs = new ArrayList<>();
		reqs.add(req("a", 1, "Set", 4));
		reqs.add(req("b", 1, "Set", 4));
		assertArrayEquals(new int[]{ 2, 2, 1 }, ClogTaskModel.collectionProgress(reqs, "all"));
	}

	// ── Cumulative value tiles ──────────────────────────────────────────────────────────────────

	private static PluginConfigResponse.TrackedValue value(String mode, long threshold, long current)
	{
		PluginConfigResponse.TrackedValue v = new PluginConfigResponse.TrackedValue();
		v.tileId = 1;
		v.label = "Bank it";
		v.mode = mode;
		v.thresholdGp = threshold;
		v.currentGp = current;
		return v;
	}

	@Test
	public void onlyTotalModeCountsAsCumulative()
	{
		assertTrue(ClogTaskModel.isTotalValue(value("total", 1, 0)));
		assertTrue(ClogTaskModel.isTotalValue(value("TOTAL", 1, 0)));
		assertFalse(ClogTaskModel.isTotalValue(value("single", 1, 0)));
		// An older server sends no mode at all, which has only ever meant single-haul.
		assertFalse(ClogTaskModel.isTotalValue(value(null, 1, 0)));
	}

	@Test
	public void gpReadsShortAndDropsAPointlessDecimal()
	{
		assertEquals("0", ClogTaskModel.formatGp(0));
		assertEquals("999", ClogTaskModel.formatGp(999));
		assertEquals("1K", ClogTaskModel.formatGp(1_000));
		assertEquals("12.5K", ClogTaskModel.formatGp(12_500));
		assertEquals("3.4M", ClogTaskModel.formatGp(3_400_000));
		assertEquals("50M", ClogTaskModel.formatGp(50_000_000));
		assertEquals("2.1B", ClogTaskModel.formatGp(2_150_000_000L));
		// Negative can't happen from the server, but must not render as "-1" either.
		assertEquals("0", ClogTaskModel.formatGp(-5));
	}

	/** Truncating rather than rounding: 49.99m must never read "50M/50M" while the tile is short. */
	@Test
	public void gpNeverRoundsUpToLookFinished()
	{
		assertEquals("49.9M", ClogTaskModel.formatGp(49_990_000));
		assertEquals("999.9M", ClogTaskModel.formatGp(999_999_999));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the drop-attribution chat-line parsing against the REAL in-game message. This line is
 * the ONLY loot signal for drops that bypass both loot events (Maggot King's spill-out uniques),
 * so if Jagex changes the string a test here goes red and tells you drop auto-detect broke for
 * those bosses (manual site submission is the fallback).
 */
public class DropNotificationLineTest
{
	@Test
	public void parsesMaggotKingSpillLine()
	{
		// Exact line observed in game, following "Some loot spills out alongside the Maggot
		// King's guts. Yuck."
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void parsesQuantityPrefixAndTrailingPeriod()
	{
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: 1,500 x Cannonball (Maggot King).");
		assertTrue(m.matches());
		assertEquals("1,500", m.group(2));
		assertEquals("Cannonball", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void keepsParenthesesInsideItemNames()
	{
		// Greedy item group: only the LAST parenthetical is the source.
		Matcher m = AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Rune platebody (g) (Maggot King)");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void ignoresClanBroadcastVariant()
	{
		// The CLAN_MESSAGE broadcast carries a value and a "from <source>" suffix. The personal
		// pattern must not match it — the broadcast has its own pattern (below) whose handler is
		// recipient-checked, and a personal-pattern match would mis-parse the source group.
		assertFalse(AnvilPlugin.DROP_NOTIFICATION_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.").matches());
	}

	@Test
	public void parsesClanBroadcastVariant()
	{
		// Exact clan broadcast observed in game alongside (and independently of) the personal
		// line — the fallback signal when a member's in-game loot notifications are off.
		Matcher m = AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Nisbro", m.group(1));
		assertNull(m.group(2));
		assertEquals("Elder venator fang", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastKeepsParenthesesInsideItemNames()
	{
		Matcher m = AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Rune platebody (g) (39,000 coins) from Maggot King.");
		assertTrue(m.matches());
		assertEquals("Rune platebody (g)", m.group(3));
		assertEquals("Maggot King", m.group(4));
	}

	@Test
	public void clanBroadcastDoesNotMatchPersonalLine()
	{
		// The personal line has no "(N coins) from" tail — each pattern matches only its own
		// variant so one chat line can never be parsed twice by both handlers.
		assertFalse(AnvilPlugin.CLAN_DROP_BROADCAST_PATTERN.matcher(
			"Nisbro received a drop: Elder venator fang (Maggot King)").matches());
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ActivityStatsTest
{
	/** A stand-in client: ids we set answer with their value, everything else reads 0. */
	private static IntUnaryOperator reader(Map<Integer, Integer> values)
	{
		return id -> values.getOrDefault(id, 0);
	}

	private static final IntUnaryOperator ZERO = id -> 0;

	@Test
	public void readsAVarbitBackedClueTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 47);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesElite"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(47), out.get("cluesElite"));
	}

	@Test
	public void readsAVarpBackedCounter()
	{
		Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.COLLECTION_COUNT, 548);
		varps.put(VarPlayerID.COLOSSEUM_GLORY, 12_400);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "colosseumGlory"), ZERO, reader(varps));

		assertEquals(Integer.valueOf(548), out.get("collectionsLogged"));
		assertEquals(Integer.valueOf(12_400), out.get("colosseumGlory"));
	}

	@Test
	public void cluesAllSumsEveryTier()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED, 1);
		varbits.put(VarbitID.COLLECTION_CLUES_EASY_COMPLETED, 2);
		varbits.put(VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED, 4);
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 8);
		varbits.put(VarbitID.COLLECTION_CLUES_ELITE_COMPLETED, 16);
		varbits.put(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, 32);

		Map<String, Integer> out = ActivityStats.read(
			Collections.singletonList("cluesAll"), reader(varbits), ZERO);

		assertEquals(Integer.valueOf(63), out.get("cluesAll"));
	}

	/** An unsynced collection log reads 0; sending it would be a request that changes nothing. */
	@Test
	public void dropsNonPositiveReads()
	{
		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("collectionsLogged", "cluesAll", "cluesHard"), ZERO, ZERO);

		assertTrue(out.isEmpty());
	}

	/**
	 * The site sends every activity key the board tracks, including the rank-based ones it has no
	 * in-game counter for. Those must fall out here rather than push a wrong number.
	 */
	@Test
	public void skipsKeysTheClientCannotAnswer()
	{
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(VarbitID.COLLECTION_CLUES_HARD_COMPLETED, 9);

		Map<String, Integer> out = ActivityStats.read(
			Arrays.asList("lastManStanding", "pvpArena", "bhHunter", "riftsClosed", "soulWarsZeal", "cluesHard"),
			reader(varbits), ZERO);

		assertEquals(1, out.size());
		assertEquals(Integer.valueOf(9), out.get("cluesHard"));
		assertNull(out.get("lastManStanding"));
		assertNull(out.get("soulWarsZeal"));

		assertFalse(ActivityStats.isReadable("riftsClosed"));
		assertTrue(ActivityStats.isReadable("cluesHard"));
		assertTrue(ActivityStats.isReadable("cluesAll"));
	}

	@Test
	public void triggersOnlyOnIdsItReads()
	{
		assertTrue(ActivityStats.isTrigger(VarbitID.COLLECTION_CLUES_MASTER_COMPLETED, -1));
		assertTrue(ActivityStats.isTrigger(-1, VarPlayerID.COLLECTION_COUNT));
		assertFalse(ActivityStats.isTrigger(VarbitID.INSIDE_WILDERNESS, -1));
		// RuneLite's "this wasn't a varbit" / "this wasn't a varp" sentinel must never match.
		assertFalse(ActivityStats.isTrigger(-1, -1));
	}

	@Test
	public void readsNothingWhenTheBoardTracksNoActivities()
	{
		assertTrue(ActivityStats.read(null, ZERO, ZERO).isEmpty());
		assertTrue(ActivityStats.read(Collections.emptyList(), ZERO, ZERO).isEmpty());
	}

	@Test
	public void clogProgressReadsLikeTheGameShowsIt()
	{
		Map<Integer, Integer> varps = new HashMap<>();
		varps.put(VarPlayerID.COLLECTION_COUNT, 548);
		varps.put(VarPlayerID.COLLECTION_COUNT_MAX, 1712);

		assertEquals("548/1712 (32.0%)", ActivityStats.clogProgress(reader(varps)));
	}

	/** Both varps read 0 until the log syncs — a missing field beats a wrong one in a clan post. */
	@Test
	public void clogProgressIsAbsentRatherThanGuessedAt()
	{
		assertNull(ActivityStats.clogProgress(ZERO));

		Map<Integer, Integer> noTotal = new HashMap<>();
		noTotal.put(VarPlayerID.COLLECTION_COUNT, 548);
		assertNull(ActivityStats.clogProgress(reader(noTotal)));

		// More obtained than exist means we're reading something other than what we think.
		Map<Integer, Integer> impossible = new HashMap<>();
		impossible.put(VarPlayerID.COLLECTION_COUNT, 2000);
		impossible.put(VarPlayerID.COLLECTION_COUNT_MAX, 1712);
		assertNull(ActivityStats.clogProgress(reader(impossible)));
	}
}

package com.anvil;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class VestigeRollsTest
{
	private static PluginConfigResponse.RollTable duke()
	{
		PluginConfigResponse.RollTable t = new PluginConfigResponse.RollTable();
		t.boss = "Duke Sucellus";
		// Virtus ×3, chromium ingot, Magus vestige, Eye of the duke.
		t.rollItemIds = Arrays.asList(26241, 26243, 26245, 28276, 28281, 28321);
		t.vestigeItemId = 28281;
		t.vestigeName = "Magus vestige";
		t.rollsPerVestige = 3;
		return t;
	}

	@Test
	public void countsRollsAndCallsTheVestigeOneAhead()
	{
		VestigeRolls v = new VestigeRolls();
		VestigeRolls.Result r1 = v.record(duke(), 28276); // chromium ingot
		assertEquals(1, r1.state.rolls);
		assertFalse(r1.vestigeNext);
		assertTrue(r1.line.contains("Roll 1 of 3"));

		VestigeRolls.Result r2 = v.record(duke(), 26241); // Virtus mask
		assertEquals(2, r2.state.rolls);
		assertTrue("two rolls in, the next unique is the vestige", r2.vestigeNext);
		assertTrue(r2.line.contains("Magus vestige"));
	}

	@Test
	public void theVestigeResetsAndAnchorsTheCycle()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		VestigeRolls.Result r = v.record(duke(), 28281); // Magus vestige
		assertTrue(r.vestige);
		assertEquals(0, r.state.rolls);
		assertTrue("a seen vestige anchors the cycle — the count is exact from here", r.state.exact);
		assertTrue(r.line.contains("cycle resets"));
	}

	@Test
	public void countsAreEstimatedUntilAVestigeIsSeen()
	{
		VestigeRolls v = new VestigeRolls();
		assertTrue(v.record(duke(), 28276).line.contains("(estimated)"));
		v.record(duke(), 28281); // vestige seen — anchored
		assertFalse(v.record(duke(), 28276).line.contains("estimated"));
	}

	@Test
	public void aNonVestigeWhereTheVestigeWasDueReAnchorsInsteadOfLying()
	{
		// Two rolls in (so we think the vestige is next), then a non-vestige: our count was wrong,
		// which is what happens when drops landed while the plugin wasn't running.
		VestigeRolls.State was = new VestigeRolls.State(2, true);
		VestigeRolls.Result r = VestigeRolls.advance(was, false, 3, "Magus vestige");
		assertEquals(1, r.state.rolls);
		assertFalse("we can't claim exact after being wrong", r.state.exact);
		assertTrue(r.line.contains("re-anchoring"));
	}

	@Test
	public void itemsOutsideTheRollTableAreNotRolls()
	{
		VestigeRolls v = new VestigeRolls();
		assertNull("the pet is its own roll, not a unique-table one", v.record(duke(), 28250));
		assertNull("awakener's orb likewise", v.record(duke(), 28334));
		assertEquals(0, v.get("Duke Sucellus").rolls);
	}

	@Test
	public void eachBossKeepsItsOwnCycle()
	{
		PluginConfigResponse.RollTable vard = new PluginConfigResponse.RollTable();
		vard.boss = "Vardorvis";
		vard.rollItemIds = Arrays.asList(26241, 28276, 28285, 28319);
		vard.vestigeItemId = 28285;
		vard.vestigeName = "Ultor vestige";
		vard.rollsPerVestige = 3;

		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 26241);
		v.record(vard, 28276);
		assertEquals(2, v.get("Duke Sucellus").rolls);
		assertEquals(1, v.get("Vardorvis").rolls);
	}

	@Test
	public void stateSurvivesASerialiseRoundTrip()
	{
		VestigeRolls v = new VestigeRolls();
		v.record(duke(), 28276);
		v.record(duke(), 28281); // vestige — exact
		v.record(duke(), 26241);

		VestigeRolls back = VestigeRolls.parse(v.serialise());
		assertEquals(1, back.get("Duke Sucellus").rolls);
		assertTrue(back.get("duke sucellus").exact);
	}

	@Test
	public void aCorruptedConfigValueLosesOnlyThatBoss()
	{
		VestigeRolls back = VestigeRolls.parse("duke sucellus=2:1;vardorvis=notanumber;the whisperer=1:0");
		assertEquals(2, back.get("Duke Sucellus").rolls);
		assertEquals(0, back.get("Vardorvis").rolls);
		assertEquals(1, back.get("The Whisperer").rolls);
	}

	@Test
	public void anEmptyOrAbsentConfigStartsClean()
	{
		assertEquals(0, VestigeRolls.parse(null).get("Duke Sucellus").rolls);
		assertEquals(0, VestigeRolls.parse("").get("Duke Sucellus").rolls);
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AnvilActivityLogTest
{
	private static ActivityEntry sub(String id, String ts, String player, String label, int amount, boolean self)
	{
		return new ActivityEntry(id, ts, player, 1, label, ActivityEntry.Kind.PROGRESS, amount, self);
	}

	private static ActivityEntry done(String id, String ts, String player, String label)
	{
		return new ActivityEntry(id, ts, player, 1, label, ActivityEntry.Kind.COMPLETE, 0, false);
	}

	@Test
	public void ingestPutsNewestOnTop()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		// Server sends ascending (oldest→newest).
		int added = log.ingest("s3_c0", Arrays.asList(
			sub("s1", "t1", "A", "x", 1, false),
			sub("s2", "t2", "B", "y", 1, false),
			sub("s3", "t3", "C", "z", 1, false)));
		assertEquals(3, added);
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s3", snap.get(0).id); // newest first
		assertEquals("s2", snap.get(1).id);
		assertEquals("s1", snap.get(2).id);
		assertEquals("s3_c0", log.getCursor());
	}

	@Test
	public void dedupsByIdAcrossOverlappingBatches()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		assertEquals(2, log.ingest("s2_c0", Arrays.asList(sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "B", "y", 1, false))));
		// The client re-sends an overlapping batch until its cursor advances — s2 must not double.
		assertEquals(1, log.ingest("s3_c0", Arrays.asList(sub("s2", "t", "B", "y", 1, false),
			sub("s3", "t", "C", "z", 1, false))));
		assertEquals(3, log.size());
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s3", snap.get(0).id);
		assertEquals("s2", snap.get(1).id);
		assertEquals("s1", snap.get(2).id);
	}

	@Test
	public void evictsOldestBeyondCapacity()
	{
		AnvilActivityLog log = new AnvilActivityLog(3);
		log.ingest("s5_c0", Arrays.asList(
			sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "A", "x", 1, false),
			sub("s3", "t", "A", "x", 1, false),
			sub("s4", "t", "A", "x", 1, false),
			sub("s5", "t", "A", "x", 1, false)));
		assertEquals(3, log.size());
		List<ActivityEntry> snap = log.snapshot();
		assertEquals("s5", snap.get(0).id);
		assertEquals("s4", snap.get(1).id);
		assertEquals("s3", snap.get(2).id); // s1, s2 evicted
	}

	@Test
	public void evictedIdCanReappear()
	{
		AnvilActivityLog log = new AnvilActivityLog(2);
		log.ingest("s3_c0", Arrays.asList(
			sub("s1", "t", "A", "x", 1, false),
			sub("s2", "t", "A", "x", 1, false),
			sub("s3", "t", "A", "x", 1, false))); // s1 evicted, seenIds must drop it too
		// If seenIds were leaked, this would be treated as a dup (added 0); it must be re-added.
		assertEquals(1, log.ingest("s3_c0", Collections.singletonList(sub("s1", "t", "A", "x", 1, false))));
	}

	@Test
	public void nullCursorLeavesCursorUnchanged()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		log.ingest("s7_c2", Collections.singletonList(sub("s7", "t", "A", "x", 1, false)));
		log.ingest(null, Collections.<ActivityEntry>emptyList());
		assertEquals("s7_c2", log.getCursor());
	}

	@Test
	public void resetClearsEverything()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		log.ingest("s2_c1", Arrays.asList(sub("s1", "t", "A", "x", 1, false), done("c1", "t", "B", "y")));
		log.reset();
		assertTrue(log.isEmpty());
		assertEquals(AnvilActivityLog.EMPTY_CURSOR, log.getCursor());
	}

	@Test
	public void nullAndBlankIdsAreIgnored()
	{
		AnvilActivityLog log = new AnvilActivityLog();
		int added = log.ingest("s1_c0", Arrays.asList(
			sub("", "t", "A", "x", 1, false),
			(ActivityEntry) null,
			sub("s1", "t", "A", "x", 1, false)));
		assertEquals(1, added);
		assertEquals(1, log.size());
	}

	@Test
	public void summaryReadsLikeAFeedLine()
	{
		assertEquals("You +3 · Dragon warhammer",
			sub("s1", "t", "Bob", "Dragon warhammer", 3, true).summary());
		assertEquals("Kayle +1 · Zulrah unique",
			sub("s2", "t", "Kayle", "Zulrah unique", 1, false).summary());
		assertEquals("Kayle completed Tanzanite fang",
			done("c1", "t", "Kayle", "Tanzanite fang").summary());
		// Unattributed completion falls back to the team.
		assertEquals("Team completed Some stat tile",
			done("c2", "t", null, "Some stat tile").summary());
	}

	@Test
	public void selfCompletionSaysYou()
	{
		ActivityEntry e = new ActivityEntry("c9", "t", "Me", 1, "Inferno cape",
			ActivityEntry.Kind.COMPLETE, 0, true);
		assertEquals("You completed Inferno cape", e.summary());
	}

	@Test
	public void kindFromWireMapsServerStrings()
	{
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("complete"));
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("COMPLETE"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("progress"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire(null));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("garbage"));
	}

	@Test
	public void aggregateForDisplayFoldsAGrindByWorkerAndTile()
	{
		// Newest-first: 3 of Kayle's "+1" kills on tile 5, a completion, then one of YOUR kills on tile 5.
		List<ActivityEntry> feed = Arrays.asList(
			new ActivityEntry("s30", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("s29", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("c9", "t", "Sara", 6, "Complete 25 ToA", ActivityEntry.Kind.COMPLETE, 0, false),
			new ActivityEntry("s28", "t", "Kayle", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 1, false),
			new ActivityEntry("s27", "t", "You", 5, "Kill 500 Dust devils", ActivityEntry.Kind.PROGRESS, 2, true));

		List<ActivityEntry> agg = AnvilActivityLog.aggregateForDisplay(feed);

		assertEquals(3, agg.size());                       // 3 Kayle kills fold to 1; completion; your line stays
		assertEquals("s30", agg.get(0).id);                // newest occurrence's metadata kept
		assertEquals("Kayle +3 · Kill 500 Dust devils", agg.get(0).summary());
		assertTrue(agg.get(1).isCompletion());             // completion preserved in place
		assertEquals(2, agg.get(2).amount);                // your own tile-5 grind is a separate line
		assertTrue(agg.get(2).self);
	}
}

package com.anvil;

import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Whole-log collection sync ({@link ClogFullSync}) — the accumulator behind the "Sync profile"
 * button. The rules that matter are all about NOT sending a fragment: a partial transmit replaces a
 * stored log, so "have the items stopped arriving" and "is this even a log" are the whole job.
 */
public class ClogFullSyncTest
{
	private static ClogFullSync receiving(int items, long at)
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		for (int i = 1; i <= items; i++)
		{
			sync.onItem(1000 + i, 1, at);
		}
		return sync;
	}

	@Test
	public void itemsArriveAndSettleAfterTheQuietPeriod()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertEquals(10, sync.size());
		// Still arriving.
		assertFalse(sync.isDue(1_000));
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void aLateItemRestartsTheClock()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.onItem(9999, 1, 2_500);
		assertFalse("the transmit is still going", sync.isDue(2_500 + ClogFullSync.QUIET_MS - 1));
		assertTrue(sync.isDue(2_500 + ClogFullSync.QUIET_MS));
		assertEquals(11, sync.size());
	}

	@Test
	public void aFragmentIsNeverSent()
	{
		// One stray item — another plugin's search toggle, or an interface closed mid-transmit.
		// Sending this would replace a full stored log with a single row.
		ClogFullSync sync = receiving(ClogFullSync.MIN_ITEMS - 1, 1_000);
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS * 10));
	}

	@Test
	public void nothingIsCollectedUntilATransmitStarts()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.onItem(4151, 1, 1_000); // an item fired while we weren't asking
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
	}

	@Test
	public void quantityIsKeptAndNeverBelowOne()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(false);
		sync.onItem(4151, 3, 1_000);
		sync.onItem(11802, 0, 1_000); // the game reports some slots without a count
		Map<Integer, Integer> snapshot = sync.snapshot();
		assertEquals(Integer.valueOf(3), snapshot.get(4151));
		assertEquals(Integer.valueOf(1), snapshot.get(11802));
	}

	@Test
	public void aSecondTransmitReplacesTheFirst()
	{
		ClogFullSync sync = receiving(10, 1_000);
		// Opening the log again re-transmits everything; the old batch must not linger and inflate it.
		sync.begin(false);
		assertEquals(0, sync.size());
		sync.onItem(4151, 1, 5_000);
		assertEquals(1, sync.size());
	}

	@Test
	public void aFailedPushKeepsTheItemsForTheNextTick()
	{
		ClogFullSync sync = receiving(10, 1_000);
		assertTrue(sync.isDue(1_000 + ClogFullSync.QUIET_MS));

		sync.onSendFailed(4_000);
		assertEquals("a site being down mustn't cost the transmit", 10, sync.size());
		assertFalse(sync.isDue(4_000));
		assertTrue(sync.isDue(4_000 + ClogFullSync.QUIET_MS));

		sync.onSent();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(9_000));
	}

	@Test
	public void aManualRequestSurvivesUntilItIsSent()
	{
		ClogFullSync sync = new ClogFullSync();
		sync.begin(true);
		assertTrue(sync.isManual());
		// Pressing the button, then opening the log (which begins its own transmit), still reports.
		sync.begin(false);
		assertTrue(sync.isManual());
		sync.onSent();
		assertFalse(sync.isManual());
	}

	@Test
	public void theFingerprintIgnoresOrderButNotContent()
	{
		ClogFullSync a = new ClogFullSync();
		a.begin(false);
		a.onItem(4151, 1, 1_000);
		a.onItem(11802, 2, 1_000);

		ClogFullSync b = new ClogFullSync();
		b.begin(false);
		b.onItem(11802, 2, 5_000);
		b.onItem(4151, 1, 5_000);
		assertEquals("the same log in any order is the same log", a.fingerprint(), b.fingerprint());

		// A new item, or another of one you had, is a different log — both must push.
		ClogFullSync more = new ClogFullSync();
		more.begin(false);
		more.onItem(4151, 1, 1_000);
		more.onItem(11802, 2, 1_000);
		more.onItem(20997, 1, 1_000);
		assertNotEquals(a.fingerprint(), more.fingerprint());

		ClogFullSync dupe = new ClogFullSync();
		dupe.begin(false);
		dupe.onItem(4151, 1, 1_000);
		dupe.onItem(11802, 3, 1_000);
		assertNotEquals(a.fingerprint(), dupe.fingerprint());
	}

	@Test
	public void switchingAccountsDropsAHalfReceivedLog()
	{
		ClogFullSync sync = receiving(10, 1_000);
		sync.reset();
		assertEquals(0, sync.size());
		assertFalse(sync.isDue(1_000 + ClogFullSync.QUIET_MS));
		// And a stray item after the reset isn't collected either.
		sync.onItem(4151, 1, 2_000);
		assertEquals(0, sync.size());
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * {@link SyncBackoff} — what stops a refused push becoming a request every 30 seconds for as long as
 * someone stays logged in.
 */
public class SyncBackoffTest
{
	@Test
	public void readyUntilSomethingFails()
	{
		SyncBackoff backoff = new SyncBackoff();
		assertTrue(backoff.ready(0));
		assertTrue(backoff.ready(1_000_000));
	}

	@Test
	public void waitsLongerEachTimeUpToTheCeiling()
	{
		SyncBackoff backoff = new SyncBackoff();
		long now = 10_000;

		backoff.onFailure(now);
		assertFalse(backoff.ready(now + SyncBackoff.FIRST_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));

		backoff.onFailure(now);
		assertFalse("second failure waits twice as long", backoff.ready(now + SyncBackoff.FIRST_MS));
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS * 2));

		// However bad it gets, it settles at the ceiling rather than growing forever.
		for (int i = 0; i < 20; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now + SyncBackoff.MAX_MS - 1));
		assertTrue(backoff.ready(now + SyncBackoff.MAX_MS));
	}

	@Test
	public void oneSuccessClearsTheWholeStreak()
	{
		SyncBackoff backoff = new SyncBackoff();
		long now = 10_000;
		for (int i = 0; i < 5; i++)
		{
			backoff.onFailure(now);
		}
		assertFalse(backoff.ready(now));

		backoff.onSuccess();
		assertTrue(backoff.ready(now));
		// And the next failure starts from the bottom again, not from where the streak left off.
		backoff.onFailure(now);
		assertTrue(backoff.ready(now + SyncBackoff.FIRST_MS));
	}

	@Test
	public void reportsHowLongTheSilenceLasts()
	{
		SyncBackoff backoff = new SyncBackoff();
		backoff.onFailure(0);
		assertEquals(SyncBackoff.FIRST_MS / 1000, backoff.secondsUntilReady(0));
		assertEquals(0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS));
		assertEquals("never negative", 0, backoff.secondsUntilReady(SyncBackoff.FIRST_MS * 10));
	}
}

package com.anvil;

import java.util.Collections;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The client setting a live board silently depends on.
 *
 * <p>A switch the member is not looking at turns their event off, and the board gives them no way to
 * tell. The in-game loot-drop line is what corpse-boss loot credits off, and the reminder to enable
 * it used to be gated on clan rare-drop POSTS being on, which has nothing to do with whether the
 * board needs it.</p>
 *
 * <p>There used to be a second one here: "Auto Submit Drops" governed every tile kind and the stat
 * pushes, not just drops, so one flick of it played a whole bingo for nothing — and the nudge was
 * the apology for a switch that should not have existed. The setting is gone, and submitting is
 * simply what the plugin does, so the nudge went with it.</p>
 *
 * <p>Asked only while an event is actually running: a plugin that lectures about settings for
 * something that is not happening is noise, and noise is what gets a nudge ignored.</p>
 */
public class EventNudgeTest
{
	private static PluginConfigResponse live()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.name = "July Bingo";
		cfg.event.startDate = "2020-01-01T00:00:00.000Z";
		return cfg;
	}

	private static PluginConfigResponse notStarted()
	{
		PluginConfigResponse cfg = live();
		cfg.event.startDate = "2099-01-01T00:00:00.000Z";
		return cfg;
	}

	@Test
	public void aBoardWithDropTilesNeedsTheInGameDropLine()
	{
		PluginConfigResponse cfg = live();
		cfg.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void soDoesOneWithValueTiles()
	{
		// Same signal, same reason: a haul from a corpse boss reaches neither tile kind without it.
		PluginConfigResponse cfg = live();
		cfg.trackedValues = Collections.singletonList(new PluginConfigResponse.TrackedValue());
		assertTrue(AnvilPlugin.eventNeedsDropLines(cfg));
	}

	@Test
	public void aBoardWithNeitherIsLeftAlone()
	{
		assertFalse("a KC-only board never reads that line", AnvilPlugin.eventNeedsDropLines(live()));
		assertFalse(AnvilPlugin.eventNeedsDropLines(null));

		PluginConfigResponse upcoming = notStarted();
		upcoming.trackedDrops = Collections.singletonList(new PluginConfigResponse.TrackedDrop());
		assertFalse("not until it starts", AnvilPlugin.eventNeedsDropLines(upcoming));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The clan broadcast for a new collection-log slot.
 *
 * <p>WHY IT IS PARSED AT ALL: the personal line — "New item added to your collection log: X" — only
 * prints when the player has the in-game collection-log notification switched on. With it off the
 * plugin saw nothing: no achievements post, no tile credit, no kill-count stamp, while the clan chat
 * announced the unlock to everyone else. The broadcast depends on the CLAN's settings instead, so
 * between the two most unlocks are seen by one line or the other.
 *
 * <p>It is only ever acted on for the local player. A clanmate's unlock belongs to their client —
 * acting on it here would post their slot from somebody else's account.
 */
public class ClogUnlockLineTest
{
	private static Matcher match(String line)
	{
		return AnvilPlugin.CLAN_CLOG_BROADCAST_PATTERN.matcher(line);
	}

	@Test
	public void readsTheNameAndTheItem()
	{
		Matcher m = match("hyperi0n received a new collection log item: Lost bag (356/1717)");
		assertTrue(m.matches());
		assertEquals("hyperi0n", m.group(1));
		assertEquals("Lost bag", m.group(2));
	}

	/** The progress tail is a clan setting, so it may simply not be there. */
	@Test
	public void theCountIsOptional()
	{
		Matcher m = match("Nisbro received a new collection log item: Twisted bow");
		assertTrue(m.matches());
		assertEquals("Twisted bow", m.group(2));
	}

	@Test
	public void keepsBracketsThatBelongToTheItem()
	{
		Matcher m = match("Zezima received a new collection log item: Ancient page 1 (part 2) (99/1717)");
		assertTrue(m.matches());
		assertEquals("Ancient page 1 (part 2)", m.group(2));
	}

	@Test
	public void toleratesATrailingStop()
	{
		Matcher m = match("Zezima received a new collection log item: Dizana's quiver (uncharged).");
		assertTrue(m.matches());
		assertEquals("Dizana's quiver (uncharged)", m.group(2));
	}

	/**
	 * The drop broadcast is a different line about a different thing, and the two must not be
	 * confused: crediting a drop as a clog slot would post it to the wrong channel.
	 */
	@Test
	public void doesNotSwallowTheDropBroadcast()
	{
		assertFalse(match("Nisbro received a drop: Elder venator fang (50,000,000 coins) from Maggot King.").matches());
	}

	/** Whose unlock it is decides whether we act, and RSN comparison is the site's rule. */
	@Test
	public void theNameIsComparedTheWayTheSiteCompares()
	{
		Matcher m = match("Hyperi0n  received a new collection log item: Lost bag (356/1717)");
		assertTrue(m.matches());
		assertTrue(Rsn.same(m.group(1), "hyperi0n"));
		assertFalse(Rsn.same(m.group(1), "someone else"));
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * WHICH CLAN a request is for, once the Site URL stops naming one.
 *
 * The member types one address and one Anvil answers on it for every clan, so on the canonical form
 * the URL says nothing about which clan is meant and the server picks from the token. That works,
 * and it is invisible: a member drafted onto two live boards had no way to see which one their drops
 * were filing into, and no way to change it.
 *
 * So there are two slugs and they are not the same thing. The one the MEMBER picked wins outright.
 * The one the SERVER last said it answered for is adopted for everything else — which is what makes
 * a submission, a starting shot and its upload land in the right clan on an address that names none,
 * since those routes resolve a clan from the address rather than from the token.
 *
 * The config poll is the exception that makes Auto work: on Auto it stays unaddressed, so every poll
 * is a fresh question and a member whose live board moves to their other clan follows it.
 */
public class ClanAddressingTest
{
	private BingoApiClient client;

	@Before
	public void setUp()
	{
		client = new BingoApiClient(new Gson(), new OkHttpClient());
		client.configure("https://anvilosrs.com", "tok");
	}

	// ---- Auto: nothing chosen, nothing heard yet ---------------------------------------------------

	@Test
	public void withNothingKnownEveryUrlIsTheBareRoot()
	{
		assertEquals("https://anvilosrs.com/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("", client.getActiveClan());
	}

	@Test
	public void theServerSAnswerIsAdoptedForEverythingButTheNextQuestion()
	{
		client.setResolvedClan("theafkspot");

		// Everything the plugin DOES is now addressed…
		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/c/theafkspot/api/events/12/submissions",
			client.clanUrl("/api/events/12/submissions"));
		assertEquals("https://anvilosrs.com/c/theafkspot/api/upload", client.clanUrl("/api/upload"));

		// …but the poll that ASKS stays open, so the site can still change its mind.
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("theafkspot", client.getActiveClan());
	}

	@Test
	public void onAutoTheSiteCanMoveUsToAnotherClan()
	{
		client.setResolvedClan("theafkspot");
		client.setResolvedClan("vanguard"); // a new board went live over there
		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
	}

	// ---- An explicit pick outranks the server ------------------------------------------------------

	@Test
	public void aMemberSPickBeatsWhateverTheServerResolved()
	{
		client.setResolvedClan("theafkspot");
		client.setChosenClan("vanguard");

		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		// And the poll is addressed too — they asked for this clan, so stop re-asking.
		assertEquals("https://anvilosrs.com/c/vanguard/api/plugin/config", client.configUrl("/api/plugin/config"));
		assertEquals("vanguard", client.getActiveClan());
	}

	@Test
	public void choosingAutoAgainHandsTheDecisionBack()
	{
		client.setResolvedClan("theafkspot");
		client.setChosenClan("vanguard");
		client.setChosenClan(""); // the Auto row

		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		assertEquals("https://anvilosrs.com/api/plugin/config", client.configUrl("/api/plugin/config"));
	}

	// ---- The slug is validated, because it goes straight into a URL --------------------------------

	@Test
	public void anythingThatIsNotASlugNamesNoClan()
	{
		for (String bad : new String[]{
			null, "", "   ",
			"a",                                // too short for the site's own pattern
			"Not A Slug",                       // spaces
			"THEAFKSPOT/../../evil",            // traversal
			"theafkspot/api/plugin/config",     // a path, not a slug
			"the_afk_spot",                     // underscore is not in the alphabet
			"..",
			"a".repeat(33),                     // past the 32-char cap
		})
		{
			client.setChosenClan(bad);
			client.setResolvedClan(bad);
			assertEquals("rejected: " + bad,
				"https://anvilosrs.com/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
		}
	}

	@Test
	public void aSlugIsLowercasedAndTrimmedRatherThanRefused()
	{
		client.setChosenClan("  TheAfkSpot  ");
		assertEquals("https://anvilosrs.com/c/theafkspot/api/plugin/stats", client.clanUrl("/api/plugin/stats"));
	}

	// ---- Signing in is about a person, so it never carries a clan ----------------------------------

	@Test
	public void deviceSignInIsNeverAddressed()
	{
		client.setChosenClan("vanguard");
		client.setResolvedClan("theafkspot");

		// The member has no clan yet at this point — that is the whole reason they are signing in — and
		// the site's device-auth pair is a platform route that a clan prefix would only redirect out of.
		assertEquals("https://anvilosrs.com/api/plugin/auth/start", client.rootUrl("/api/plugin/auth/start"));
		assertEquals("https://anvilosrs.com/api/plugin/auth/poll", client.rootUrl("/api/plugin/auth/poll"));
	}

	// ---- Old addresses are untouched, which is the point of keeping them ---------------------------

	@Test
	public void aPerClanSubdomainStillWorksAndIsNotDoublyAddressed()
	{
		// A jar installed before any of this has its clan's own hostname stored. The site resolves the
		// clan from that host and ignores what the token says — but it still ANSWERS with a slug, and
		// prefixing on top of a host that already names the clan is harmless: /c/<same slug> resolves to
		// the same clan. Pinned so nobody 'optimises' the prefix away and breaks the apex instead.
		client.configure("https://theafkspot.anvilosrs.com", "tok");
		client.setResolvedClan("theafkspot");
		assertEquals("https://theafkspot.anvilosrs.com/c/theafkspot/api/plugin/stats",
			client.clanUrl("/api/plugin/stats"));
	}

	@Test
	public void anUnconfiguredClientBuildsNothingSurprising()
	{
		BingoApiClient blank = new BingoApiClient(new Gson(), new OkHttpClient());
		blank.setResolvedClan("theafkspot");
		// No base URL: the caller checks isConfigured() before ever calling out, and the builder must
		// not throw on the way to that check.
		assertEquals("null/c/theafkspot/api/plugin/stats", blank.clanUrl("/api/plugin/stats"));
	}
}

package com.anvil;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The highlight queue: what collapses, what survives a failed push, and what gets dropped when a
 * session outruns the site.
 *
 * <p>The behaviour worth defending is the collapsing. The game announces everything more than once —
 * a kill fires two loot events, a pet fires up to three chat lines — so a queue that took each
 * sighting at face value would put the same drop on the clan's feed twice.
 */
public class AnvilMomentsTest
{
	private static AnvilMoments.Moment drop(String source, int itemId, long at)
	{
		return new AnvilMoments.Moment("drop", itemId, "Tanzanite fang", 1, 3_100_000L, source, "npc", 210, at,
			AnvilMoments.keyFor("drop", source, itemId, at));
	}

	@Test
	public void theSameDropSeenTwiceIsOneEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// NpcLootReceived then LootReceived, a tick apart — one drop, not two.
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_000_600L));
		assertEquals(1, moments.size());
	}

	@Test
	public void theSameItemFromTheSameBossMinutesLaterIsANewEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.record(drop("Zulrah", 12922, 1_300_000L));
		assertEquals(2, moments.size());
	}

	@Test
	public void aPetIsNamedAfterTheFactWithoutBecomingASecondEntry()
	{
		AnvilMoments moments = new AnvilMoments();
		// The chat line announces a pet without saying which one; the collection-log line follows.
		String key = AnvilMoments.keyFor("pet", "Zulrah", null, 5_000L);
		moments.record(new AnvilMoments.Moment("pet", null, null, 1, null, "Zulrah", "npc", 210, 5_000L, key));
		assertTrue(moments.nameQueued(key, "Pet snakeling", 12921));

		assertEquals(1, moments.size());
		AnvilMoments.Moment queued = moments.nextBatch().get(0);
		assertEquals("Pet snakeling", queued.itemName);
		assertEquals(Integer.valueOf(12921), queued.itemId);
		// Naming must not disturb what the moment already knew.
		assertEquals("Zulrah", queued.source);
		assertEquals(Integer.valueOf(210), queued.kc);
	}

	@Test
	public void namingSomethingThatIsNotQueuedDoesNothing()
	{
		AnvilMoments moments = new AnvilMoments();
		assertFalse(moments.nameQueued("nothing-here", "Beaver", 13322));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchStaysQueuedUntilItIsConfirmed()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		List<AnvilMoments.Moment> batch = moments.nextBatch();
		assertEquals(1, batch.size());
		// The push failed — nothing was confirmed, so nothing is lost.
		assertEquals(1, moments.size());
		moments.onSent(batch);
		assertTrue(moments.isEmpty());
	}

	@Test
	public void aBatchIsCappedAndTheRestWaits()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.BATCH + 5; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.BATCH, moments.nextBatch().size());
	}

	@Test
	public void anOverflowingQueueDropsItsOldestNotItsNewest()
	{
		AnvilMoments moments = new AnvilMoments();
		for (int i = 0; i < AnvilMoments.MAX_QUEUED + 10; i++)
		{
			moments.record(drop("Zulrah", 12922, i * 60_000L));
		}
		assertEquals(AnvilMoments.MAX_QUEUED, moments.size());
		// The pet you just got must not be evicted to keep a loot pile from an hour ago.
		long newest = (AnvilMoments.MAX_QUEUED + 9) * 60_000L;
		boolean holdsNewest = false;
		for (AnvilMoments.Moment m : moments.nextBatch())
		{
			holdsNewest |= m.at == newest;
		}
		// nextBatch() returns the oldest first, so check the whole queue rather than the batch head.
		while (!holdsNewest && !moments.isEmpty())
		{
			List<AnvilMoments.Moment> batch = moments.nextBatch();
			for (AnvilMoments.Moment m : batch)
			{
				holdsNewest |= m.at == newest;
			}
			moments.onSent(batch);
		}
		assertTrue(holdsNewest);
	}

	@Test
	public void aKeylessMomentIsRefused()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(new AnvilMoments.Moment("drop", 12922, "Tanzanite fang", 1, 1L, "Zulrah", "npc", 1, 0L, null));
		assertTrue(moments.isEmpty());
	}

	@Test
	public void resetForgetsEverything()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(drop("Zulrah", 12922, 1_000_000L));
		moments.reset();
		assertTrue(moments.isEmpty());
	}

	@Test
	public void deathsFromDifferentKillersDoNotShareAKey()
	{
		String olm = AnvilMoments.keyFor("death", "Great Olm", null, 1_000_000L);
		String vasa = AnvilMoments.keyFor("death", "Vasa Nistirio", null, 1_000_000L);
		assertFalse(olm.equals(vasa));
		// An unknown killer still produces a usable key rather than a null one — a death nobody can
		// attribute is still a death, and the site is what decides it belongs nowhere.
		assertTrue(AnvilMoments.keyFor("death", null, null, 1_000_000L).startsWith("death|"));
	}

	@Test
	public void aCombatTaskCarriesItsTaskAndTierAndNothingElse()
	{
		AnvilMoments.Moment m = AnvilMoments.Moment.combatTask("Perfect Zulrah", "Master", 1_000_000L);
		assertEquals("ca", m.kind);
		assertEquals("Perfect Zulrah", m.taskName);
		assertEquals("Master", m.tier);
		// No item, no price, no source: which boss it belongs to is the site's answer, out of its own
		// dataset, so inventing one here would only be something to disagree with later.
		assertNull(m.itemId);
		assertNull(m.itemName);
		assertNull(m.source);
		assertNull(m.valueGp);
		assertTrue(m.key.startsWith("ca|perfect zulrah|"));
	}

	@Test
	public void twoTasksInTheSameTickKeepTheirOwnKeys()
	{
		AnvilMoments moments = new AnvilMoments();
		moments.record(AnvilMoments.Moment.combatTask("Perfect Zulrah", "Master", 1_000_000L));
		moments.record(AnvilMoments.Moment.combatTask("Zulrah Adept", "Hard", 1_000_000L));
		assertEquals(2, moments.nextBatch().size());
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What the side panel is allowed to offer, per clan.
 *
 * The rule that matters: a roster is scraped from the clan channel this account is standing in, so
 * it can never be synced for a clan you aren't in — admin or not — because you cannot see it.
 */
public class SidebarActionsTest
{
	private static AnvilSidebarDataSource source()
	{
		return new AnvilSidebarDataSource(() -> new PluginConfigResponse(),
			new BingoApiClient(new Gson(), new OkHttpClient()));
	}

	@Test
	public void offersNothingForAnotherClan()
	{
		SidebarDataSource.PanelActions remote = source().actionsFor("some-other-clan");
		assertFalse("a roster you can't see is not a button", remote.canSyncRoster);
		assertFalse("and there is no wire to send a profile there yet", remote.canSyncProfile);
		assertNull(remote.rosterNote);
	}

	@Test
	public void offersNothingWithNoPluginBound()
	{
