package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Which kill-count line belongs to a drop.
 *
 * THE BUG THIS FIXES. RuneLite reports raid loot under the BASE name — its event says "Tombs of
 * Amascut" whichever mode you ran — while the game's kill-count line names the mode: "Your completed
 * Tombs of Amascut: Expert Mode count is: 220". The plugin keyed its counts on the chat name and
 * looked them up by the loot name, so the two never met, and the lookup answered with whatever the
 * NORMAL-mode count happened to be. A Masori mask off an Expert raid at 220 posted to Discord as
 * "KC 54".
 */
public class RaidKillCountTest
{
	@Test
	public void aModeCreditsItsBaseRaid()
	{
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut: Expert Mode"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut: Entry Mode"));
		// CoX Challenge Mode carries no colon in the game's line — punctuation is normalised away, so
		// the two spellings behave the same.
		assertTrue(AnvilPlugin.kcLineBelongsTo("Chambers of Xeric", "Chambers of Xeric Challenge Mode"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Theatre of Blood", "Theatre of Blood: Hard Mode"));
	}

	@Test
	public void theSameActivityStillMatchesItself()
	{
		assertTrue(AnvilPlugin.kcLineBelongsTo("Zulrah", "Zulrah"));
		assertTrue(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Tombs of Amascut"));
	}

	@Test
	public void aLongerUNRELATEDNameIsNotAMode()
	{
		// The boundary is what stops a short name swallowing a longer one once punctuation is gone.
		// A mode adds WORDS; it never merely extends one.
		assertFalse(AnvilPlugin.kcLineBelongsTo("Kree", "Kree'Arra"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Cerb", "Cerberus"));
	}

	@Test
	public void adifferentActivityNeverMatches()
	{
		assertFalse(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut", "Chambers of Xeric"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Zulrah", "Vorkath"));
	}

	@Test
	public void theBaseDoesNotCreditFromAMoreSpecificSource()
	{
		// Direction matters. A drop from the mode should not be answered by the base raid's line —
		// only the other way round, which is the direction RuneLite's naming actually produces.
		assertFalse(AnvilPlugin.kcLineBelongsTo("Tombs of Amascut: Expert Mode", "Tombs of Amascut"));
	}

	@Test
	public void nothingMatchesNothing()
	{
		assertFalse(AnvilPlugin.kcLineBelongsTo(null, "Zulrah"));
		assertFalse(AnvilPlugin.kcLineBelongsTo("Zulrah", null));
		assertFalse(AnvilPlugin.kcLineBelongsTo("", "Zulrah"));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Turning the path OBS reports into a file NAME, which is the only part of it the plugin may act on.
 *
 * <p>The path itself is off limits: a Filepath cannot be built from a string, so the clip is found
 * by looking up its name inside a directory the plugin already holds. Get the name wrong and a clip
 * that is sitting right there in our own folder reads as "somewhere we may not look", and the player
 * is asked for a folder they already gave us.
 *
 * <p>Both separators matter regardless of the OS running this code: OBS reports Windows paths with
 * backslashes, and RuneLite on Windows is where most clips are taken.
 */
public class ClipFolderTest
{
	@Test
	public void readsTheNameOffAWindowsPath()
	{
		assertEquals("Replay 2026-09-20 03-15-42.mkv",
			ClipFolder.fileName("C:\\Users\\ahmed\\Videos\\Replay 2026-09-20 03-15-42.mkv"));
	}

	@Test
	public void readsTheNameOffAUnixPath()
	{
		assertEquals("Replay 2026-09-20.mp4", ClipFolder.fileName("/home/ahmed/Videos/Replay 2026-09-20.mp4"));
	}

	@Test
	public void keepsABareName()
	{
		assertEquals("clip.mp4", ClipFolder.fileName("clip.mp4"));
	}

	@Test
	public void ignoresATrailingSeparator()
	{
		assertEquals("Videos", ClipFolder.fileName("/home/ahmed/Videos/"));
	}

	/**
	 * Nothing usable is null, never the empty string: the caller treats null as "we can't reach this
	 * clip" and queues it, whereas an empty name handed to joinSegment is an exception per clip.
	 */
	@Test
	public void nothingUsableIsNull()
	{
		assertNull(ClipFolder.fileName(null));
		assertNull(ClipFolder.fileName(""));
		assertNull(ClipFolder.fileName("   "));
		assertNull(ClipFolder.fileName("/"));
		assertNull(ClipFolder.fileName("\\\\"));
	}

	/**
	 * A name that escapes the directory is the sandbox's whole concern, so it must survive parsing
	 * intact rather than being quietly normalised — joinSegment is what rejects it, loudly.
	 */
	@Test
	public void doesNotUnwindTraversal()
	{
		assertEquals("..", ClipFolder.fileName("/home/ahmed/Videos/.."));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Pins the personal-best parsing to REAL in-game completion messages.
 *
 * <p>The case that matters most is the explicit form: "Duration: 172:18. Personal best: 134:52"
 * contains two times, and reading the first one would file a bad run as somebody's record.
 */
public class PersonalBestParserTest
{
	@Test
	public void newPersonalBestTakesTheRunsOwnDuration()
	{
		// Inferno, and the generic boss fight timer.
		assertEquals(Integer.valueOf(17803), PersonalBestParser.parseCentis("Duration: 2:58.03 (new personal best)"));
		assertEquals(Integer.valueOf(9600), PersonalBestParser.parseCentis("Fight duration: 1:36 (new personal best)"));
		// Barracuda Trials print "Time:" instead of "Duration:".
		assertEquals(Integer.valueOf(36420), PersonalBestParser.parseCentis("Time: 6:04.20 (new personal best)."));
	}

	@Test
	public void explicitPersonalBestIgnoresThisRunsSlowerTime()
	{
		// The whole point: 172:18 is this run, 134:52 is the record.
		assertEquals(Integer.valueOf(809200), PersonalBestParser.parseCentis("Duration: 172:18. Personal best: 134:52"));
		assertEquals(Integer.valueOf(47900), PersonalBestParser.parseCentis("Challenge duration: 10:24. Personal best: 7:59."));
	}

	@Test
	public void hoursMinutesSecondsAreReadAsThreeParts()
	{
		// 1:02:03 is an hour and change, not one minute two seconds.
		assertEquals(Integer.valueOf(372300), PersonalBestParser.parseCentis("Duration: 1:02:03 (new personal best)"));
	}

	@Test
	public void fractionsPadToHundredths()
	{
		// ".3" is three tenths — 30 centiseconds, not 3.
		assertEquals(Integer.valueOf(6030), PersonalBestParser.parseCentis("Duration: 1:00.3 (new personal best)"));
		assertEquals(Integer.valueOf(6003), PersonalBestParser.parseCentis("Duration: 1:00.03 (new personal best)"));
	}

	@Test
	public void linesWithoutAPersonalBestAreIgnored()
	{
		// An ordinary clear is not a record, and must not overwrite one.
		assertNull(PersonalBestParser.parseCentis("Duration: 2:58.03"));
		assertNull(PersonalBestParser.parseCentis("Congratulations - your raid is complete! Duration: 15:39"));
		assertNull(PersonalBestParser.parseCentis("Your Zulrah kill count is: 1,204."));
		assertNull(PersonalBestParser.parseCentis(null));
		// The words with no time attached: nothing to record.
		assertNull(PersonalBestParser.parseCentis("You have a new personal best!"));
	}
}

