		assertEquals("me@home", AnvilPlugin.stripChatTags("me@home"));
		assertEquals("Phantom Muspah Speed-Chaser", AnvilPlugin.stripChatTags("Phantom Muspah Speed-Chaser"));
	}

	@Test
	public void aCombatTaskLineParsesToTheTaskNameAlone()
	{
