			"Congratulations, you've completed an Elite combat task: @ach_comp@Whack-a-Mole (5 points).");
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(plain);
		assertEquals(true, m.find());
		assertEquals("Whack-a-Mole",
			AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim());
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The plugin folds a name the same way the server does, or it matches the wrong account.
 *
 * <p>Every case here is a pair: a name the client read out of the game, and a name the site sent for
 * the same person. The site's rule is
 * {@code rsn.trim().toLowerCase().replace(/[\s_]+/g, ' ')} — the expectations below are that rule's
 * output, not this class's.</p>
 *
 * <p>There were three normalisers in this plugin. Two collapsed whitespace runs and one did not;
 * none of the three folded underscores, which the server has always done.</p>
 */
public class RsnTest
{
	@Test
	public void nothingIsAnEmptyKeyRatherThanNull()
	{
		assertEquals("", Rsn.normalize(null));
		assertEquals("", Rsn.normalize(""));
		assertEquals("", Rsn.normalize("   "));
	}

	@Test
	public void anEmptyKeyMatchesNobody()
	{
		// The guard the call sites rely on: an unknown local name must match no rows, not every row.
		assertFalse(Rsn.same(null, "Zezima"));
		assertFalse(Rsn.same("", "Zezima"));
		assertFalse(Rsn.same("", ""));
	}

	@Test
	public void caseIsCosmetic()
	{
		assertEquals("zezima", Rsn.normalize("ZEZIMA"));
		assertTrue(Rsn.same("ZEZIMA", "zezima"));
	}

	@Test
	public void theGameSNonBreakingSpaceIsAnOrdinarySpace()
	{
		// OSRS encodes the spaces in a display name as U+00A0 so a name never wraps a line; the site
		// stores a plain one. This is the oldest of the mismatches and the only one all three
		// implementations already handled.
		assertEquals("zez alt", Rsn.normalize("Zez\u00A0Alt"));
		assertTrue(Rsn.same("Zez\u00A0Alt", "Zez Alt"));
	}

	@Test
	public void anUnderscoreIsASpace()
	{
		// THE BUG. OSRS treats them as the same character: the game shows "GIM Nisbro", while logins,
		// hiscores lookups and hand-entered roster rows carry "GIM_nisbro". The site folds them
		// together; the plugin did not, so that player matched none of their own rows.
		assertEquals("gim nisbro", Rsn.normalize("GIM_nisbro"));
		assertEquals("gim nisbro", Rsn.normalize("GIM Nisbro"));
		// Both directions of the real pairing: the site's hand-entered underscore form against the
		// plain-space form, and against the non-breaking form the game actually hands us.
		assertTrue(Rsn.same("GIM Nisbro", "GIM_nisbro"));
		assertTrue(Rsn.same("GIM\u00A0Nisbro", "GIM_nisbro"));
	}

	@Test
	public void runsCollapseToOneSpace()
	{
		assertEquals("iron man", Rsn.normalize("Iron  Man"));
		assertEquals("iron man", Rsn.normalize("Iron__Man"));
		assertEquals("iron man", Rsn.normalize("Iron _\u00A0Man"));
	}

	@Test
	public void edgesAreTrimmed_includingTheOnesJavaSTrimWouldNotTouch()
	{
		// String.trim() strips only up to U+0020, so a name padded with non-breaking spaces would keep
		// them and fold to " zezima" — which equals nothing the server ever produces.
		assertEquals("zezima", Rsn.normalize("  Zezima "));
		assertEquals("zezima", Rsn.normalize("\u00A0Zezima\u00A0"));
		assertEquals("zezima", Rsn.normalize("_Zezima_"));
	}

	@Test
	public void aTurkishClientStillMatchesItsOwnRosterRow()
	{
		// The default locale lower-cases 'I' to a dotless 'ı' in Turkish, so an unqualified
		// toLowerCase() folds "IRON MIKE" to something the server has never seen — and that player
		// silently stops matching anything, on their machine only.
		java.util.Locale original = java.util.Locale.getDefault();
		try
		{
			java.util.Locale.setDefault(new java.util.Locale("tr", "TR"));
			assertEquals("iron mike", Rsn.normalize("IRON MIKE"));
			assertTrue(Rsn.same("IRON MIKE", "Iron Mike"));
		}
		finally
		{
			java.util.Locale.setDefault(original);
		}
	}

	/**
	 * The site's rule, transcribed, run over the same inputs.
	 *
	 * Not a second implementation to maintain — a statement of what this class is FOR. If somebody
	 * changes the fold here, this fails and points at the file on the other side that also has to
	 * change (and at the backfill its own comment warns about).
	 */
	@Test
	public void agreesWithTheServerSRuleAcrossTheAwkwardCases()
	{
		String[] names = {
			"Zezima", "ZEZIMA", "  Zezima ", "GIM_nisbro", "GIM Nisbro", "Iron  Man",
			"Iron__Man", "Zez\u00A0Alt", "a", "A B", "x_ y", "Mod\u00A0\u00A0Ash",
		};
		for (String name : names)
		{
			assertEquals("fold of " + escape(name), serverRule(name), Rsn.normalize(name));
		}
	}

	/** {@code rsn.trim().toLowerCase().replace(/[\s_]+/g, ' ')}, with JS's whitespace and trim. */
	private static String serverRule(String rsn)
	{
		// JS trim() and \s both include U+00A0; Java's include neither, so spell it out on both.
		String trimmed = rsn.replaceAll("^[\\s\\u00a0]+|[\\s\\u00a0]+$", "");
		return trimmed.toLowerCase(java.util.Locale.ROOT).replaceAll("[\\s\\u00a0_]+", " ");
	}

	private static String escape(String s)
	{
		return s.replace("\u00A0", "<nbsp>");
	}
}

package com.anvil;

import java.time.Instant;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The ladder missions board's pure math ({@link LadderMissions}): the grow/decay ramp mirrors the
 * server's completionAward formula ({@code face * (1 - (1 - targetPct/100) * frac)}), and the
 * per-second countdown. Kept in lockstep with Anvil.Site/src/lib/eventRules.ts.
 */
public class LadderMissionsTest
{
	private static PluginConfigResponse.Decay decay(int targetPct, int hours)
	{
		PluginConfigResponse.Decay d = new PluginConfigResponse.Decay();
		d.targetPct = targetPct;
		d.hours = hours;
		return d;
	}

	private static String isoAgo(long ms)
	{
		return Instant.ofEpochMilli(System.currentTimeMillis() - ms).toString();
	}

	@Test
	public void faceWhenNoDecayOrNoRevealTime()
	{
		long now = System.currentTimeMillis();
		assertEquals(100, LadderMissions.liveValue(100, isoAgo(0), null, now));
		assertEquals(100, LadderMissions.liveValue(100, null, decay(50, 24), now));
		assertEquals(100, LadderMissions.liveValue(100, "not-a-time", decay(50, 24), now));
	}

	@Test
	public void decaysLinearlyToTargetOverTheWindow()
	{
		long now = System.currentTimeMillis();
		// 200-pt mission, decays to 50% over 24h. At reveal → 200; half-way (12h) → 150; full → 100; past → 100.
		PluginConfigResponse.Decay d = decay(50, 24);
		assertEquals(200, LadderMissions.liveValue(200, isoAgo(0), d, now));
		assertEquals(150, LadderMissions.liveValue(200, isoAgo(12L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(24L * 3_600_000), d, now));
		assertEquals(100, LadderMissions.liveValue(200, isoAgo(48L * 3_600_000), d, now)); // clamps at the floor
	}

	@Test
	public void growsToTargetAboveFace()
	{
		long now = System.currentTimeMillis();
		// 100-pt mission that GROWS to 200% over 10h. Half-way → 150; full → 200; capped after.
		PluginConfigResponse.Decay d = decay(200, 10);
		assertEquals(150, LadderMissions.liveValue(100, isoAgo(5L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(10L * 3_600_000), d, now));
		assertEquals(200, LadderMissions.liveValue(100, isoAgo(20L * 3_600_000), d, now));
	}

	@Test
	public void valueLabelShowsMovementOnly()
	{
		assertEquals("120", LadderMissions.valueLabel(120, 120));
		assertEquals("120 -> 90", LadderMissions.valueLabel(120, 90));
		assertEquals("120 -> 200", LadderMissions.valueLabel(120, 200));
	}

	@Test
	public void countdownFormatsMinuteSecondAndDue()
	{
		long now = System.currentTimeMillis();
		assertEquals("12:34", LadderMissions.countdown(Instant.ofEpochMilli(now + (12 * 60 + 34) * 1000L).toString(), now));
		assertEquals("0:09", LadderMissions.countdown(Instant.ofEpochMilli(now + 9_000L).toString(), now));
		assertEquals("1:02:03", LadderMissions.countdown(Instant.ofEpochMilli(now + (3600 + 2 * 60 + 3) * 1000L).toString(), now));
		assertEquals("now", LadderMissions.countdown(Instant.ofEpochMilli(now - 1000L).toString(), now));
		assertNull(LadderMissions.countdown(null, now));
		assertNull(LadderMissions.countdown("", now));
	}

	@Test
	public void isLadderMatchesOnlyLadder()
	{
		assertTrue(LadderMissions.isLadder("ladder"));
		assertTrue(LadderMissions.isLadder("Ladder"));
		assertTrue(!LadderMissions.isLadder("bingo"));
		assertTrue(!LadderMissions.isLadder(null));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the Combat Achievement completion chat-line parsing. CA bingo tiles credit off this
 * line (including recompletions fired by the in-game "Repeat completion" setting, which append a
 * " (N points)" suffix) — if Jagex changes the string a test here goes red and tells you CA tile
 * auto-detect broke (manual site submission is the fallback).
 */
public class CombatTaskLineTest
{
	/** Runs a line through the same parse the plugin does: match, then strip the points suffix. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.CA_TASK_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		String task = AnvilPlugin.CA_TASK_POINTS.matcher(m.group(2).trim()).replaceAll("").trim();
		return new String[]{m.group(1), task};
	}

	@Test
	public void parsesFirstCompletion()
	{
		String[] r = parse("Congratulations, you've completed an Elite combat task: Whack-a-Mole.");
		assertEquals("Elite", r[0]);
		assertEquals("Whack-a-Mole", r[1]);
	}

	@Test
	public void parsesRepeatCompletionWithPointsSuffix()
	{
		// The in-game "Repeat completion" setting re-fires the line with a points suffix.
		String[] r = parse("Congratulations, you've completed a Master combat task: Nylocas, On the Rocks (5 points).");
		assertEquals("Master", r[0]);
		assertEquals("Nylocas, On the Rocks", r[1]);
	}

	@Test
	public void parsesSinglePointSuffixAndAArticle()
	{
		String[] r = parse("Congratulations, you've completed an Easy combat task: Noxious Foe (1 point).");
		assertEquals("Easy", r[0]);
		assertEquals("Noxious Foe", r[1]);
	}

	@Test
	public void tierResolvesForEveryGroupOneValue()
	{
		String[] r = parse("Congratulations, you've completed a Grandmaster combat task: The Worst Ranged Weapon.");
		assertEquals(CombatAchievementTier.GRANDMASTER, CombatAchievementTier.byName(r[0]));
	}

	@Test
	public void ignoresUnrelatedCongratulationsLines()
	{
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you've just advanced your Mining level. You are now level 99.").find());
	}

	@Test
	public void keepsParenthesesThatAreNotAPointsSuffix()
	{
		// Task names can legitimately end in a parenthesised qualifier — only "(N points)" strips.
		String[] r = parse("Congratulations, you've completed an Elite combat task: Chambers of Xeric: CM (Solo) Speed-Chaser.");
		assertEquals("Chambers of Xeric: CM (Solo) Speed-Chaser", r[1]);
	}

	@Test
	public void matcherRequiresTierWord()
	{
		assertTrue(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"Congratulations, you've completed a Hard combat task: Whack-a-Mole.").find());
		assertFalse(AnvilPlugin.CA_TASK_PATTERN.matcher(
			"you've completed a combat task").find());
	}
}

package com.anvil;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.atomic.AtomicInteger;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * STARTING SHOT (site lib/startProof) — the plugin half. Covers what the sidebar is allowed to ask
 * for ({@link AnvilSidebarDataSource#startProof()}) and the one retry rule that keeps a real drop
 * from being thrown away while a screenshot is outstanding.
 */
public class StartProofTest
{
	private static PluginConfigResponse liveConfig()
	{
		PluginConfigResponse cfg = new PluginConfigResponse();
		cfg.event = new PluginConfigResponse.EventInfo();
		cfg.event.id = 7;
		cfg.event.name = "Summer Bingo";
		cfg.event.startDate = Instant.now().minus(1, ChronoUnit.HOURS).toString();
		cfg.event.endDate = Instant.now().plus(1, ChronoUnit.DAYS).toString();
		cfg.team = new PluginConfigResponse.TeamInfo();
		cfg.team.name = "Team Molten";
		return cfg;
	}

	private static PluginConfigResponse.StartProof owed()
	{
		PluginConfigResponse.StartProof sp = new PluginConfigResponse.StartProof();
		sp.required = true;
		sp.drawn = true;
		sp.location = "Edgeville bank";
		sp.keyword = "ANVIL-GRAPE-47";
		sp.needsUpload = true;
		return sp;
	}

	private static AnvilSidebarDataSource sourceFor(PluginConfigResponse cfg)
	{
		return new AnvilSidebarDataSource(() -> cfg, new BingoApiClient(new Gson(), new OkHttpClient()));
	}

	@Test
	public void owedShotIsOfferedWhileTheEventIsLive()
	{
		PluginConfigResponse cfg = liveConfig();
		cfg.startProof = owed();

		PluginConfigResponse.StartProof offered = sourceFor(cfg).startProof();
		assertNotNull(offered);
		assertEquals("Edgeville bank", offered.location);
		assertEquals("ANVIL-GRAPE-47", offered.keyword);
	}

	@Test
	public void nothingIsAskedForWhenNothingIsOwed()
	{
		// No starting-shot block at all — an event without the rule, or a site that predates it.
		assertNull(sourceFor(liveConfig()).startProof());

		// Required but not yet drawn: the event hasn't started, so there is no location and no keyword.
		PluginConfigResponse notDrawn = liveConfig();
		notDrawn.startProof = owed();
		notDrawn.startProof.drawn = false;
		assertNull(sourceFor(notDrawn).startProof());

		// Already filed — the server says the obligation is settled.
		PluginConfigResponse filed = liveConfig();
		filed.startProof = owed();
		filed.startProof.needsUpload = false;
		assertNull(sourceFor(filed).startProof());
	}

	@Test
	public void endedEventNeverAsksForAShot()
	{
		PluginConfigResponse over = liveConfig();
		over.startProof = owed();
		over.event.endDate = Instant.now().minus(1, ChronoUnit.MINUTES).toString();
		assertNull(sourceFor(over).startProof());

		PluginConfigResponse forceEnded = liveConfig();
		forceEnded.startProof = owed();
		forceEnded.event.forceEndedAt = Instant.now().toString();
		assertNull(sourceFor(forceEnded).startProof());
	}

	@Test
	public void captureRunsTheBoundActionAndIsSafeWithoutOne()
	{
		AnvilSidebarDataSource ds = sourceFor(liveConfig());
		ds.captureStartProof(); // unbound (tests, or before the plugin wires itself up) — must not throw

		AtomicInteger fired = new AtomicInteger();
		ds.setStartProofCapture(fired::incrementAndGet);
		ds.captureStartProof();
		assertEquals(1, fired.get());
	}

	private static PluginConfigResponse.StartProof checked()
	{
		PluginConfigResponse.StartProof sp = owed();
		sp.spot = new PluginConfigResponse.StartProof.Spot();
		sp.spot.x = 3094;
		sp.spot.y = 3491;
		sp.spot.radius = 25;
		sp.maxSessionMinutes = 15;
		return sp;
	}

	private static final long NOW = 1_800_000_000_000L;

	@Test
	public void aShotFromTheSpotOnAFreshSessionIsLetThrough()
	{
		// Six squares out, five minutes into the session: nothing to complain about.
		assertNull(StartProofRules.blockReason(checked(), NOW - 5 * 60_000L, NOW, 3100, 3489));
	}

	@Test
	public void standingSomewhereElseIsRefusedBeforeTheFrameIsGrabbed()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, 2400, 3489);
		assertNotNull(reason);
		// The distance is the useful half of the message — "go to Edgeville bank" alone reads like a
		// bug when you believe you ARE at Edgeville bank.
		assertTrue(reason, reason.contains("694"));
		assertTrue(reason, reason.contains("Edgeville bank"));
	}

	@Test
	public void aSessionOlderThanTheWindowIsRefused()
	{
		String reason = StartProofRules.blockReason(checked(), NOW - 130 * 60_000L, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.contains("2h 10m"));
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void notKnowingWhenTheSessionStartedCountsAsStale()
	{
		// Plugin enabled mid-session: we can't vouch for the logout that flushed the hiscores, and
		// "probably fine" is exactly the answer this rule exists to stop giving.
		String reason = StartProofRules.blockReason(checked(), StartProofRules.UNKNOWN_LOGIN, NOW, 3094, 3491);
		assertNotNull(reason);
		assertTrue(reason, reason.toLowerCase().contains("log out"));
	}

	@Test
	public void checksThatCannotRunNeverBlock()
	{
		// An older site: no pin, no window. Exactly the behaviour before any of this existed.
		assertNull(StartProofRules.blockReason(owed(), StartProofRules.UNKNOWN_LOGIN, NOW, 2400, 3489));

		// Pinned spot, but logged out / no position to read — the distance check simply doesn't run.
		PluginConfigResponse.StartProof spotOnly = checked();
		spotOnly.maxSessionMinutes = 0;
		assertNull(StartProofRules.blockReason(spotOnly, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));

		// Session window on, position unknown, session fresh: still fine.
		assertNull(StartProofRules.blockReason(checked(), NOW - 60_000L, NOW, null, null));

		// And nothing owed at all can't block anything.
		assertNull(StartProofRules.blockReason(null, StartProofRules.UNKNOWN_LOGIN, NOW, null, null));
	}

	@Test
	public void distanceIsMeasuredTheWayTheGameMeasuresIt()
	{
		PluginConfigResponse.StartProof sp = checked();
		// The longer axis wins — 30 east and 4 north is 30 squares away, not 34.
		assertEquals(30, StartProofRules.distance(sp, 3124, 3495));
		assertEquals(0, StartProofRules.distance(sp, 3094, 3491));
		// Nothing to measure against.
		assertEquals(-1, StartProofRules.distance(owed(), 3094, 3491));
		assertEquals(-1, StartProofRules.distance(sp, null, null));
	}

	@Test
	public void describeWindowCountsDownAndThenGivesUp()
	{
		PluginConfigResponse.StartProof sp = owed();
		long now = java.time.Instant.parse("2026-08-16T19:00:00Z").toEpochMilli();
		sp.windowEndsAt = "2026-08-17T00:00:00Z";
		assertEquals("5h 00m", StartProofRules.describeWindow(sp, now));

		// Past the end there is nothing to quote — the ask has lapsed, it hasn't been failed.
		sp.windowEndsAt = "2026-08-16T18:30:00Z";
		assertEquals(null, StartProofRules.describeWindow(sp, now));

		// A site too old to send one, and a stamp we can't read, both say nothing rather than lying.
		sp.windowEndsAt = null;
		assertEquals(null, StartProofRules.describeWindow(sp, now));
		sp.windowEndsAt = "not a date";
		assertEquals(null, StartProofRules.describeWindow(sp, now));
	}

	@Test
	public void awaitingAStartingShotIsRetryable()
	{
		// 409 is normally a permanent 4xx — but this one clears the moment the player files their
		// shot, and the pending drop must survive until then.
		java.io.IOException awaiting = BingoApiClient.submissionErrorForTest(
			"Submission failed", 409, "{\"error\":\"Upload your starting shot first\",\"code\":\"start_proof_required\"}");
		assertTrue(!(awaiting instanceof BingoApiClient.PermanentSubmissionException));

		// Any other 409 stays permanent (tile already complete, etc.) so it can't loop forever.
		java.io.IOException other = BingoApiClient.submissionErrorForTest(
			"Submission failed", 409, "{\"error\":\"Tile already complete\"}");
		assertTrue(other instanceof BingoApiClient.PermanentSubmissionException);
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Naming a drop's source, and reading the server's facts about it.
 */
public class DropSourceTest
{
	private static PluginConfigResponse.DropFacts facts()
	{
		PluginConfigResponse.DropFacts f = new PluginConfigResponse.DropFacts();
		f.pets = new HashMap<>();
		f.guaranteed = new HashMap<>();
		return f;
	}

	private static PluginConfigResponse.DropFacts.Pet pet(String kind, String... sources)
	{
		PluginConfigResponse.DropFacts.Pet p = new PluginConfigResponse.DropFacts.Pet();
		p.kind = kind;
		p.sources = Arrays.asList(sources);
		return p;
	}

	// ---- naming the source ------------------------------------------------------------------

	@Test
	public void lootKeyIsNamedAsOneRatherThanAsAChest()
	{
		// "Loot Chest" is RuneLite's name for an opened Wilderness key. Repeating it names no
		// content and reads like PvM loot to the whole channel.
		assertTrue(DropSource.isLootKey("Loot Chest"));
		assertTrue(DropSource.isLootKey("loot key"));
		assertFalse(DropSource.isLootKey("Chest (Bryophyta's lair)"));
		assertEquals(" from a loot key", DropSource.fromPhrase("Loot Chest", "pvp"));
	}

	@Test
	public void aPlayerKillSaysSoRatherThanReadingAsAMonster()
	{
		// The source of PvP loot is the victim's RSN, so the old wording had a monster called Zezima
		// dropping a whip.
		assertEquals(" from a player kill (Zezima)", DropSource.fromPhrase("Zezima", "pvp"));
		assertEquals(" from a player kill", DropSource.fromPhrase(null, "pvp"));
	}

	@Test
	public void ordinaryLootKeepsItsOwnName()
	{
		assertEquals(" from Vorkath", DropSource.fromPhrase("Vorkath", "npc"));
		assertEquals(" from Tombs of Amascut", DropSource.fromPhrase("Tombs of Amascut", "event"));
		assertEquals(" from pickpocketing Elves", DropSource.fromPhrase("Elves", "pickpocket"));
		// Nothing true to say beats a dangling "from".
		assertEquals("", DropSource.fromPhrase(null, "npc"));
		assertEquals("", DropSource.fromPhrase("  ", "npc"));
	}

	@Test
	public void countIsLabelledForWhatWasActuallyCounted()
	{
		assertEquals("Keys opened", DropSource.countLabel("Loot Chest", "pvp"));
		assertEquals("Caskets", DropSource.countLabel("Clue Scroll (Master)", "event"));
		assertEquals("KC", DropSource.countLabel("Vorkath", "npc"));
	}

	// ---- guaranteed drops -------------------------------------------------------------------

	@Test
	public void aGuaranteedDropIsRecognisedFromTheSourceThatOwesIt()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("ancient blood ornament kit", Arrays.asList("duke sucellus", "vardorvis"));
		assertTrue(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "Duke Sucellus"));
		assertTrue(DropSource.isGuaranteed(f, "ANCIENT BLOOD ORNAMENT KIT", "vardorvis"));
		// Same item, a source that does not owe it: still a real roll.
		assertFalse(DropSource.isGuaranteed(f, "Ancient blood ornament kit", "The Whisperer"));
	}

	@Test
	public void aStarSourceMeansWhereverItDrops()
	{
		// What a clan override that named no sources stores.
		PluginConfigResponse.DropFacts f = facts();
		f.guaranteed.put("some kit", Collections.singletonList("*"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", "Anything"));
		assertTrue(DropSource.isGuaranteed(f, "Some kit", null));
	}

	@Test
	public void anOlderSiteKnowsNothingAndChangesNothing()
	{
		assertFalse(DropSource.isGuaranteed(null, "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), "Ancient blood ornament kit", "Duke Sucellus"));
		assertFalse(DropSource.isGuaranteed(facts(), null, "Duke Sucellus"));
	}

	// ---- pets -------------------------------------------------------------------------------

	@Test
	public void aPetComesFromItsOwnBossNotFromWhateverDroppedLootLast()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("baby mole", pet("npc", "Giant Mole"));
		// The client had just seen loot from something else entirely — a stray kill on the way out.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", "Hill Giant", null));
		// And with nothing observed at all, which is the skilling-adjacent case.
		assertEquals("Giant Mole", DropSource.resolvePetSource(f, "Baby mole", null, null));
	}

	@Test
	public void whatTheClientSawWinsWhenItIsOneOfTheRealSources()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "vet'ion", null));
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", "Calvar'ion", null));
	}

	@Test
	public void severalSourcesAndNoSightingFallBackToWhereTheyActuallyGrind()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("vet'ion jr.", pet("npc", "Calvar'ion", "Vet'ion"));
		Map<String, Integer> kc = new HashMap<>();
		kc.put("calvar'ion", 12);
		kc.put("vet'ion", 940);
		assertEquals("Vet'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, kc));
		// No kills recorded anywhere: the first listed source beats naming nothing.
		assertEquals("Calvar'ion", DropSource.resolvePetSource(f, "Vet'ion jr.", null, null));
	}

	@Test
	public void aSkillingPetHasNoMonsterAndDoesNotBorrowOne()
	{
		PluginConfigResponse.DropFacts f = facts();
		f.pets.put("beaver", pet("skill"));
		// Whatever loot the client saw, a Beaver did not come from it.
		assertNull(DropSource.resolvePetSource(f, "Beaver", "Hill Giant", null));
	}

	@Test
	public void anUnknownPetKeepsWhateverTheClientSaw()
	{
		// A pet released after the site's last dataset regen: the old guess is still the best there
		// is, so nothing gets worse while the server catches up.
		assertEquals("New Boss", DropSource.resolvePetSource(facts(), "Newpet", "New Boss", null));
		assertEquals("New Boss", DropSource.resolvePetSource(null, "Newpet", "New Boss", null));
	}
}

package com.anvil;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * When the plugin is allowed to reach the network, and when it offers to sign in.
 *
 * THE PROPERTY THAT MATTERS FOR THE HUB. An install nobody signs into must contact nothing: the Site
 * URL defaults to "" and every unauthenticated poll — hello, active-weekly, schedule,
 * weekly-leaderboard — bails on an empty URL. So the first request is always downstream of an
 * explicit click, and the button names its destination before it is pressed.
 *
 * The canonical site is therefore a constant offered on that click, NOT a config default. The
 * distinction is the whole compliance argument, and a future "simplification" that moves the address
 * into {@code AnvilConfig.apiUrl()} would quietly undo it — which is what this test is here to stop.
 */
public class SignInGateTest
{
	private BingoApiClient client()
	{
		return new BingoApiClient(new Gson(), new OkHttpClient());
	}

	@Test
	public void aFreshInstallKnowsNoSite()
	{
		// Nothing configured: no address, so nothing to call.
		assertEquals("", client().getApiUrl());
	}

	@Test
	public void signInIsOfferedBeforeASiteIsKnown()
	{
		// It used to require a URL, which hid the button that would have configured them behind the
		// configuration it was meant to perform.
		BingoApiClient c = client();
		assertTrue("a fresh install is offered the way in", c.needsSignIn());
	}

	@Test
	public void signInStopsBeingOfferedOnceThereIsAToken()
	{
		BingoApiClient c = client();
		c.configure(BingoApiClient.CANONICAL_SITE, "tok");
		assertFalse(c.needsSignIn());
	}

	@Test
	public void aTypedSiteIsStillTheirSiteAndKeepsTheOffer()
	{
		// Somebody running their own Anvil, or an older per-clan address: signed out, so still offered
		// the sign-in — and the auto-fill must not touch a URL they chose (asserted in the panel by
		// only writing when empty; here we pin that a set URL survives configure()).
		BingoApiClient c = client();
		c.configure("https://bingo.myclan.example", "");
		assertTrue(c.needsSignIn());
		assertEquals("https://bingo.myclan.example", c.getApiUrl());
	}

	@Test
	public void theCanonicalSiteIsAnAbsoluteHttpsAddress()
	{
		// It is written into config on click, so it has to be usable verbatim — a bare hostname would
		// be normalised somewhere and a trailing slash would double up in every built URL.
		assertEquals("https://anvilosrs.com", BingoApiClient.CANONICAL_SITE);
		assertTrue(BingoApiClient.CANONICAL_SITE.startsWith("https://"));
		assertFalse(BingoApiClient.CANONICAL_SITE.endsWith("/"));
	}
}

package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Which thing a collection-log unlock says it came from.
 *
 * <p>The source used to be "whatever loot event happened most recently", which is right for a drop
 * announced the instant it lands and wrong for anything that arrives on its own schedule. A clue
 * reward is the clean example: kill a Saradomin wizard, open the casket that kill eventually led to,
 * and the unlock for Enchanted top was stamped <em>Saradomin wizard</em> — the last thing the player
 * hit rather than the thing the item fell out of.</p>
 *
 * <p>Nothing failed. The post went out, read plausibly, and named the wrong monster.</p>
 */
public class ClogSourceTest
{
	private static final long WINDOW = 60_000;

	private static Map<String, AnvilPlugin.RecentItem> seen(Object... triples)
	{
		Map<String, AnvilPlugin.RecentItem> m = new HashMap<>();
		for (int i = 0; i < triples.length; i += 3)
		{
			String name = (String) triples[i];
			long at = ((Number) triples[i + 1]).longValue();
			String source = (String) triples[i + 2];
			m.put(name.toLowerCase(), new AnvilPlugin.RecentItem(1, at, source));
		}
		return m;
	}

	@Test
	public void anItemIsCreditedToWhatItFellOutOf()
	{
		// Both happened inside the window; the casket is not the most recent, and is still correct.
		Map<String, AnvilPlugin.RecentItem> m = seen(
			"Enchanted top", 1_000L, "Clue Scroll (Medium)",
			"Grimy guam leaf", 5_000L, "Saradomin wizard");

		assertEquals("Clue Scroll (Medium)", AnvilPlugin.sourceOf(m, "Enchanted top", 5_000L, WINDOW));
		assertEquals("Saradomin wizard", AnvilPlugin.sourceOf(m, "Grimy guam leaf", 5_000L, WINDOW));
	}

	@Test
	public void nameLookupIgnoresCase()
	{
		Map<String, AnvilPlugin.RecentItem> m = seen("Enchanted top", 0L, "Clue Scroll (Medium)");
		assertEquals("Clue Scroll (Medium)", AnvilPlugin.sourceOf(m, "ENCHANTED TOP", 0L, WINDOW));
	}

	/** Past the window it is not this unlock's loot, and guessing is what caused the bug. */
	@Test
	public void anItemFromTooLongAgoNamesNothing()
	{
		Map<String, AnvilPlugin.RecentItem> m = seen("Enchanted top", 0L, "Clue Scroll (Medium)");
		assertNull(AnvilPlugin.sourceOf(m, "Enchanted top", WINDOW + 1, WINDOW));
	}

	@Test
	public void anUnlockWithNoLootBehindItNamesNothing()
	{
		// A skilling pet or a quest reward: the caller falls back to the recent-loot source, which is
		// the only signal there is when no loot event carried the item.
		assertNull(AnvilPlugin.sourceOf(seen(), "Rocky", 0L, WINDOW));
		assertNull(AnvilPlugin.sourceOf(seen("Rocky", 0L, ""), "Rocky", 0L, WINDOW));
		assertNull(AnvilPlugin.sourceOf(seen("Rocky", 0L, "Thieving"), null, 0L, WINDOW));
	}
}

