package com.anvil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.regex.Matcher;
import org.junit.Test;

/**
 * The level-up line, as the game prints it.
 *
 * <p>The pattern used to look for "you just advanced". The game says "you've just advanced", and has
 * for as long as it has said anything, so the chat fallback matched nothing from the day it was
 * written. It survived because the test next to it asserted the same invented sentence — written
 * from the same memory as the pattern, so the two agreed with each other and neither agreed with
 * RuneScape.</p>
 *
 * <p>Every string below is the real thing.</p>
 */
public class LevelUpLineTest
{
	private static Matcher match(String line)
	{
		Matcher m = AnvilPlugin.LEVEL_UP_PATTERN.matcher(line);
		assertTrue("should match: " + line, m.find());
		return m;
	}

	@Test
	public void readsTheLineTheGameActuallyPrints()
	{
		Matcher m = match("Congratulations, you've just advanced your Cooking level. You are now level 99.");
		assertEquals("Cooking", m.group(1));
		assertEquals("99", m.group(2));
	}

	@Test
	public void readsTheSkillsThatTakeAnArticleInsteadOfYour()
	{
		assertEquals("Agility",
			match("Congratulations, you've just advanced an Agility level. You are now level 70.").group(1));
	}

	/** Some clients render the apostrophe as a typographic one; the sentence is the same sentence. */
	@Test
	public void acceptsACurlyApostrophe()
	{
		assertEquals("Fishing",
			match("Congratulations, you’ve just advanced your Fishing level. You are now level 99.").group(1));
	}

	@Test
	public void stillReadsTheFormWithoutTheContraction()
	{
		assertEquals("Mining",
			match("Congratulations, you just advanced your Mining level. You are now level 99.").group(1));
	}

	@Test
	public void doesNotMatchAnUnrelatedCongratulation()
	{
		assertFalse(AnvilPlugin.LEVEL_UP_PATTERN
			.matcher("Congratulations, you've completed a combat task: Peach Conjurer.").find());
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * What killed us, as opposed to what we were killing.
 *
 * <p>The feed used to name the last thing we landed a hit on, which produced "died to Abyssal
 * portal", "died to Volatile earth" and "died to Jug" — three things a player attacked and none
 * that killed anybody. A hitsplat carries no attacker, so the inference runs off who had us
 * TARGETED when we last took damage.
 */
public class DeathAttributionTest
{
	private static final long T = 1_000_000L;

	@Test
	public void namesTheThingAttackingUsRatherThanTheThingWeAttacked()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("The Whisperer", T);
		d.tookDamage(T + 100);
		// We spent the fight hitting a mechanic. It did not kill us.
		assertEquals("The Whisperer", d.killer("Volatile earth", T + 200));
	}

	@Test
	public void aMutualFightWinsOverAnythingElseOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Tekton", T);
		d.targetedUs("Abyssal portal", T + 50); // more recent, but not who we were fighting
		d.tookDamage(T + 100);
		assertEquals("Tekton", d.killer("Tekton", T + 200));
	}

	@Test
	public void otherwiseTheThingThatJustTurnedOnUs()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Guardian", T);
		d.targetedUs("Vasa Nistirio", T + 500);
		d.tookDamage(T + 600);
		// We were hitting neither; the newest acquisition is the one that finished it.
		assertEquals("Vasa Nistirio", d.killer("Muttadile", T + 700));
	}

	@Test
	public void reAcquiringUsRefreshesTheClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Nylocas Ischyros", T);
		d.targetedUs("Nylocas Toxobolos", T + 100);
		d.targetedUs("Nylocas Ischyros", T + 900); // switched back onto us
		d.tookDamage(T + 950);
		assertEquals("Nylocas Ischyros", d.killer(null, T + 1_000));
	}

	@Test
	public void somethingThatStoppedAttackingUsIsNotASuspect()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Zulrah", T);
		d.tookDamage(T + 100);
		d.stoppedTargetingUs("Zulrah");
		assertNull(d.killer("Zulrah", T + 200));
	}

	@Test
	public void nothingOnUsIsAnsweredWithNothing()
	{
		// A mechanic, a fall, poison after the fight. Naming what we were hitting is exactly the bug.
		DeathAttribution d = new DeathAttribution();
		d.tookDamage(T);
		assertNull(d.killer("Jug", T + 100));
	}

	@Test
	public void damageTooOldToBeThisDeathNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		assertNull(d.killer("Vorkath", T + 60_000));
	}

	@Test
	public void neverHavingTakenDamageNamesNobody()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void clearingEndsEveryClaim()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs("Vorkath", T);
		d.tookDamage(T);
		d.clear();
		assertEquals(0, d.attackerCount());
		assertNull(d.killer("Vorkath", T + 100));
	}

	@Test
	public void theAttackerListCannotGrowWithoutBound()
	{
		DeathAttribution d = new DeathAttribution();
		for (int i = 0; i < 200; i++)
		{
			d.targetedUs("Attacker " + i, T + i);
		}
		// Capped, and it is the OLDEST that get dropped — the newest arrivals are the suspects.
		assertEquals(24, d.attackerCount());
		d.tookDamage(T + 500);
		assertEquals("Attacker 199", d.killer(null, T + 600));
	}

	@Test
	public void blankNamesAreIgnoredRatherThanStored()
	{
		DeathAttribution d = new DeathAttribution();
		d.targetedUs(null, T);
		d.targetedUs("", T);
		d.tookDamage(T);
		assertEquals(0, d.attackerCount());
		assertNull(d.killer(null, T + 100));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The Hallowed Sepulchre announces itself in its own shape rather than the "Your &lt;X&gt; count
 * is: N" one every other activity uses, so agility tiles targeting it rest entirely on these two
 * patterns. Both lines carry a running total that must stay OUT of the credit path — one line is
 * one credit, so a player arriving with 4,000 coffins already opened starts an event on zero.
 */
public class SepulchreLineTest
{
	private static String floorOf(String line)
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(line);
		return m.find() ? m.group(1) : null;
	}

	@Test
	public void parsesFloorCompletion()
	{
		Matcher m = AnvilPlugin.SEPULCHRE_FLOOR_PATTERN.matcher(
			"You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 1,234.");
		assertTrue(m.find());
		assertEquals("3", m.group(1));
		assertEquals("1,234", m.group(2));
	}

	/** Every floor announces separately — a full 1→5 run emits five lines, so five credits. */
	@Test
	public void parsesEveryFloor()
	{
		for (int floor = 1; floor <= 5; floor++)
		{
			String line = "You have completed Floor " + floor
				+ " of the Hallowed Sepulchre! Total completions: 7.";
			assertEquals(String.valueOf(floor), floorOf(line));
		}
	}

	@Test
	public void parsesGrandHallowedCoffinPlural()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	/** The first-ever coffin says "1 time!", not "1 times!" — the optional s is load-bearing. */
	@Test
	public void parsesGrandHallowedCoffinSingular()
	{
		assertTrue(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 1 time!").find());
	}

	/**
	 * The Sepulchre lines must not also match the generic KC parser: a double match would credit a
	 * floor twice on clients where a tile happens to carry both name shapes.
	 */
	@Test
	public void sepulchreLinesDoNotMatchTheGenericKcParser()
	{
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertFalse(AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("You have opened the Grand Hallowed Coffin 42 times!").find());
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertEquals(null, floorOf("You have completed the Hallowed Sepulchre course."));
		assertFalse(AnvilPlugin.SEPULCHRE_COFFIN_PATTERN
			.matcher("You have opened the coffin.").find());
	}

	// ---- Hunter Guild rumours -------------------------------------------------------------

	@Test
	public void parsesRumourCompletion()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 42 rumours for the Hunter Guild.").find());
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1,250 rumours for the Hunter Guild.").find());
	}

	/** The first hand-in reads "1 rumour" — the optional s is load-bearing, as with the coffin. */
	@Test
	public void parsesSingularRumour()
	{
		assertTrue(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed 1 rumour for the Hunter Guild.").find());
	}

	@Test
	public void rumourLineIsNotConfusedWithTheSepulchreFloorLine()
	{
		assertFalse(AnvilPlugin.HUNTER_RUMOUR_PATTERN
			.matcher("You have completed Floor 3 of the Hallowed Sepulchre! Total completions: 12.").find());
		assertEquals(null, floorOf("You have completed 42 rumours for the Hunter Guild."));
	}

	// ---- Woodcutting Guild egg offerings --------------------------------------------------

	@Test
	public void parsesEggOfferings()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 7 offerings.").find());
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made 1,024 offerings.").find());
	}

	/** The first offering reads "one offering", spelled out — not a digit. */
	@Test
	public void parsesFirstEggOfferingSpelledOut()
	{
		assertTrue(AnvilPlugin.EGG_OFFERING_PATTERN.matcher("You have made one offering.").find());
	}

	/**
	 * The offering line never names the activity, so the trailing full stop is the only thing
	 * stopping it from swallowing longer sentences that merely start the same way.
	 */
	@Test
	public void offeringLineDoesNotSwallowLongerSentences()
	{
		assertFalse(AnvilPlugin.EGG_OFFERING_PATTERN
			.matcher("You have made 3 offerings to the shrine and received nothing").find());
	}

	// ---- Brimhaven Agility Arena ----------------------------------------------------------

	/**
	 * Brimhaven counts TICKETS, and its counter word is two words long. Without it in the pattern
	 * the arena's name parses as "Agility Arena Total Ticket" and matches no tile.
	 */
	@Test
	public void brimhavenTicketCounterWordStaysOutOfTheName()
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN
			.matcher("Your Agility Arena Total Ticket count is: 480.");
		assertTrue(m.find());
		assertEquals("Agility Arena", m.group(1).trim());
		assertEquals("480", m.group(2));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies the timed-clear chat parsing against REAL in-game completion messages. These are the
 * fragile, game-version-specific bits — if Jagex changes a string, a test here goes red and tells
 * you exactly which activity's auto-detect broke (the site's manual time submit is the fallback).
 */
public class TimedClearParserTest
{
	@Test
	public void parsesDurationWithFractionalSeconds()
	{
		// Inferno
		assertEquals(Integer.valueOf(178), TimedClearParser.parseDurationSeconds("Duration: 2:58.03 (new personal best)"));
		// TzHaar-Ket-Rak's challenge
		assertEquals(Integer.valueOf(534), TimedClearParser.parseDurationSeconds("Challenge duration: 8:54.00 (new personal best)"));
		// Fortis Colosseum (final wave time)
		assertEquals(Integer.valueOf(2012), TimedClearParser.parseDurationSeconds("Wave 12 completed! Wave duration: 33:32.40"));
	}

	@Test
	public void parsesPlainDuration()
	{
		// Nightmare
		assertEquals(Integer.valueOf(1475), TimedClearParser.parseDurationSeconds("Team size: Solo Fight duration: 24:35 (new personal best)"));
		// Chambers of Xeric raid-complete message
		assertEquals(Integer.valueOf(939), TimedClearParser.parseDurationSeconds("Congratulations - your raid is complete! Duration: 15:39"));
	}

	@Test
	public void parsesHourLongDuration()
	{
		assertEquals(Integer.valueOf(3750), TimedClearParser.parseDurationSeconds("Theatre of Blood total completion time: 1:02:30"));
	}

	@Test
	public void parsesThreeDigitMinuteDurations()
	{
		// Slow Inferno/Zuk clears print raw minutes past 99 — real formats captured by RuneLite's
		// chat-commands tests: "Duration: 172:18. Personal best: 134:52".
		assertEquals(Integer.valueOf(10338), TimedClearParser.parseDurationSeconds("Duration: 172:18. Personal best: 134:52"));
		assertEquals(Integer.valueOf(6271), TimedClearParser.parseDurationSeconds("Duration: 104:31 (new personal best)"));
	}

	@Test
	public void parsesTimeColonFormats()
	{
		// Sailing Barracuda Trials
		assertEquals(Integer.valueOf(364), TimedClearParser.parseDurationSeconds("Time: 6:04.20 (new personal best)."));
		// Hallowed Sepulchre floor + overall lines
		assertEquals(Integer.valueOf(407), TimedClearParser.parseDurationSeconds("Floor 5 time: 6:47.40 (new personal best)"));
		assertEquals(Integer.valueOf(1599), TimedClearParser.parseDurationSeconds("Overall time: 26:39.20 (new personal best)"));
	}

	@Test
	public void usesRaidTotalTimeNotRoomOrChallengeSubTimes()
	{
		// The raid clear time is the "total completion time" line — accept it (ToA + ToB).
		assertEquals(Integer.valueOf(2090), TimedClearParser.parseDurationSeconds(
			"Tombs of Amascut: Expert Mode total completion time: 34:50. Personal best: 18:31"));
		assertEquals(Integer.valueOf(3750), TimedClearParser.parseDurationSeconds(
			"Theatre of Blood total completion time: 1:02:30"));
		// ToA sub-times must NOT parse — crediting the 7:05 final room let a 34:50 raid pass a
		// 25-minute tile. Reject the per-room, per-challenge, and rooms-only aggregate lines.
		assertNull(TimedClearParser.parseDurationSeconds("Challenge complete: The Wardens. Duration: 7:05"));
		assertNull(TimedClearParser.parseDurationSeconds("Challenge time: 10:23"));
		assertNull(TimedClearParser.parseDurationSeconds(
			"Tombs of Amascut: Expert Mode challenge completion time: 30:16. Personal best: 16:08"));
		// But "Challenge duration:" (Gauntlet / Corrupted Gauntlet / TzHaar-Ket-Rak) is a real
		// clear time and must still parse.
		assertEquals(Integer.valueOf(534), TimedClearParser.parseDurationSeconds("Challenge duration: 8:54.00 (new personal best)"));
		assertEquals(Integer.valueOf(624), TimedClearParser.parseDurationSeconds("Corrupted challenge duration: 10:24. Personal best: 7:59."));
	}

	@Test
	public void parsesTemporossSubduedFormat()
	{
		assertEquals(Integer.valueOf(392), TimedClearParser.parseDurationSeconds("Subdued in 6:32 (new personal best)."));
	}

	@Test
	public void ignoresMessagesWithoutADurationKeyword()
	{
		// A failed Inferno/TzHaar attempt carries a time but no "duration"/"completion time" keyword.
		assertNull(TimedClearParser.parseDurationSeconds("You survived for 1:16.80 but failed to kill any JalTok-Jads before perishing."));
		assertNull(TimedClearParser.parseDurationSeconds("Your TzKal-Zuk kill count is: 1."));
		assertNull(TimedClearParser.parseDurationSeconds(null));
		// Countdowns aren't clears: "time" without a fused colon must not parse.
		assertNull(TimedClearParser.parseDurationSeconds("Time remaining: 5:00"));
		// Clan broadcast carries the time after "personal best:" — no duration keyword.
		assertNull(TimedClearParser.parseDurationSeconds("Drenvox mdps has achieved a new Maggot King personal best: 1:19"));
	}

	@Test
	public void matchesBarracudaTrialIdentityLines()
	{
		// Specific-course tiles ride the plain fallback — both flanking lines name the course.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Gwenith Glide"));
		assertTrue(TimedClearParser.messageMatchesActivity(
			"You have completed the Gwenith Glide and achieved the Marlin rank.", "The Gwenith Glide"));
		// A generic any-trial tile matches every course via the signature table.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Barracuda Trials"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Tempor Tantrum completion count is: 3", "Barracuda Trials"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your Gwenith Glide completion count is: 49", "Tempor Tantrum"));
	}

	@Test
	public void matchesSepulchreRunsAndFloors()
	{
		// Full-run tiles: the "Overall time" exit line both carries the time and identifies the run.
		assertTrue(TimedClearParser.messageMatchesActivity("Overall time: 26:39.20 (new personal best)", "Hallowed Sepulchre"));
		assertFalse(TimedClearParser.messageMatchesActivity("Floor 5 time: 6:47.40 (new personal best)", "Hallowed Sepulchre"));
		// Floor tiles ride the fallback against the floor line itself.
		assertTrue(TimedClearParser.messageMatchesActivity("Floor 5 time: 6:47.40 (new personal best)", "Floor 5"));
	}

	@Test
	public void matchesActivityFromTheAdjacentIdentityLine()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your TzKal-Zuk kill count is: 1.", "Inferno"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Sol Heredit kill count is: 100.", "Fortis Colosseum"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Chambers of Xeric count is: 306.", "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Nightmare kill count is: 11.", "Nightmare"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completion count for TzHaar-Ket-Rak's Sixth Challenge is: 1.", "TzHaar-Ket-Rak"));
	}

	@Test
	public void doesNotCrossMatchUnrelatedActivities()
	{
		assertFalse(TimedClearParser.messageMatchesActivity("Your Sol Heredit kill count is: 100.", "Inferno"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your TzKal-Zuk kill count is: 1.", "Chambers of Xeric"));
	}

	@Test
	public void matchesArticledBossNamesAgainstArticleFreeKillCountLines()
	{
		// DT2-style bosses: the kill-count line drops the "The".
		assertTrue(TimedClearParser.messageMatchesActivity("Your Leviathan kill count is: 4.", "The Leviathan"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Whisperer kill count is: 12.", "The Whisperer"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Hueycoatl kill count is: 3.", "The Hueycoatl"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Royal Titans kill count is: 8.", "The Royal Titans"));
		// Article-free tile names ride the plain-substring fallback.
		assertTrue(TimedClearParser.messageMatchesActivity("Your Vardorvis kill count is: 20.", "Vardorvis"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Duke Sucellus kill count is: 7.", "Duke Sucellus"));
	}

	@Test
	public void nexOnlyMatchesItsKillCountLine()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your Nex kill count is: 51.", "Nex"));
		// "next" must not credit a Nex tile from an unrelated nearby line.
		assertFalse(TimedClearParser.messageMatchesActivity("The next wave will begin soon.", "Nex"));
	}

	@Test
	public void gauntletMatchesItsCompletionLineButNotCorrupted()
	{
		assertTrue(TimedClearParser.messageMatchesActivity("Your Gauntlet completion count is: 45.", "The Gauntlet"));
		assertFalse(TimedClearParser.messageMatchesActivity("Your Corrupted Gauntlet completion count is: 4.", "The Gauntlet"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your Corrupted Gauntlet completion count is: 4.", "Corrupted Gauntlet"));
	}

	@Test
	public void forgivingRaidModeSpellingsMatchTheModeCountLine()
	{
		// The game's CoX Challenge Mode count line carries NO colon. Admins type the mode a dozen
		// ways; every reasonable spelling must still match (colons/spacing folded, shorthands aliased).
		String coxCm = "Your completed Chambers of Xeric Challenge Mode count is: 1.";
		for (String activity : new String[] {
			"Chambers of Xeric Challenge Mode",
			"Chambers of Xeric: Challenge Mode",
			"chambers of xeric challenge mode",
			"CoX Challenge Mode",
			"CoX CM",
			"CoX: CM",
			"Chambers of Xeric CM",
		})
		{
			assertTrue(activity, TimedClearParser.messageMatchesActivity(coxCm, activity));
		}

		// ToB Hard Mode + ToA Expert Mode (which DO carry a colon in-game) — same tolerance.
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood: Hard Mode count is: 3.", "ToB HM"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood: Hard Mode count is: 3.", "Theatre of Blood Hard Mode"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Tombs of Amascut: Expert Mode count is: 2.", "ToA Expert"));
		assertTrue(TimedClearParser.messageMatchesActivity("Your completed Tombs of Amascut: Expert Mode count is: 2.", "ToA: Expert Mode"));
	}

	@Test
	public void modeTileNeverCreditsOffABaseClearButBaseMatchesEveryMode()
	{
		String coxBase = "Your completed Chambers of Xeric count is: 306.";
		String coxCm = "Your completed Chambers of Xeric Challenge Mode count is: 1.";

		// A CM tile must NOT complete off a normal Chambers clear (its line lacks "challenge mode").
		assertFalse(TimedClearParser.messageMatchesActivity(coxBase, "CoX CM"));
		assertFalse(TimedClearParser.messageMatchesActivity(coxBase, "Chambers of Xeric: Challenge Mode"));

		// A base Chambers tile keeps matching every harder mode (the mode line contains the base name).
		assertTrue(TimedClearParser.messageMatchesActivity(coxBase, "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity(coxCm, "Chambers of Xeric"));
		assertTrue(TimedClearParser.messageMatchesActivity(coxCm, "CoX"));

		// ToB Hard Mode tile likewise doesn't fire on a base Theatre clear.
		assertFalse(TimedClearParser.messageMatchesActivity("Your completed Theatre of Blood count is: 5.", "ToB HM"));
	}

	@Test
	public void formatsClock()
	{
		assertEquals("2:58", TimedClearParser.formatClock(178));
		assertEquals("0:09", TimedClearParser.formatClock(9));
		assertEquals("33:32", TimedClearParser.formatClock(2012));
	}
}

package com.anvil;

import javax.swing.plaf.basic.BasicHTML;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * §2/§6 — the Swing plain-text guard for federated strings. A {@link javax.swing.JLabel} renders as HTML when
 * its text begins with {@code <html}, so an untrusted clan/tile/activity name could inject markup;
 * {@link AnvilSidebarPanel#plainText(String)} (which every federated field routes through) must neutralize it.
 * The authoritative check is {@link BasicHTML#isHTMLString(String)} — exactly what the label UI uses; if it
 * returns {@code false} for our output, Swing renders verbatim (no markup, no injection).
 */
public class SidebarTextSafetyTest
{
	@Test
	public void htmlInjectedNameRendersAsLiteralText()
	{
		String injected = "<html><b>pwned</b><img src=x></html>";
		assertTrue("precondition: the raw string WOULD be treated as HTML by a JLabel",
			BasicHTML.isHTMLString(injected));

		String safe = AnvilSidebarPanel.plainText(injected);
		assertFalse("sanitized federated string must NOT be treated as HTML", BasicHTML.isHTMLString(safe));
		assertFalse("no live '<html' prefix survives", safe.toLowerCase().startsWith("<html"));
		assertTrue("the intended text is still visible (as literal, escaped markup)", safe.contains("pwned"));
	}

	@Test
	public void neutralizesLeadingWhitespaceAndMixedCase()
	{
		// A JLabel trims leading whitespace before its HTML sniff, and the tag match is case-insensitive.
		for (String injected : new String[] { "   <HTML>x</HTML>", "\t<Html><i>y</i>", "<html>" })
		{
			String safe = AnvilSidebarPanel.plainText(injected);
			assertFalse("‘" + injected + "’ must not render as HTML", BasicHTML.isHTMLString(safe));
		}
	}

	@Test
	public void ordinaryStringsPassThroughUnchanged()
	{
		assertEquals("Clan A", AnvilSidebarPanel.plainText("Clan A"));
		assertEquals("Any barrows item", AnvilSidebarPanel.plainText("Any barrows item"));
		assertEquals("You + Kayle", AnvilSidebarPanel.plainText("You + Kayle"));
		// A stray '<' that isn't the HTML trigger is left alone (JLabel wouldn't treat it as HTML either).
		assertEquals("<3 clan", AnvilSidebarPanel.plainText("<3 clan"));
		assertFalse(BasicHTML.isHTMLString(AnvilSidebarPanel.plainText("<3 clan")));
	}

	@Test
	public void nullBecomesEmpty()
	{
		assertEquals("", AnvilSidebarPanel.plainText(null));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Guards {@link BingoApiClient#normalizeBaseUrl} — the gate that decides which Site URL the plugin
 * trusts to carry the account token. Two jobs: (1) assume https:// when the user leaves the scheme
 * off (the common "your-clan.vercel.app" case, which otherwise looked unconfigured); (2) still refuse
 * a plaintext http:// host that isn't local, so the Bearer token never rides over the wire in clear.
 */
public class NormalizeBaseUrlTest
{
	@Test
	public void prependsHttpsWhenSchemeMissing()
	{
		assertEquals("https://your-clan.vercel.app", BingoApiClient.normalizeBaseUrl("your-clan.vercel.app"));
		// trailing slash + whitespace still cleaned, then scheme added
		assertEquals("https://your-clan.vercel.app", BingoApiClient.normalizeBaseUrl("  your-clan.vercel.app/  "));
	}

	@Test
	public void keepsExplicitHttps()
	{
		assertEquals("https://x.example.com", BingoApiClient.normalizeBaseUrl("https://x.example.com"));
		assertEquals("https://x.example.com", BingoApiClient.normalizeBaseUrl("https://x.example.com/"));
	}

	@Test
	public void rejectsNonLocalHttp()
	{
		// An explicit http:// host is NOT silently upgraded — it's left as http:// and the HTTPS gate
		// rejects it (returns "") so the token is never sent in clear to a remote plaintext host.
		assertEquals("", BingoApiClient.normalizeBaseUrl("http://evil.example.com"));
	}

	@Test
	public void permitsLocalHttpForDev()
	{
		assertEquals("http://localhost:3000", BingoApiClient.normalizeBaseUrl("http://localhost:3000"));
		assertEquals("http://127.0.0.1:3000", BingoApiClient.normalizeBaseUrl("http://127.0.0.1:3000/"));
	}

	@Test
	public void blankOrNullIsUnconfigured()
	{
		assertEquals("", BingoApiClient.normalizeBaseUrl(null));
		assertEquals("", BingoApiClient.normalizeBaseUrl("   "));
		assertEquals("", BingoApiClient.normalizeBaseUrl("/"));
	}
}

