package com.anvil;

import com.google.gson.Gson;
import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Provides;
import java.lang.reflect.Method;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import org.junit.Test;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards a failure that once made the plugin fail to load: a {@code @Provides} method reading a not-yet-injected
 * {@code this.}-field. Guice may invoke {@link AnvilPlugin#provideSidebarDataSource} before the plugin's own
 * {@code @Inject} fields are populated, so the provider must take its collaborators as PARAMETERS. This boots a
 * real injector, then invokes the real provider on an <em>uninjected</em> {@code new AnvilPlugin()} — the scenario
 * that used to NPE. A regression to {@code this.apiClient} throws here; dropping the param fails {@code getDeclaredMethod}.
 */
public class InjectionSmokeTest
{
	/** Binds just the two roots (Gson + OkHttp); everything else has an {@code @Inject} constructor. */
	private static Injector sidebarGraph()
	{
		return Guice.createInjector(new AbstractModule()
		{
			@Override
			protected void configure()
			{
				// All bindings are @Provides methods below; nothing to configure explicitly.
			}

			@Provides
			@Singleton
			Gson gson()
			{
				return new Gson();
			}

			@Provides
			@Singleton
			OkHttpClient okHttp()
			{
				return new OkHttpClient();
			}
		});
	}

	@Test
	public void sidebarGraphResolvesAndProviderTakesDepsAsParams() throws Exception
	{
		Injector inj = sidebarGraph();

		// The @Inject-constructor graph resolves under a real injector.
		BingoApiClient client = inj.getInstance(BingoApiClient.class);
		assertNotNull(client);

		// getDeclaredMethod fails if the provider drops a param; invoking on an uninjected plugin reproduces the bug.
		AnvilPlugin uninjectedPlugin = new AnvilPlugin();
		Method provider = AnvilPlugin.class.getDeclaredMethod(
			"provideSidebarDataSource", BingoApiClient.class, ScheduledExecutorService.class);
		provider.setAccessible(true);
		Object sds = provider.invoke(uninjectedPlugin, client, Executors.newSingleThreadScheduledExecutor());
		assertNotNull("provider must not read not-yet-injected this.-fields", sds);
		assertTrue(sds instanceof SidebarDataSource);

		// A resolved SidebarDataSource is usable straight away (single-home; unconfigured ⇒ empty).
		assertTrue(((SidebarDataSource) sds).fetchConnections().isEmpty());
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Luck / troll classification for drop posts — the difference between "spooned" and "finally".
 */
public class DropLuckTest
{
	private static final long BIG_VALUE = 50_000_000L;

	@Test
	public void obtainedShareFollowsTheDropRate()
	{
		// At exactly 1/rate kills, ~63% of players have it (1 - 1/e).
		assertEquals(0.632, DropLuck.obtainedShare(1.0 / 512, 512), 0.005);
		// A single kill at 1/512 is just the drop rate.
		assertEquals(1.0 / 512, DropLuck.obtainedShare(1.0 / 512, 1), 1e-9);
		// Missing inputs never blow up.
		assertEquals(0.0, DropLuck.obtainedShare(0, 100), 1e-9);
		assertEquals(0.0, DropLuck.obtainedShare(1.0 / 512, 0), 1e-9);
	}

	@Test
	public void earlyDropsAreSpoonedAndLongGrindsAreDry()
	{
		// 1/512 on the 20th kill: only ~4% of players are there yet.
		assertEquals(DropLuck.Verdict.SPOONED, DropLuck.classify(1.0 / 512, 20));
		// ~200 kills in: ahead of the pack, not miraculous.
		assertEquals(DropLuck.Verdict.LUCKY, DropLuck.classify(1.0 / 512, 200));
		// Around the drop rate: unremarkable.
		assertEquals(DropLuck.Verdict.TYPICAL, DropLuck.classify(1.0 / 512, 500));
		// Triple the rate: almost everyone had it by now.
		assertEquals(DropLuck.Verdict.DRY, DropLuck.classify(1.0 / 512, 1500));
	}

	@Test
	public void classifyNeedsBothARateAndAKillCount()
	{
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(null, 500));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, null));
		assertEquals(DropLuck.Verdict.UNKNOWN, DropLuck.classify(1.0 / 512, 0));
	}

	@Test
	public void luckLabelOnlySpeaksWhenThereIsSomethingToSay()
	{
		assertTrue(DropLuck.luckLabel(1.0 / 512, 20).startsWith("Top "));
		assertTrue(DropLuck.luckLabel(1.0 / 512, 20).endsWith("spooned"));
		assertTrue(DropLuck.luckLabel(1.0 / 512, 1500).startsWith("Dry"));
		assertNull("typical drops add no field", DropLuck.luckLabel(1.0 / 512, 500));
		assertNull("no kill count, no claim", DropLuck.luckLabel(1.0 / 512, null));
	}

	@Test
	public void trollsAreRareRollsOnWorthlessItems()
	{
		// A 1/10,000 roll on a ~35k item — the joke drop.
		assertTrue(DropLuck.isTrollDrop(1.0 / 10_000, 35_000, 10_000));
		// Same rarity, real money: just a rare drop.
		assertFalse(DropLuck.isTrollDrop(1.0 / 10_000, 5_000_000, 10_000));
		// Cheap but not rare enough to be funny — this is the herb spam we don't want.
		assertFalse(DropLuck.isTrollDrop(1.0 / 2_000, 5_000, 10_000));
		// Qualified on value alone (no rate known).
		assertFalse(DropLuck.isTrollDrop(null, 5_000, 10_000));
	}

	@Test
	public void earnedAwardsAreNeverCalledSpooned()
	{
		assertTrue(DropLuck.isEarnedAward("Infernal cape"));
		assertTrue(DropLuck.isEarnedAward("Dizana's quiver"));
		assertTrue(DropLuck.isEarnedAward("Fire cape"));
		assertFalse(DropLuck.isEarnedAward("Twisted bow"));

		// Even a 1-KC Inferno clear gets no "spooned" line — it was earned, not rolled.
		assertFalse(DropLuck.deservesSpoonLine("Infernal cape", 0, 1.0 / 1, 1, BIG_VALUE));
		// A genuine early roll does.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 20, BIG_VALUE));
		// A dry grind doesn't get called lucky just because the item is worth a lot... unless it's
		// worth *so* much that the drop is a moment on its own.
		assertTrue(DropLuck.deservesSpoonLine("Twisted bow", 1_000_000_000L, 1.0 / 512, 1500, BIG_VALUE));
		assertFalse(DropLuck.deservesSpoonLine("Dragon spear", 35_000, 1.0 / 512, 1500, BIG_VALUE));
		// No rate/KC to judge by: value decides.
		assertFalse(DropLuck.deservesSpoonLine("Rune platebody", 38_000, null, null, BIG_VALUE));
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * PB capture: correlating a time with the activity that earned it, and never letting a slower run
 * overwrite a record.
 *
 * <p>Both message orderings are tested because the game uses both — the Inferno prints its duration
 * before the kill count, most bosses print it after.
 */
public class PersonalBestsTest
{
	@Test
	public void killCountThenDuration()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 1_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void durationThenKillCount()
	{
		PersonalBests pbs = new PersonalBests();
		// The Inferno's ordering: the time lands with nothing to attach it to yet.
		assertFalse(pbs.onChatLine("Duration: 2:58.03 (new personal best)", 1_000));
		assertTrue(pbs.nextBatch().isEmpty());
		pbs.onActivitySeen("TzKal-Zuk", 1_200);
		assertEquals(Integer.valueOf(17803), pbs.nextBatch().get("tzkal-zuk"));
	}

	@Test
	public void aStaleActivityIsNotCredited()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		// Ten minutes later, an unrelated PB line must not be filed under Zulrah.
		assertFalse(pbs.onChatLine("Duration: 1:00 (new personal best)", 600_000));
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void anOrphanTimeExpiresRatherThanAttachingToTheNextBoss()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onChatLine("Duration: 1:00 (new personal best)", 0);
		// A different boss, long after: the loose time must not land on it.
		pbs.onActivitySeen("Vorkath", 600_000);
		assertTrue(pbs.nextBatch().isEmpty());
	}

	@Test
	public void onlyFasterTimesReplaceARecord()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Vorkath", 0);
		assertTrue(pbs.onChatLine("Fight duration: 1:30 (new personal best)", 10));
		pbs.onActivitySeen("Vorkath", 1_000);
		// A slower run reported as an explicit PB line still can't raise the record.
		assertFalse(pbs.onChatLine("Fight duration: 2:00. Personal best: 1:30.", 1_010));
		assertEquals(Integer.valueOf(9000), pbs.nextBatch().get("vorkath"));
		// A faster one does.
		pbs.onActivitySeen("Vorkath", 2_000);
		assertTrue(pbs.onChatLine("Fight duration: 1:12 (new personal best)", 2_010));
		assertEquals(Integer.valueOf(7200), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void seedingAdoptsOnlyImprovements()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);

		Map<String, Integer> imported = new HashMap<>();
		imported.put("Zulrah", 12000);  // slower than what we have — ignored
		imported.put("Vorkath", 8000);  // new — adopted
		assertEquals(1, pbs.seed(imported, 100));
		assertEquals(Integer.valueOf(9600), pbs.nextBatch().get("zulrah"));
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("vorkath"));
	}

	@Test
	public void flushWaitsForQuiet()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 1_000);
		assertFalse(pbs.isDue(1_000 + PersonalBests.QUIET_MS - 1));
		assertTrue(pbs.isDue(1_000 + PersonalBests.QUIET_MS));
	}

	@Test
	public void stateSurvivesARestartAndIsNotResent()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Chambers of Xeric: Challenge Mode", 0);
		pbs.onChatLine("Duration: 40:00 (new personal best)", 10);
		pbs.onSent(pbs.nextBatch());
		String state = pbs.serializeState();

		PersonalBests restarted = new PersonalBests();
		restarted.restoreState(state);
		assertEquals(1, restarted.knownCount());
		assertEquals(0, restarted.pendingCount());
		// A slower run after the restart is still not a record.
		restarted.onActivitySeen("Chambers of Xeric: Challenge Mode", 100);
		assertFalse(restarted.onChatLine("Duration: 45:00 (new personal best)", 110));
	}

	@Test
	public void anImprovementMidFlightStaysPending()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		pbs.onChatLine("Fight duration: 1:36 (new personal best)", 10);
		Map<String, Integer> inFlight = pbs.nextBatch();
		// A better time lands while the request is on the wire.
		pbs.onActivitySeen("Zulrah", 20);
		pbs.onChatLine("Fight duration: 1:20 (new personal best)", 30);
		pbs.onSent(inFlight);
		assertEquals(1, pbs.pendingCount());
		assertEquals(Integer.valueOf(8000), pbs.nextBatch().get("zulrah"));
	}

	@Test
	public void ordinaryChatCostsNothingAndRecordsNothing()
	{
		PersonalBests pbs = new PersonalBests();
		pbs.onActivitySeen("Zulrah", 0);
		assertFalse(pbs.onChatLine("Your Zulrah kill count is: 1,204.", 10));
		assertFalse(pbs.onChatLine("Oh dear, you are dead!", 20));
		assertNull(pbs.nextBatch().get("zulrah"));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * What the plugin says about its own setup.
 *
 * THE CASE THIS EXISTS FOR: nothing configured at all. It used to fall out of the comparison as
 * "both agree, so say nothing", which is right for a connected install and wrong for a fresh one —
 * and a fresh one is now the normal way in, since an Anvil account is a person's rather than a
 * clan's hand-me-down. The cap is the other half: it has to stop, and it has to stop across
 * restarts, or the nudge becomes the reason somebody removes the plugin.
 */
public class SetupNudgeTest
{
	@Test
	public void aFreshInstallIsToldWhereToGo()
	{
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide("", "", 0));
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide(null, null, 0));
		assertEquals("blank is empty, whitespace included", SetupNudge.Kind.FIRST_RUN,
			SetupNudge.decide("  ", "\t", 0));
	}

	@Test
	public void theFreshInstallLineStopsAfterTheCap()
	{
		assertEquals(SetupNudge.Kind.FIRST_RUN, SetupNudge.decide("", "", SetupNudge.FIRST_RUN_NUDGES - 1));
		assertEquals(SetupNudge.Kind.NONE, SetupNudge.decide("", "", SetupNudge.FIRST_RUN_NUDGES));
		assertEquals("a count from a mangled config never re-arms it", SetupNudge.Kind.NONE,
			SetupNudge.decide("", "", 99));
	}

	@Test
	public void aConnectedInstallIsLeftAlone()
	{
		assertEquals(SetupNudge.Kind.NONE, SetupNudge.decide(BingoApiClient.CANONICAL_SITE, "tok", 0));
		assertArrayEquals(new String[0], SetupNudge.lines(SetupNudge.Kind.NONE));
	}

	@Test
	public void halfConfiguredIsStillNamedAsTheErrorItIs()
	{
		// The cap does not apply to these: they are a misconfiguration the member created by filling
		// in one box, and they stay once-per-login the way they always were.
		assertEquals(SetupNudge.Kind.MISSING_TOKEN, SetupNudge.decide(BingoApiClient.CANONICAL_SITE, "", 99));
		assertEquals(SetupNudge.Kind.MISSING_URL, SetupNudge.decide("", "tok", 99));
	}

	@Test
	public void theFreshInstallLinesNameTheSiteAndTheButton()
	{
		String[] lines = SetupNudge.lines(SetupNudge.Kind.FIRST_RUN);
		assertEquals(2, lines.length);
		assertTrue("the instruction names the button that does it", lines[0].contains("Sign in with Discord"));
		assertTrue("the reason names where the account lives", lines[1].contains(SetupNudge.SITE_HOST));
		assertTrue("and that a clan is not a prerequisite", lines[1].contains("No clan needed"));
	}

	@Test
	public void theSiteHostIsTheAddressSignInWrites()
	{
		// One source of truth: the chat line and the button's destination cannot drift into naming
		// different sites.
		assertEquals("anvilosrs.com", SetupNudge.SITE_HOST);
		assertTrue(BingoApiClient.CANONICAL_SITE.endsWith(SetupNudge.SITE_HOST));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Reveal-policy plumbing (showdown / lucky draw / bounty events): the {@code "reveal"} activity
 * kind and the sidebar's "still hidden" one-liner ({@link AnvilSidebarDataSource#revealNote}).
 */
public class RevealModeTest
{
	@Test
	public void revealKindParsesFromWireAndOldKindsStillMap()
	{
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire("reveal"));
		assertEquals(ActivityEntry.Kind.REVEAL, ActivityEntry.Kind.fromWire(" Reveal "));
		assertEquals(ActivityEntry.Kind.COMPLETE, ActivityEntry.Kind.fromWire("complete"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("progress"));
		// Forward-compat contract: anything unknown stays a harmless progress row.
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire("mystery"));
		assertEquals(ActivityEntry.Kind.PROGRESS, ActivityEntry.Kind.fromWire(null));
	}

	@Test
	public void revealSummaryLeadsWithTheTile()
	{
		ActivityEntry e = new ActivityEntry("r42", "2026-07-24T18:00:00Z", null, 42, "500 Zulrah KC",
			ActivityEntry.Kind.REVEAL, 0, false);
		assertEquals("New tile revealed: 500 Zulrah KC", e.summary());
	}

	private static PluginConfigResponse.EventInfo event(String policy, int hidden, String nextAt)
	{
		PluginConfigResponse.EventInfo ev = new PluginConfigResponse.EventInfo();
		ev.revealPolicy = policy;
		ev.hiddenTileCount = hidden;
		ev.nextRevealAt = nextAt;
		return ev;
	}

	@Test
	public void revealNoteIsNullForClassicBoardsAndWhenNothingIsHidden()
	{
		assertNull(AnvilSidebarDataSource.revealNote(null));
		assertNull(AnvilSidebarDataSource.revealNote(event(null, 5, null)));
		assertNull(AnvilSidebarDataSource.revealNote(event("interval", 0, null)));
	}

	@Test
	public void revealNoteCountsTilesAndBounties()
	{
		String interval = AnvilSidebarDataSource.revealNote(
			event("interval", 4, java.time.Instant.now().plusSeconds(42 * 60 + 30).toString()));
		assertTrue(interval, interval.startsWith("4 tiles hidden"));
		assertTrue(interval, interval.contains("next in 42m"));

		String scheduledNoClock = AnvilSidebarDataSource.revealNote(event("scheduled", 1, null));
		assertEquals("1 tile hidden", scheduledNoClock);

		String bounty = AnvilSidebarDataSource.revealNote(event("bounty", 3, null));
		assertEquals("3 bounties left · next on claim", bounty);

		String lastBounty = AnvilSidebarDataSource.revealNote(event("bounty", 1, null));
		assertEquals("1 bounty left · next on claim", lastBounty);
	}

	@Test
	public void revealNoteHandlesImminentAndFarReveals()
	{
		String imminent = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds(10).toString()));
		assertTrue(imminent, imminent.endsWith("next any minute"));

		String hours = AnvilSidebarDataSource.revealNote(
			event("interval", 2, java.time.Instant.now().plusSeconds((3 * 60 + 10) * 60 + 30).toString()));
		assertTrue(hours, hours.contains("next in 3h 10m"));

		// Malformed server stamp → drop the clock, keep the count.
		String malformed = AnvilSidebarDataSource.revealNote(event("interval", 2, "not-a-time"));
		assertEquals("2 tiles hidden", malformed);
	}
}

package com.anvil;

import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The collection-log flush policy: what gets queued, what gets skipped, and what survives a restart.
 *
 * <p>The behaviour worth defending is the skipping. The game redraws a log page on every scroll and
 * tab click, so a sync that pushed what it saw would be hundreds of identical requests a session.
 */
public class ClogSyncTest
{
	private static ClogPage page(String name, int obtained, int... itemIds)
	{
		int[] quantities = new int[itemIds.length];
		java.util.Arrays.fill(quantities, 1);
		return new ClogPage(name, itemIds, quantities, obtained, 9, Collections.emptyMap());
	}

	@Test
	public void anUnchangedPageIsNeverQueuedTwice()
	{
		ClogSync sync = new ClogSync();
		assertTrue(sync.offer(page("Abyssal Sire", 2, 4151, 7979), 0));
		// The same page redrawn — scrolling, clicking away and back — is not news.
		assertFalse(sync.offer(page("Abyssal Sire", 2, 4151, 7979), 10));
		assertEquals(1, sync.pendingCount());
	}

	@Test
	public void aNewItemOnAPageRequeuesIt()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Abyssal Sire", 2, 4151, 7979), 0);
		sync.onSent(sync.nextBatch());
		assertEquals(0, sync.pendingCount());
		// Third item drops: same page, different contents, must go again.
		assertTrue(sync.offer(page("Abyssal Sire", 3, 4151, 7979, 13262), 100));
		assertEquals(1, sync.pendingCount());
	}

	@Test
	public void quantityChangesCount()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Abyssal Sire", 1, 4151), 0);
		sync.onSent(sync.nextBatch());
		int[] ids = {4151};
		int[] quantities = {2}; // second whip
		assertTrue(sync.offer(new ClogPage("Abyssal Sire", ids, quantities, 1, 9, Collections.emptyMap()), 100));
	}

	@Test
	public void flushWaitsForQuietThenGoes()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Zulrah", 1, 12345), 1_000);
		assertFalse("still browsing", sync.isDue(1_000 + ClogSync.QUIET_MS - 1));
		assertTrue("settled", sync.isDue(1_000 + ClogSync.QUIET_MS));
	}

	@Test
	public void aBigQueueGoesWithoutWaiting()
	{
		ClogSync sync = new ClogSync();
		for (int i = 0; i < ClogSync.BATCH_PAGES; i++)
		{
			sync.offer(page("Page " + i, 1, 100 + i), 0);
		}
		// A player paging through their whole log shouldn't sit behind the quiet timer.
		assertTrue(sync.isDue(1));
		assertEquals(ClogSync.BATCH_PAGES, sync.nextBatch().size());
	}

	@Test
	public void batchesAreCappedAndDrainAcrossPushes()
	{
		ClogSync sync = new ClogSync();
		for (int i = 0; i < ClogSync.BATCH_PAGES + 7; i++)
		{
			sync.offer(page("Page " + i, 1, 100 + i), 0);
		}
		List<ClogPage> first = sync.nextBatch();
		assertEquals(ClogSync.BATCH_PAGES, first.size());
		sync.onSent(first);
		assertEquals(7, sync.pendingCount());
	}

	@Test
	public void aFailedPushLeavesPagesQueued()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Vorkath", 1, 22106), 0);
		List<ClogPage> batch = sync.nextBatch();
		// onSent is only called on success, so a failure is simply not calling it.
		assertEquals(1, sync.pendingCount());
		sync.onSent(batch);
		assertEquals(0, sync.pendingCount());
	}

	@Test
	public void aPageThatChangesMidFlightStaysQueued()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Vorkath", 1, 22106), 0);
		List<ClogPage> inFlight = sync.nextBatch();
		// The drop lands while the request is on the wire.
		sync.offer(page("Vorkath", 2, 22106, 22109), 10);
		sync.onSent(inFlight);
		assertEquals("the newer version must still go", 1, sync.pendingCount());
	}

	@Test
	public void stateSurvivesARestartSoNothingIsResent()
	{
		ClogSync sync = new ClogSync();
		// A colon in the name is the case a naive "name:hash" format would corrupt.
		sync.offer(page("Chambers of Xeric: Challenge Mode", 1, 20851), 0);
		sync.onSent(sync.nextBatch());
		String state = sync.serializeState();

		ClogSync restarted = new ClogSync();
		restarted.restoreState(state);
		assertEquals(1, restarted.syncedPages());
		assertFalse("already synced before the restart",
			restarted.offer(page("Chambers of Xeric: Challenge Mode", 1, 20851), 100));
	}

	@Test
	public void malformedStateIsSkippedNotFatal()
	{
		ClogSync sync = new ClogSync();
		sync.restoreState("garbage\n|\nzzzz|Zulrah\n1a2b|Vorkath");
		assertEquals("only the valid line survives", 1, sync.syncedPages());
	}

	@Test
	public void resetForgetsTheAccount()
	{
		ClogSync sync = new ClogSync();
		sync.offer(page("Zulrah", 1, 12345), 0);
		sync.onSent(sync.nextBatch());
		sync.reset();
		assertEquals(0, sync.syncedPages());
		// The next account's identical page is new information, not a duplicate.
		assertTrue(sync.offer(page("Zulrah", 1, 12345), 100));
	}
}

package com.anvil;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * What a clip's caption is allowed to say it caught.
 *
 * <p>The behaviour worth defending is that the window belongs to the FOOTAGE, not to the moment the
 * file turned up. OBS writes a clip whenever it gets round to it — on a busy machine that can be
 * minutes after the hotkey — and the replay buffer holds the seconds BEFORE the press. So a caption
 * built when the file lands describes a stretch of time the clip doesn't contain: the player has
 * killed other things, walked to another boss, taken other drops. Every test here is a version of
 * that.
 */
public class ClipMomentsTest
{
	private static final int WINDOW_SECONDS = 30;

	@Test
	public void namesWhatHappenedInsideTheWindow()
	{
		ClipMoments moments = new ClipMoments();
		moments.record("💀 Zulrah kill 1,204");
		String summary = moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3);
		assertEquals("💀 Zulrah kill 1,204", summary);
	}

	@Test
	public void ignoresWhatHappenedAfterTheClipEnded()
	{
		// The whole bug, in one case: the clip was asked for, OBS took its time, and the player
		// carried on playing. Nothing they did afterwards is in the footage.
		// The clip was asked for ten minutes ago and OBS is only now handing us the file, so "now" and
		// "when the footage ended" are ten minutes apart. That gap is the entire bug, and a test that
		// puts the later moments in the FUTURE doesn't reproduce it — a now-anchored window excludes
		// those for the wrong reason and passes by accident.
		ClipMoments moments = new ClipMoments();
		long now = System.currentTimeMillis();
		long clipRequestedAt = now - 600_000L;
		moments.record("🐉 Vorkath kill 500", clipRequestedAt - 5_000L);

		// …ten minutes of other content, all of it already in the past by the time the file lands.
		moments.record("⚔️ Fighting Zulrah", clipRequestedAt + 60_000L);
		moments.record("💰 Tanzanite fang", now - 2_000L);

		String summary = moments.summarize(clipRequestedAt, WINDOW_SECONDS, 3);
		assertEquals("the caption must describe the clip, not the wait", "🐉 Vorkath kill 500", summary);
	}

	@Test
	public void ignoresWhatHappenedBeforeTheWindowOpened()
	{
		ClipMoments moments = new ClipMoments();
		long now = System.currentTimeMillis();
		// A kill from well before the buffer's start edge isn't in the footage either.
		moments.record("🐉 Vorkath kill 499", now);
		String summary = moments.summarize(now + (WINDOW_SECONDS * 1000L) + 60_000L, WINDOW_SECONDS, 3);
		assertNull(summary);
	}

	@Test
	public void survivesABusyWaitWithoutLosingTheMomentItNeeds()
	{
		// Eviction used to be "keep the newest 40", which a raid fills in well under the time OBS can
		// take to write a file — so the moment the clip was FOR got pushed out by moments that came
		// after it. Retention is by age now, so a long wait doesn't cost the caption.
		ClipMoments moments = new ClipMoments();
		long clipRequestedAt = System.currentTimeMillis();
		moments.record("🏆 Twisted bow", clipRequestedAt - 5_000L);
		for (int i = 0; i < 200; i++)
		{
			moments.record("⚔️ Lizardman shaman kill " + i, clipRequestedAt + 10_000L + i);
		}
		String summary = moments.summarize(clipRequestedAt, WINDOW_SECONDS, 3);
		assertEquals("🏆 Twisted bow", summary);
	}

	@Test
	public void collapsesRepeatsAndSummarisesTheRest()
	{
		ClipMoments moments = new ClipMoments();
		moments.record("⚔️ Goblin kill 1");
		moments.record("⚔️ Goblin kill 1"); // the game announces things more than once
		moments.record("💰 Dragon claws");
		moments.record("📕 New clog slot: Dragon claws");
		moments.record("🐾 Pet");
		String summary = moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 2);
		assertTrue("newest first", summary.startsWith("🐾 Pet"));
		assertTrue("names two then counts the rest", summary.endsWith("…and 2 more"));
	}

	@Test
	public void saysNothingWhenNothingHappened()
	{
		assertNull(new ClipMoments().summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3));
	}

	@Test
	public void blankMomentsAreNotMoments()
	{
		ClipMoments moments = new ClipMoments();
		moments.record(null);
		moments.record("   ");
		assertNull(moments.summarize(System.currentTimeMillis(), WINDOW_SECONDS, 3));
	}
}

package com.anvil;

import java.util.regex.Matcher;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Verifies the Jagex kill-count chat-line parsing that drives real-time boss-KC pushes, KC-line
 * kill crediting, and the KC shown on rare-drop posts. The captured boss name must exactly match
 * the server's trackedKcNames watch-list (after shared normalization), so counter words that vary
 * by activity ("completion", "chest", "success", …) and the "subdued"/"completed" prefixes must
 * never leak into it — the Gauntlet's "completion count" wording did exactly that and silently
 * killed its real-time tracking.
 */
public class KillCountLineTest
{
	/** Runs a line through the plugin's KC parse: [bossName, count], or null when it doesn't match. */
	private static String[] parse(String line)
	{
		Matcher m = AnvilPlugin.KILL_COUNT_PATTERN.matcher(line);
		if (!m.find())
		{
			return null;
		}
		return new String[]{m.group(1).trim(), m.group(2)};
	}

	@Test
	public void parsesPlainKillCount()
	{
		String[] r = parse("Your Leviathan kill count is: 42.");
		assertEquals("Leviathan", r[0]);
		assertEquals("42", r[1]);
	}

	@Test
	public void parsesRaidCompletedVariant()
	{
		String[] r = parse("Your completed Chambers of Xeric count is: 125.");
		assertEquals("Chambers of Xeric", r[0]);
		assertEquals("125", r[1]);
	}

	@Test
	public void parsesRaidModeVariantWithColon()
	{
		String[] r = parse("Your completed Tombs of Amascut: Expert Mode count is: 8.");
		assertEquals("Tombs of Amascut: Expert Mode", r[0]);
		assertEquals("8", r[1]);
	}

	@Test
	public void completionCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Gauntlet completion count is: 15.");
		assertEquals("Gauntlet", r[0]);
		assertEquals("15", r[1]);
	}

	@Test
	public void corruptedGauntletCompletionVariant()
	{
		String[] r = parse("Your Corrupted Gauntlet completion count is: 3.");
		assertEquals("Corrupted Gauntlet", r[0]);
		assertEquals("3", r[1]);
	}

	@Test
	public void subduedPrefixStaysOutOfName()
	{
		String[] r = parse("Your subdued Wintertodt count is: 200.");
		assertEquals("Wintertodt", r[0]);
		assertEquals("200", r[1]);
	}

	@Test
	public void chestCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Barrows chest count is: 310.");
		assertEquals("Barrows", r[0]);
		assertEquals("310", r[1]);
	}

	@Test
	public void successCounterWordStaysOutOfName()
	{
		String[] r = parse("Your Zalcano success count is: 61.");
		assertEquals("Zalcano", r[0]);
		assertEquals("61", r[1]);
	}

	@Test
	public void parsesThousandsSeparators()
	{
		String[] r = parse("Your Zulrah kill count is: 1,250.");
		assertEquals("Zulrah", r[0]);
		assertEquals("1,250", r[1]);
	}

	/**
	 * Agility-lap tiles are kill tiles whose targets are course names, so the whole kind rests on
	 * the "lap" counter word staying out of the captured name. A course whose name reaches the
	 * index as "Ardougne Rooftop lap" matches nothing and the tile counts zero for a whole event.
	 */
	@Test
	public void lapCounterWordStaysOutOfCourseName()
	{
		String[] r = parse("Your Gnome Stronghold Agility lap count is: 1.");
		assertEquals("Gnome Stronghold Agility", r[0]);
		assertEquals("1", r[1]);
	}

	@Test
	public void parsesRooftopLapCountWithApostropheAndThousands()
	{
		String[] r = parse("Your Seers' Village Rooftop lap count is: 1,234.");
		assertEquals("Seers' Village Rooftop", r[0]);
		assertEquals("1,234", r[1]);
	}

	/** The Colossal Wyrm courses parenthesise their tier — the brackets are part of the name. */
	@Test
	public void parsesParenthesisedCourseTier()
	{
		String[] r = parse("Your Colossal Wyrm Agility Course (Advanced) lap count is: 5.");
		assertEquals("Colossal Wyrm Agility Course (Advanced)", r[0]);
		assertEquals("5", r[1]);
	}

	@Test
	public void ignoresUnrelatedChat()
	{
		assertNull(parse("Your heart is racing."));
	}
}

package com.anvil;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Rank titles go out in clan posts, where a wrong one gets repeated — and the Gilded cutoff is a
 * moving target, so it gets its own coverage.
 */
public class ClogRankTest
{
	/** Slots in the log as of writing. Only used to place Gilded; the rest are fixed cutoffs. */
	private static final int TOTAL = 1712;

	@Test
	public void fixedRanksTakeTheHighestThresholdReached()
	{
		assertEquals("Bronze", ClogRank.forSlots(100, TOTAL));
		assertEquals("Bronze", ClogRank.forSlots(299, TOTAL));
		assertEquals("Iron", ClogRank.forSlots(300, TOTAL));
		assertEquals("Steel", ClogRank.forSlots(613, TOTAL));
		assertEquals("Black", ClogRank.forSlots(855, TOTAL));
		assertEquals("Mithril", ClogRank.forSlots(900, TOTAL));
		assertEquals("Adamant", ClogRank.forSlots(1000, TOTAL));
		assertEquals("Rune", ClogRank.forSlots(1100, TOTAL));
		assertEquals("Dragon", ClogRank.forSlots(1200, TOTAL));
	}

	/** Below the first cutoff, and on an unreadable count, there is no rank to report. */
	@Test
	public void noRankIsBetterThanAWrongOne()
	{
		assertNull(ClogRank.forSlots(99, TOTAL));
		assertNull(ClogRank.forSlots(0, TOTAL));
		assertNull(ClogRank.forSlots(-1, TOTAL));
	}

	/**
	 * Gilded is 90% of the log's total slots rounded down to the nearest 25 — a proportion, not a
	 * number, so it shifts every time slots are added. At 1712 slots that lands on 1525.
	 */
	@Test
	public void gildedTracksTheLogsTotalSize()
	{
		assertEquals(1525, ClogRank.gildedThreshold(1712));
		assertEquals("Dragon", ClogRank.forSlots(1524, TOTAL));
		assertEquals("Gilded", ClogRank.forSlots(1525, TOTAL));
		assertEquals("Gilded", ClogRank.forSlots(1712, TOTAL));

		// A later expansion moves the bar: 2000 slots → 90% = 1800 → already a multiple of 25.
		assertEquals(1800, ClogRank.gildedThreshold(2000));
		assertEquals("Dragon", ClogRank.forSlots(1799, 2000));
		assertEquals("Gilded", ClogRank.forSlots(1800, 2000));
	}

	/** Without a readable total, Gilded is unreachable rather than wrongly awarded to everyone. */
	@Test
	public void anUnknownTotalNeverAwardsGilded()
	{
		assertEquals("Dragon", ClogRank.forSlots(1600, 0));
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * The account's best times, kept locally and pushed to the clan site.
 *
 * <p>Two ways in, because neither alone is enough:
 * <ul>
 *   <li><b>Live</b> — the completion messages the plugin already reads for timed tiles also carry
 *       "(new personal best)" / "Personal best: 7:59". Free: no extra chat parsing, and no waiting.</li>
 *   <li><b>Seed</b> — RuneLite's own chat-commands plugin has been recording these into its config
 *       for years. Importing that once turns a blank profile into a complete one on first login,
 *       which is what makes this feel like a sync rather than a slow accrual. The plugin reads it;
 *       this class only receives the numbers ({@link #seed}).</li>
 * </ul>
 *
 * <p>Times are centiseconds — the game separates runs by hundredths and so should a leaderboard.
 *
 * <p>The activity is supplied by the caller from the "Your X kill count is: N" line it already
 * parses, so a PB costs no additional regex on the chat hot path. Correlation works in both
 * directions because the game is inconsistent about ordering: the Inferno prints the duration
 * before the kill count, most bosses print it after.
 *
 * <p>RuneLite-free, so the correlation and flush rules are unit-testable without a client.
 */
final class PersonalBests
{
	/** How long a kill-count line and a duration line can be apart and still be the same kill. */
	static final long CORRELATION_MS = 6_000;
	/** Settle time before a push — a raid prints several lines at once. */
	static final long QUIET_MS = 3_000;

	/** Best known time per activity, keyed lowercase. Lower is better; that's the whole model. */
	private final Map<String, Integer> best = new HashMap<>();
	/** What the server already has, so an unchanged PB is never re-sent. */
	private final Map<String, Integer> sent = new HashMap<>();
	/** Activities whose best has moved since the last successful push. */
	private final Set<String> dirty = new LinkedHashSet<>();

	/** The most recent activity name from a kill-count line, and when we saw it. */
	private String recentActivity;
	private long recentActivityAt;
	/** A PB that arrived before its activity did (Inferno ordering), awaiting a name. */
	private int orphanCentis;
	private long orphanAt;

	private long lastChangeAt;

	/** The activity a kill-count line just named. Cheap: two field writes, no parsing. */
	void onActivitySeen(String activity, long now)
	{
		if (activity == null || activity.isEmpty())
		{
			return;
		}
		recentActivity = activity.toLowerCase();
		recentActivityAt = now;
		// A duration that arrived first now has its name.
		if (orphanCentis > 0 && now - orphanAt <= CORRELATION_MS)
		{
			record(recentActivity, orphanCentis, now);
			orphanCentis = 0;
		}
	}

	/**
	 * Offer a chat line. Returns true when it produced a new best.
	 *
	 * <p>Lines with no personal best in them cost one {@code indexOf} — this runs on every line of
	 * chat, so the negative path is the one that has to be free.
	 */
	boolean onChatLine(String message, long now)
	{
		Integer centis = PersonalBestParser.parseCentis(message);
		if (centis == null)
		{
			return false;
		}
		if (recentActivity != null && now - recentActivityAt <= CORRELATION_MS)
		{
			return record(recentActivity, centis, now);
		}
		// No name yet — hold it for the kill-count line that's about to arrive.
		orphanCentis = centis;
		orphanAt = now;
		return false;
	}

	/**
	 * Import times recorded by another source (RuneLite's chat-commands store).
	 *
	 * @return how many were adopted as new bests
	 */
	int seed(Map<String, Integer> centisByActivity, long now)
	{
		if (centisByActivity == null || centisByActivity.isEmpty())
		{
			return 0;
		}
		int adopted = 0;
		for (Map.Entry<String, Integer> e : centisByActivity.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			if (record(e.getKey().toLowerCase(), e.getValue(), now))
			{
				adopted++;
			}
		}
		return adopted;
	}

	/** Keep the fastest. A PB only ever goes down, so a slower number is noise, not an update. */
	private boolean record(String activity, int centis, long now)
	{
		if (activity == null || activity.isEmpty() || centis <= 0)
		{
			return false;
		}
		Integer current = best.get(activity);
		if (current != null && current <= centis)
		{
			return false;
		}
		best.put(activity, centis);
		dirty.add(activity);
		lastChangeAt = now;
		return true;
	}

	boolean isDue(long now)
	{
		return !dirty.isEmpty() && now - lastChangeAt >= QUIET_MS;
	}

	/** The pending bests, activity → centiseconds. */
	Map<String, Integer> nextBatch()
	{
		Map<String, Integer> batch = new LinkedHashMap<>(dirty.size());
		for (String activity : dirty)
		{
			Integer centis = best.get(activity);
			if (centis != null)
			{
				batch.put(activity, centis);
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Anything that improved again mid-flight stays dirty, so the better
	 * time is sent next round rather than being silently dropped.
	 */
	void onSent(Map<String, Integer> batch)
	{
		for (Map.Entry<String, Integer> e : batch.entrySet())
		{
			sent.put(e.getKey(), e.getValue());
			Integer current = best.get(e.getKey());
			if (current != null && current.equals(e.getValue()))
			{
				dirty.remove(e.getKey());
			}
		}
	}

	int knownCount()
	{
		return best.size();
	}

	int pendingCount()
	{
		return dirty.size();
	}

	/** Forget everything — the next account's bests are not this one's. */
	void reset()
	{
		best.clear();
		sent.clear();
		dirty.clear();
		recentActivity = null;
		orphanCentis = 0;
		lastChangeAt = 0;
	}

	/**
	 * The delivered bests as one config string: {@code <centis>|<activity>} per line.
	 *
	 * <p>Value first for the same reason as the collection log's state: activity names contain
	 * colons and spaces, an integer can't contain a pipe, so the parse needs no escaping.
	 */
	String serializeState()
	{
		StringBuilder out = new StringBuilder(sent.size() * 20);
		for (Map.Entry<String, Integer> e : sent.entrySet())
		{
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('\n');
			}
			out.append(e.getValue()).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/**
	 * Restore delivered state. These count as known bests too — otherwise every login would re-push
	 * the whole set to tell the server what it already stored.
	 */
	void restoreState(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		for (String line : raw.split("\n"))
		{
			int pipe = line.indexOf('|');
			if (pipe <= 0 || pipe == line.length() - 1)
			{
				continue;
			}
			try
			{
				int centis = Integer.parseInt(line.substring(0, pipe));
				String activity = line.substring(pipe + 1);
				if (centis > 0)
				{
					sent.put(activity, centis);
					Integer current = best.get(activity);
					if (current == null || current > centis)
					{
						best.put(activity, centis);
					}
				}
			}
			catch (NumberFormatException e)
			{
				// Truncated or hand-edited: drop the line and let the next kill re-establish it.
			}
		}
	}
}

