import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One collection-log page as the game drew it: the entry name, every item the account has obtained
 * on it, and the counters the log prints under the title ("Abyssal Sire kills: 1,204").
 *
 * <p>Deliberately RuneLite-free so the accumulator and its tests never need a client. Reading the
 * widgets is {@link ClogPageReader}'s job; deciding what to send is {@link ClogSync}'s.
 *
 * <p><b>Only obtained items are carried.</b> The site already ships the full 1,712-item catalogue
 * (src/data/clog.json), so the missing half is derivable — sending it would double every payload to
 * say "still nothing here".
 */
final class ClogPage
{
	/** Entry title as the log prints it — "Abyssal Sire". The site maps it to its own page id. */
	final String name;
	/** Obtained item ids, in the order the log lists them. Parallel to {@link #quantities}. */
	final int[] itemIds;
	final int[] quantities;
	/** The log's own "Obtained: 5/9" pair — the site shows progress without owning the catalogue. */
	final int obtained;
	final int total;
	/** The counter lines under the title, label → value. Empty for pages that print none. */
	final Map<String, Integer> counts;
	/** 64-bit content hash — what makes "has this page changed?" a comparison, not a diff. */
	final long hash;

	ClogPage(String name, int[] itemIds, int[] quantities, int obtained, int total, Map<String, Integer> counts)
	{
		this.name = name;
		this.itemIds = itemIds;
		this.quantities = quantities;
		this.obtained = obtained;
		this.total = total;
		this.counts = counts == null || counts.isEmpty()
			? Collections.emptyMap()
			: Collections.unmodifiableMap(new LinkedHashMap<>(counts));
		this.hash = computeHash();
	}

	/**
	 * FNV-1a over the page's contents.
	 *
	 * <p>Hand-rolled rather than {@code Objects.hash} / a JSON round-trip because this runs on the
	 * client thread every time the log redraws — which is every keystroke while a player scrolls the
	 * log. No boxing, no allocation, no string building; a page is folded in a few hundred nanoseconds
	 * and the result is what stops us re-sending 125 identical pages.
	 */
	private long computeHash()
	{
		long h = 0xcbf29ce484222325L;
		h = fold(h, name == null ? 0 : name.hashCode());
		h = fold(h, obtained);
		h = fold(h, total);
		for (int i = 0; i < itemIds.length; i++)
		{
			h = fold(h, itemIds[i]);
			h = fold(h, quantities[i]);
		}
		for (Map.Entry<String, Integer> e : counts.entrySet())
		{
			h = fold(h, e.getKey().hashCode());
			h = fold(h, e.getValue());
		}
		return h;
	}

	private static long fold(long h, int value)
	{
		h ^= value;
		return h * 0x100000001b3L;
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Decides what of the collection log is worth sending, and when.
 *
 * <p>The game redraws a log page on every scroll, filter and tab click, so the naive "push what's on
 * screen" would be hundreds of identical requests per session. This keeps a hash per page and only
 * queues one that actually changed, then batches the queue behind a quiet period.
 *
 * <p>The hashes of pages we've already sent are persisted (see {@link #serializeState}), so logging
 * back in and opening the log doesn't re-send a log that hasn't moved. That's the difference between
 * a sync that costs one request a week and one that costs a request a minute forever.
 *
 * <p>RuneLite-free on purpose: the flush policy is the part with edge cases, and this way it's
 * unit-testable without a client. The plugin owns the widget hook, the scheduler and the HTTP.
 */
final class ClogSync
{
	/** Wait this long after the last change before sending — a player paging through settles first. */
	static final long QUIET_MS = 2_500;
	/** Send at most this many pages per request; a full first sync becomes a handful of them. */
	static final int BATCH_PAGES = 25;
	/** Queue this many and go early — a bulk sync shouldn't sit waiting on the quiet timer. */
	private static final int EAGER_AT = BATCH_PAGES;

	/** Last hash we successfully sent, per page name. The persisted half of the state. */
	private final Map<String, Long> sent = new HashMap<>();
	/** Changed pages awaiting a push, newest write wins. Insertion-ordered so batches are stable. */
	private final Map<String, ClogPage> pending = new LinkedHashMap<>();

	private long lastChangeAt;
	private boolean stateLoaded;

	/**
	 * Offer the page currently on screen. Cheap and idempotent — the common case is a hash compare
	 * against what we already sent, and no allocation at all.
	 *
	 * @return true when the page was queued (i.e. it's new or changed)
	 */
	boolean offer(ClogPage page, long now)
	{
		if (page == null || page.name == null || page.name.isEmpty())
		{
			return false;
		}
		Long alreadySent = sent.get(page.name);
		if (alreadySent != null && alreadySent == page.hash)
		{
			return false;
		}
		ClogPage queued = pending.get(page.name);
		if (queued != null && queued.hash == page.hash)
		{
			return false;
		}
		pending.put(page.name, page);
		lastChangeAt = now;
		return true;
	}

	/** Whether a flush should run now: the queue has settled, or it's big enough to go early. */
	boolean isDue(long now)
	{
		if (pending.isEmpty())
		{
			return false;
		}
		return pending.size() >= EAGER_AT || now - lastChangeAt >= QUIET_MS;
	}

	/** Pages to send in the next request, oldest first. Does NOT clear them — see {@link #onSent}. */
	List<ClogPage> nextBatch()
	{
		List<ClogPage> batch = new ArrayList<>(Math.min(BATCH_PAGES, pending.size()));
		for (ClogPage page : pending.values())
		{
			batch.add(page);
			if (batch.size() >= BATCH_PAGES)
			{
				break;
			}
		}
		return batch;
	}

	/**
	 * Mark a batch delivered. Only called after the server has accepted it, so a failed push leaves
	 * the pages queued and the next flush retries them — no bookkeeping, no lost pages.
	 */
	void onSent(Collection<ClogPage> batch)
	{
		for (ClogPage page : batch)
		{
			ClogPage queued = pending.get(page.name);
			// Left queued if it changed again while the request was in flight.
			if (queued != null && queued.hash == page.hash)
			{
				pending.remove(page.name);
			}
			sent.put(page.name, page.hash);
		}
	}

	int pendingCount()
	{
		return pending.size();
	}

	/** How many distinct pages we've delivered — the numerator of the "68% synced" nudge. */
	int syncedPages()
	{
		return sent.size();
	}

	boolean hasState()
	{
		return stateLoaded;
	}

	/** Forget everything. Called when the account changes — one player's log is not another's. */
	void reset()
	{
		sent.clear();
		pending.clear();
		lastChangeAt = 0;
		stateLoaded = false;
	}

	/**
	 * The sent-hash map as one config string: {@code <hex hash>|<page name>} per line.
	 *
	 * <p>Hash first, split on the first pipe: page names contain colons ("Chambers of Xeric:
	 * Challenge Mode") and spaces, so a name-first format would need escaping. A hex hash can't
	 * contain a pipe, which makes the parse total.
	 */
	String serializeState()
	{
		StringBuilder out = new StringBuilder(sent.size() * 24);
		for (Map.Entry<String, Long> e : sent.entrySet())
		{
			if (e.getKey() == null || e.getKey().indexOf('\n') >= 0)
			{
				continue;
			}
			if (out.length() > 0)
			{
				out.append('\n');
			}
			out.append(Long.toHexString(e.getValue())).append('|').append(e.getKey());
		}
		return out.toString();
	}

	/** Restore from {@link #serializeState}. Junk lines are skipped, never fatal. */
	void restoreState(String raw)
	{
		sent.clear();
		stateLoaded = true;
		if (raw == null || raw.isEmpty())
		{
			return;
		}
		for (String line : raw.split("\n"))
		{
			int pipe = line.indexOf('|');
			if (pipe <= 0 || pipe == line.length() - 1)
			{
				continue;
			}
			try
			{
				sent.put(line.substring(pipe + 1), Long.parseUnsignedLong(line.substring(0, pipe), 16));
			}
			catch (NumberFormatException e)
			{
				// A truncated or hand-edited config line: drop it and re-sync that page.
			}
		}
	}
}

package com.anvil;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.RuneLite;
import net.runelite.client.util.Filepath;

/**
 * One-click support export: a diagnostic header plus the Anvil-relevant slice of RuneLite's
 * client.log, written to a shareable .txt in the plugin's own {@code debug/} folder with its path on
 * the clipboard, so "my drop never submitted" arrives with the stack trace already attached.
 *
 * <p>THE USER HANDS US THE LOG. {@code .runelite/logs/client.log} belongs to RuneLite, and a
 * {@link Filepath} cannot escape the directory it is rooted at — so the plugin cannot open it on its
 * own, and does not try. It asks: a file picker, and the file the user chooses is the one we read.
 * That is what {@link Filepath.Chooser} exists for, and it was confirmed acceptable on the hub
 * review for exactly this.
 *
 * <p>THE PICKER CANNOT BE PRE-POINTED: a plugin may only turn its own directory, or what the user
 * picks, into a Filepath, so the logs folder is named in the dialog title and copied to the clipboard
 * instead of opened.
 * {@code setCurrentDirectory} only accepts a Filepath, and the plugin can only name its own folder
 * without it. It is used for nothing but the dialog's starting folder: the plugin still reads only
 * the file the user picks. Pre-pointing was agreed on the hub review, and the packager's
 * disallowed-API list does not cover Filepath at all — the file rule is a review rule, and this is
 * what the reviewer approved.
 *
 * <p>Cancelling is fine: the header still exports, and says the log was not included so whoever
 * reads it knows to ask. All file work runs off the client thread by the caller; the dialog itself
 * is marshalled onto the Swing thread here.
 */
@Slf4j
@Singleton
public class DebugLogExporter
{
	private static final DateTimeFormatter FILE_TS = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	// Read at most the tail of client.log — the file can be many MB across a long session and only the
	// recent end is relevant to a just-now problem.
	private static final int MAX_LOG_TAIL_BYTES = 512 * 1024;
	// Keep the raw tail bounded so the bundle stays small enough to share easily.
	private static final int RAW_TAIL_LINES = 200;

	private final Client client;

	/** The plugin's own `debug/` folder, handed over by AnvilPlugin at startUp. Null = no export. */
	private volatile Filepath root;

	@Inject
	public DebugLogExporter(Client client)
	{
		this.client = client;
	}

	public static class Result
	{
		/** Where it landed, as text — the same string that went on the clipboard. */
		public final String path;
		/** Whether the user picked a log, so the chat message can say what the file contains. */
		public final boolean logIncluded;

		Result(String path, boolean logIncluded)
		{
			this.path = path;
			this.logIncluded = logIncluded;
		}
	}

	public void setRoot(Filepath debugDir)
	{
		this.root = debugDir;
	}

	/**
	 * Ask for the log, write the bundle, copy its path. Never throws — on failure it returns null and
	 * logs, so the caller can show a friendly fallback message. Must NOT be called on the Swing thread:
	 * it blocks there until the user answers the picker.
	 */
	public Result export(String header)
	{
		Filepath dir = root;
		if (dir == null)
		{
			log.warn("Anvil: no plugin directory, cannot export a debug log");
			return null;
		}
		try
		{
			if (!dir.exists())
			{
				dir.createDirectories();
			}

			List<String> anvilLines = new ArrayList<>();
			List<String> rawTail = new ArrayList<>();
			Filepath chosen = pickClientLog();
			boolean logRead = chosen != null && readLogTail(chosen, anvilLines, rawTail);

			String nl = System.lineSeparator();
			StringBuilder sb = new StringBuilder();
			sb.append(header).append(nl).append(nl);

			if (!logRead)
			{
				// Said rather than left as an absence, because the person reading this file is a clan
				// admin wondering where the stack trace went.
				sb.append("=== Client log ===").append(nl);
				sb.append(chosen == null
					? "Not included — no log was picked. Attach .runelite/logs/client.log yourself if this is a crash."
					: "Not included — the chosen file could not be read.").append(nl);
			}
			else
			{
				sb.append("=== Anvil log lines (").append(anvilLines.size()).append(") ===").append(nl);
				if (anvilLines.isEmpty())
				{
					sb.append("(no Anvil lines in the recent log — the action may not have run, or logs rotated)")
						.append(nl);
				}
				for (String l : anvilLines)
				{
					sb.append(l).append(nl);
				}
				sb.append(nl).append("=== Recent client.log tail (last ").append(rawTail.size())
					.append(" lines) ===").append(nl);
				for (String l : rawTail)
				{
					sb.append(l).append(nl);
				}
			}

			Filepath out = dir.joinSegment("anvil-debug-" + LocalDateTime.now().format(FILE_TS) + ".txt");
			out.write(sb.toString());

			String path = out.toString();
			Clipboards.copy(path);

			log.info("Anvil: exported debug log to {} (client log {})", path, logRead ? "included" : "omitted");
			return new Result(path, logRead);
		}
		catch (Exception e)
		{
			log.warn("Anvil: debug log export failed: {}", e.getMessage());
			return null;
		}
	}

	/**
	 * Show the picker on the Swing thread and wait for an answer. Null when the user cancels, or when
	 * the dialog could not be shown — either way the export carries on without the log.
	 */
	private Filepath pickClientLog()
	{
		AtomicReference<Filepath> picked = new AtomicReference<>();
		// The folder is NAMED rather than opened. A plugin gets a Filepath from exactly two places —
		// its own directory, and what the user picks here — so pointing the dialog at RuneLite's logs
		// folder needs Filepath.Unchecked, which the hub review rules out. Saying where it is, and
		// putting the path on the clipboard, is what is left: most file dialogs take a pasted path
		// (Ctrl+L on GTK, straight into the name box on Windows).
		String logsPath = logsPath();
		Clipboards.copy(logsPath);
		Runnable show = () ->
		{
			Filepath.Chooser chooser = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsFiles()
				.setDialogTitle("Pick client.log — it lives in " + logsPath + " (path copied, paste it in)")
				.addExtensionFilter("RuneLite log", "log");
			List<Filepath> result = chooser.showDialog(client);
			if (result != null && !result.isEmpty())
			{
				picked.set(result.get(0));
			}
		};
		try
		{
			if (SwingUtilities.isEventDispatchThread())
			{
				show.run();
			}
			else
			{
				SwingUtilities.invokeAndWait(show);
			}
		}
		catch (Exception e)
		{
			log.warn("Anvil: could not show the log picker: {}", e.getMessage());
			return null;
		}
		return picked.get();
	}

	/**
	 * Where RuneLite keeps its logs, as TEXT to tell the user — never as something to open.
	 *
	 * <p>No file is touched here: this reads the path RuneLite already holds and hands it back as a
	 * string. Turning it into a Filepath would take Unchecked, which is exactly what the hub review
	 * ruled out, and the file still arrives the sanctioned way — the user picks it.</p>
	 */
	private String logsPath()
	{
		try
		{
			return RuneLite.LOGS_DIR.getAbsolutePath();
		}
		catch (RuntimeException e)
		{
			log.debug("Anvil: could not name the logs folder: {}", e.getMessage());
			return "your .runelite/logs folder";
		}
	}

	/**
	 * Reads the tail of the chosen log into {@code rawTail} (last {@link #RAW_TAIL_LINES}) and every
	 * Anvil-related line into {@code anvilLines}. Matching on "anvil" catches the logger name
	 * (com.anvil.*) that logback prefixes onto every plugin log line. False if it could not be read.
	 *
	 * <p>A FileChannel rather than reading the whole file: a long session's log runs to many MB, and
	 * only the recent end is about a just-now problem.
	 */
	private boolean readLogTail(Filepath logFile, List<String> anvilLines, List<String> rawTail)
	{
		try (FileChannel ch = logFile.openFileChannel())
		{
			long len = ch.size();
			long from = Math.max(0, len - MAX_LOG_TAIL_BYTES);
			ByteBuffer buf = ByteBuffer.allocate((int) (len - from));
			ch.position(from);
			while (buf.hasRemaining() && ch.read(buf) > 0)
			{
				// read until the tail is full or the file ends
			}
			String text = new String(buf.array(), 0, buf.position(), StandardCharsets.UTF_8);
			// If we started mid-file, drop the first partial line.
			if (from > 0)
			{
				int firstNl = text.indexOf('\n');
				if (firstNl >= 0)
				{
					text = text.substring(firstNl + 1);
				}
			}
			String[] lines = text.split("\r?\n");
			for (String line : lines)
			{
				if (line.toLowerCase().contains("anvil"))
				{
					anvilLines.add(line);
				}
			}
			int start = Math.max(0, lines.length - RAW_TAIL_LINES);
			for (int i = start; i < lines.length; i++)
			{
				rawTail.add(lines[i]);
			}
			return true;
		}
		catch (IOException e)
		{
			log.warn("Anvil: could not read the chosen log: {}", e.getMessage());
			return false;
		}
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class PluginConfigResponse
{
	/**
	 * Version/capability handshake, sent by sites ≥ v1.0.0 on every /config shape. Null on
	 * older sites — {@link #serverSupports(String)} treats that as the v1.0.0 baseline set,
	 * never as "supports nothing". Contract: docs/PLUGIN_WIRE.md in the anvil site repo.
	 */
	public ServerInfo server;

	public static class ServerInfo
	{
		public String version;      // site semver, e.g. "1.0.0"
		public String sha;          // exact commit the site image was built from
		public int apiLevel;        // breaking-change counter; bumps are rare and loud
		public List<String> capabilities;
		/**
		 * The address this deployment would rather be reached at, e.g. "https://anvilosrs.com".
		 *
		 * One site now serves every clan, so a per-clan subdomain is a legacy address: it works, but
		 * it resolves the clan from the hostname instead of from your token, which stops being
		 * right the moment you join a second clan. The canonical address keeps working either way.
		 *
		 * SENT BY THE SERVER rather than baked in here, because Anvil is self-hostable — a
		 * hard-coded anvilosrs.com would tell every self-hoster to point at somebody else's site.
		 * Null on older sites and on any deployment that names none, in which case we say nothing.
		 */
		public String canonicalUrl;
	}

	/**
	 * Whether the configured URL should be swapped for the one the site prefers.
	 *
	 * Only when the site both advertises a canonical address AND says it can resolve a clan without
	 * one — otherwise moving someone to the apex would break them, which is a far worse outcome
	 * than an out-of-date URL that works.
	 *
	 * Compared on host alone: scheme and trailing slashes are noise, and a user who typed a path is
	 * still on a working address.
	 */
	public String suggestedUrlMigration(String configuredUrl)
	{
		if (server == null || server.canonicalUrl == null || server.canonicalUrl.isEmpty()) return null;
		if (!serverSupports("apex-routing")) return null;
		if (configuredUrl == null || configuredUrl.isEmpty()) return null;

		String have = hostOf(configuredUrl);
		String want = hostOf(server.canonicalUrl);
		if (have == null || want == null || have.equalsIgnoreCase(want)) return null;
		return server.canonicalUrl;
	}

	/** Host portion of a URL, lowercased, or null if it cannot be read as one. */
	static String hostOf(String url)
	{
		try
		{
			String s = url.trim();
			if (!s.toLowerCase().startsWith("http://") && !s.toLowerCase().startsWith("https://"))
			{
				s = "https://" + s;
			}
			String host = new java.net.URI(s).getHost();
			return host == null ? null : host.toLowerCase();
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/** Everything the plugin-facing API already supported when the handshake first shipped (site v1.0.0). */
	private static final Set<String> BASELINE_CAPABILITIES = new HashSet<>(Arrays.asList(
		"stats-live", "drop-tiles", "kill-tiles", "timed-tiles", "lms-tiles", "value-tiles",
		"gain-tiles", "deathless-tiles", "pvp-tiles", "diary-tiles", "ca-tiles", "clog-tiles",
		"weekly", "schedule", "notify", "counters", "activity-feed", "ladder",
		"reveal-modes", "config-etag"));

	/**
	 * Gate new plugin surfaces on this instead of calling an endpoint and 404ing: self-hosted
	 * sites can lag the hub plugin by months, and each federated connection may be on a
	 * different version. Capabilities newer than the baseline return false until the site
	 * explicitly advertises them — the surface should hide, not error.
	 */
	public boolean serverSupports(String capability)
	{
		if (server == null || server.capabilities == null)
		{
			return BASELINE_CAPABILITIES.contains(capability);
		}
		return server.capabilities.contains(capability);
	}

	// ── WHICH CLAN, AND WHICH OTHERS ──────────────────────────────────────────────────────────
	//
	// One Anvil serves every clan, so the canonical Site URL names none of them and the server picks
	// one from the token: a live event first, then the latest-started of several, then the newest
	// seat. That guess is nearly always right and completely invisible, which is the problem — a
	// member on two boards had no way to see which one their drops were filing into.
	//
	// So the server says which clan it answered for, and lists the rest. The plugin addresses the one
	// it means with a /c/<slug> prefix from then on, and offers the list as a dropdown.
	//
	// Null on a site that predates this (see the `clan-switch` capability): then there is one clan,
	// the address names it, and there was never a choice to make.

	/** The clan THIS response is about — whatever named it: a path, a host, or the token. */
	public ClanRef activeClan;

	/** Every clan the token's owner holds a seat in. Empty/null on an older site. */
	public List<ClanRef> clans;

	public static class ClanRef
	{
		public String slug;
		public String name;
		/** 'member' or 'guest' — a dropdown says which of these is your home. Null on activeClan. */
		public String kind;
		/** The most relevant thing running here, or null. */
		public ClanBoard live;
		/**
		 * How many things are running here in total — boards plus the competition.
		 *
		 * {@link #live} is one line in a dropdown, so it names ONE. Without this a clan running five
		 * boards reads exactly like a clan running one, and the named board is an arbitrary pick
		 * presented as the whole answer. Zero on a site too old to send it, which is indistinguishable
		 * from "nothing running" — and on such a site there is no count to show anyway.
		 */
		public int liveCount;
	}

	/**
	 * A live board in one of the person's clans.
	 *
	 * Shaped like {@link HomeBoard} but a type of its own because it carries the event id, and the id
	 * is load-bearing: a co-hosted event belongs to every host, so the same board arrives listed under
	 * each of them and the id is the only thing that says so. {@link HomeBoard} is the summary for the
	 * clan the plugin is addressing, where the question never comes up.
	 */
	public static class ClanBoard
	{
		/**
		 * "bingo" or "weekly" — and half of this thing's identity.
		 *
		 * A board id and a competition id come out of different tables and collide freely, so anything
		 * deduping across clans has to key on the PAIR. Null on a site that predates the field, where
		 * only boards were ever reported.
		 */
		public String kind;
		public int eventId;
		public String eventName;
		/** Zero on a weekly: a competition has a leaderboard, not a board to fill. */
		public int tilesComplete;
		public int tilesTotal;
		public boolean pointsScored;

		/** True for a SOTW/BOTW — no board to fill, so no progress bar and no tile tally. */
		public boolean isWeekly()
