		public int requiredAmount;         // total gains needed across the pool
		public int currentAmount;          // team's submitted gains so far
		public boolean completed;          // team already completed this tile
	}

	public static class TrackedDeathless
	{
		public int tileId;
		public int position;   // board position — the list mirrors the site's tile order (0 on old servers)
		public String label;
		public String description;
		public int points;
		public String category;
		public String activity;            // the raid, e.g. "Theatre of Blood"
		public int requiredAmount;         // deathless runs needed
		public int currentAmount;          // team's submitted runs so far
		public int partySize;              // exact party size required; 0/absent = any size
		public int itemId = -1;            // activity's signature reward (icon), -1 = book sprite
		public boolean completed;          // team already completed this tile
	}

	public static class TrackedValue
	{
		public int tileId;
		public int position;   // board position — the list mirrors the site's tile order (0 on old servers)
		public String label;
		public String description;
		public int points;
		public String category;
		public long thresholdGp;           // single: a haul must be worth ≥ this; total: the gp target to reach
		public String mode;                // "single" (one haul ≥ threshold) | "total" (hauls sum to threshold)
		public long currentGp;             // total mode: gp banked so far (the server's sum of submissions); 0 on single

		public List<String> sources;       // optional source filter: NPC/chest names, or "PvP"; empty = any
		public boolean completed;          // team already completed this tile
	}

	public static class TrackedStat
	{
		public int tileId;
		public int position;   // board position — the list mirrors the site's tile order (0 on old servers)
		public String label;
		public String description;   // tile description, for the clog task accordion
		public int points;           // Leagues-style reward value (0 = not a points event)
		public String category;      // free-text grouping (boss/skill) for the clog task filter
		public String statName;     // e.g. "mining", "zulrah"
		public String statType;     // "skill" | "boss" | "kc"
		public int itemId = -1;     // boss KC tiles: the boss's representative clog item (icon); -1 for skills
		public String trackingMode; // "team" | "individual"
		public int currentAmount;   // gained XP / KC since baseline
		public int goalAmount;
		// Teammates (RSNs) actively grinding this stat tile right now, for the sidebar's "Active now".
		// The caller is never included (the plugin marks itself "You"). null on older servers that don't
		// compute it (the sidebar then falls back to an unnamed "a teammate" via config-count deltas);
		// an empty list means the server DID compute it and no teammate is currently active.
		public java.util.List<String> activeWorkers;
	}
}

package com.anvil;

import java.util.List;

/**
 * The single seam between the always-on progress sidebar ({@link AnvilSidebarPanel}) and whatever
 * supplies its data. The panel depends only on this interface, so what actually answers — a live
 * site, a fixture in a test — is a wiring decision the panel never sees.
 *
 * <p><b>Contract</b></p>
 * <ul>
 *   <li>{@link #fetchConnections()} is <em>blocking</em> — implementations do network I/O. The panel
 *       always calls it off the Swing EDT (via a {@code SwingWorker}) and marshals the result back.</li>
 *   <li>Returns the clan this plugin is currently addressing, shaped as a {@link ConnectionView}.
 *       A list rather than one value because the panel renders and selects over a list, and because
 *       an implementation may legitimately have nothing to show.</li>
 *   <li>Never returns {@code null}. An <em>empty</em> list is a valid, distinct state (the member has
 *       no connected clans) and drives the panel's empty view.</li>
 *   <li>A <em>total</em> failure (no reachable homes at all, auth broken, etc.) throws
 *       {@link SidebarDataException}, which drives the panel's error view + retry. A <em>partial</em>
 *       failure (one home down, others fine) is expressed per-connection via
 *       {@link ConnectionView#error} instead — do not throw for that.</li>
 * </ul>
 *
 * <p>Bound to {@link AnvilSidebarDataSource}, a view over the config the plugin already polls.</p>
 */
public interface SidebarDataSource
{
	/**
	 * Fetch every connected clan and its board progress. Blocking; call off the EDT. Never {@code null}.
	 *
	 * @throws SidebarDataException on a total load failure (drives the panel's error state)
	 */
	List<ConnectionView> fetchConnections() throws SidebarDataException;

	/**
	 * As {@link #fetchConnections()}; {@code manualRefresh} marks a member-initiated Refresh, so a source
	 * may bypass whatever it normally throttles — the live source re-reads the weekly standings it
	 * otherwise caches for a minute. Default ignores the flag (nothing throttled, nothing to bypass).
	 */
	default List<ConnectionView> fetchConnections(boolean manualRefresh) throws SidebarDataException
	{
		return fetchConnections();
	}

	// ── The clan this plugin is pointed at ───────────────────────────────────────────────────────
	//
	// One Anvil serves every clan, so the Site URL names none of them and a person may hold seats in
	// several. The site says which clan it answered for and lists the rest; these three carry that to
	// the panel, which offers it as a dropdown.

	/** Every clan the signed-in person holds a seat in. Empty on an older site, or before the first poll. */
	default List<PluginConfigResponse.ClanRef> clans()
	{
		return java.util.Collections.emptyList();
	}

	/** The member's explicit pick, or "" when they are on Auto and the site is deciding. */
	default String chosenClan()
	{
		return "";
	}

	/**
	 * The clan slug this plugin is actually addressing — a pick if there is one, else whatever the
	 * site resolved. "" before the first answer. Distinct from {@link #chosenClan()}: the merged view
	 * needs to know which board is already on screen in full, not whether anybody chose it.
	 */
	default String activeClan()
	{
		return "";
	}

	/**
	 * The board the panel is RENDERING, as a cross-clan identity ({@code "bingo:<id>"}), or "" when
	 * there is none.
	 *
	 * <p>Not the same question as {@link #activeClan()}, and that gap is the bug it exists to close:
	 * a co-hosted board belongs to both hosts, so the clan being addressed and the clan whose row
	 * reports that board need not be the same one. Dedup "Also live" against the board on screen and
	 * the two can drift as much as they like without the panel listing one event twice.</p>
	 */
	default String addressedBoard()
	{
		return "";
	}

	/**
	 * The member picked a clan (or "" for Auto).
	 *
	 * Blocking-free: implementations persist the pick and kick off a refetch, they do not wait for one.
	 * The panel calls this from the EDT.
	 */
	default void chooseClan(String slug)
	{
	}

	/**
	 * The STARTING SHOT this account still owes on the addressed clan's live event (site lib/startProof),
	 * or {@code null} when nothing is owed — which is the case on every event that doesn't ask for
	 * one, on sites that predate the feature, and the moment one is filed.
	 *
	 * <p>Deliberately NOT a {@link ConnectionView} field: it is about the one home this plugin is
	 * authenticated against, not about each connected clan, and the view's constructors are already
	 * positional enough to make an eighth optional field a hazard.</p>
	 */
	default PluginConfigResponse.StartProof startProof()
	{
		return null;
	}

	/** Take + file the starting shot. No-op where {@link #startProof()} is null. Never blocks the EDT. */
	default void captureStartProof()
	{
	}

	/**
	 * What the panel may DO for one connection, which is not the same question for every clan.
	 *
	 * <p>A roster sync scrapes the clan channel you are standing in, so it is only ever offered for
	 * the clan you are actually a member of — an admin elsewhere still cannot see a roster they
	 * aren't in. A profile sync goes to the site the plugin is authenticated against, so it is
	 * offered for the home clan alone until there is a wire for relaying one.
	 */
	class PanelActions
	{
		public static final PanelActions NONE = new PanelActions(false, false, null);

		/** Show "Sync clan roster": admin, at home, with a readable clan channel. */
		public final boolean canSyncRoster;
		/** Show "Sync profile": the site takes profile data and it's the one we're signed in to. */
		public final boolean canSyncProfile;
		/** Why the roster button is absent, when the reason is worth saying. Null when it isn't. */
		public final String rosterNote;

		public PanelActions(boolean canSyncRoster, boolean canSyncProfile, String rosterNote)
		{
			this.canSyncRoster = canSyncRoster;
			this.canSyncProfile = canSyncProfile;
			this.rosterNote = rosterNote;
		}
	}

	/** Actions available for the clan currently on screen. Never null. */
	default PanelActions actionsFor(String instanceId)
	{
		return PanelActions.NONE;
	}

	/** Push the in-game clan roster to the home site. No-op unless {@code canSyncRoster}. */
	default void syncRoster()
	{
	}

	/** Send this account's collection log + bests to the home site. No-op unless {@code canSyncProfile}. */
	default void syncProfile()
	{
	}

	/** Local banner-sound clips, newest listing each call. Empty when the folder has none. */
	default java.util.List<String> bannerSounds()
	{
		return java.util.Collections.emptyList();
	}

	/** Is this clip in the play cycle? */
	default boolean bannerSoundOn(String clip)
	{
		return false;
	}

	/** Flip one clip in or out of the cycle. */
	default void toggleBannerSound(String clip)
	{
	}

	/** Open the local clips folder — these live on this machine, not on any account. */
	/** Copy the sounds folder's path — hub releases may not open a file manager (see Clipboards). */
	default void copyBannerSoundsPath()
	{
	}

	/** Import a .wav into the local clips folder. */
	default void importBannerSounds()
	{
	}

	/** Mission clips — the folder that decides whether missions play a clip or the built-in chime. */
	default java.util.List<String> missionSounds()
	{
		return java.util.Collections.emptyList();
	}

	/** Import a .wav into the mission clips folder. */
	default void importMissionSounds()
	{
	}

	/** Total-failure signal for {@link #fetchConnections()} — carries a member-facing message for the error view. */
	class SidebarDataException extends Exception
	{
		public SidebarDataException(String message)
		{
			super(message);
		}

		public SidebarDataException(String message, Throwable cause)
		{
			super(message, cause);
		}
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The queue behind the clan's highlight feed: pets, uniques, big hauls and deaths, held until the
 * next push.
 *
 * <p>WHAT THIS DOES NOT DO is decide whether any of it matters. The client cannot know which
 * competition is running, what counts as a unique at this clan, or which pets belong to which skill
 * — all of that lives on the site (src/lib/moments.ts), so a clan can change its mind without
 * waiting on a plugin release. This sends what it saw, generously, and expects most of it to be
 * thrown away.
 *
 * <p>EVERY MOMENT IS RECORDED AT THE EVENT, never inside a notification gate. A member with the
 * drops channel switched off still gets their pet on the site's feed — the two settings are about
 * different things, and tying them together is exactly the bug that once captioned every saved clip
 * "Clip saved".
 *
 * <p>Each entry carries its own idempotency key, because the game says everything twice: one pet
 * fires up to three chat lines, one kill fires two loot events, and a retry after a timeout is a
 * third copy on purpose. The key is derived from what happened rather than from a counter, so all
 * of those collapse into one row server-side.
 *
 * <p>Bounded and lossy by design. If a session outruns the pushes, the OLDEST entries go: a feed
 * that drops the pet you just got to keep a 200k loot pile would be worse than useless. Touched
 * from the client thread (game events) and drained on the executor, so every method is synchronized.
 */
class AnvilMoments
{
	/**
	 * A session's backlog, not a history. The site takes 25 per push and the pushes are debounced to
	 * seconds, so this only fills at all when the site is unreachable.
	 */
	static final int MAX_QUEUED = 50;

	/** How many go in one request — matches the site's own cap. */
	static final int BATCH = 25;

	/** Below this a drop isn't worth reporting on price alone. The site's floors are stricter. */
	static final long MIN_REPORTABLE_GP = 100_000L;

	static final class Moment
	{
		/** 'pet' | 'drop' | 'death' | 'ca'. */
		final String kind;
		final Integer itemId;
		final String itemName;
		final int quantity;
		final Long valueGp;
		final String source;
		final String sourceKind;
		final Integer kc;
		/** 'ca' only: the task the completion line named, and the tier it claimed. */
		final String taskName;
		final String tier;
		final long at;
		final String key;

		Moment(String kind, Integer itemId, String itemName, int quantity, Long valueGp,
			   String source, String sourceKind, Integer kc, long at, String key)
		{
			this(kind, itemId, itemName, quantity, valueGp, source, sourceKind, kc, null, null, at, key);
		}

		Moment(String kind, Integer itemId, String itemName, int quantity, Long valueGp,
			   String source, String sourceKind, Integer kc, String taskName, String tier, long at, String key)
		{
			this.kind = kind;
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
			this.valueGp = valueGp;
			this.source = source;
			this.sourceKind = sourceKind;
			this.kc = kc;
			this.taskName = taskName;
			this.tier = tier;
			this.at = at;
			this.key = key;
		}

		/** A completed combat task. The site decides which boss it belongs to and whether it's news. */
		static Moment combatTask(String taskName, String tier, long at)
		{
			return new Moment("ca", null, null, 1, null, null, null, null, taskName, tier, at,
				keyFor("ca", taskName, null, at));
		}

		/**
		 * A level worth telling people about: a 99, a total-level milestone, or a max.
		 *
		 * <p>{@code skill} is the skill's name, or null when the news is the total rather than any one
		 * skill. {@code level} rides in the quantity column and {@code scope} in sourceKind, so this
		 * needs no new columns anywhere -- the site reads both to decide what sentence to write.</p>
		 *
		 * <p>Keyed on the skill and the number, NOT on the clock: a 99 happens once, and if a retry or
		 * a second sighting arrives ten seconds later it is still the same 99.</p>
		 */
		static Moment level(String skill, int level, String scope, long at)
		{
			return new Moment("level", null, skill, level, null, null, scope, null, at,
				"level|" + (skill == null ? "total" : skill.toLowerCase()) + "|" + level);
		}
	}

	/** Keyed so a duplicate observation replaces rather than repeats; insertion-ordered for the batch. */
	private final Map<String, Moment> pending = new LinkedHashMap<>();

	/**
	 * Queue one. A repeat of a key already waiting REPLACES it — the second sighting of the same pet
	 * is the one that knows its name.
	 */
	synchronized void record(Moment moment)
	{
		if (moment == null || moment.key == null || moment.key.isEmpty())
		{
			return;
		}
		pending.remove(moment.key);
		pending.put(moment.key, moment);
		while (pending.size() > MAX_QUEUED)
		{
			pending.remove(pending.keySet().iterator().next());
		}
	}

	/**
	 * Fill in the name of something already queued — a pet is announced by one chat line and named
	 * by the next, and the feed wants the name.
	 *
	 * @return true when there was something to name
	 */
	synchronized boolean nameQueued(String key, String itemName, Integer itemId)
	{
		return nameQueued(key, itemName, itemId, null, null);
	}

	/**
	 * As above, and correct where it came from at the same time.
	 *
	 * <p>A pet is queued before anything knows which pet it is, so its source can only be whatever
	 * loot the client had just seen — the chest rather than the raid, a minion rather than the boss.
	 * The name is what makes the real source knowable, so the two corrections arrive together. A null
	 * {@code source} leaves the queued one alone: the caller learned nothing better.
	 */
	synchronized boolean nameQueued(String key, String itemName, Integer itemId, String source, Integer kc)
	{
		Moment existing = pending.get(key);
		if (existing == null || itemName == null || itemName.isEmpty())
		{
			return false;
		}
		pending.put(key, new Moment(existing.kind, itemId != null ? itemId : existing.itemId, itemName,
			existing.quantity, existing.valueGp, source != null ? source : existing.source, existing.sourceKind,
			source != null ? kc : existing.kc, existing.at, existing.key));
		return true;
	}

	synchronized boolean isEmpty()
	{
		return pending.isEmpty();
	}

	synchronized int size()
	{
		return pending.size();
	}

	/** The next batch to send. Stays queued until {@link #onSent} confirms it — a failed push retries. */
	synchronized List<Moment> nextBatch()
	{
		List<Moment> batch = new ArrayList<>();
		for (Moment m : pending.values())
		{
			batch.add(m);
			if (batch.size() >= BATCH)
			{
				break;
			}
		}
		return batch;
	}

	/** Drop what the site has taken. */
	synchronized void onSent(List<Moment> batch)
	{
		if (batch == null)
		{
			return;
		}
		for (Moment m : batch)
		{
			pending.remove(m.key);
		}
	}

	/** Forget everything — a different account logging in doesn't inherit this one's moments. */
	synchronized void reset()
	{
		pending.clear();
	}

	/**
	 * A key for one thing that happened.
	 *
	 * <p>Built from WHAT happened rather than from a counter, so the two loot events and three chat
	 * lines the game fires for a single occurrence all produce the same string. Time is bucketed to
	 * ten seconds so the copies — which arrive within a tick or two of each other — agree, while a
	 * second genuine drop of the same item minutes later does not.
	 */
	static String keyFor(String kind, String source, Integer itemId, long at)
	{
		long bucket = at / 10_000L;
		return kind + "|" + (source == null ? "" : source.toLowerCase()) + "|"
			+ (itemId == null ? "" : itemId) + "|" + bucket;
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class BingoApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");

	private final Gson gson;
	private final OkHttpClient httpClient;
	// Clip relay uploads are multi-MB video. The normal client's 30s write timeout aborts those
	// mid-upload on a slow connection, so file posts get their own generous timeouts (the pool and
	// dispatcher are still shared via newBuilder, so an extra client is cheap).
	private final OkHttpClient uploadClient;
	private String apiUrl;
	private String playerToken;
	// In-game RSN of the locally logged-in account. Sent as `X-RSN` on every player-token
	// request so the server can scope the per-user plugin token to the correct clan_member
	// (and reject drops on accounts that aren't signed up for the active event).
	private volatile String currentRsn;
	// Stable Jagex account hash (client.getAccountHash()) of the locally logged-in account.
	// Sent as `X-Account-Hash` so the server can anchor auto-verification to the account even
	// across in-game renames. Null when logged out / unavailable.
	private volatile String accountHash;
	/** True while the logged-in world is a seasonal (Leagues) world. Set from the plugin on login/hop. */
	private volatile boolean seasonal;

	@Inject
	public BingoApiClient(Gson gson, OkHttpClient client)
	{
		this.gson = gson;
		// Read timeout is generous because some server reads do several round-trips to Turso
		// and can take a while; tighter timeouts here will trip even on healthy servers.
		this.httpClient = client.newBuilder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(90, TimeUnit.SECONDS)
			.writeTimeout(30, TimeUnit.SECONDS)
			.build();
		this.uploadClient = client.newBuilder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.callTimeout(120, TimeUnit.SECONDS)
			.writeTimeout(120, TimeUnit.SECONDS)
			.readTimeout(60, TimeUnit.SECONDS)
			.build();
	}

	public void configure(String apiUrl, String playerToken)
	{
		this.apiUrl = normalizeBaseUrl(apiUrl);
		this.playerToken = playerToken;
	}

	/** The configured site base URL (normalized, no trailing slash), or "" when unconfigured. */
	public String getApiUrl()
	{
		return apiUrl == null ? "" : apiUrl;
	}

	// ── WHICH CLAN THIS CLIENT IS TALKING TO ────────────────────────────────────────────────
	//
	// The Site URL the member typed is one Anvil, and one Anvil serves every clan. On the canonical
	// address it therefore names no clan at all, and the server picks one from the token — live event
	// first, then latest start, then newest seat.
	//
	// Good defaults, but a guess re-made on every request. Once we have been TOLD which clan we are
	// dealing with — either because the member chose one in the sidebar, or because /config answered
	// and said which one it answered for — we say so outright, by addressing `/c/<slug>` instead of
	// the bare root. Same canonical path a browser uses, and the site has resolved it since the day
	// clans stopped being subdomains.
	//
	// Two things fall out of it that are worth having on purpose. A member in two live boards stops
	// being at the mercy of "latest start wins". And the handful of routes outside /api/plugin that
	// still resolve a clan from the ADDRESS rather than the token — filing a submission, filing the
	// starting shot, uploading its image — resolve correctly on the bare apex, which they do not when
	// nothing names a clan.

	/** A clan slug as the site accepts one; anything else is treated as naming no clan. */
	private static final java.util.regex.Pattern CLAN_SLUG = java.util.regex.Pattern.compile("[a-z0-9-]{2,32}");

	// TWO SLUGS, and the difference between them is the whole design.
	//
	// `chosen` is the member's pick in the sidebar. Empty means "Auto" — they have not chosen, and
	// the server should keep deciding.
	//
	// `resolved` is what the server last told us it answered for. In Auto we adopt it for every call
	// EXCEPT the config poll itself, which stays unaddressed so the server keeps re-deciding: a member
	// whose live board moves to their other clan should follow it without touching a dropdown. Adopting
	// it everywhere else is what makes a submission, a starting shot and its upload land in the right
	// clan on the canonical address, where nothing in the URL says which clan is meant.

	/** The member's explicit pick, or "" for Auto. Survives restarts (AnvilPlugin persists it). */
	private volatile String chosenClan = "";

	/** The clan the site last said it answered for. In-memory: it is the server's judgement, not a setting. */
	private volatile String resolvedClan = "";

	/** The member picked a clan in the sidebar, or picked Auto (null/blank). */
	public void setChosenClan(String slug)
	{
		this.chosenClan = cleanSlug(slug);
	}

	/** The member's explicit pick, or "" when they are on Auto. */
	public String getChosenClan()
	{
		return chosenClan;
	}

	/** The site answered, and named the clan it answered for. */
	public void setResolvedClan(String slug)
	{
		this.resolvedClan = cleanSlug(slug);
	}

	/** The clan this client is actually addressing right now — a pick beats the server's guess. */
	public String getActiveClan()
	{
		return !chosenClan.isEmpty() ? chosenClan : resolvedClan;
	}

	/**
	 * Validated rather than trusted: a slug arrives over the wire and is about to be pasted into every
	 * URL this client builds. Anything that is not a slug names no clan — which is the behaviour we
	 * already had, and so cannot break anything.
	 */
	private static String cleanSlug(String slug)
	{
		String clean = slug == null ? "" : slug.trim().toLowerCase();
		return !clean.isEmpty() && CLAN_SLUG.matcher(clean).matches() ? clean : "";
	}

	/**
	 * A clan-scoped URL: the base, the clan we are addressing, then the path.
	 *
	 * Everything the plugin calls is clan-scoped except signing in, which is about a person and happens
	 * before any clan is known ({@link #rootUrl}), and the config poll in Auto ({@link #configUrl}).
	 */
	String clanUrl(String path)
	{
		String slug = getActiveClan();
		return slug.isEmpty() ? apiUrl + path : apiUrl + "/c/" + slug + path;
	}

	/**
	 * Where to ask for the config.
	 *
	 * An explicit pick is addressed like everything else. On Auto this stays deliberately unaddressed,
	 * so every poll is a fresh question — the answer names the clan, and the answer is allowed to
	 * change when the member's live board does.
	 */
	String configUrl(String path)
	{
		return chosenClan.isEmpty() ? apiUrl + path : apiUrl + "/c/" + chosenClan + path;
	}

	/** A URL that must NOT carry a clan: the device sign-in pair, which is identity, not membership. */
