	/**
	 * POST /api/plugin/progress — quest points, combat-achievement points/tier, diary counts.
	 *
	 * <p>Account state the hiscores never publish (site: lib/memberProgress). Only keys whose value
	 * actually moved since the last successful push are sent, so the steady state is no request at
	 * all; the server max-merges what does arrive, which makes a retry free and stops a client that
	 * read a varbit before the game populated it from walking somebody's account backwards.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitProgress(java.util.Map<String, Integer> progress) throws IOException
	{
		submitProgress(progress, null, null);
	}

	/**
	 * The same push, carrying an item list — every quest with its state, so the site can show which
	 * are left rather than only how many are done. Sent whole and only when it changed, since half a
	 * list is worse than none.
	 */
	public void submitProgress(java.util.Map<String, Integer> progress, String itemCategory,
		java.util.List<AccountProgress.Item> items) throws IOException
	{
		submitProgress(progress, itemCategory, items, null, 0);
	}

	/**
	 * The same push, carrying the raw combat-achievement varps.
	 *
	 * <p>We send the numbers and the game's own point total; the site decodes which task each bit is
	 * and refuses the lot if the points don't reconcile. Nothing here knows what a combat task is,
	 * which is the point: the catalogue lives where it can be updated without a release.
	 */
	public void submitProgress(java.util.Map<String, Integer> progress, String itemCategory,
		java.util.List<AccountProgress.Item> items, java.util.Map<Integer, Integer> caVarps,
		int caPoints) throws IOException
	{
		boolean hasItems = itemCategory != null && items != null && !items.isEmpty();
		boolean hasVarps = caVarps != null && !caVarps.isEmpty() && caPoints > 0;
		if ((progress == null || progress.isEmpty()) && !hasItems && !hasVarps)
		{
			return;
		}
		if (progress == null)
		{
			progress = java.util.Collections.emptyMap();
		}
		JsonArray rows = new JsonArray();
		for (java.util.Map.Entry<String, Integer> e : progress.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null)
			{
				continue;
			}
			JsonObject row = new JsonObject();
			row.addProperty("key", e.getKey());
			row.addProperty("value", e.getValue());
			rows.add(row);
		}
		if (rows.size() == 0 && !hasItems && !hasVarps)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("progress", rows);
		if (hasItems)
		{
			JsonArray itemRows = new JsonArray();
			for (AccountProgress.Item item : items)
			{
				if (item == null || item.name == null || item.name.isEmpty())
				{
					continue;
				}
				JsonObject row = new JsonObject();
				row.addProperty("id", item.id);
				row.addProperty("name", item.name);
				row.addProperty("state", item.state);
				itemRows.add(row);
			}
			JsonObject set = new JsonObject();
			set.addProperty("category", itemCategory);
			set.add("items", itemRows);
			JsonArray sets = new JsonArray();
			sets.add(set);
			payload.add("items", sets);
		}
		if (hasVarps)
		{
			JsonObject varpObj = new JsonObject();
			for (java.util.Map.Entry<Integer, Integer> e : caVarps.entrySet())
			{
				varpObj.addProperty(String.valueOf(e.getKey()), e.getValue());
			}
			payload.add("caVarps", varpObj);
			payload.addProperty("caPoints", caPoints);
		}

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(clanUrl("/api/plugin/progress"))
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			String responseBody = response.body() != null ? response.body().string() : "";
			if (!response.isSuccessful())
			{
				throw new IOException("Progress push failed: HTTP " + response.code() + " — "
					+ (responseBody.isEmpty() ? "no body" : responseBody));
			}
			// The reply says what the server made of it — including, for combat achievements, whether
			// the bits reconciled against the point total and how many tasks it couldn't name. Logged
			// at INFO because when this feature is quiet the only alternative is guessing which half
			// went wrong, which has cost a day already.
			log.info("Anvil progress pushed ({} key(s), {} varps): {}", rows.size(),
				hasVarps ? caVarps.size() : 0, responseBody);
		}
	}

	/**
	 * POST /api/plugin/clog — collection-log pages the player has actually opened.
	 *
	 * <p>Sends ONLY obtained items, and only pages whose contents changed since the last successful
	 * push ({@link ClogSync} owns that decision). The site already ships the full item catalogue, so
	 * the missing half is derivable — transmitting it would double every payload to say "still
	 * nothing here".
	 *
	 * <p>Idempotent: the server keys on (member, page) and replaces, so a retry or a client restart
	 * mid-sync costs nothing. Profile data only — never scoring.
	 */
	public void submitClogPages(java.util.List<ClogPage> pages, int syncedPages) throws IOException
	{
		if (pages == null || pages.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (ClogPage page : pages)
		{
			if (page == null || page.name == null || page.name.isEmpty())
			{
				continue;
			}
			JsonArray items = new JsonArray();
			for (int i = 0; i < page.itemIds.length; i++)
			{
				JsonObject item = new JsonObject();
				item.addProperty("id", page.itemIds[i]);
				item.addProperty("q", page.quantities[i]);
				items.add(item);
			}
			JsonObject p = new JsonObject();
			p.addProperty("name", page.name);
			p.addProperty("obtained", page.obtained);
			p.addProperty("total", page.total);
			p.add("items", items);
			if (!page.counts.isEmpty())
			{
				JsonObject counts = new JsonObject();
				for (java.util.Map.Entry<String, Integer> e : page.counts.entrySet())
				{
					counts.addProperty(e.getKey(), e.getValue());
				}
				p.add("counts", counts);
			}
			out.add(p);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("pages", out);
		// How much of the log this account has opened at all — drives the site's "68% synced" note.
		payload.addProperty("syncedPages", syncedPages);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(clanUrl("/api/plugin/clog"))
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Collection log push failed", response.code(), responseBody);
			}
			log.debug("Collection log pushed: {} page(s), {} synced", out.size(), syncedPages);
		}
	}

	/**
	 * POST /api/plugin/pb — the account's best times, in centiseconds.
	 *
	 * <p>Centiseconds because the game separates runs by hundredths; whole seconds would tie times
	 * the game itself doesn't. The server keeps the FASTEST of stored and pushed, so a retry, a
	 * stale client or an out-of-order request can never raise somebody's record.
	 */
	public void submitPersonalBests(java.util.Map<String, Integer> bests) throws IOException
	{
		if (bests == null || bests.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (java.util.Map.Entry<String, Integer> e : bests.entrySet())
		{
			if (e.getKey() == null || e.getKey().isEmpty() || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			JsonObject b = new JsonObject();
			b.addProperty("activity", e.getKey());
			b.addProperty("centis", e.getValue());
			out.add(b);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("bests", out);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(clanUrl("/api/plugin/pb"))
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Personal best push failed", response.code(), responseBody);
			}
			log.debug("Personal bests pushed: {}", out.size());
		}
	}

	/**
	 * POST /api/plugin/moments — the clan's highlight feed: pets, uniques, big hauls and deaths.
	 *
	 * <p>Reports what the client SAW; the site decides what it meant. It knows which competition
	 * week or board is running, what counts as a unique, and which pets belong to which skill — so
	 * most of what goes up here is discarded there, on purpose, and a clan changing its mind about
	 * any of it costs no plugin release.
	 *
	 * <p>Idempotent: every entry carries a key derived from what happened, so the two loot events
	 * and three chat lines one occurrence fires — and a retry after a timeout — collapse into one
	 * row. A failure therefore just retries with the queue intact.
	 *
	 * <p>Never scoring: nothing here completes a tile or moves a standing.
	 */
	public void submitMoments(java.util.List<AnvilMoments.Moment> batch) throws IOException
	{
		if (batch == null || batch.isEmpty())
		{
			return;
		}
		JsonArray out = new JsonArray();
		for (AnvilMoments.Moment m : batch)
		{
			if (m == null || m.kind == null || m.key == null)
			{
				continue;
			}
			JsonObject o = new JsonObject();
			o.addProperty("kind", m.kind);
			o.addProperty("key", m.key);
			o.addProperty("at", java.time.Instant.ofEpochMilli(m.at).toString());
			o.addProperty("quantity", Math.max(1, m.quantity));
			// Everything below is best-effort — a skilling pet has no source, no KC and no price, and
			// inventing any of them would be worse than a shorter line on the feed.
			if (m.itemId != null)
			{
				o.addProperty("itemId", m.itemId);
			}
			if (m.itemName != null && !m.itemName.isEmpty())
			{
				o.addProperty("itemName", m.itemName);
			}
			if (m.valueGp != null && m.valueGp > 0)
			{
				o.addProperty("valueGp", m.valueGp);
			}
			if (m.source != null && !m.source.isEmpty())
			{
				o.addProperty("source", m.source);
			}
			if (m.taskName != null && !m.taskName.isEmpty())
			{
				o.addProperty("taskName", m.taskName);
			}
			if (m.tier != null && !m.tier.isEmpty())
			{
				o.addProperty("tier", m.tier);
			}
			if (m.sourceKind != null && !m.sourceKind.isEmpty())
			{
				o.addProperty("sourceKind", m.sourceKind);
			}
			if (m.kc != null && m.kc > 0)
			{
				o.addProperty("kc", m.kc);
			}
			out.add(o);
		}
		if (out.size() == 0)
		{
			return;
		}

		JsonObject payload = new JsonObject();
		payload.add("moments", out);

		RequestBody body = RequestBody.create(JSON, payload.toString());
		Request request = authedRequest(clanUrl("/api/plugin/moments"))
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw new IOException("Moment push failed: HTTP " + response.code() + " — " + responseBody);
			}
			log.debug("Moments pushed: {}", out.size());
		}
	}

	/**
	 * POST /api/events/{eventId}/submissions — submits a timed-clear with image proof.
	 * amount is fixed at 1; the clear time (seconds) rides in durationSeconds. The server
	 * completes the tile when durationSeconds ≤ the tile's threshold.
	 */
	public void submitTimed(int eventId, int tileId, int teamId, int durationSeconds, String imageUrl, String note, int creditPlayerId) throws IOException
	{
		JsonObject payload = new JsonObject();
		payload.addProperty("tileId", tileId);
		payload.addProperty("teamId", teamId);
		payload.addProperty("amount", 1);
		payload.addProperty("durationSeconds", durationSeconds);
		payload.addProperty("imageUrl", imageUrl);
		payload.addProperty("note", note);
		payload.addProperty("creditPlayerId", creditPlayerId);

		RequestBody body = RequestBody.create(JSON, payload.toString());

		Request request = authedRequest(clanUrl("/api/events/" + eventId + "/submissions"))
			.post(body)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				String responseBody = response.body() != null ? response.body().string() : "no body";
				throw submissionError("Timed submission failed", response.code(), responseBody);
			}
			log.info("Timed clear submitted successfully for tile {}", tileId);
		}
	}

}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import java.util.stream.Collectors;

/**
 * Looks up the drop rarity (probability) of an item from a given source, using
 * a wiki-scraped dataset bundled as a JSON resource.
 *
 * Adapted from Dink (pajlads/DinkPlugin), BSD-2-Clause — see
 * THIRD_PARTY_NOTICES.md. The bundled npc_drops.json / thieving.json datasets
 * are also from Dink.
 */
@Slf4j
public abstract class AbstractRarityService {

    protected final Gson gson;
    protected final ItemManager itemManager;
    protected final Map<String, Collection<RareDrop>> dropsBySourceName;

    AbstractRarityService(String resourceName, int expectedSize, Gson gson, ItemManager itemManager) {
        this.gson = gson;
        this.itemManager = itemManager;
        this.dropsBySourceName = new HashMap<>(expectedSize);

        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream(resourceName); Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            raw = gson.fromJson(reader, new TypeToken<Map<String, List<RawDrop>>>() {
            }.getType());
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((sourceName, rawDrops) -> {
            ArrayList<RareDrop> drops = rawDrops.stream()
                    .map(RawDrop::transform)
                    .flatMap(Collection::stream)
                    .collect(Collectors.toCollection(ArrayList::new));
            drops.trimToSize();
            dropsBySourceName.put(sourceName, drops);
        });
    }

    public OptionalDouble getRarity(String sourceName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
                ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsBySourceName.getOrDefault(sourceName, Collections.emptyList())
                .stream()
                .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
                .filter(drop -> {
                    int id = drop.getItemId();
                    if (id == itemId) {
                        return true;
                    }
                    return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
                })
                .mapToDouble(RareDrop::getProbability)
                .reduce(Double::sum);
    }

    @Value
    protected static class RareDrop {

        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {

        private @SerializedName("i")
        int itemId;
        private @SerializedName("r")
        Integer rolls;
        private @SerializedName("d")
        double denominator;
        private @SerializedName("q")
        Integer quantity;
        private @SerializedName("m")
        Integer quantMin;
        private @SerializedName("n")
        Integer quantMax;

        Collection<RareDrop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new RareDrop(itemId, min, max, prob));
            }
            List<RareDrop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = MathUtils.binomialProbability(prob, rounds, successCount);
                drops.add(new RareDrop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
    }
}

package com.anvil;

/**
 * The collection log's rank title for a given number of unique slots obtained.
 *
 * The game shows this next to the log's completion count, and it's the one number that makes a clog
 * post mean something to a reader who doesn't know how many slots exist — "855/1712" is arithmetic,
 * "Black" is a standing.
 *
 * The thresholds live here, alone, so there is exactly one place to correct if Jagex moves them.
 * Deliberately returns null below the first threshold and for an unreadable count rather than
 * inventing a rank: a missing field in a clan post is unremarkable, a wrong one gets repeated.
 */
final class ClogRank
{
	/** Fixed slot requirements, ascending. Gilded is NOT here — see {@link #gildedThreshold}. */
	private static final int[] THRESHOLDS = {100, 300, 500, 700, 900, 1000, 1100, 1200};
	private static final String[] NAMES = {
		"Bronze", "Iron", "Steel", "Black", "Mithril", "Adamant", "Rune", "Dragon"
	};

	private static final String GILDED = "Gilded";

	/**
	 * Gilded is defined as a PROPORTION, not a number: 90% of the log's total slots, rounded down to
	 * the nearest 25. So it moves every time Jagex adds slots — hardcoding today's value would go
	 * quietly wrong on the next content update. At the current 1712 slots this is 1525.
	 */
	static int gildedThreshold(int totalSlots)
	{
		return totalSlots <= 0 ? Integer.MAX_VALUE : (int) (totalSlots * 0.9) / 25 * 25;
	}

	/**
	 * Rank title for {@code obtained} of {@code totalSlots} unique slots, or null when it earns none
	 * / the counts are bogus. {@code totalSlots} is only needed to place Gilded; pass the log's own
	 * maximum (the client reports it alongside the count).
	 */
	static String forSlots(int obtained, int totalSlots)
	{
		if (obtained <= 0)
		{
			return null;
		}
		if (obtained >= gildedThreshold(totalSlots))
		{
			return GILDED;
		}
		String rank = null;
		for (int i = 0; i < THRESHOLDS.length; i++)
		{
			if (obtained >= THRESHOLDS[i])
			{
				rank = NAMES[i];
			}
		}
		return rank;
	}

	private ClogRank()
	{
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure, side-effect-free parsing for timed-clear tiles. Kept out of the plugin so the fragile,
 * game-version-specific bits (the exact completion strings) are unit-testable against real chat
 * messages without standing up RuneLite.
 *
 * Two responsibilities:
 *   1. {@link #parseDurationSeconds} — pull a clear time out of a "...duration: mm:ss(.ff)" /
 *      "...completion time: mm:ss" message (raids, gauntlet, colosseum, inferno, ToB/ToA).
 *   2. {@link #messageMatchesActivity} — decide whether a chat line identifies a given tile's
 *      activity, via a signature table. The identifying line is usually NOT the duration line
 *      (it's the adjacent "Your X kill/completion count is:" line), which is why the plugin
 *      correlates the two across a short window.
 *
 * Real message formats this was built against (verify/extend as Jagex changes them):
 *   Inferno      "Duration: 2:58.03 (new personal best)"  +  "Your TzKal-Zuk kill count is: 1."
 *   TzHaar-Ket-Rak "Challenge duration: 8:54.00"  +  "Your completion count for TzHaar-Ket-Rak's ... is: 1."
 *   Nightmare    "Team size: Solo Fight duration: 24:35"  +  "Your Nightmare kill count is: 11."
 *   Colosseum    "Wave 12 completed! Wave duration: 33:32.40"  +  "Your Sol Heredit kill count is: 100."
 *   CoX          "...your raid is complete! Duration: 15:39"  +  "Your completed Chambers of Xeric count is: 306."
 *   Boss timers  "Fight duration: 1:36 (new personal best)"  +  "Your <boss> kill count is: N." — the
 *                generic pair for every boss with an in-game kill timer (GWD, Zulrah, Vorkath, Hydra,
 *                Grotesque Guardians, Muspah, the DT2 four, Scurrius, Araxxor, Yama, etc.); the
 *                identity line names the boss, so the activity-name fallback covers them.
 *   Gauntlet     "Challenge duration: 10:24. Personal best: 7:59."  +  "Your Gauntlet completion count is: 45."
 *   Barracuda Trials (Sailing)
 *                "You have completed the Gwenith Glide and achieved the Marlin rank."
 *                + "Time: 6:04.20 (new personal best)."  +  "Your Gwenith Glide completion count is: 49"
 *                — no signature entry needed: both flanking lines name the trial, so the
 *                activity-name fallback matches tiles like "gwenith glide" / "tempor tantrum".
 */
final class TimedClearParser
{
	private TimedClearParser() {}

	// A duration keyword followed (within a few non-digits) by an [h:]mm:ss token. Fractional
	// ".ff" tails are intentionally left out of the capture group. Minutes go to three digits:
	// slow Inferno/Zuk clears print raw minutes past 99 ("Duration: 172:18. Personal best:
	// 134:52") rather than rolling into h:mm:ss. Keyword family, mirroring the formats
	// RuneLite's chat-commands PB tracker knows:
	//   duration        — "Fight/Wave/Challenge/Corrupted challenge duration:", raid "Duration:"
	//   completion time — ToB/ToA "total completion time:"
	//   time:           — Barracuda Trials "Time: 6:04.20", Sepulchre "Floor 5 time:"/"Overall
	//                     time:". Colon fused so countdown lines ("Time remaining: 5:00") don't
	//                     parse as a clear.
	//   subdued in      — Tempoross "Subdued in 6:32"
	// ToA's per-room / per-challenge sub-times also match "duration"/"time:" but are filtered
	// out before this (see RAID_SUBTIME) — they're not the raid clear time.
	private static final Pattern DURATION = Pattern.compile(
			"(?:duration|completion time|time:|subdued in)[^0-9]{0,16}((?:\\d{1,2}:)?\\d{1,3}:\\d{2})");

	// ToA reports several *sub*-times before the raid total, each carrying its own duration:
	//   "Challenge complete: The Wardens. Duration: 7:05"     — one room
	//   "Challenge time: 10:23"                                — one challenge
	//   "Tombs of Amascut: Expert Mode challenge completion time: 30:16" — rooms only, no overhead
	// None of these is the raid clear time — a "clear the raid under X" tile must use the
	// "… total completion time:" line (or CoX's "raid is complete! Duration:"). Crediting a room
	// duration was letting a 34:50 raid pass a 25-minute tile off its 7:05 final room. These are
	// the only "challenge …"/"… completion time" phrasings we reject; "Challenge duration:"
	// (Gauntlet / Corrupted Gauntlet / TzHaar-Ket-Rak) and "total completion time" are kept.
	private static final Pattern RAID_SUBTIME = Pattern.compile(
			"challenge complete|challenge time:|challenge completion time");

	// Lowercased activity (as configured on the tile) -> substrings that, if present in a nearby
	// chat line, identify that activity. The identifying line is typically the boss/raid
	// kill/completion-count message, which names the boss rather than the activity (e.g. Inferno
	// -> "tzkal-zuk", Colosseum -> "sol heredit"). Default signature is the activity name itself.
	private static final Map<String, List<String>> SIGNATURES = new HashMap<>();

	static
	{
		SIGNATURES.put("inferno", Arrays.asList("tzkal-zuk", "inferno"));
		SIGNATURES.put("fight caves", Arrays.asList("tztok-jad", "fight cave"));
		SIGNATURES.put("chambers of xeric", Collections.singletonList("chambers of xeric"));
		SIGNATURES.put("theatre of blood", Collections.singletonList("theatre of blood"));
		SIGNATURES.put("tombs of amascut", Collections.singletonList("tombs of amascut"));
		// Raid-mode shorthands, so a mode tile matches however the admin phrased it. Colons and
		// spacing are already folded away by norm(), so we only enumerate the abbreviations here;
		// each pins the EXACT game count-line substring. A CM/HM/Expert tile must carry the full
		// mode text so a *base*-mode clear (whose line omits it) can't wrongly complete it — while a
		// base-raid tile keeps matching every harder mode (the mode line contains the base name).
		SIGNATURES.put("cox", Collections.singletonList("chambers of xeric"));
		SIGNATURES.put("cox cm", Collections.singletonList("chambers of xeric challenge mode"));
		SIGNATURES.put("cox challenge mode", Collections.singletonList("chambers of xeric challenge mode"));
		SIGNATURES.put("chambers of xeric cm", Collections.singletonList("chambers of xeric challenge mode"));
		SIGNATURES.put("tob", Collections.singletonList("theatre of blood"));
		SIGNATURES.put("tob hm", Collections.singletonList("theatre of blood hard mode"));
		SIGNATURES.put("tob hard mode", Collections.singletonList("theatre of blood hard mode"));
		SIGNATURES.put("theatre of blood hm", Collections.singletonList("theatre of blood hard mode"));
		SIGNATURES.put("toa", Collections.singletonList("tombs of amascut"));
		SIGNATURES.put("toa em", Collections.singletonList("tombs of amascut expert mode"));
		SIGNATURES.put("toa expert", Collections.singletonList("tombs of amascut expert mode"));
		SIGNATURES.put("toa expert mode", Collections.singletonList("tombs of amascut expert mode"));
		SIGNATURES.put("tombs of amascut em", Collections.singletonList("tombs of amascut expert mode"));
		SIGNATURES.put("fortis colosseum", Arrays.asList("sol heredit", "colosseum"));
		SIGNATURES.put("colosseum", Arrays.asList("sol heredit", "colosseum"));
		SIGNATURES.put("the nightmare", Collections.singletonList("nightmare"));
		SIGNATURES.put("nightmare", Collections.singletonList("nightmare"));
		SIGNATURES.put("phosani's nightmare", Collections.singletonList("phosani's nightmare"));
		SIGNATURES.put("tzhaar-ket-rak", Collections.singletonList("tzhaar-ket-rak"));
		// The completion line reads "Your Gauntlet completion count is: N" — it never contains
		// "the gauntlet", so a self-signature could never match. "your gauntlet completion" is
		// also Corrupted-safe: CG's line reads "your corrupted gauntlet completion count".
		SIGNATURES.put("the gauntlet", Arrays.asList("your gauntlet completion", "the gauntlet"));
		SIGNATURES.put("corrupted gauntlet", Collections.singletonList("corrupted gauntlet"));
		// Bosses whose kill-count line drops the article ("Your Leviathan kill count is: N"),
		// so a tile named with "The …" would miss on the plain-substring fallback.
		SIGNATURES.put("the leviathan", Collections.singletonList("leviathan"));
		SIGNATURES.put("the whisperer", Collections.singletonList("whisperer"));
		SIGNATURES.put("the hueycoatl", Collections.singletonList("hueycoatl"));
		SIGNATURES.put("the royal titans", Collections.singletonList("royal titans"));
		// "nex" is too short for the contains-fallback — "next" in any nearby line would
		// false-match. Pin it to the real kill-count line.
		SIGNATURES.put("nex", Collections.singletonList("your nex kill count"));
		// Sailing Barracuda Trials: no chat line ever says "barracuda", so a generic
		// any-trial tile needs the three course names. Tiles naming a specific course
		// ("Gwenith Glide") ride the plain fallback — both flanking lines name it.
		SIGNATURES.put("barracuda trials", Arrays.asList("tempor tantrum", "jubbly jive", "gwenith glide"));
		SIGNATURES.put("barracuda trial", Arrays.asList("tempor tantrum", "jubbly jive", "gwenith glide"));
		// Hallowed Sepulchre full runs: no chat line says "sepulchre" either — the exit
		// message is "Overall time: 26:39.20", which both carries the time and identifies
		// the run. Floor tiles ("Floor 5") ride the fallback against "Floor 5 time: ...".
		SIGNATURES.put("hallowed sepulchre", Collections.singletonList("overall time"));
		SIGNATURES.put("sepulchre", Collections.singletonList("overall time"));
	}

	/** Returns the clear time in whole seconds, or null if the message carries no duration. */
	static Integer parseDurationSeconds(String message)
	{
		if (message == null)
		{
			return null;
		}
		String lower = message.toLowerCase();
		// A ToA per-room / per-challenge sub-time — never the raid clear time. Ignore it so a
		// slow raid can't pass a timed tile off a fast final room (see RAID_SUBTIME).
		if (RAID_SUBTIME.matcher(lower).find())
		{
			return null;
		}
		Matcher m = DURATION.matcher(lower);
		if (!m.find())
		{
			return null;
		}
		String[] p = m.group(1).split(":");
		try
		{
			int s = p.length == 3
					? Integer.parseInt(p[0]) * 3600 + Integer.parseInt(p[1]) * 60 + Integer.parseInt(p[2])
					: Integer.parseInt(p[0]) * 60 + Integer.parseInt(p[1]);
			return s > 0 ? s : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static List<String> signaturesFor(String activity)
	{
		String a = norm(activity);
		List<String> s = SIGNATURES.get(a);
		if (s != null)
		{
			return s;
		}
		return a.isEmpty() ? Collections.emptyList() : Collections.singletonList(a);
	}

	/**
	 * Folds the punctuation/spacing admins add inconsistently so an activity string still matches the
	 * game's count line. Colons especially: the game writes CoX Challenge Mode with NO colon, yet
	 * "Chambers of Xeric: Challenge Mode" is the natural way to type it, and ToB/ToA modes DO carry a
	 * colon — dropping it on BOTH sides of the compare makes colons irrelevant either way.
	 */
	static String norm(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.toLowerCase(java.util.Locale.ROOT).replace(':', ' ').replaceAll("\\s+", " ").trim();
	}

	/** True when {@code message} contains any of the activity's identifying signatures. */
	static boolean messageMatchesActivity(String message, String activity)
	{
		if (message == null)
		{
			return false;
		}
		String nmsg = norm(message);
		for (String sig : signaturesFor(activity))
		{
			if (nmsg.contains(norm(sig)))
			{
				return true;
			}
		}
		return false;
	}

	static String formatClock(int totalSeconds)
	{
		int mm = totalSeconds / 60;
		int ss = totalSeconds % 60;
		return mm + ":" + (ss < 10 ? "0" + ss : String.valueOf(ss));
	}

	// ── Barracuda Trials (Sailing) rank tiles ──────────────────────────────────────────────────────
	// Each course awards a rank by time, but the three ranks are SEPARATE challenges (different routes,
	// each with its own PB) — so a rank tile must match the EXACT rank the game reports, never a time
	// cap (a Shark run is not just a slow Marlin run). The completion line names both:
	//   "You have completed the Gwenith Glide and achieved the Marlin rank."
	private static final String[] TRIAL_COURSES = { "tempor tantrum", "jubbly jive", "gwenith glide" };
	private static final String[] TRIAL_RANKS = { "swordfish", "shark", "marlin" };
	private static final Pattern TRIAL_COMPLETION = Pattern.compile("completed the (.+?) and achieved the (\\w+) rank");

	/** {course, rank} from a Barracuda Trials completion line, or null if this line isn't one. */
	static String[] parseTrialCompletion(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = TRIAL_COMPLETION.matcher(message.toLowerCase());
		if (!m.find())
		{
			return null;
		}
		String course = norm(m.group(1));
		String rank = m.group(2);
		for (String c : TRIAL_COURSES)
		{
			if (course.endsWith(c))
			{
				for (String r : TRIAL_RANKS)
				{
					if (rank.equals(r))
					{
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}

	/** {course, rank} a tile's activity targets (e.g. "Gwenith Glide — Marlin"), or null if it's not a rank tile. */
	static String[] trialTileTarget(String activity)
	{
		String a = norm(activity);
		if (a.isEmpty())
		{
			return null;
		}
		for (String r : TRIAL_RANKS)
		{
			if (a.endsWith(" " + r))
			{
				String course = a.substring(0, a.length() - r.length()).replaceAll("[^a-z]+$", "");
				for (String c : TRIAL_COURSES)
				{
					if (course.equals(c) || course.endsWith(c))
					{
						return new String[]{ c, r };
					}
				}
			}
		}
		return null;
	}
}

package com.anvil;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * What happened recently, so a saved clip can say what it caught.
 *
 * A clip posted as "<rsn> saved a clip 🎬" tells nobody whether they are about to watch a vestige
 * drop or someone walking to a bank. The plugin already knows: within the same few seconds it
 * notices drops, kills, tile completions, deaths and mission announces. This keeps a short trail of
 * those, and when the replay buffer is flushed the caller asks for the ones that fall inside the
 * clip's own window — the buffer holds the last N seconds of footage, so the moments from the last
 * N seconds are exactly what is in it.
 *
 * Deliberately tiny and dumb: a bounded deque of (timestamp, text), no allocation on the hot path
 * beyond one record, and no dependency on anything else in the plugin. Touched from the client
 * thread (game events) and read from the executor when a clip lands, so every method is synchronized.
 */
class ClipMoments
{
	/**
	 * A safety net, not the eviction policy — see RETENTION_MS.
	 *
	 * This used to be 40 with plain FIFO eviction, on the reasoning that a 60s buffer can't produce
	 * more than that. True of the WINDOW, false of the WAIT: OBS can take minutes to write a clip on
	 * a busy machine, and a raid fills 40 entries long before then, so by the time the file landed
	 * the moments it was supposed to describe had been evicted by newer ones.
	 */
	private static final int MAX_ENTRIES = 400;

	/**
	 * How long a moment is kept. Long enough that a clip whose file arrives late can still find what
	 * it caught; short enough that this never becomes a session-long log.
	 */
	private static final long RETENTION_MS = 15 * 60 * 1000L;

	/**
	 * Grace added to the clip window when selecting moments. OBS writes the file a moment after the
	 * event, and the buffer's start edge is approximate, so a strict cutoff drops the very drop the
	 * player clipped.
	 */
	private static final long WINDOW_GRACE_MS = 3000L;

	private static final class Moment
	{
		final long at;
		final String text;

		Moment(long at, String text)
		{
			this.at = at;
			this.text = text;
		}
	}

	private final Deque<Moment> entries = new ArrayDeque<>();

	/** Note something worth clipping. No-ops on blank text. */
	synchronized void record(String text)
	{
		record(text, System.currentTimeMillis());
	}

	/**
	 * The same, at an explicit time. Exists so tests can lay moments out across minutes without
	 * sleeping through them — the behaviour worth pinning here is entirely about WHEN things
	 * happened relative to each other, and a test that can't control that can't check it.
	 */
	synchronized void record(String text, long atMs)
	{
		if (text == null)
		{
			return;
		}
		String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return;
		}
		long now = atMs;
		// Age out first: dropping the oldest ENTRY is what let a busy raid evict the moments a
		// pending clip still needed. Dropping the oldest MINUTES can't.
		while (!entries.isEmpty() && now - entries.peekFirst().at > RETENTION_MS)
		{
			entries.removeFirst();
		}
		while (entries.size() >= MAX_ENTRIES)
		{
			entries.removeFirst();
		}
		entries.addLast(new Moment(now, trimmed));
	}

	synchronized void clear()
	{
		entries.clear();
	}

	/**
	 * A one-line summary of everything inside a clip of {@code windowSeconds}, newest first, or null
	 * when nothing notable happened. Duplicates collapse — ten kills of the same NPC in one window
	 * are one line, not ten.
	 *
	 * @param maxItems how many distinct moments to name before summarising the remainder
	 */
	synchronized String summarize(long asOfMs, int windowSeconds, int maxItems)
	{
		// The window is the footage: it ends when the clip was ASKED FOR, not when its file turned
		// up. Anchoring on "now" meant a clip OBS took ten minutes to write got captioned with
		// whatever happened in the last thirty seconds of those ten minutes — a drop the player
		// wasn't clipping, or a boss they'd since walked to.
		long end = asOfMs + WINDOW_GRACE_MS;
		long cutoff = asOfMs - (Math.max(1, windowSeconds) * 1000L) - WINDOW_GRACE_MS;
		// LinkedHashSet: dedup while keeping the order we walk them in (newest first).
		Set<String> recent = new LinkedHashSet<>();
		List<Moment> all = new ArrayList<>(entries);
		for (int i = all.size() - 1; i >= 0; i--)
		{
			Moment m = all.get(i);
			if (m.at > end)
			{
				continue; // happened after the clip ended — not in the footage
			}
			if (m.at < cutoff)
			{
				break; // entries are append-ordered, so everything earlier is older still
			}
			recent.add(m.text);
		}
		if (recent.isEmpty())
		{
			return null;
		}
		List<String> named = new ArrayList<>(recent);
		int limit = Math.max(1, maxItems);
		if (named.size() <= limit)
		{
			return String.join("\n", named);
		}
		String head = String.join("\n", named.subList(0, limit));
		int rest = named.size() - limit;
		return head + "\n…and " + rest + " more";
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * What killed us — as opposed to what we were killing.
 *
 * <p>The feed used to answer this with the last thing we landed a hit on, which is the only thing
 * the client volunteers and is wrong exactly when it matters. It reads fine at a boss, because the
 * boss you are hitting is the boss hitting you; it reads as nonsense the moment those differ, which
 * is why the clan feed filled up with "died to Abyssal portal", "died to Volatile earth" and, best
 * of all, "died to Jug". Those are things a player attacked. None of them killed anybody.
 *
 * <p>The game will not simply tell us. A hitsplat carries a type and an amount and no attacker
 * ({@link net.runelite.api.Hitsplat}), so "who dealt that damage" is not a question the API answers.
 * What it does answer is who is TARGETING us: an NPC or player acquiring us fires an interaction
 * change naming itself. So the killer is inferred from the things that had us in their sights when
 * we last took damage, which is a different guess from the old one and wrong in far fewer places.
 *
 * <p>When nothing was on us — a mechanic, a fall, poison after the fight — the answer is null and
 * the feed says only that someone died. That is a deliberate downgrade from the old behaviour: a
 * death with no killer is a smaller story than a death with the wrong one.
 *
 * <p>Pure and RuneLite-free so it is unit-tested directly (DeathAttributionTest). The plugin feeds
 * it names; it never holds an Actor, which would keep a dead NPC alive for as long as we did.
 */
final class DeathAttribution
{
	/**
	 * How long an attacker stays a candidate after we last took a hit. Long enough to cover the
	 * gap between a killing blow and the death animation, short enough that the thing that killed
	 * us half a minute ago in another fight is not still on the list.
	 */
	private static final long DAMAGE_WINDOW_MS = 15_000;

	/** Nothing sane has this many things attacking it; the cap is against a leak, not a crowd. */
	private static final int MAX_ATTACKERS = 24;

	/** Who has us targeted, and when they acquired us. Insertion-ordered so "most recent" is cheap. */
	private final Map<String, Long> attackers = new LinkedHashMap<>();

	/** When we last took damage from something other than ourselves. */
	private long lastDamageAt;

	/**
	 * Something acquired us as its target.
	 *
	 * <p>Re-acquiring refreshes the timestamp: an NPC that switches away and back is a better
	 * candidate than one that has been plinking at us since the start of the fight, because the
	 * thing that just turned to face you is the thing that just started hitting you.
	 */
	synchronized void targetedUs(String name, long nowMs)
	{
		if (name == null || name.isEmpty())
		{
			return;
		}
		attackers.remove(name); // re-insert so iteration order stays "oldest first"
		attackers.put(name, nowMs);
		while (attackers.size() > MAX_ATTACKERS)
		{
			attackers.remove(attackers.keySet().iterator().next());
		}
	}

	/** Something stopped targeting us — it is no longer a candidate for killing us. */
	synchronized void stoppedTargetingUs(String name)
	{
		if (name != null)
		{
			attackers.remove(name);
		}
	}

	/** We took a hit from something other than ourselves. Only the timing matters; see the class doc. */
	synchronized void tookDamage(long nowMs)
	{
		lastDamageAt = nowMs;
	}

	/** Forget everything. A new login, a new region, a fresh death — none of it carries over. */
	synchronized void clear()
	{
		attackers.clear();
		lastDamageAt = 0;
	}

	/**
	 * The killer, or null when nothing can honestly be named.
	 *
	 * <p>Two rules, in order:
	 *
	 * <ol>
	 *   <li>if one of the things targeting us is the thing we were fighting, it is that one — a
	 *       mutual fight is the least ambiguous case there is, and it is most deaths;
	 *   <li>otherwise the one that acquired us most recently, because in a room where several
	 *       things are on you the one that just turned to face you is the one that finished it.
	 * </ol>
	 *
	 * <p>Null when nothing had us targeted, or when the last damage we took is too old to connect
	 * to this death at all.
	 *
	 * @param weWereFighting the last thing we landed a hit on, used only to break a tie
	 */
	synchronized String killer(String weWereFighting, long nowMs)
	{
		if (lastDamageAt <= 0 || nowMs - lastDamageAt > DAMAGE_WINDOW_MS || attackers.isEmpty())
		{
			return null;
		}
		if (weWereFighting != null && !weWereFighting.isEmpty())
		{
			String fighting = weWereFighting.toLowerCase(Locale.ROOT);
			for (String name : attackers.keySet())
			{
				if (name.toLowerCase(Locale.ROOT).equals(fighting))
				{
					return name;
				}
			}
		}
		String newest = null;
		long newestAt = Long.MIN_VALUE;
		for (Map.Entry<String, Long> entry : attackers.entrySet())
		{
			if (entry.getValue() >= newestAt)
			{
				newestAt = entry.getValue();
				newest = entry.getKey();
			}
		}
		return newest;
	}

	/** How many things currently have us targeted — for the log line that explains an attribution. */
	synchronized int attackerCount()
	{
		return attackers.size();
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * The hiscores counters that are neither a boss nor a skill — clue completions per tier, Colosseum
 * glory, collection-log slots — read from the client instead of waited for.
 *
 * <p>The site can score a tile on any of these, but its only source was the 15-minute hiscores
 * sweep, so "20 elite clues" sat still while every other tile on the board moved within seconds of
 * the kill. The game already knows these numbers; this is just reporting them.
 *
 * <p><b>Only counters the client can actually read are here.</b> The site also offers LMS, PvP
 * Arena and Bounty Hunter — those are hiscores RANKS with no in-game equivalent — and GOTR, which
 * has per-game varbits but no absolute rifts-closed total. Soul Wars is left out for a subtler
 * reason: the varp is a spendable zeal BALANCE while the hiscores counter is zeal EARNED, and a
 * balance is not a smaller-but-honest version of a total, it's a different number. All of those
 * keep their sweep-only behaviour, which is what they had before this existed.
 *
 * <p>Values are absolute and the server keeps {@code max(hiscores, pushed)}, so a counter the
 * client hasn't populated yet (an unsynced collection log reads 0) can never walk a tile backwards.
 * Zero and negative reads are dropped here anyway rather than sent as a no-op request.
 *
 * <p>RuneLite-free apart from the id constants, so the mapping is unit-testable without a client.
 */
final class ActivityStats
{
	/** Where a counter lives — the two id spaces are separate, so the kind picks the reader. */
	private enum Kind
	{
		VARBIT,
		VARP
	}

	private static final class Source
	{
		final Kind kind;
		final int id;

		Source(Kind kind, int id)
		{
			this.kind = kind;
			this.id = id;
		}
	}

	/** Clue tiers, in the order the hiscores lists them. {@code cluesAll} is their sum. */
	private static final int[] CLUE_TIER_VARBITS = {
		VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED,
		VarbitID.COLLECTION_CLUES_EASY_COMPLETED,
		VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED,
		VarbitID.COLLECTION_CLUES_HARD_COMPLETED,
		VarbitID.COLLECTION_CLUES_ELITE_COMPLETED,
		VarbitID.COLLECTION_CLUES_MASTER_COMPLETED,
	};

	/** Site tracked-stat key -> where to read it. Keys mirror lib/hiscoresActivities.ts exactly. */
	private static final Map<String, Source> SOURCES;

	/** The site's key for the summed clue total, which has no single counter of its own. */
	static final String CLUES_ALL = "cluesAll";

	static
	{
		Map<String, Source> m = new LinkedHashMap<>();
		m.put("cluesBeginner", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_BEGINNER_COMPLETED));
		m.put("cluesEasy", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_EASY_COMPLETED));
		m.put("cluesMedium", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_MEDIUM_COMPLETED));
		m.put("cluesHard", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_HARD_COMPLETED));
		m.put("cluesElite", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_ELITE_COMPLETED));
		m.put("cluesMaster", new Source(Kind.VARBIT, VarbitID.COLLECTION_CLUES_MASTER_COMPLETED));
		m.put("colosseumGlory", new Source(Kind.VARP, VarPlayerID.COLOSSEUM_GLORY));
		m.put("collectionsLogged", new Source(Kind.VARP, VarPlayerID.COLLECTION_COUNT));
		SOURCES = Collections.unmodifiableMap(m);
	}

	/** Every key this can report, for callers that want to filter the site's list down to the real ones. */
	static Set<String> readableKeys()
	{
		Set<String> keys = new HashSet<>(SOURCES.keySet());
		keys.add(CLUES_ALL);
		return keys;
	}

	static boolean isReadable(String key)
	{
		return key != null && (SOURCES.containsKey(key) || CLUES_ALL.equals(key));
	}

	/**
	 * True when a varbit/varp change could have moved one of these counters, so the caller can
	 * re-read on the event rather than polling every tick.
	 *
	 * <p>Only the varbit ids are matched, not the varps that back them — a caller that misses an
	 * edge here loses nothing but latency, because the periodic re-read is the actual guarantee.
	 * Passing -1 (RuneLite's "not a varbit"/"not a varp") never matches.
	 */
	static boolean isTrigger(int varbitId, int varpId)
	{
		for (Source s : SOURCES.values())
		{
			if (s.kind == Kind.VARBIT ? s.id == varbitId : s.id == varpId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Read every wanted key the client can answer for. Unknown or unreadable keys are skipped, as
	 * are non-positive values — a counter reading 0 is almost always one the client hasn't synced
	 * (an unopened collection log), and pushing it would be a request that changes nothing.
	 *
	 * @param wanted the site's tracked activity keys; null/empty reads nothing
	 * @param varbit reads a varbit by id (normally {@code client::getVarbitValue})
	 * @param varp   reads a varplayer by id (normally {@code client::getVarpValue})
	 */
	static Map<String, Integer> read(Collection<String> wanted, IntUnaryOperator varbit, IntUnaryOperator varp)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		if (wanted == null || wanted.isEmpty())
		{
			return out;
		}
		for (String key : wanted)
		{
			if (key == null)
			{
				continue;
			}
			String k = key.trim();
			int value;
			if (CLUES_ALL.equals(k))
			{
				value = Arrays.stream(CLUE_TIER_VARBITS).map(varbit).map(v -> Math.max(0, v)).sum();
			}
			else
			{
				Source s = SOURCES.get(k);
				if (s == null)
				{
					continue; // a rank-based or unreadable key — the hiscores sweep still covers it
				}
				value = s.kind == Kind.VARBIT ? varbit.applyAsInt(s.id) : varp.applyAsInt(s.id);
			}
			if (value > 0)
			{
				out.put(k, value);
			}
		}
		return out;
	}

	/**
	 * The collection log's own completion line — "548/1712 (32.0%)" — for a new-slot post.
	 *
	 * <p>Lives here because it reads the same varps as {@code collectionsLogged} and the ids are
	 * worth keeping in one place.
	 *
	 * <p>Returns null rather than a guess whenever the client can't answer: both varps read 0 until
	 * the collection log has been synced this session, and a count above its own maximum means we're
	 * reading something other than what we think. A missing field in a clan post is unremarkable; a
	 * wrong number in one gets repeated.
	 */
	static String clogProgress(IntUnaryOperator varp)
	{
		int obtained = clogSlots(varp);
		int total = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT_MAX);
		if (obtained <= 0 || total <= 0 || obtained > total)
		{
			return null;
		}
		double percent = (obtained * 100d) / total;
		return String.format(java.util.Locale.ROOT, "%d/%d (%.1f%%)", obtained, total, percent);
	}

	/**
	 * Unique collection-log slots obtained, or 0 when the client can't answer (the log hasn't synced
	 * this session, or the count exceeds its own maximum and is therefore not what we think it is).
	 * Same guard as {@link #clogProgress}, exposed as a number so callers can rank it.
	 */
	static int clogSlots(IntUnaryOperator varp)
	{
		int obtained = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT);
		int total = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT_MAX);
		return obtained > 0 && total > 0 && obtained <= total ? obtained : 0;
	}

	/**
	 * Total collection-log slots in the game, or 0 when unreadable. Needed to place the Gilded rank,
	 * which is a proportion of the total rather than a fixed number (see {@link ClogRank}).
	 */
	static int clogSlotsMax(IntUnaryOperator varp)
	{
		int total = varp.applyAsInt(VarPlayerID.COLLECTION_COUNT_MAX);
		return Math.max(0, total);
	}

	private ActivityStats()
	{
	}
}

package com.anvil;

/**
 * Schedules one step of a polling flow to run later, off the Swing EDT.
 *
 * Production binds RuneLite's shared {@link java.util.concurrent.ScheduledExecutorService}; tests
 * bind a scheduler that runs the step inline, so a sign-in loop that would take two minutes of
 * wall-clock finishes in a millisecond and asserts deterministically.
 *
 * <p>Hoisted out of the federation data source for the same reason as {@link BrowserOpener}: the
 * device sign-in poll outlives federation.</p>
 */
@FunctionalInterface
public interface PollScheduler
{
	void schedule(Runnable step, long delayMs);
}

package com.anvil;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pulls a personal best out of a completion message.
 *
 * <p>Two shapes, and the difference matters — reading the wrong number would record a slow run as
 * somebody's best:
 * <pre>
 *   "Duration: 2:58.03 (new personal best)"          → the PB is the duration, 2:58.03
 *   "Challenge duration: 10:24. Personal best: 7:59." → the PB is 7:59, NOT this run's 10:24
 * </pre>
 *
 * <p>Times are returned in <b>centiseconds</b>. The game prints hundredths and a leaderboard that
 * rounded to whole seconds would tie runs the game itself separates.
 *
 * <p>The activity is deliberately NOT parsed here: the plugin already extracts it from the adjacent
 * "Your X kill count is: N" line for kill crediting, so PB capture reuses that instead of running a
 * second regex over every line of chat. RuneLite-free, so the fragile part is unit-tested.
 */
final class PersonalBestParser
{
	private PersonalBestParser() {}

	/** An [h:]mm:ss[.cc] token. The game never prints a bare seconds count for a PB. */
	private static final Pattern TIME = Pattern.compile("(\\d{1,3}):(\\d{2})(?::(\\d{2}))?(?:\\.(\\d{1,2}))?");
	/** "personal best: 7:59" — the explicit form, where this run was NOT the best. */
	private static final Pattern EXPLICIT = Pattern.compile("personal best:\\s*");

	/**
	 * The personal best this line reports, in centiseconds, or null when it reports none.
	 */
	static Integer parseCentis(String message)
	{
		if (message == null)
		{
			return null;
		}
		String lower = message.toLowerCase();
		int marker = lower.indexOf("personal best");
		if (marker < 0)
		{
			return null;
		}

		// "Personal best: <time>" — read the time AFTER the label, and only that one.
		Matcher explicit = EXPLICIT.matcher(lower);
		if (explicit.find(marker))
		{
			Matcher time = TIME.matcher(lower);
			if (time.find(explicit.end()))
			{
				return toCentis(time);
			}
			return null;
		}

		// "(new personal best)" — this run IS the best, so the line's own duration is the number.
		Matcher time = TIME.matcher(lower);
		if (time.find())
		{
			return toCentis(time);
		}
		return null;
	}

	private static Integer toCentis(Matcher m)
	{
		try
		{
			int a = Integer.parseInt(m.group(1));
			int b = Integer.parseInt(m.group(2));
			// Three parts means h:mm:ss; two means mm:ss.
			int seconds = m.group(3) != null
				? a * 3600 + b * 60 + Integer.parseInt(m.group(3))
				: a * 60 + b;
			int centis = seconds * 100;
			String fraction = m.group(4);
			if (fraction != null)
			{
				// ".3" is three tenths — pad to hundredths rather than reading it as three.
				centis += fraction.length() == 1
					? Integer.parseInt(fraction) * 10
					: Integer.parseInt(fraction);
			}
			return centis > 0 ? centis : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.anvil;

import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.io.Writer;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class PendingSubmissionStore
{
	// Garbage-collect pending submissions older than this. Prevents unbounded disk growth
	// when retries keep failing (e.g. site URL permanently wrong) and the user never clears.
	private static final long MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000; // 7 days

	/**
	 * The plugin's own directory, handed over by AnvilPlugin — the only class allowed to ask for it.
	 *
	 * THE ROOT ITSELF, not a subfolder, and that is the migration's doing rather than a preference:
	 * `legacyDataDirectory` MOVES `.runelite/osrs-bingo-pending` to BE the plugin directory, so
	 * everything that folder held arrives at its root. Reading from anywhere else would mean not
	 * finding the very files the migration exists to carry across.
	 *
	 * Null until startUp resolves it, and null forever if that failed. Every method treats that as
	 * "no store": nothing queues, nothing loads, and the caller's own error path takes over — which
	 * is the same thing that happened when the disk was full.
	 */
	private volatile Filepath root;

	private final Gson gson;

	@Inject
	public PendingSubmissionStore(Gson gson)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	public static class PendingSubmission
	{
		public int eventId;
		public int tileId;
		public int teamId;
		public int playerId;
		public int amount;
		public String label;
		public String note;
		public String screenshotFile; // filename of PNG in pending dir
		public long timestamp;
		public Integer itemId; // specific item ID for per-item tracking (nullable)
		public Integer durationSeconds; // timed-tile clear time in seconds (nullable; non-null routes to submitTimed)
		public String capturedRsn; // character the drop was obtained on; only re-submitted while on it
		// A proof the plugin can't auto-submit to a specific tile (pet drop, duplicate Champion's
		// scroll — the "would have received" line names no item), captured so the player has a ready
		// screenshot to attach when they submit by hand on the site. The retry loop skips these.
		public boolean manual;
	}

	public void setRoot(Filepath dir)
	{
		this.root = dir;
	}

	/** The directory, created on demand, or null when there is nowhere to write. */
	private Filepath dir()
	{
		Filepath d = root;
		if (d == null)
		{
			return null;
		}
		try
		{
			if (!d.exists())
			{
				d.createDirectories();
			}
			return d;
		}
		catch (IOException e)
		{
			log.warn("Anvil: cannot create the pending-submission directory: {}", e.getMessage());
			return null;
		}
	}

	public String save(PendingSubmission sub, byte[] pngBytes)
	{
		Filepath dir = dir();
		if (dir == null)
		{
			return null;
		}
		String id = sub.tileId + "-" + sub.timestamp;

		Filepath png = dir.joinSegment(id + ".png");
		try
		{
			png.write(pngBytes);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending screenshot: {}", e.getMessage());
			return null;
		}

		sub.screenshotFile = id + ".png";
		try (Writer w = dir.joinSegment(id + ".json").openWriter())
		{
			gson.toJson(sub, w);
		}
		catch (IOException e)
		{
			log.error("Failed to save pending submission metadata: {}", e.getMessage());
			// The PNG without its metadata is an orphan nothing will ever read.
			try
			{
				png.deleteIfExists();
			}
			catch (IOException ignored)
			{
				// Already logged the real failure; a leftover file is the lesser problem.
			}
			return null;
		}

		log.info("Saved pending submission: {} (tile '{}')", id, sub.label);
		return id;
	}

	public List<PendingSubmission> loadAll()
	{
		List<PendingSubmission> result = new ArrayList<>();
		List<Filepath> jsonFiles = listJson();
		long now = System.currentTimeMillis();
		for (Filepath f : jsonFiles)
		{
			try (Reader r = f.openReader())
			{
				PendingSubmission sub = gson.fromJson(r, PendingSubmission.class);
				if (sub != null && sub.timestamp > 0 && (now - sub.timestamp) > MAX_AGE_MS)
				{
					log.info("Pruning expired pending submission '{}' ({} days old)",
						sub.label, (now - sub.timestamp) / (24 * 60 * 60 * 1000));
					remove(sub);
					continue;
				}
				result.add(sub);
			}
			catch (Exception e)
			{
				log.warn("Failed to read pending submission {}: {}", f.getFileName(), e.getMessage());
			}
		}
		return result;
	}

	/**
	 * The queued metadata files, one per waiting submission.
	 *
	 * Depth 1 rather than a full walk: the migration drops these at the root of the plugin directory
	 * alongside `sounds/` and `debug/`, and descending would read a banner clip's neighbours looking
	 * for JSON.
	 */
	private List<Filepath> listJson()
	{
		Filepath dir = dir();
		if (dir == null)
		{
			return new ArrayList<>();
		}
		try (java.util.stream.Stream<Filepath> walk = dir.walk(1))
		{
			return walk
				.filter(f -> f.isFile() && f.getFileName().endsWith(".json"))
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.warn("Failed to list pending submissions: {}", e.getMessage());
			return new ArrayList<>();
		}
	}

	public byte[] readScreenshot(PendingSubmission sub)
	{
		Filepath dir = dir();
		if (dir == null || sub.screenshotFile == null)
		{
			return null;
		}
		// joinSegment, not join: it refuses a separator, so a screenshotFile read back out of a JSON
		// file cannot walk anywhere with "../" in it.
		try (InputStream in = dir.joinSegment(sub.screenshotFile).openInputStream())
		{
			return readAll(in);
		}
		catch (IOException | RuntimeException e)
		{
			log.error("Failed to read pending screenshot {}: {}", sub.screenshotFile, e.getMessage());
			return null;
		}
	}

	private static byte[] readAll(InputStream in) throws IOException
	{
		java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
		byte[] buf = new byte[8192];
		int n;
		while ((n = in.read(buf)) > 0)
		{
			out.write(buf, 0, n);
		}
		return out.toByteArray();
	}

	public void remove(PendingSubmission sub)
	{
		Filepath dir = dir();
		if (dir == null || sub.screenshotFile == null)
		{
			return;
		}
		String baseName = sub.screenshotFile.replace(".png", "");
		try
		{
			dir.joinSegment(baseName + ".png").deleteIfExists();
			dir.joinSegment(baseName + ".json").deleteIfExists();
			log.info("Removed pending submission: {} (tile '{}')", baseName, sub.label);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to remove pending submission {}: {}", baseName, e.getMessage());
		}
	}

	/** Number of submissions still waiting to upload. */
	public int count()
	{
		return listJson().size();
	}

	/** Puts the pending-proofs folder on the clipboard, off the calling thread. */
	public void copyFolderPath()
	{
		Filepath dir = dir();
		if (dir == null)
		{
			return;
		}
		// LinkBrowser::open is restricted for hub releases, so the path goes on the clipboard and the
		// player pastes it wherever they were going to open it.
		Clipboards.copy(dir.toString());
	}
}

package com.anvil;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;
import java.time.Duration;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Uploads an on-demand OBS replay clip straight to a Discord webhook URL that the USER pastes into
 * the plugin config (Clips section). Nothing else posts to Discord from the plugin: deaths, kills,
 * rare drops and CAs all go through {@link BingoApiClient#postNotification} to our own server, which
 * forwards them. Clips are the one exception because a multi-MB video can't be proxied through the
 * site's request-body limit — and a user-supplied webhook URL is allowed by the plugin hub (unlike a
 * URL handed to us inside a server response).
 *
 * Kept deliberately separate from {@link BingoApiClient}: this talks to discord.com, carries no
 * site auth, and never persists — the upload is throwaway, unlike bingo drops.
 *
 * The upload uses OkHttp's async dispatcher so the round-trip runs off both the game thread and the
 * plugin's executor. Nothing here can stall the client.
 *
 * Rate limits: on a 429 we re-enqueue with the server's Retry-After plus randomized jitter, so
 * simultaneous clients don't retry in lockstep and re-collide (thundering herd).
 */
@Slf4j
@Singleton
public class DiscordWebhookClient
{
	// Discord hard-caps webhook message content at 2000 chars.
	private static final int MAX_CONTENT = 2000;
	// A throwaway notification isn't worth hammering Discord over — a couple of polite retries is plenty.
	private static final int MAX_RETRIES = 2;
	private static final long MAX_RETRY_MS = 10_000L;
	private static final long DEFAULT_RETRY_MS = 1_000L;
	private static final long MAX_JITTER_MS = 500L;

	// Clips are multi-MB video uploads; the shared RuneLite client's short write timeout aborts them
	// mid-upload on slower connections. Give file posts their own generous timeouts (pool/dispatcher
	// are still shared via newBuilder, so this is cheap).
	private final OkHttpClient uploadClient;

	/** RuneLite's shared client-lifetime scheduler — paces 429 retries; nothing to shut down here. */
	private final ScheduledExecutorService retryScheduler;

	@Inject
	public DiscordWebhookClient(OkHttpClient client, ScheduledExecutorService retryScheduler)
	{
		this.retryScheduler = retryScheduler;
		this.uploadClient = client.newBuilder()
			.callTimeout(Duration.ofSeconds(120))
			.writeTimeout(Duration.ofSeconds(120))
			.readTimeout(Duration.ofSeconds(60))
			.build();
	}

	/**
	 * Post a text message with a file attached (e.g. a video clip) via Discord multipart, streaming
	 * straight from disk on the long-timeout upload client. {@code onComplete} receives true only on a
	 * 2xx (after any retries) so the caller can report real success/failure instead of guessing.
	 * Discord infers preview from the filename extension; {@code contentType} is the part's media type.
	 */
	public void sendWithFile(String webhookUrl, String content, byte[] data, String filename, String contentType, Consumer<Boolean> onComplete)
	{
		if (isBlank(webhookUrl) || data == null || data.length == 0)
		{
			if (onComplete != null)
			{
				onComplete.accept(false);
			}
			return;
		}
		MediaType type = MediaType.parse(contentType != null ? contentType : "application/octet-stream");
		JsonObject payload = buildPayload(content, null);
		MultipartBody multipart = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("payload_json", payload.toString())
			.addFormDataPart("files[0]", filename, RequestBody.create(type, data))
			.build();
		enqueue(uploadClient, new Request.Builder().url(webhookUrl).post(multipart).build(), onComplete);
	}

	private JsonObject buildPayload(String content, JsonObject embed)
	{
		JsonObject payload = new JsonObject();
		if (!isBlank(content))
		{
			payload.addProperty("content", truncate(content));
		}
		if (embed != null)
		{
			JsonArray embeds = new JsonArray();
			embeds.add(embed);
			payload.add("embeds", embeds);
		}
		return payload;
	}

	private void enqueue(OkHttpClient client, Request request, Consumer<Boolean> onComplete)
	{
		enqueueWithRetry(client, request, 0, onComplete);
	}

	private void enqueueWithRetry(OkHttpClient client, Request request, int attempt, Consumer<Boolean> onComplete)
	{
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Anvil webhook post failed: {}", e.getMessage());
				complete(onComplete, false);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				// Drain + close so the connection can be reused.
				try (Response r = response)
				{
					if (r.code() == 429 && attempt < MAX_RETRIES)
					{
						long delayMs = retryDelayMs(r);
						log.debug("Anvil webhook rate-limited, retry {} in {}ms", attempt + 1, delayMs);
						retryScheduler.schedule(
							() -> enqueueWithRetry(client, request, attempt + 1, onComplete),
							delayMs, TimeUnit.MILLISECONDS);
						return;
					}
					if (!r.isSuccessful())
					{
						log.debug("Anvil webhook returned HTTP {}", r.code());
						complete(onComplete, false);
						return;
					}
					complete(onComplete, true);
				}
			}
		});
	}

	private static void complete(Consumer<Boolean> onComplete, boolean ok)
	{
		if (onComplete != null)
		{
			onComplete.accept(ok);
		}
	}

	/** Honor Discord's Retry-After (seconds, may be fractional), capped, plus jitter to de-sync clients. */
	private static long retryDelayMs(Response r)
	{
		long base = DEFAULT_RETRY_MS;
		String header = r.header("Retry-After");
		if (header != null && !header.isEmpty())
		{
			try
			{
				base = (long) Math.ceil(Double.parseDouble(header.trim()) * 1000.0);
			}
			catch (NumberFormatException ignored)
			{
				// Header wasn't a number — stick with the default.
			}
		}
		base = Math.max(0L, Math.min(base, MAX_RETRY_MS));
		return base + ThreadLocalRandom.current().nextLong(MAX_JITTER_MS + 1);
	}

	private static String truncate(String s)
	{
		return s.length() <= MAX_CONTENT ? s : s.substring(0, MAX_CONTENT);
	}

	private static boolean isBlank(String s)
	{
		return s == null || s.isEmpty();
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Singleton;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.util.Filepath;

/**
 * WHERE A CLIP IS, AND WHETHER WE MAY READ IT.
 *
 * <p>OBS writes the replay buffer wherever OBS is configured to, and tells us the absolute path over
 * the websocket. That path is a string, and a string cannot become a {@link Filepath}: the only ways
 * a plugin gets one are its own directory and a folder the player picks in a chooser. So the upload
 * needs the clip to be in one of exactly two places:
 *
 * <ul>
 *   <li>OUR OWN clips folder, when the player let the plugin point OBS at it. Nothing to ask, ever.
 *   <li>A FOLDER THE PLAYER GRANTED this session, by picking their OBS recordings folder once.
 * </ul>
 *
 * <p>The grant lasts one session and cannot be remembered: there is no public way to rebuild a
 * Filepath from a stored path, and RuneLite's config cannot serialize one. That is the reason the
 * managed-folder option exists at all — it is the only way to never be asked again.
 *
 * <p>A clip we may not read is not lost. The caller queues it, and a grant later in the session
 * posts it retroactively: the file is still sitting where OBS left it.
 */
@Slf4j
@Singleton
class ClipFolder
{
	/** Unsent clips in OUR folder are swept on startup — a failed upload must not fill someone's disk. */
	private static final long PRUNE_AFTER_MS = 7L * 24 * 60 * 60 * 1000;
	/** Keep the sweep honest even if the clock is odd: never leave more than this many behind. */
	private static final int MAX_KEPT = 30;

	/** Our own clips directory, inside the plugin directory. Always readable. */
	private volatile Filepath clipsDir;
	/** The OBS recordings folder the player picked. Null until they do; forgotten on shutdown. */
	private volatile Filepath granted;
	/** One ask per session. Dismissing it means dismissed, not "ask again on the next clip". */
	private volatile boolean asked;

	void setRoot(Filepath dir)
	{
		this.clipsDir = dir;
	}

	/** Our own clips folder as an OS path, for handing to OBS. Null when it can't be created. */
	String managedPath()
	{
		Filepath dir = ensureClipsDir();
		return dir == null ? null : dir.toString();
	}

	/** True once the player has been asked this session, whatever they answered. */
	boolean asked()
	{
		return asked;
	}

	/**
	 * The clip OBS just named, as something we are allowed to open — or null when it landed somewhere
	 * we may not read.
	 *
	 * <p>Matched by FILE NAME inside a folder we hold, never by the path OBS gave us: the path is the
	 * thing we are not allowed to act on. Our own folder is tried first, so a managed setup never
	 * depends on a grant.
	 */
	Filepath locate(String obsPath)
	{
		String name = fileName(obsPath);
		if (name == null)
		{
			return null;
		}
		for (Filepath dir : new Filepath[]{clipsDir, granted})
		{
			if (dir == null)
			{
				continue;
			}
			try
			{
				Filepath candidate = dir.joinSegment(name);
				if (candidate.isFile())
				{
					return candidate;
				}
			}
			catch (Exception e)
			{
				// A name this directory won't accept (traversal, a reserved device name) is simply not
				// a clip we can reach — the next folder still gets its turn.
				log.debug("Anvil clips: {} not resolvable in {}: {}", name, dir, e.getMessage());
			}
		}
		return null;
	}

	/** True when this clip is ours to delete after posting — i.e. it is in our own folder. */
	boolean isOurs(Filepath clip)
	{
		Filepath dir = clipsDir;
		return dir != null && clip != null && clip.startsWith(dir);
	}

	/**
	 * The last segment of a path OBS reported. Handles both separators because OBS reports Windows
	 * paths with backslashes and everything else with forward slashes, and the plugin may be running
	 * on a different OS than the string implies is only true for a remote OBS — which is exactly the
	 * case where the file is unreachable anyway.
	 */
	static String fileName(String path)
	{
		if (path == null)
		{
			return null;
		}
		String trimmed = path.trim();
		while (trimmed.endsWith("/") || trimmed.endsWith("\\"))
		{
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		int cut = Math.max(trimmed.lastIndexOf('/'), trimmed.lastIndexOf('\\'));
		String name = cut >= 0 ? trimmed.substring(cut + 1) : trimmed;
		return name.isEmpty() ? null : name;
	}

	/** What the player chose when asked how clips should reach Discord. */
	enum Ask
	{
		/** Let the plugin point OBS at its own folder, for good. Never asked again. */
		MANAGE,
		/** They picked their OBS recordings folder. Lasts until RuneLite closes. */
		GRANTED,
		/** Neither. Clips go on the clipboard and they paste them. */
		DISMISSED
	}

	/**
	 * Ask how clips should reach Discord. Once per session, whatever they answer.
	 *
	 * <p>BOTH ANSWERS ARE OFFERED HERE, because the difference between them is not a preference — it
	 * is "be asked every session" versus "never again", and nobody goes looking in a settings panel
	 * for a choice they don't know exists. The permanent option costs them OBS's recording folder
	 * while RuneLite runs, so it is stated plainly rather than made the quiet default.
	 *
	 * <p>MUST NOT be called on the client thread — it blocks on a modal dialog. The caller picks the
	 * moment: the login screen, never mid-clip.
	 *
	 * @param obsDir where OBS says it records. We may name it; we may not open it.
	 */
	Ask ask(Client client, String obsDir)
	{
		if (asked)
		{
			return granted != null ? Ask.GRANTED : Ask.DISMISSED;
		}
		asked = true;
		Ask choice = chooseHow(obsDir);
		if (choice != Ask.GRANTED)
		{
			return choice;
		}
		return pickFolder(client, obsDir) ? Ask.GRANTED : Ask.DISMISSED;
	}

	/** The three-way question, on the EDT, on top of the client. */
	private Ask chooseHow(String obsDir)
	{
		String[] options = {"Let Anvil handle it", "Pick my OBS folder", "Not now"};
		String where = obsDir == null || obsDir.isEmpty() ? "your OBS recordings folder" : obsDir;
		String message = "<html><body style='width:380px'>"
			+ "<b>Post your clips to Discord automatically?</b><br><br>"
			+ "Anvil can post a clip the moment OBS saves it, but it has to read the file first — and "
			+ "RuneLite only lets a plugin read its own folder, or one you pick each time you play.<br><br>"
			+ "<b>Let Anvil handle it</b> — Anvil points OBS at its own clips folder while RuneLite is "
			+ "running, and puts your setting back when it closes. Your ordinary OBS recordings will "
			+ "save there too. You won't be asked again.<br><br>"
			+ "<b>Pick my OBS folder</b> — choose " + escape(where) + " yourself. Nothing of yours changes, "
			+ "but you'll be asked again next time you start RuneLite.<br><br>"
			+ "<b>Not now</b> — each clip goes on your clipboard instead, ready to paste into Discord."
			+ "</body></html>";
		final int[] picked = {2};
		try
		{
			Runnable show = () ->
			{
				JOptionPane pane = new JOptionPane(message, JOptionPane.QUESTION_MESSAGE,
					JOptionPane.DEFAULT_OPTION, null, options, options[0]);
				JDialog dialog = pane.createDialog("Anvil — clips");
				// The client is full-screen for a lot of people; a dialog behind it is a hang as far as
				// anyone can tell.
				dialog.setAlwaysOnTop(true);
				dialog.setVisible(true);
				dialog.dispose();
				Object value = pane.getValue();
				for (int i = 0; i < options.length; i++)
				{
					if (options[i].equals(value))
					{
						picked[0] = i;
					}
				}
			};
			if (SwingUtilities.isEventDispatchThread())
			{
				show.run();
			}
			else
			{
				SwingUtilities.invokeAndWait(show);
			}
		}
		catch (Exception e)
		{
			log.debug("Anvil clips: prompt failed: {}", e.getMessage());
			return Ask.DISMISSED;
		}
		switch (picked[0])
		{
			case 0:
				return Ask.MANAGE;
			case 1:
				return Ask.GRANTED;
			default:
				return Ask.DISMISSED;
		}
	}

	/** The folder chooser itself. True when they picked one. */
	private boolean pickFolder(Client client, String obsDir)
	{
		try
		{
			String title = obsDir == null || obsDir.isEmpty()
				? "Anvil — pick the folder OBS saves clips to"
				: "Anvil — pick the folder OBS saves clips to:  " + obsDir;
			List<Filepath> picked = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsDirectories()
				.setDialogTitle(title)
				.showDialog(client);
			if (picked == null || picked.isEmpty())
			{
				return false;
			}
			granted = picked.get(0);
			log.debug("Anvil clips: folder granted");
			return true;
		}
		catch (Exception e)
		{
			log.debug("Anvil clips: folder chooser failed: {}", e.getMessage());
			return false;
		}
	}

	/** The OBS path lands inside HTML, and Windows paths are full of characters that is fussy about. */
	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * Delete clips we kept but never sent. Only ever our OWN folder — a granted folder is the
	 * player's recordings, and nothing of theirs is ours to remove.
	 */
	void prune()
	{
		Filepath dir = clipsDir;
		if (dir == null || !dir.isDirectory())
		{
			return;
		}
		try (java.util.stream.Stream<Filepath> walk = dir.walk(1))
		{
			List<Filepath> files = walk.filter(Filepath::isFile).collect(Collectors.toList());
			long cutoff = System.currentTimeMillis() - PRUNE_AFTER_MS;
			List<Filepath> doomed = new ArrayList<>();
			for (Filepath f : files)
			{
				if (lastModified(f) < cutoff)
				{
					doomed.add(f);
				}
			}
			if (files.size() - doomed.size() > MAX_KEPT)
			{
				files.stream()
					.filter(f -> !doomed.contains(f))
					.sorted(Comparator.comparingLong(ClipFolder::lastModified))
					.limit(files.size() - doomed.size() - MAX_KEPT)
					.forEach(doomed::add);
			}
			for (Filepath f : doomed)
			{
				f.deleteIfExists();
			}
			if (!doomed.isEmpty())
			{
				log.debug("Anvil clips: swept {} unsent clip(s)", doomed.size());
			}
		}
		catch (Exception e)
		{
			log.debug("Anvil clips: sweep skipped: {}", e.getMessage());
		}
	}

	private static long lastModified(Filepath f)
	{
		try
		{
			return f.getLastModifiedTime().toMillis();
		}
		catch (Exception e)
		{
			return 0L;
		}
	}

	/** Our clips directory, created on first use. Null when it can't be made. */
	private Filepath ensureClipsDir()
	{
		Filepath dir = clipsDir;
		if (dir == null)
		{
			return null;
		}
		try
		{
			if (!dir.isDirectory())
			{
				dir.createDirectories();
			}
			return dir;
		}
		catch (Exception e)
		{
			log.debug("Anvil clips: can't create {}: {}", dir, e.getMessage());
			return null;
		}
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * The live {@link SidebarDataSource} behind the sidebar: renders the plugin's one home — a view over the
 * already-polled {@link PluginConfigResponse} plus the injected {@link BingoApiClient} — into a single
 * {@link ConnectionView}. Board summary + nearest tiles come from the polled config (no extra request); the
 * feed is the source's only network call (one conditional GET to {@code /api/plugin/activity}, 304 while idle).
 *
 * <p><b>"Active now"</b> fuses three signals so it works for every tile kind: config-count deltas (the only
 * signal for stat grinds, and the unnamed "a teammate" fallback for any kind), the local stat signal
 * ({@code AnvilPlugin::localStatProgress}, which attributes a rise to "You"), and the feed (submission tiles
 * by name). Signals merge by tile (deduped, "You" first), newest-first, capped.</p>
 *
 * <p>Called off the EDT by the panel's worker (one at a time), so the delta state needs no locking.</p>
 */
@Slf4j
public class AnvilSidebarDataSource implements SidebarDataSource
{
	/** Stable id for the plugin's one home. */
	static final String LOCAL_INSTANCE_ID = "local";

	private static final int NEAREST_LIMIT = 10;
	private static final int MAX_ACTIVE = 4;

	/** How recent a signal counts as "active now" — matched to the Site's 5-min stat-worker window. */
	private static final long ACTIVE_WINDOW_MS = 5 * 60_000L;

	/** How long a weekly's standings stay good. Way slacker than the 15 s panel poll — weekly gains are
	 *  swept by the site's 15-min stats cron, so re-reading a leaderboard every refresh is pure noise. */
	private static final long WEEKLY_STANDINGS_TTL_MS = 60_000L;

	/** Leaderboard rows kept per weekly — the sidebar shows the head of the board, not all 50. */
	private static final int WEEKLY_TOP_LIMIT = 10;

	private final Supplier<PluginConfigResponse> configSupplier;

	/** The plugin's injected client — the sidebar's one network call (the activity feed) rides on it. */
	private final BingoApiClient apiClient;

	/** Stat tiles this account recently progressed (tileId → millis) — the "You" attribution for stat grinds. */
	private final Supplier<Map<Integer, Long>> localStatProgress;

	/** The playing account's RSN — flags "you" in a weekly's standings. Null/blank while logged out. */
	private final Supplier<String> localRsn;

	/** Is this account a real member of the HOME clan? {@code null} until the login handshake answers. */
	private final Supplier<Boolean> homeMembership;

	// Weekly standings cache (compId → last leaderboard read), the comps already read this generation,
	// and when the generation opened — so the panel's 15 s poll doesn't re-read the same board four
	// times a minute (nor hammer a failing one). See refreshWeeklyBoards.
	private final Map<Integer, BingoApiClient.WeeklyLeaderboard> weeklyBoards = new HashMap<>();
	private final java.util.Set<Integer> weeklyBoardsTried = new java.util.HashSet<>();
	private long weeklyBoardsAt;

	// Live-sidebar state, scoped to the active event.
	private final AnvilActivityLog activityLog = new AnvilActivityLog();
	private int scopedEventId = -1;

	// Config-delta signal state (per instance id): last-seen amount per tile + when each rose. Cleared on event change.
	private final Map<String, Map<Integer, Integer>> lastAmounts = new HashMap<>();
	private final Map<String, Map<Integer, Long>> roseAt = new HashMap<>();

	/** Single-home binding — the plugin's live config + injected client. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient)
	{
		this(configSupplier, apiClient, Collections::emptyMap);
	}

	/** Single-home binding with the local stat signal (drives attribution in tests). */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress)
	{
		this(configSupplier, apiClient, localStatProgress, () -> null);
	}

	/** Adds the playing account's RSN for the weekly standings' "you" row. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress, Supplier<String> localRsn)
	{
		this(configSupplier, apiClient, localStatProgress, localRsn, () -> null);
	}

	/** The real plugin binding — also carries whether this account is a member (not a guest) at home. */
	public AnvilSidebarDataSource(Supplier<PluginConfigResponse> configSupplier, BingoApiClient apiClient,
		Supplier<Map<Integer, Long>> localStatProgress, Supplier<String> localRsn,
		Supplier<Boolean> homeMembership)
	{
		this.configSupplier = configSupplier;
		this.apiClient = apiClient;
		this.localStatProgress = localStatProgress == null ? Collections::emptyMap : localStatProgress;
		this.localRsn = localRsn == null ? () -> null : localRsn;
		this.homeMembership = homeMembership == null ? () -> null : homeMembership;
	}

	/**
	 * The starting-shot action, bound by the plugin after construction (Guice builds this source
	 * before the plugin's own fields exist, so it can't be a constructor argument). Null in tests and
	 * anywhere the panel is driven without a live plugin — the sidebar then simply shows no button.
	 */
	private volatile Runnable startProofCapture;

	/** Bind the capture action. Idempotent; passing null unbinds. */
	public void setStartProofCapture(Runnable capture)
	{
		this.startProofCapture = capture;
	}

	/** The plugin behind the panel's buttons, bound after construction like the capture above. */
	private volatile AnvilPlugin plugin;

	public void setPlugin(AnvilPlugin plugin)
	{
		this.plugin = plugin;
	}

	@Override
	public PanelActions actionsFor(String instanceId)
	{
		AnvilPlugin p = plugin;
		if (p == null || !LOCAL_INSTANCE_ID.equals(instanceId))
		{
			// Another clan's card. A roster sync there is impossible (you can only read the clan
			// channel you're in) and a profile sync has nowhere to go yet, so the panel offers
			// neither rather than offering something that would fail.
			return new PanelActions(false, false, null);
		}
		boolean profile = p.supportsProfileSync();
		if (!p.isAdmin())
		{
			return new PanelActions(false, profile, null);
		}
		// Admin, at home — but the roster comes from the clan channel, so it has to be readable. The
		// CACHED answer: this runs while the panel paints, on the EDT, where asking the client
		// directly is a thread violation.
		boolean scrape = p.isClanRosterReadable();
		return new PanelActions(scrape, profile, scrape ? null : "Join your clan channel to sync the roster");
	}

	@Override
	public void syncRoster()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.syncClanRosterFromPanel();
		}
	}

	@Override
	public void syncProfile()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.syncProfileNow();
		}
	}

	@Override
	public java.util.List<String> bannerSounds()
	{
		AnvilPlugin p = plugin;
		return p == null ? java.util.Collections.emptyList() : p.bannerSoundClips();
	}

	@Override
	public boolean bannerSoundOn(String clip)
	{
		AnvilPlugin p = plugin;
		return p != null && p.bannerSoundSelected(clip);
	}

	@Override
	public void toggleBannerSound(String clip)
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.toggleBannerSound(clip);
		}
	}

	@Override
	public void copyBannerSoundsPath()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.copyBannerSoundsPath();
		}
	}

	@Override
	public void importBannerSounds()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.importBannerSounds();
		}
	}

	@Override
	public java.util.List<String> missionSounds()
	{
		AnvilPlugin p = plugin;
		return p == null ? java.util.Collections.emptyList() : p.missionSoundClips();
	}

	@Override
	public void importMissionSounds()
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.importMissionSounds();
		}
	}

	@Override
	public PluginConfigResponse.StartProof startProof()
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null || cfg.startProof == null || !cfg.startProof.required
			|| !cfg.startProof.drawn || !cfg.startProof.needsUpload)
		{
			return null;
		}
		// Only while the event is actually live — the same gate the in-game overlay uses, so the
		// panel can't ask for a shot of an event that has ended.
		return AnvilOverlay.isEventActive(cfg.event) ? cfg.startProof : null;
	}

	@Override
	public void captureStartProof()
	{
		Runnable capture = startProofCapture;
		if (capture != null)
		{
			capture.run();
		}
	}

	@Override
	public List<ConnectionView> fetchConnections() throws SidebarDataException
	{
		return fetchConnections(false);
	}

	/** {@code force} = the member clicked Refresh — bypasses the weekly-standings throttle too. */
	@Override
	public List<ConnectionView> fetchConnections(boolean force) throws SidebarDataException
	{
		ConnectionView view = buildView(force);
		return view == null ? Collections.emptyList() : Collections.singletonList(view);
	}

	// ── The clan switcher's data ────────────────────────────────────────────────────────────────
	//
	// Straight off the config this source already reads, so offering the dropdown costs no request.

	@Override
	public List<PluginConfigResponse.ClanRef> clans()
	{
		PluginConfigResponse cfg = configSupplier.get();
		return cfg == null ? Collections.emptyList() : cfg.switchableClans();
	}

	@Override
	public String chosenClan()
	{
		AnvilPlugin p = plugin;
		return p == null ? "" : p.getChosenClan();
	}

	@Override
	public String activeClan()
	{
		return apiClient.getActiveClan();
	}

	@Override
	public String addressedBoard()
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null)
		{
			return "";
		}
		// The member-scoped event when one resolved, else the board the site resolved from the token
		// alone (the logged-out card). Both are the SAME board a clan row may also be reporting.
		if (cfg.event != null)
		{
			return PluginConfigResponse.boardIdentity(cfg.event.id);
		}
		return cfg.homeBoard != null && cfg.homeBoard.eventId > 0
			? PluginConfigResponse.boardIdentity(cfg.homeBoard.eventId)
			: "";
	}

	@Override
	public void chooseClan(String slug)
	{
		AnvilPlugin p = plugin;
		if (p != null)
		{
			p.setChosenClan(slug);
		}
	}

	private ConnectionView buildView(boolean force)
	{
		PluginConfigResponse cfg = configSupplier.get();
		if (cfg == null)
		{
			if (scopedEventId != -1)
			{
				resetLiveState();
			}
			return null; // no config at all (site unreachable / bad token) — nothing to anchor a card on
		}

		// SOTW/BOTW ride alongside the board as events of their own, so they show up whether or not the
		// member is in a live bingo — a weekly-only clan still has something on the card. The clan's
		// other/coming bingos ride along the same way, so "what's next" needs no site visit.
		List<ConnectionView.WeeklyView> weeklies = buildWeeklies(cfg, force);
		List<ConnectionView.ScheduledView> scheduled = buildScheduled(cfg);

		if (cfg.event == null)
		{
			if (scopedEventId != -1)
			{
				resetLiveState();
			}
			// No member-scoped event: either the clan genuinely has no live event, or one IS running
			// but this account can't be resolved right now (logged out / unlinked RSN). Still render a
			// home card — without it, a federated sidebar shows only the OTHER clans, which reads as
			// "my main clan disappeared".
			PluginConfigResponse.HomeBoard hb = cfg.homeBoard;
			if (hb != null)
			{
				// The site resolved the user's live enrollment server-side (token → linked member →
				// team), so the board summary renders even at the login screen; the live layers
				// (nearest tiles, active-now) still wait for a playing account.
				return new ConnectionView(LOCAL_INSTANCE_ID, homeClanName(cfg), hb.eventName,
					null, hb.tilesComplete, hb.tilesTotal, null, null, null, null, hb.pointsScored,
					"Log in in-game for live tracking.", null, null, weeklies, scheduled, homeMembership.get());
			}
			String note = cfg.unlinkedActiveEvent != null && !cfg.unlinkedActiveEvent.isEmpty()
				? "Log in in-game to load your board."
				: null; // null → the panel's "No active event yet."
			return new ConnectionView(LOCAL_INSTANCE_ID, homeClanName(cfg), cfg.unlinkedActiveEvent,
				null, 0, 0, null, null, null, null, false, note, null, null, weeklies, scheduled, homeMembership.get());
		}

		if (cfg.event.id != scopedEventId)
		{
			resetLiveState(); // a new event's deltas must not inherit the old board's amounts
			scopedEventId = cfg.event.id;
		}

		List<ClogTaskModel.TaskRow> rows = ClogTaskModel.build(cfg);
		// Optional tiles are bonus: excluded from BOTH the total and the earned/complete tally, exactly
		// like the website's scoredTiles filter (else a completed optional tile inflates the numerator
		// and every optional tile inflates the denominator).
		java.util.Set<Integer> optionalIds = cfg.optionalTileIds == null
			? java.util.Collections.emptySet()
			: new java.util.HashSet<>(cfg.optionalTileIds);
		// Leagues (scoringMode=points) ranks by summed tile WEIGHT, so the summary reads earned/total
		// POINTS (matching the website + board banner); classic bingo + tile race stay tile counts.
		// Guard the degenerate no-points board so a mis-tagged event still shows a sane count.
		boolean pointsScored = "points".equalsIgnoreCase(cfg.event.scoringMode)
			&& ClogTaskModel.totalPoints(rows, optionalIds) > 0;
		int tilesTotal = pointsScored
			? ClogTaskModel.totalPoints(rows, optionalIds)
			: ClogTaskModel.scoredCount(rows, optionalIds);
		int tilesComplete = pointsScored
			? ClogTaskModel.earnedPoints(rows, optionalIds)
			: ClogTaskModel.completedCount(rows, optionalIds);
		// THE BOARD, NOT THE PART OF IT THIS PLUGIN CAN SEE. The rows above are the tiles it can
		// DETECT — a drop, a KC, an XP goal — so a board carrying manual tiles counted 10 of its 25
		// and called that 50% while every other surface said 20%. When the site sends the board's own
		// fraction, that is the board's fraction; the local count stays the answer for sites that don't.
		if (cfg.board != null && cfg.board.tilesTotal > 0)
		{
			pointsScored = cfg.board.pointsScored;
			tilesTotal = cfg.board.tilesTotal;
			tilesComplete = cfg.board.tilesComplete;
		}
		List<ConnectionView.TileProgressView> nearest = nearestTiles(rows);

		// One conditional GET for the feed. A failure leaves the log as-is (partial failure), surfaced inline.
		String error = null;
		try
		{
			BingoApiClient.ActivityResponse ar = apiClient.fetchActivity(activityLog.getCursor());
			if (ar != null && !ar.noActiveEvent)
			{
				activityLog.ingest(ar.cursor, toEntries(ar.activity));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("activity fetch failed", e);
			error = "Live feed unavailable";
		}

		List<ActivityEntry> feed = activityLog.snapshot();
		// Raw feed drives "Active now"; the display list folds a grind's "+1" rows into one "+N" (Team activity).
		List<ConnectionView.ActiveTask> activeNow = buildActiveNow(cfg, rows, feed);

		// Ladder events render a DMM-All-Stars-style missions board instead of the tile-count reveal note:
		// a live countdown, the open missions with their live grow/decay value, and your rank.
		ConnectionView.Ladder ladder = buildLadder(cfg.event);

		// The clan filter is a CLAN switcher, so the label is the clan name (site-provided) — the
		// event name lives on the card itself. Falls back to team/event for pre-clanName sites;
		// ConnectionView maps "" → "(unnamed clan)".
		return new ConnectionView(
			LOCAL_INSTANCE_ID, homeClanName(cfg), cfg.event.name, error,
			tilesComplete, tilesTotal, nearest, AnvilActivityLog.aggregateForDisplay(feed), activeNow, boardUrlFor(cfg), pointsScored,
			null, ladder != null && ladder.ladderFormat ? null : revealNote(cfg.event),
			ladder, weeklies, scheduled, homeMembership.get());
	}

	// ---- Weekly competitions (SOTW/BOTW) as sidebar events ----------------------------------------

	/**
	 * The clan's weeklies — live ones folded with the caller's standing, upcoming ones as an
	 * announcement. The comps themselves come from the config the plugin already polls (no extra
	 * request); a LIVE comp's standings are one throttled read ({@link #WEEKLY_STANDINGS_TTL_MS}) that
	 * degrades to a comp-only card when unreachable, and an upcoming one is never read at all (nothing
	 * has happened yet). Live first, then soonest-starting.
	 */
	private List<ConnectionView.WeeklyView> buildWeeklies(PluginConfigResponse cfg, boolean force)
	{
		List<BingoApiClient.ScheduledWeekly> weeklies = scheduledWeeklies(cfg);
		if (weeklies.isEmpty())
		{
			weeklyBoards.clear();
			weeklyBoardsTried.clear();
			return Collections.emptyList();
		}
		List<BingoApiClient.ScheduledWeekly> live = new ArrayList<>();
		for (BingoApiClient.ScheduledWeekly w : weeklies)
		{
			if (isLive(w.status))
			{
				live.add(w);
			}
		}
		refreshWeeklyBoards(live, force);

		String me = Rsn.normalize(localRsn.get());
		List<ConnectionView.WeeklyView> out = new ArrayList<>(weeklies.size());
		for (BingoApiClient.ScheduledWeekly w : weeklies)
		{
			out.add(toWeeklyView(w, weeklyBoards.get(w.id), me));
		}
		return out;
	}

	/**
	 * Every weekly the site is advertising (live AND upcoming), deduped by id, live first then by
	 * soonest start. Reads the schedule — which carries both comps when a SOTW and a BOTW overlap —
	 * and falls back to the single {@code activeWeekly} field so an older site still surfaces its one
	 * live comp. The site only ships non-completed comps, so nothing here is over.
	 */
	private static List<BingoApiClient.ScheduledWeekly> scheduledWeeklies(PluginConfigResponse cfg)
	{
		List<BingoApiClient.ScheduledWeekly> out = new ArrayList<>();
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		if (cfg.schedule != null && cfg.schedule.weeklies != null)
		{
			for (BingoApiClient.ScheduledWeekly w : cfg.schedule.weeklies)
			{
				if (w != null && seen.add(w.id))
				{
					out.add(w);
				}
			}
		}
		BingoApiClient.ActiveWeekly a = cfg.activeWeekly;
		if (a != null && seen.add(a.id))
		{
			BingoApiClient.ScheduledWeekly w = new BingoApiClient.ScheduledWeekly();
			w.id = a.id;
			w.title = a.title;
			w.type = a.type;
			w.metric = a.metric;
			w.metricLabel = a.metricLabel;
			w.status = "active";
			w.startDate = a.startDate;
			w.endDate = a.endDate;
			out.add(w);
		}
		out.sort(SCHEDULE_ORDER);
		return out;
	}

	/**
	 * Bingo events on the clan's schedule other than the caller's own board — live ones they aren't in,
	 * plus what's coming up. Straight off the polled config; the caller's own event is dropped because
	 * the board card already IS that event.
	 */
	private List<ConnectionView.ScheduledView> buildScheduled(PluginConfigResponse cfg)
	{
		if (cfg.schedule == null || cfg.schedule.bingos == null)
		{
			return Collections.emptyList();
		}
		int ownEventId = cfg.event != null ? cfg.event.id : -1;
		List<BingoApiClient.ScheduledBingo> bingos = new ArrayList<>();
		for (BingoApiClient.ScheduledBingo b : cfg.schedule.bingos)
		{
			if (b != null && b.id != ownEventId)
			{
				bingos.add(b);
			}
		}
		bingos.sort((x, y) -> SCHEDULE_ORDER.compare(
			asEntry(x.status, x.startDate), asEntry(y.status, y.startDate)));

		String base = apiClient.getApiUrl();
		List<ConnectionView.ScheduledView> out = new ArrayList<>(bingos.size());
		for (BingoApiClient.ScheduledBingo b : bingos)
		{
			out.add(new ConnectionView.ScheduledView(b.id, b.title, b.startDate, b.endDate,
				isLive(b.status), b.tileCount == null ? 0 : b.tileCount,
				b.boardSize == null ? 0 : b.boardSize, b.format, b.scoringMode,
				base == null || base.isEmpty() ? null : base + "/events/" + b.id));
		}
		return out;
	}

	/** Live first, then soonest start (ISO strings sort chronologically); undated last. */
	private static final Comparator<BingoApiClient.ScheduledWeekly> SCHEDULE_ORDER = (a, b) ->
	{
		boolean la = isLive(a.status);
		boolean lb = isLive(b.status);
		if (la != lb)
		{
			return la ? -1 : 1;
		}
		String sa = a.startDate == null ? "" : a.startDate;
		String sb = b.startDate == null ? "" : b.startDate;
		if (sa.isEmpty() != sb.isEmpty())
		{
			return sa.isEmpty() ? 1 : -1;
		}
		return sa.compareTo(sb);
	};

	/** Adapter so the bingo list can reuse {@link #SCHEDULE_ORDER} (same status/start ordering). */
	private static BingoApiClient.ScheduledWeekly asEntry(String status, String startDate)
	{
		BingoApiClient.ScheduledWeekly w = new BingoApiClient.ScheduledWeekly();
		w.status = status;
		w.startDate = startDate;
		return w;
	}

	private static boolean isLive(String status)
	{
		return "active".equalsIgnoreCase(status);
	}

	/**
	 * One standings read per live comp per {@link #WEEKLY_STANDINGS_TTL_MS} window (a member-forced
	 * Refresh opens a new window immediately) — including a comp whose read FAILED, so an unreachable
	 * leaderboard is retried on the same slow cadence instead of every poll. A comp that stopped
	 * running is dropped, so the cache can't outlive it.
	 */
	private void refreshWeeklyBoards(List<BingoApiClient.ScheduledWeekly> live, boolean force)
	{
		final long now = System.currentTimeMillis();
		if (force || now - weeklyBoardsAt >= WEEKLY_STANDINGS_TTL_MS)
		{
			weeklyBoardsTried.clear();
			weeklyBoardsAt = now;
		}
		java.util.Set<Integer> liveIds = new java.util.HashSet<>();
		for (BingoApiClient.ScheduledWeekly w : live)
		{
			liveIds.add(w.id);
			if (!weeklyBoardsTried.add(w.id))
			{
				continue; // already read this window — the cached board stands
			}
			try
			{
				BingoApiClient.WeeklyLeaderboard lb = apiClient.fetchWeeklyLeaderboard(w.id);
				if (lb != null)
				{
					weeklyBoards.put(w.id, lb);
				}
			}
			catch (RuntimeException e)
			{
				// A weekly board is a nice-to-have: keep whatever we had and render the comp without it.
				log.debug("weekly leaderboard fetch failed for {}", w.id, e);
			}
		}
		weeklyBoards.keySet().retainAll(liveIds);
		weeklyBoardsTried.retainAll(liveIds);
	}

	/** Fold one comp + its (possibly absent) leaderboard into the panel's weekly card. */
	private ConnectionView.WeeklyView toWeeklyView(BingoApiClient.ScheduledWeekly w,
		BingoApiClient.WeeklyLeaderboard lb, String me)
	{
		List<ConnectionView.Standing> top = new ArrayList<>();
		int yourRank = 0;
		long yourGained = 0;
		int participants = 0;
		if (lb != null && isLive(w.status))
		{
			participants = lb.total;
			if (lb.entries != null)
			{
				for (BingoApiClient.LeaderboardEntry e : lb.entries)
				{
					if (e == null)
					{
						continue;
					}
					// Match on whitespace-normalized names — OSRS display names carry non-breaking
					// spaces, so a raw equalsIgnoreCase both misses and mis-flags the local player.
					boolean self = !me.isEmpty() && me.equals(Rsn.normalize(e.rsn));
					if (self)
					{
						yourRank = e.rank;
						yourGained = e.gained;
					}
					if (top.size() < WEEKLY_TOP_LIMIT || self)
					{
						top.add(new ConnectionView.Standing(e.rank, e.rsn, e.gained, self));
					}
				}
			}
		}
		return new ConnectionView.WeeklyView(w.id, w.title, w.type, w.metric, w.metricLabel,
			w.startDate, w.endDate, !isLive(w.status), yourRank, yourGained, participants, top,
			weeklyUrlFor(w.id));
	}

	/** The comp's page on the site, or null when the base URL is unknown (offline / unconfigured). */
	private String weeklyUrlFor(int competitionId)
	{
		String base = apiClient.getApiUrl();
		return base == null || base.isEmpty() ? null : base + "/weekly/" + competitionId;
	}

	/**
	 * Fold missions into the sidebar's {@link ConnectionView.Ladder} view-model: the countdown target,
	 * the caller's month + all-time rank, and the open missions.
	 *
	 * Built for a ladder (where it REPLACES the board summary) and, since a normal bingo can drop
	 * hidden missions mid-event too, for any board that currently has missions — there it renders as
	 * a strip under the usual summary. Null when neither applies, and the plain summary + reveal note
	 * render on their own.
	 */
	static ConnectionView.Ladder buildLadder(PluginConfigResponse.EventInfo event)
	{
		if (event == null)
		{
			return null;
		}
		boolean ladder = LadderMissions.isLadder(event.format);
		boolean hasMissions = event.missions != null && !event.missions.isEmpty();
		if (!ladder && !hasMissions)
		{
			return null;
		}
		List<ConnectionView.Ladder.Mission> missions = new ArrayList<>();
		if (event.missions != null)
		{
			for (PluginConfigResponse.Mission m : event.missions)
			{
				if (m != null)
				{
					missions.add(new ConnectionView.Ladder.Mission(m.tileId, m.label, m.points, m.revealedAt));
				}
			}
		}
		int monthRank = event.monthlyStandings != null ? event.monthlyStandings.yourRank : 0;
		long monthPoints = event.monthlyStandings != null ? event.monthlyStandings.yourPoints : 0;
		int allTimeRank = event.standings != null ? event.standings.yourRank : 0;
		return new ConnectionView.Ladder(event.nextRevealAt, monthRank, monthPoints, allTimeRank,
			event.decay, missions, ladder);
	}

	/**
	 * Reveal-policy boards: the "still hidden" one-liner under the board summary, or null on classic
	 * boards / older servers (no field). Bounty draws on claim, the others on a clock the server sends.
	 */
	static String revealNote(PluginConfigResponse.EventInfo event)
	{
		if (event == null || event.revealPolicy == null || event.revealPolicy.isEmpty() || event.hiddenTileCount <= 0)
		{
			return null;
		}
		boolean bounty = "bounty".equalsIgnoreCase(event.revealPolicy);
		String what = bounty
			? event.hiddenTileCount + (event.hiddenTileCount == 1 ? " bounty" : " bounties") + " left"
			: event.hiddenTileCount + (event.hiddenTileCount == 1 ? " tile" : " tiles") + " hidden";
		String next = bounty ? "next on claim" : nextRevealLabel(event.nextRevealAt);
		return what + (next == null ? "" : " · " + next);
	}

	/** "next in 42m" / "next in 3h 10m" from the server's ISO next-reveal stamp; null when absent/past. */
	private static String nextRevealLabel(String nextRevealAt)
	{
		if (nextRevealAt == null || nextRevealAt.isEmpty())
		{
			return null;
		}
		try
		{
			long at = java.time.Instant.parse(nextRevealAt).toEpochMilli();
			long mins = Math.max(0, (at - System.currentTimeMillis()) / 60_000);
			if (mins < 1)
			{
				return "next any minute";
			}
			if (mins < 60)
			{
				return "next in " + mins + "m";
			}
			return "next in " + (mins / 60) + "h " + (mins % 60) + "m";
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** The home entry's clan-filter label: the site's clan name, else the old team/event fallback. */
	private static String homeClanName(PluginConfigResponse cfg)
	{
		if (cfg.clanName != null && !cfg.clanName.isEmpty())
		{
			return cfg.clanName;
		}
		return primaryDisplayName(cfg);
	}

	/** The site's public board/standings page for the active event, or null when the base URL is unknown. */
	private String boardUrlFor(PluginConfigResponse cfg)
	{
		String base = apiClient.getApiUrl();
		if (base == null || base.isEmpty() || cfg.event == null)
		{
			return null;
		}
		return base + "/events/" + cfg.event.id;
	}

	/** Reset the feed + delta state when the active event changes (or clears). */
	private void resetLiveState()
	{
		activityLog.reset();
		scopedEventId = -1;
		forgetDeltas(LOCAL_INSTANCE_ID);
	}

	/** The clan/event label for the header: team name ?? event name ?? "". */
	private static String primaryDisplayName(PluginConfigResponse cfg)
	{
		if (cfg.team != null && cfg.team.name != null && !cfg.team.name.isEmpty())
		{
			return cfg.team.name;
		}
		if (cfg.event != null && cfg.event.name != null && !cfg.event.name.isEmpty())
		{
			return cfg.event.name;
		}
		return "";
	}

	private void forgetDeltas(String instanceId)
	{
		lastAmounts.remove(instanceId);
		roseAt.remove(instanceId);
	}

	/** Fuse the feed, named stat workers, the local stat signal, and config deltas into "Active now". */
	private List<ConnectionView.ActiveTask> buildActiveNow(PluginConfigResponse cfg,
		List<ClogTaskModel.TaskRow> rows, List<ActivityEntry> feed)
	{
		final long now = System.currentTimeMillis();
		Map<Integer, ClogTaskModel.TaskRow> incompleteById = new HashMap<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (!r.isCompleted())
			{
				incompleteById.put(r.tileId, r);
			}
		}

		// Server-computed named teammates per stat tile (tileId → RSNs); absent on an older server (unnamed fallback).
		Map<Integer, List<String>> namedByTile = new HashMap<>();
		if (cfg.trackedStats != null)
		{
			for (PluginConfigResponse.TrackedStat s : cfg.trackedStats)
			{
				if (s != null && s.activeWorkers != null)
				{
					namedByTile.put(s.tileId, s.activeWorkers);
				}
			}
		}
		Map<Integer, Acc> acc = new HashMap<>();

		// 1. Feed — submission tiles, named. Newest-first.
		for (ActivityEntry e : feed)
		{
			if (e.kind != ActivityEntry.Kind.PROGRESS)
			{
				continue;
			}
			long t = parseTsMillis(e.ts);
			if (t >= 0 && now - t > ACTIVE_WINDOW_MS)
			{
				continue;
			}
			String worker = e.self ? "You" : (e.player == null || e.player.isEmpty() ? null : e.player);
			add(acc, incompleteById, e.tileId, worker, e.self, t < 0 ? now : t);
		}

		// 2. Local stat signal — "You" on stat tiles this account is grinding.
		Map<Integer, Long> local = localStatProgress.get();
		if (local != null)
		{
			for (Map.Entry<Integer, Long> en : local.entrySet())
			{
				long t = en.getValue() == null ? 0 : en.getValue();
				if (now - t > ACTIVE_WINDOW_MS)
				{
					continue;
				}
				add(acc, incompleteById, en.getKey(), "You", true, t);
			}
		}

		// 2b. Named teammates on stat tiles (server-computed) — the good version of "a teammate".
		for (Map.Entry<Integer, List<String>> en : namedByTile.entrySet())
		{
			for (String name : en.getValue())
			{
				add(acc, incompleteById, en.getKey(), name, false, now);
			}
		}

		// 3. Config-count deltas → an UNNAMED "a teammate" for ANY tile kind — the only signal for a teammate
		//    grinding before the feed ships. Suppressed where the server named the tile (2b) or you're on it (2).
		Map<Integer, Integer> last = lastAmounts.computeIfAbsent(LOCAL_INSTANCE_ID, k -> new HashMap<>());
		Map<Integer, Long> rose = roseAt.computeIfAbsent(LOCAL_INSTANCE_ID, k -> new HashMap<>());
		Map<Integer, Integer> current = new HashMap<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			current.put(r.tileId, r.current);
			if (r.isCompleted())
			{
				continue;
			}
			Integer prev = last.get(r.tileId);
			if (prev != null && r.current > prev)
			{
				rose.put(r.tileId, now); // first call has no prev → seeds silently, never a false "active"
			}
		}
		for (Map.Entry<Integer, Long> en : rose.entrySet())
		{
			if (now - en.getValue() > ACTIVE_WINDOW_MS || !incompleteById.containsKey(en.getKey()))
			{
				continue;
			}
			if (namedByTile.containsKey(en.getKey()))
			{
				continue; // the server named this tile's teammates (stat tile) — don't add an unnamed one
			}
			Acc a = acc.get(en.getKey());
			if (a != null && a.self)
			{
				continue; // you're already credited on this tile — don't also tag a teammate
			}
			add(acc, incompleteById, en.getKey(), "a teammate", false, en.getValue());
		}
		lastAmounts.put(LOCAL_INSTANCE_ID, current);

		// Newest-active first, capped; "You" leads each row's workers.
		List<Map.Entry<Integer, Acc>> ordered = new ArrayList<>(acc.entrySet());
		ordered.sort((x, y) -> Long.compare(y.getValue().recency, x.getValue().recency));
		List<ConnectionView.ActiveTask> out = new ArrayList<>();
		for (Map.Entry<Integer, Acc> en : ordered)
		{
			if (out.size() >= MAX_ACTIVE)
			{
				break;
			}
			Acc a = en.getValue();
			List<String> workers = new ArrayList<>();
			if (a.self)
			{
				workers.add("You");
			}
			for (String w : a.workers)
			{
				if (!"You".equals(w))
				{
					workers.add(w);
				}
			}
			out.add(new ConnectionView.ActiveTask(incompleteById.get(en.getKey()), workers, a.self));
		}
		return out;
	}

	/** Per-tile accumulator while fusing signals. */
	private static final class Acc
	{
		final LinkedHashSet<String> workers = new LinkedHashSet<>();
		boolean self;
		long recency;
	}

	private static void add(Map<Integer, Acc> acc, Map<Integer, ClogTaskModel.TaskRow> incompleteById,
		int tileId, String worker, boolean self, long recency)
	{
		if (worker == null || !incompleteById.containsKey(tileId))
		{
			return;
		}
		Acc a = acc.computeIfAbsent(tileId, k -> new Acc());
		a.workers.add(worker);
		a.self |= self;
		a.recency = Math.max(a.recency, recency);
	}

	/** Incomplete tiles, nearest-to-done first (highest completion fraction), capped at {@link #NEAREST_LIMIT}. */
	private static List<ConnectionView.TileProgressView> nearestTiles(List<ClogTaskModel.TaskRow> rows)
	{
		List<ClogTaskModel.TaskRow> incomplete = new ArrayList<>();
		for (ClogTaskModel.TaskRow r : rows)
		{
			if (!r.isCompleted())
			{
				incomplete.add(r);
			}
		}
		incomplete.sort(Comparator.comparingDouble(AnvilSidebarDataSource::fraction).reversed()
			.thenComparingInt(r -> r.position));

		List<ConnectionView.TileProgressView> out = new ArrayList<>();
		for (int i = 0; i < incomplete.size() && i < NEAREST_LIMIT; i++)
		{
			ClogTaskModel.TaskRow r = incomplete.get(i);
			out.add(new ConnectionView.TileProgressView(r.label, r.current, r.goal, false));
		}
		return out;
	}

	private static double fraction(ClogTaskModel.TaskRow r)
	{
		return r.goal > 0 ? Math.min(1.0, (double) r.current / r.goal) : 0.0;
	}

	/** Parse the server's {@code "yyyy-MM-dd HH:mm:ss"} UTC timestamp to epoch millis, or -1 if unparseable. */
	private static long parseTsMillis(String ts)
	{
		if (ts == null || ts.isEmpty())
		{
			return -1;
		}
		String s = ts.trim().replace(' ', 'T');
		if (s.endsWith("Z"))
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return java.time.LocalDateTime.parse(s).toInstant(java.time.ZoneOffset.UTC).toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}

	private static List<ActivityEntry> toEntries(List<BingoApiClient.ActivityItem> items)
	{
		if (items == null || items.isEmpty())
		{
			return Collections.emptyList();
		}
		List<ActivityEntry> out = new ArrayList<>(items.size());
		for (BingoApiClient.ActivityItem it : items)
		{
			if (it == null)
			{
				continue;
			}
			out.add(new ActivityEntry(it.id, it.ts, it.player, it.tileId, it.tileLabel,
				ActivityEntry.Kind.fromWire(it.kind), it.amount, it.isSelf));
		}
		return out;
	}
}

package com.anvil;

import java.util.function.BooleanSupplier;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * An "Anvil" button in a game interface's title bar — the collection log's, beside WikiSync and
 * RuneProfile, and the clan window's, beside Wise Old Man's.
 *
 * <p>WHY BUTTONS AND NOT THE TAB WE DELETED. The in-game clog TAB went in 5d2e425 — four thousand
 * lines of hand-drawn widgets nobody read, sitting between the side panel (progress at a glance) and
 * the site (real search). These are not that: one control each, in the place the player already is,
 * doing what the sidebar already does, for somebody whose hands are in the game interface rather
 * than in RuneLite's.
 *
 * <p>DRAWN AS A BUTTON, NOT AS A WORD. The first version was a bare text widget, which read as a
 * stray label rather than something to click — its neighbours have a raised stone frame and a hover
 * state, and beside them a floating "Anvil" looks like a rendering fault. So this is the game's own
 * button: the V2 stone button's nine sprites (a backing, four corners, four edges) with the text
 * laid over the whole area carrying the listeners, swapping to the pressed-in set on hover. There is
 * essentially one right answer here and every plugin with a button in these bars has found it — the
 * sprites are the same ids whether a codebase spells them the legacy way (WORLD_MAP_BUTTON_*,
 * EQUIPMENT_BUTTON_*_HOVERED) or the generated way used here.
 *
 * <p>POSITIONED FROM THE RIGHT EDGE, not off a measured neighbour. Everything in these bars is
 * anchored right — the close button, then each plugin's button walking left — so an absolute-right
 * offset lands in the same slot at any window size, where arithmetic off another plugin's
 * coordinates moves the moment they move theirs.
 *
 * <p>SURVIVES A NEIGHBOUR REBUILDING THE BAR. WikiSync clears every dynamic child of this container
 * before adding its own, on the same script we draw on, so whether our button exists comes down to
 * who ran last — which is plugin load order, and nobody's to rely on. The answer is not to fight it:
 * we keep hold of what we made, notice when it is no longer attached, and build it again.
 */
final class HeaderButton
{
	/** Matches the native header buttons: small, and tall enough to hit comfortably. */
	private static final int WIDTH = 71;
	private static final int FALLBACK_HEIGHT = 20;
	/** The dimensions the nine-slice sprites are cut at. Stretching a corner is what looks wrong. */
	private static final int CORNER = 9;
	private static final int EDGE = 4;

	/** The stone button as it sits: raised, on the light backing. */
	private static final int[] SPRITES_IDLE = {
		SpriteID.TRADEBACKING,
		SpriteID.V2StoneButtonOut.A_TOP_LEFT,
		SpriteID.V2StoneButtonOut.A_TOP_RIGHT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonOut.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_LEFT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_TOP,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_RIGHT,
		SpriteID.V2StoneButtonOut.A_MAP_EDGE_BOTTOM,
	};

	/** The same button pressed in, on the dark backing — the game's own hover state for it. */
	private static final int[] SPRITES_HOVERED = {
		SpriteID.TRADEBACKING_DARK,
		SpriteID.V2StoneButtonIn.A_TOP_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_LEFT,
		SpriteID.V2StoneButtonIn.A_BOTTOM_RIGHT,
		SpriteID.V2StoneButtonIn.A_LEFT,
		SpriteID.V2StoneButtonIn.A_TOP,
		SpriteID.V2StoneButtonIn.A_RIGHT,
		SpriteID.V2StoneButtonIn.A_BOTTOM,
	};

	/** The frame's nine pieces, then the text on top. */
	private static final int PARTS = 10;
	private static final int TEXT = 9;

	private static final int TEXT_IDLE = 0xd6d6d6;
	private static final int TEXT_HOVERED = 0xffffff;

	/**
	 * The menu TARGET. The game builds an entry as "&lt;action&gt; &lt;name&gt;", which is why the
	 * action passed in is a verb alone — spelling it in both produced "Sync to Anvil Anvil".
	 */
	private static final String NAME = "Anvil";

	private final Client client;
	/** The container to draw in — the one the neighbouring buttons use, so we share its space. */
	private final int parentId;
	/** A native control in that bar, read for the row's height and vertical anchoring. */
	private final int anchorId;
	/** Distance from the bar's right edge to our left edge, in the slot left of our neighbours. */
	private final int rightOffset;
	/** Where to sit when the slot nearer the close button is empty. Equal to rightOffset when the
	 *  caller has no nearer slot to fall back to (the clan window, where we are already first). */
	private final int nearOffset;
	private final String label;
	/** The verb alone; the game appends {@link #NAME} to it. */
	private final String action;
	/** Whether syncing is possible right now — no site or no token means no button. */
	private final BooleanSupplier enabled;
	private final Runnable onClick;

	/** What we drew last time. Null until the first render, stale after a neighbour clears the bar. */
	private Widget[] parts;
	/** The slot those parts were drawn in, so a change of neighbours can be noticed and acted on. */
	private int drawnAt = Integer.MIN_VALUE;

	HeaderButton(Client client, int parentId, int anchorId, int rightOffset, String label, String action,
			BooleanSupplier enabled, Runnable onClick)
	{
		this(client, parentId, anchorId, rightOffset, rightOffset, label, action, enabled, onClick);
	}

	HeaderButton(Client client, int parentId, int anchorId, int rightOffset, int nearOffset, String label, String action,
				 BooleanSupplier enabled, Runnable onClick)
	{
		this.client = client;
		this.parentId = parentId;
		this.anchorId = anchorId;
		this.rightOffset = rightOffset;
		this.nearOffset = nearOffset;
		this.label = label;
		this.action = action;
		this.enabled = enabled;
		this.onClick = onClick;
	}

	/**
	 * Draw the button, or leave alone the one already there.
	 *
	 * <p>Safe to call on every draw of the interface. Must run on the client thread — and, because of
	 * the neighbour that clears this container, wants to run AFTER every other subscriber to the
	 * script has had its turn.
	 */
	void render()
	{
		Widget parent = client.getWidget(parentId);
		Widget anchor = client.getWidget(anchorId);
		if (parent == null || anchor == null || !enabled.getAsBoolean())
		{
			return;
		}
		final int x = slotFor(parent);
		if (stillAttached(parent))
		{
			if (drawnAt == x)
			{
				return; // ours, intact, in the right slot — drawing again would only make a second one
			}
			// THE NEIGHBOURS MOVED. Enabling WikiSync mid-session fills the slot we took while it was
			// away, and returning early here left the two buttons stacked on the same spot: ours was
			// still attached, so nothing ever reconsidered where it should be. Hide the old copy and
			// draw again at the slot that is free now.
			hideParts();
		}

		final int h = anchor.getOriginalHeight() > 0 ? anchor.getOriginalHeight() : FALLBACK_HEIGHT;
		final int y = anchor.getOriginalY();
		final int yMode = anchor.getYPositionMode();
		final int span = WIDTH - (CORNER * 2);
		final Widget[] made = new Widget[PARTS];

		// Background first so every edge draws over it, then the corners, then the edges between.
		made[0] = piece(parent, 0, x, y, WIDTH, h, yMode);
		made[1] = piece(parent, 1, x + WIDTH - CORNER, y, CORNER, CORNER, yMode);
		made[2] = piece(parent, 2, x, y, CORNER, CORNER, yMode);
		made[3] = piece(parent, 3, x + WIDTH - CORNER, y + h - CORNER, CORNER, CORNER, yMode);
		made[4] = piece(parent, 4, x, y + h - CORNER, CORNER, CORNER, yMode);
		made[5] = piece(parent, 5, x + WIDTH - CORNER, y + CORNER, CORNER, EDGE, yMode);
		made[7] = piece(parent, 7, x, y + CORNER, CORNER, EDGE, yMode);
		made[6] = piece(parent, 6, x + CORNER, y, span, CORNER, yMode);
		made[8] = piece(parent, 8, x + CORNER, y + h - CORNER, span, CORNER, yMode);

		// The text covers the whole button, so it is what the mouse actually meets: one layer owns
		// the click, the hover and the label, and the nine underneath are decoration.
		Widget text = parent.createChild(-1, WidgetType.TEXT);
		text.setName(NAME);
		text.setText(label);
		text.setTextColor(TEXT_IDLE);
		text.setFontId(FontID.PLAIN_11);
		text.setTextShadowed(true);
		text.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		text.setYPositionMode(yMode);
		text.setXTextAlignment(WidgetTextAlignment.CENTER);
		text.setYTextAlignment(WidgetTextAlignment.CENTER);
		text.setOriginalX(x);
		text.setOriginalY(y);
		text.setOriginalWidth(WIDTH);
		text.setOriginalHeight(h);
		text.setHasListener(true);
		text.setAction(0, action);
		text.setOnOpListener((JavaScriptCallback) e -> onClick.run());
		text.setOnMouseOverListener((JavaScriptCallback) e -> paint(made, SPRITES_HOVERED, TEXT_HOVERED));
		text.setOnMouseLeaveListener((JavaScriptCallback) e -> paint(made, SPRITES_IDLE, TEXT_IDLE));
		text.revalidate();
		made[TEXT] = text;

		parts = made;
		drawnAt = x;
		parent.revalidate();
	}

	/**
	 * Which slot to sit in — the far one when a neighbour holds the near one, the near one otherwise.
	 *
	 * The offsets stay FIXED; this only chooses between two of them. Deriving coordinates from
	 * another plugin's widget is what the class comment warns off, and this does not: it asks whether
	 * anything foreign is anchored in the near slot, which is a yes/no about occupancy rather than a
	 * position to copy.
	 *
	 * Without it the far offset was unconditional, so somebody with WikiSync disabled got a button
	 * floating a slot-width away from the close button with an empty gap between them — reserved for
	 * a plugin that was not running.
	 */
	private int slotFor(Widget parent)
	{
		if (nearOffset >= rightOffset)
		{
			return rightOffset;
		}
		Widget[] children = parent.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child == null || NAME.equals(child.getName()))
				{
					continue; // ours, from a previous render we are about to replace
				}
				if (child.getXPositionMode() != WidgetPositionMode.ABSOLUTE_RIGHT)
				{
					continue;
				}
				final int childX = child.getOriginalX();
				if (childX >= nearOffset && childX < rightOffset)
				{
					return rightOffset; // somebody is in the near slot; take the one beyond it
				}
			}
		}
		return nearOffset;
	}

	/** One piece of the frame, by its index into the sprite sets. */
	private Widget piece(Widget parent, int index, int x, int y, int w, int h, int yMode)
	{
		Widget piece = parent.createChild(-1, WidgetType.GRAPHIC);
		piece.setName(NAME);
		piece.setSpriteId(SPRITES_IDLE[index]);
		piece.setXPositionMode(WidgetPositionMode.ABSOLUTE_RIGHT);
		piece.setYPositionMode(yMode);
		piece.setOriginalX(x);
		piece.setOriginalY(y);
		piece.setOriginalWidth(w);
		piece.setOriginalHeight(h);
		piece.revalidate();
		return piece;
	}

	/**
	 * Re-evaluate while the window is open: draw, move, or clear as the situation now stands.
	 *
	 * <p>Cheap enough for every tick. When the parent is gone there is nothing to do; when the button
	 * should not be there it is hidden once and then there is nothing to hide; when it is already
	 * right, render() returns on an identity scan.</p>
	 */
	void refresh()
	{
		Widget parent = client.getWidget(parentId);
		if (parent == null)
		{
			// The window is closed. Our widgets went with it, so forget them rather than hiding
			// objects that are no longer attached to anything.
			parts = null;
			drawnAt = Integer.MIN_VALUE;
			return;
		}
		if (!enabled.getAsBoolean())
		{
			if (parts != null)
			{
				hideParts();
			}
			return;
		}
		render();
	}

	/**
	 * Hide what we drew, and forget it.
	 *
	 * <p>Hidden rather than deleted because a dynamic child cannot be removed on its own — the only
	 * removal the API offers clears the whole container, which would take the neighbours with it.
	 * A hidden widget does not render and is collected when the interface is next rebuilt.</p>
	 */
	void hideParts()
	{
		if (parts != null)
		{
			for (Widget w : parts)
			{
				if (w != null)
				{
					w.setHidden(true);
				}
			}
		}
		parts = null;
		drawnAt = Integer.MIN_VALUE;
	}

	/** Swap the frame between its idle and hovered sprite sets. */
	private static void paint(Widget[] made, int[] sprites, int textColour)
	{
		for (int i = 0; i < TEXT; i++)
		{
			if (made[i] != null)
			{
				made[i].setSpriteId(sprites[i]);
			}
		}
		if (made[TEXT] != null)
		{
			made[TEXT].setTextColor(textColour);
		}
	}

	/**
	 * Is the button we last drew still a child of this bar?
	 *
	 * <p>Identity, not a name lookup. After a neighbour clears the container our widgets are still
	 * perfectly good objects — just no longer attached to anything — so the question is whether the
	 * bar still holds the one we made, which answers both "were we wiped" and "did the interface
	 * rebuild underneath us".
	 */
	private boolean stillAttached(Widget parent)
	{
		if (parts == null || parts[TEXT] == null)
		{
			return false;
		}
		Widget[] children = parent.getDynamicChildren();
		if (children == null)
		{
			return false;
		}
		for (Widget w : children)
		{
			if (w == parts[TEXT])
			{
				return true;
			}
		}
		return false;
	}
}

