	/** " · ends in 2d 4h" / " · starts in 3d 1h" for the compact list row; "" when there's no usable date. */
	private static String timingSuffix(boolean upcoming, String startIso, String endIso)
	{
		String label = timingLabel(upcoming, startIso, endIso);
		return label == null ? "" : " · " + label.substring(0, 1).toLowerCase() + label.substring(1);
	}

	/** What matters about the clock right now: when it starts if it hasn't, else when it ends. */
	static String timingLabel(boolean upcoming, String startIso, String endIso)
	{
		return upcoming ? gapLabel("Starts in ", startIso, "Starting…") : endsInLabel(endIso);
	}

	/** "Ends in 2d 4h" / "Ends in 42m" / "Ended", or null when the date is missing or unparseable. */
	static String endsInLabel(String endIso)
	{
		return gapLabel("Ends in ", endIso, "Ended");
	}

	/** "{prefix}2d 4h" until {@code iso}; {@code passed} once it's behind us; null when unparseable. */
	private static String gapLabel(String prefix, String iso, String passed)
	{
		long at = epochMillis(iso);
		if (at < 0)
		{
			return null;
		}
		long left = at - System.currentTimeMillis();
		if (left <= 0)
		{
			return passed;
		}
		long mins = left / 60_000;
		if (mins < 60)
		{
			return prefix + Math.max(1, mins) + "m";
		}
		long hours = mins / 60;
		if (hours < 24)
		{
			return prefix + hours + "h " + (mins % 60) + "m";
		}
		return prefix + (hours / 24) + "d " + (hours % 24) + "h";
	}

	/** ISO date ("2026-06-21") or UTC datetime → epoch millis, or -1 when unparseable. */
	private static long epochMillis(String iso)
	{
		if (iso == null || iso.length() < 10)
		{
			return -1;
		}
		try
		{
			if (iso.length() == 10)
			{
				return java.time.LocalDate.parse(iso)
					.atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli();
			}
			String s = iso.trim().replace(' ', 'T');
			return java.time.Instant.parse(s.endsWith("Z") ? s : s + "Z").toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}

	// ---- Component builders -----------------------------------------------------------------------

	/** A small gold section label, matching the panel's header style. */
	private static JLabel sectionHeader(String text)
	{
		JLabel header = new JLabel(text);
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setForeground(ColorScheme.BRAND_ORANGE);
		header.setAlignmentX(LEFT_ALIGNMENT);
		return header;
	}

	/**
	 * One "Active now" row: tile name + a "who's on it" byline + a thin progress bar. Your own tasks lead in
	 * gold, teammate-only stay neutral. Value/label are JLabels (never painted inside the bar) for crisp text.
	 */
	/**
	 * The starting-shot prompt: where to stand, this account's keyword, and the one button that
	 * captures the frame, burns the proof banner onto it and files it. Rendered only while a shot is
	 * actually owed — {@link SidebarDataSource#startProof()} returns null the moment one is filed.
	 */
	private JPanel buildStartProofCard(PluginConfigResponse.StartProof proof)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setAlignmentX(LEFT_ALIGNMENT);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE),
			BorderFactory.createEmptyBorder(6, 8, 8, 8)));

		JLabel title = new JLabel("Starting shot needed");
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		card.add(title);

		if (proof.location != null && !proof.location.isEmpty())
		{
			JLabel where = new JLabel(plainText("Go to " + proof.location));
			where.setFont(FontManager.getRunescapeSmallFont());
			where.setForeground(Color.WHITE);
			where.setAlignmentX(LEFT_ALIGNMENT);
			where.setToolTipText(plainText(proof.location));
			card.add(gap(4));
			card.add(where);
		}

		if (proof.keyword != null && !proof.keyword.isEmpty())
		{
			JLabel word = new JLabel(plainText("Keyword: " + proof.keyword));
			word.setFont(FontManager.getRunescapeSmallFont());
			word.setForeground(VALUE_COLOR);
			word.setAlignmentX(LEFT_ALIGNMENT);
			card.add(gap(2));
			card.add(word);
		}

		if (proof.maxSessionMinutes > 0)
		{
			// Said here as well as in chat, because it's the one requirement you can't fix after the
			// fact: the logout is what flushes the hiscores the event's baseline is read from.
			JLabel relog = new JLabel(plainText("Log out and back in first (within " + proof.maxSessionMinutes + " min)"));
			relog.setFont(FontManager.getRunescapeSmallFont());
			relog.setForeground(Color.WHITE);
			relog.setAlignmentX(LEFT_ALIGNMENT);
			relog.setToolTipText("Hiscores only save when you log out, so this is what sets your starting totals.");
			card.add(gap(2));
			card.add(relog);
		}

		if ("rejected".equals(proof.status))
		{
			card.add(gap(2));
			card.add(warningLabel("Your last shot was rejected — take another."));
		}

		// WHY it matters, which the card never said. A player who reads "starting shot needed" and
		// carries on has no way to know their drops are landing in a review queue meanwhile.
		card.add(gap(4));
		card.add(warningLabel("Drops you send now are held for review until this is filed."));

		String left = StartProofRules.describeWindow(proof, System.currentTimeMillis());
		if (left != null)
		{
			JLabel expires = new JLabel(plainText("Asked for another " + left + ", then it lapses"));
			expires.setFont(FontManager.getRunescapeSmallFont());
			expires.setForeground(Color.WHITE);
			expires.setAlignmentX(LEFT_ALIGNMENT);
			expires.setToolTipText("Six hours in, the game has logged everyone out anyway, so the shot stops being asked for.");
			card.add(gap(2));
			card.add(expires);
		}

		JButton take = new JButton("Take starting shot");
		styleFlatButton(take, ColorScheme.BRAND_ORANGE);
		take.setAlignmentX(LEFT_ALIGNMENT);
		take.addActionListener(e ->
		{
			take.setEnabled(false);
			take.setText("Sending...");
			// The capture itself hops to the next rendered frame and then to a worker; the panel just
			// asks for it. The button goes away entirely on the next poll, once the site agrees.
			dataSource.captureStartProof();
			// ...unless the capture refused it — standing in the wrong place, or a session too old to
			// have flushed the hiscores. That answer arrives in chat, so the button has to come back
			// rather than sit on "Sending..." until the next poll redraws the card.
			javax.swing.Timer restore = new javax.swing.Timer(4000, ev ->
			{
				take.setText("Take starting shot");
				take.setEnabled(true);
			});
			restore.setRepeats(false);
			restore.start();
		});
		card.add(gap(6));
		card.add(take);

		return card;
	}

	private JPanel buildActiveRow(ConnectionView.ActiveTask task)
	{
		ClogTaskModel.TaskRow tile = task.tile;
		Color accent = task.includesSelf ? ColorScheme.BRAND_ORANGE : ColorScheme.TEXT_COLOR;

		JPanel row = new JPanel(new GridBagLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.WEST;

		JLabel name = new JLabel(plainText(ellipsize(tile.label, 24)));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(accent);
		name.setToolTipText(plainText(tile.label));
		row.add(name, gbc);

		JLabel value = new JLabel(progressValue(tile));
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(VALUE_COLOR);
		gbc.gridx = 1;
		gbc.weightx = 0;
		gbc.fill = GridBagConstraints.NONE;
		gbc.anchor = GridBagConstraints.EAST;
		row.add(value, gbc);

		JLabel who = new JLabel(plainText(task.workersLabel()));
		who.setFont(FontManager.getRunescapeSmallFont());
		who.setForeground(task.includesSelf ? ColorScheme.BRAND_ORANGE : VALUE_COLOR);
		gbc.gridx = 0;
		gbc.gridy = 1;
		gbc.gridwidth = 2;
		gbc.weightx = 1;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.WEST;
		gbc.insets = new java.awt.Insets(1, 0, 0, 0);
		row.add(who, gbc);

		JProgressBar bar = new JProgressBar(0, 100);
		bar.setValue(tile.goal > 0 ? Math.min(100, (int) Math.round(tile.current * 100.0 / tile.goal)) : 0);
		bar.setStringPainted(false);
		bar.setBorderPainted(false);
		bar.setForeground(task.includesSelf ? ColorScheme.BRAND_ORANGE : ColorScheme.PROGRESS_INPROGRESS_COLOR);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setPreferredSize(new Dimension(0, PROGRESS_BAR_HEIGHT));
		gbc.gridy = 2;
		gbc.insets = new java.awt.Insets(3, 0, 0, 0);
		row.add(bar, gbc);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** "1.5M / 2M", "248 / 500", or "" for an untargeted tile — big numbers abbreviated for the narrow panel. */
	private static String progressValue(ClogTaskModel.TaskRow tile)
	{
		return tile.goal > 0 ? formatCount(tile.current) + " / " + formatCount(tile.goal) : "";
	}

	/** Compact count: 1_507_300 → "1.5M", 2_000_000 → "2M", 15_000 → "15K", 500 → "500". */
	// One definition, shared with ConnectionView.WeeklyView's gain formatting (which also has to know
	// about EHP/EHB milli-hours) so the card and the standings rows can't drift apart.
	private static String formatCount(long n)
	{
		return ConnectionView.formatCount(n);
	}

	/** The team activity feed — one colored line per event (newest first), capped so the panel stays glanceable. */
	private JPanel buildActivityFeed(List<ActivityEntry> entries)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setAlignmentX(LEFT_ALIGNMENT);

		int shown = 0;
		for (ActivityEntry e : entries)
		{
			if (shown >= ACTIVITY_ROWS_SHOWN)
			{
				break;
			}
			if (shown > 0)
			{
				list.add(gap(3));
			}
			list.add(buildActivityRow(e));
			shown++;
		}
		if (entries.size() > ACTIVITY_ROWS_SHOWN)
		{
			list.add(gap(3));
			JLabel more = new JLabel("+" + (entries.size() - ACTIVITY_ROWS_SHOWN) + " more");
			more.setFont(FontManager.getRunescapeSmallFont());
			more.setForeground(VALUE_COLOR);
			more.setAlignmentX(LEFT_ALIGNMENT);
			list.add(more);
		}
		list.setMaximumSize(new Dimension(Integer.MAX_VALUE, list.getPreferredSize().height));
		return list;
	}

	private JLabel buildActivityRow(ActivityEntry e)
	{
		JLabel row = new JLabel(plainText(ellipsize(e.summary(), 36)));
		row.setFont(FontManager.getRunescapeSmallFont());
		row.setToolTipText(plainText(e.summary()));
		row.setAlignmentX(LEFT_ALIGNMENT);
		// Completions read as wins (green); reveals are announcements (gold, like your own actions);
		// your own actions stand out (gold); teammates stay neutral.
		if (e.isCompletion())
		{
			row.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		}
		else if (e.kind == ActivityEntry.Kind.REVEAL || e.self)
		{
			row.setForeground(ColorScheme.BRAND_ORANGE);
		}
		else
		{
			row.setForeground(ColorScheme.TEXT_COLOR);
		}
		return row;
	}

	/**
	 * Neutralize a site-supplied string for Swing. A {@link JLabel}/{@link javax.swing.JToolTip} renders as
	 * HTML when its text begins (ignoring leading whitespace, case-insensitive) with {@code <html}, so an
	 * untrusted clan/tile/activity name could inject markup. Such strings get their markup chars escaped so they
	 * render only as literal text; ordinary strings pass through. An explicit sanitize rather than reliance on
	 * {@code html.disable}; every server-supplied field the panel renders routes through here.
	 *
	 * <p>Use {@link #esc} instead when the string is being placed INSIDE markup we are building: there the
	 * leading-{@code <html} test does not apply and every occurrence has to be escaped.</p>
	 */
	static String plainText(String s)
	{
		if (s == null)
		{
			return "";
		}
		int i = 0;
		while (i < s.length() && Character.isWhitespace(s.charAt(i)))
		{
			i++;
		}
		if (s.regionMatches(true, i, "<html", 0, 5))
		{
			return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		}
		return s;
	}

	/** Clip an over-long label to width with an ellipsis so a feed/spotlight row never overflows the panel. */
	private static String ellipsize(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		return s.length() <= max ? s : s.substring(0, Math.max(0, max - 1)).trim() + "…";
	}

	/**
	 * Drop the held ladder-card refs. Only one card renders at a time, so every render path that isn't
	 * building a ladder card must clear them — otherwise the 1 s tick keeps updating labels that are no
	 * longer on screen.
	 */
	private void clearLadderRefs()
	{
		ladderState = null;
		ladderCountdownLabel = null;
		ladderCardPanel = null;
		ladderValueLabels.clear();
	}

	private JPanel buildSummary(ConnectionView c)
	{
		// Only one card renders at a time (renderSelected), so the ladder tick binds to a single set of
		// held refs. Reset them each render; a non-ladder card leaves the tick idle.
		clearLadderRefs();
		// A ladder IS its missions board, so the card replaces the summary. A bingo that merely carries
		// missions keeps its tile-count summary and gets the mission strip as its own section below.
		if (c.ladder != null && c.ladder.ladderFormat)
		{
			return buildLadderCard(c);
		}

		JPanel panel = new JPanel(new BorderLayout(0, 4));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		panel.setAlignmentX(LEFT_ALIGNMENT);

		String eventLine = c.eventName == null || c.eventName.isEmpty() ? c.clanName : c.eventName;
		JLabel event = new JLabel(plainText(eventLine));
		event.setFont(FontManager.getRunescapeFont());
		event.setForeground(ColorScheme.TEXT_COLOR);
		panel.add(event, BorderLayout.NORTH);

		// Count is a FontManager JLabel, NOT painted inside the bar (default L&F font rendered poorly).
		JPanel bottom = new JPanel(new BorderLayout(0, 2));
		bottom.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (c.tilesTotal <= 0)
		{
			// No live board on this clan (federated homes with no running event report 0/0) — a bare
			// "0 / 0 tiles · 0%" reads like a bug, so say what's actually going on instead. The view
			// can carry a more specific line (e.g. the logged-out home's "Log in in-game …").
			JLabel none = new JLabel(c.statusNote != null && !c.statusNote.isEmpty()
				? c.statusNote : "No active event yet.");
			none.setFont(FontManager.getRunescapeSmallFont());
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			bottom.add(none, BorderLayout.NORTH);
		}
		else
		{
			JLabel count = new JLabel(c.tilesComplete + " / " + c.tilesTotal + " " + c.unitNoun() + " · " + c.completionPercent() + "%");
			count.setFont(FontManager.getRunescapeSmallFont());
			count.setForeground(VALUE_COLOR);
			bottom.add(count, BorderLayout.NORTH);

			JProgressBar bar = new JProgressBar(0, 100);
			bar.setValue(c.completionPercent());
			bar.setStringPainted(false);
			bar.setForeground(c.completionPercent() >= 100
				? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE);
			bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
			bar.setBorderPainted(false);
			bar.setPreferredSize(new Dimension(0, PROGRESS_BAR_HEIGHT + 1));
			bottom.add(bar, BorderLayout.CENTER);

			// Reveal-policy boards: "4 tiles hidden · next in 42m" under the bar, so members know
			// more is coming (and when) without opening the site. Null on classic boards.
			if (c.revealNote != null && !c.revealNote.isEmpty())
			{
				JLabel reveal = new JLabel(plainText(c.revealNote));
				reveal.setFont(FontManager.getRunescapeSmallFont());
				reveal.setForeground(ColorScheme.BRAND_ORANGE);
				bottom.add(reveal, BorderLayout.SOUTH);
			}
		}

		panel.add(bottom, BorderLayout.CENTER);

		JPanel south = new JPanel();
		south.setLayout(new BoxLayout(south, BoxLayout.Y_AXIS));
		south.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		if (c.boardUrl != null && !c.boardUrl.isEmpty())
		{
			south.add(boardLink(c.boardUrl));
		}
		if (south.getComponentCount() > 0)
		{
			panel.add(south, BorderLayout.SOUTH);
		}

		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	/**
	 * One open mission: label on the left, live grow/decay value on the right. Shared by the ladder
	 * card and the bingo mission strip so both age their values on the same per-second tick — the
	 * label is registered with {@link #ladderValueLabels} either way.
	 */
	private JPanel buildMissionRow(ConnectionView.Ladder.Mission m, ConnectionView.Ladder l, long now)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);

		JLabel name = new JLabel(plainText(ellipsize(m.label, 22)));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.TEXT_COLOR);

		long val = LadderMissions.liveValue(m.face, m.revealedAtIso, l.decay, now);
		JLabel value = new JLabel(LadderMissions.valueLabel(m.face, val));
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(valueColor(m.face, val));
		value.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(name, BorderLayout.CENTER);
		row.add(value, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		ladderValueLabels.add(new LadderValueLabel(value, m.face, m.revealedAtIso));
		return row;
	}

	/**
	 * Missions on an ordinary bingo — the countdown to the next drop plus what's open right now, with
	 * the same live values a ladder shows. No rank line: a bingo scores by team, not by a personal
	 * ladder position.
	 */
	private JPanel buildMissionStrip(ConnectionView.Ladder l)
	{
		final long now = System.currentTimeMillis();
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		panel.setAlignmentX(LEFT_ALIGNMENT);

		JLabel countdown = leftLabel(countdownText(l, now), FontManager.getRunescapeBoldFont(), ColorScheme.BRAND_ORANGE);
		panel.add(countdown);
		panel.add(gap(4));
		for (ConnectionView.Ladder.Mission m : l.missions)
		{
			panel.add(buildMissionRow(m, l, now));
		}
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));

		// Bind the per-second tick to this strip, exactly as the ladder card does for itself — without
		// it the countdown would sit frozen until the next config poll.
		ladderState = l;
		ladderCountdownLabel = countdown;
		ladderCardPanel = panel;
		return panel;
	}

	/**
	 * The DMM-All-Stars-style missions board for a ladder event: your rank, a live per-second countdown
	 * to the next drop, and the currently-open missions with a live grow/decay value each. Replaces the
	 * tile-count summary + reveal note (a rotating daily ladder has no fixed board to count). The held
	 * label refs let {@link #tickLadder()} update the countdown + values once a second without a refetch.
	 */
	private JPanel buildLadderCard(ConnectionView c)
	{
		ConnectionView.Ladder l = c.ladder;
		final long now = System.currentTimeMillis();

		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		panel.setAlignmentX(LEFT_ALIGNMENT);

		String eventLine = c.eventName == null || c.eventName.isEmpty() ? c.clanName : c.eventName;
		panel.add(leftLabel(eventLine, FontManager.getRunescapeFont(), ColorScheme.TEXT_COLOR));
		panel.add(leftLabel(rankLine(l), FontManager.getRunescapeSmallFont(), VALUE_COLOR));
		panel.add(gap(6));

		JLabel countdown = leftLabel(countdownText(l, now), FontManager.getRunescapeBoldFont(), ColorScheme.BRAND_ORANGE);
		panel.add(countdown);
		panel.add(gap(6));

		if (l.missions.isEmpty())
		{
			panel.add(leftLabel("Waiting for the next mission…", FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR));
		}
		else
		{
			panel.add(leftLabel("Active missions", FontManager.getRunescapeSmallFont(), ColorScheme.LIGHT_GRAY_COLOR));
			panel.add(gap(2));
			for (ConnectionView.Ladder.Mission m : l.missions)
			{
				panel.add(buildMissionRow(m, l, now));
			}
		}

		if (c.boardUrl != null && !c.boardUrl.isEmpty())
		{
			panel.add(gap(6));
			panel.add(boardLink(c.boardUrl));
		}

		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));

		// Bind the tick to this card.
		ladderState = l;
		ladderCountdownLabel = countdown;
		ladderCardPanel = panel;
		return panel;
	}

	/** A left-aligned JLabel (BoxLayout children default to centre), sanitized for federated text. */
	private JLabel leftLabel(String text, Font font, Color color)
	{
		JLabel label = new JLabel(plainText(text));
		label.setFont(font);
		label.setForeground(color);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	/** "You: #4 this month · #12 all-time", or an encouraging line when the caller hasn't scored yet. */
	private static String rankLine(ConnectionView.Ladder l)
	{
		if (l.monthRank <= 0)
		{
			return "You: unranked — finish a mission to get on the board";
		}
		String line = "You: #" + l.monthRank + " this month · " + l.monthPoints + " pts";
		if (l.allTimeRank > 0)
		{
			line += " · #" + l.allTimeRank + " all-time";
		}
		return line;
	}

	/** "Next mission in 12:34" / "New mission dropping…" / "Next mission: on a claim" (bounty, no clock). */
	private static String countdownText(ConnectionView.Ladder l, long now)
	{
		String cd = LadderMissions.countdown(l.nextRevealAtIso, now);
		if (cd == null)
		{
			return "Next mission drops on a claim";
		}
		return "now".equals(cd) ? "New mission dropping…" : "Next mission in " + cd;
	}

	/** Grey when unchanged, green when it grew, orange when it's decaying. */
	private static Color valueColor(long face, long current)
	{
		if (current == face)
		{
			return VALUE_COLOR;
		}
		return current > face ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE;
	}

	/** Live per-second refresh of the shown ladder card: the countdown, each mission's value, the flash. */
	private void tickLadder()
	{
		final long now = System.currentTimeMillis();
		ConnectionView.Ladder l = ladderState;
		if (l != null)
		{
			if (ladderCountdownLabel != null)
			{
				ladderCountdownLabel.setText(plainText(countdownText(l, now)));
			}
			for (LadderValueLabel v : ladderValueLabels)
			{
				long val = LadderMissions.liveValue(v.face, v.revealedAtIso, l.decay, now);
				v.label.setText(LadderMissions.valueLabel(v.face, val));
				v.label.setForeground(valueColor(v.face, val));
			}
		}
		applyFlash(now);
	}

	/** Pulse the card border gold while a new-mission / claim signal is fresh (see {@link #flashLadder()}). */
	private void applyFlash(long now)
	{
		if (ladderCardPanel == null)
		{
			return;
		}
		if (now < ladderFlashUntil)
		{
			boolean on = ((ladderFlashUntil - now) / 350) % 2 == 0;
			ladderCardPanel.setBorder(BorderFactory.createMatteBorder(8, 8, 8, 8,
				on ? LADDER_FLASH_COLOR : ColorScheme.DARKER_GRAY_COLOR));
			ladderFlashPainted = true;
		}
		else if (ladderFlashPainted)
		{
			ladderCardPanel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
			ladderFlashPainted = false;
		}
	}

	/**
	 * Signal a fresh new-mission / claim so the ladder card pulses gold for a few seconds. Called from the
	 * plugin's config-refresh diff OFF the EDT — a plain volatile write the 1s tick picks up on the EDT.
	 */
	public void flashLadder()
	{
		ladderFlashUntil = System.currentTimeMillis() + LADDER_FLASH_MS;
	}

	/** Held ref for one mission's value label so the tick recomputes its grow/decay value in place. */
	private static final class LadderValueLabel
	{
		final JLabel label;
		final int face;
		final String revealedAtIso;

		LadderValueLabel(JLabel label, int face, String revealedAtIso)
		{
			this.label = label;
			this.face = face;
			this.revealedAtIso = revealedAtIso;
		}
	}

	/** A clickable "View standings" link opening the board's site page in the system browser. */
	private JLabel boardLink(String url)
	{
		return siteLink("View standings ↗", "Open the full standings on the Anvil site", url);
	}

	/** As {@link #boardLink}, for an event you're not in yet — the site page is where you sign up. */
	private JLabel eventLink(String url)
	{
		return siteLink("View event ↗", "Open this event on the Anvil site", url);
	}

	private JLabel siteLink(String text, String tooltip, String url)
	{
		JLabel link = new JLabel(text);
		link.setFont(FontManager.getRunescapeSmallFont());
		link.setForeground(ColorScheme.BRAND_ORANGE);
		link.setToolTipText(tooltip);
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		link.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		link.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				if (isSafeHttpUrl(url)) // defense-in-depth: never a javascript:/data:/file: or creds@host URL
				{
					LinkBrowser.browse(url);
				}
			}
		});
		return link;
	}

	/** True only for a well-formed absolute {@code http}/{@code https} URL with a host and no embedded
	 *  credentials — refuses {@code javascript:} / {@code data:} / {@code file:} and {@code user@host} tricks. */
	static boolean isSafeHttpUrl(String url)
	{
		if (url == null || url.isEmpty())
		{
			return false;
		}
		try
		{
			java.net.URI u = new java.net.URI(url);
			String scheme = u.getScheme();
			return u.getHost() != null && u.getUserInfo() == null
				&& ("https".equalsIgnoreCase(scheme) || "http".equalsIgnoreCase(scheme));
		}
		catch (java.net.URISyntaxException ex)
		{
			return false;
		}
	}

	private JPanel buildTileRow(ConnectionView.TileProgressView tile)
	{
		JPanel row = new JPanel(new GridBagLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.anchor = GridBagConstraints.WEST;

		JLabel name = new JLabel(plainText(tile.name));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(tile.complete ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.TEXT_COLOR);
		row.add(name, gbc);

		JLabel value = new JLabel(progressText(tile));
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(VALUE_COLOR);
		gbc.gridx = 1;
		gbc.weightx = 0;
		gbc.fill = GridBagConstraints.NONE;
		gbc.anchor = GridBagConstraints.EAST;
		row.add(value, gbc);

		JProgressBar bar = new JProgressBar(0, 100);
		bar.setValue(tile.percent());
		bar.setStringPainted(false);
		bar.setBorderPainted(false);
		bar.setForeground(tile.complete
			? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_INPROGRESS_COLOR);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setPreferredSize(new Dimension(0, PROGRESS_BAR_HEIGHT));
		gbc.gridx = 0;
		gbc.gridy = 1;
		gbc.gridwidth = 2;
		gbc.weightx = 1;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.insets = new java.awt.Insets(3, 0, 0, 0);
		row.add(bar, gbc);

		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** "c / t" for counted tiles, "42%" for very large targets (XP), or "Done"/"—". */
	private static String progressText(ConnectionView.TileProgressView tile)
	{
		if (tile.complete)
		{
			return "Done";
		}
		if (tile.target <= 0)
		{
			return "—";
		}
		if (tile.target >= 100_000)
		{
			// Big numeric goals (XP, gp) read better as a percentage than as raw counts.
			return tile.percent() + "%";
		}
		return tile.current + " / " + tile.target;
	}

	private JLabel warningLabel(String message)
	{
		JLabel warn = new JLabel(plainText(message));
		warn.setFont(FontManager.getRunescapeSmallFont());
		warn.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		warn.setAlignmentX(LEFT_ALIGNMENT);
		return warn;
	}

	/** Swap the single content component and repaint. */
	private void setContent(Component component)
	{
		SwingUtilities.invokeLater(() ->
		{
			content.removeAll();
			if (component instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) component).setAlignmentX(LEFT_ALIGNMENT);
			}
			content.add(component);
			content.revalidate();
			content.repaint();
		});
	}

	private static Component gap(int height)
	{
		return javax.swing.Box.createVerticalStrut(height);
	}

	/** Renders a {@link ConnectionView} in the clan dropdown by name, flagging an unreachable home. */
	// ---- Anvil-themed widget chrome ---------------------------------------------------------------

	/** Flat dark button matching the sidebar theme: dark surface, thin border, hover lift, no L&F chrome. */
	/** A themed action button in the panel's orange, wired to one thing it does. */
	private static JButton actionButton(String label, String tooltip, Runnable onClick)
	{
		JButton b = new JButton(label);
		styleFlatButton(b, ColorScheme.BRAND_ORANGE);
		b.setAlignmentX(LEFT_ALIGNMENT);
		b.setToolTipText(tooltip);
		b.addActionListener(e -> onClick.run());
		return b;
	}

	/**
	 * Two buttons on one line, equal halves.
	 *
	 * <p>The height cap matters: a grid inside a vertical BoxLayout will happily stretch to whatever
	 * space is left, which turns a pair of buttons into a pair of slabs.
	 */
	private static JPanel buttonRow(JButton left, JButton right)
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(left);
		row.add(right);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	/** One button holding a whole row, so a lone action doesn't sit in half a line. */
	private static JPanel fullWidth(JButton button)
	{
		JPanel row = new JPanel(new GridLayout(1, 1));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(button);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private static void styleFlatButton(JButton b, Color foreground)
	{
		b.setFocusPainted(false);
		b.setForeground(foreground);
		b.setBackground(WIDGET_BG);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(WIDGET_BORDER),
			BorderFactory.createEmptyBorder(4, 10, 4, 10)));
		b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		b.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (b.isEnabled())
				{
					b.setBackground(WIDGET_BG_HOVER);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				b.setBackground(WIDGET_BG);
			}
		});
	}

	/** Theme the clan-filter combo: dark flat field, gold arrow, dark popup — default Swing sticks out. */
	private static void styleClanPicker(JComboBox<ClanChoice> combo)
	{
		combo.setBackground(WIDGET_BG);
		combo.setForeground(Color.WHITE);
		combo.setFont(FontManager.getRunescapeSmallFont());
		combo.setBorder(BorderFactory.createLineBorder(WIDGET_BORDER));
		combo.setUI(new BasicComboBoxUI()
		{
			@Override
			protected JButton createArrowButton()
			{
				BasicArrowButton arrow = new BasicArrowButton(
					SwingConstants.SOUTH, WIDGET_BG, WIDGET_BG, ColorScheme.BRAND_ORANGE, WIDGET_BG);
				arrow.setBorder(BorderFactory.createEmptyBorder());
				return arrow;
			}
		});
	}

	/**
	 * Two real labels, not one HTML one.
	 *
	 * The second line was <code>&lt;font size='-2'&gt;</code> inside a label already set to
	 * RuneScape's small font. That font is a bitmap face: asked to render smaller still it does not
	 * get daintier, it gets illegible — and the size the browser-ish HTML renderer picks is not one
	 * the face was drawn at. The rest of this panel never shrinks type to mean "secondary"; it keeps
	 * the same small font and drops the colour to {@link #VALUE_COLOR}. This does the same.
	 *
	 * Building the row out of components also means no markup, which means no clan name can smuggle
	 * any: {@link #plainText} was guarding a string we were about to concatenate into HTML ourselves,
	 * which is the one case it does not guard.
	 */
	private static final class ClanChoiceRenderer implements ListCellRenderer<ClanChoice>
	{
		private final JPanel row = new JPanel(new BorderLayout(0, 1));
		private final JLabel name = new JLabel();
		private final JLabel detail = new JLabel();

		ClanChoiceRenderer()
		{
			name.setFont(FontManager.getRunescapeSmallFont());
			detail.setFont(FontManager.getRunescapeSmallFont());
			row.setOpaque(true);
			row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
			row.add(name, BorderLayout.NORTH);
			row.add(detail, BorderLayout.SOUTH);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends ClanChoice> list, ClanChoice value,
			int index, boolean isSelected, boolean cellHasFocus)
		{
			// index >= 0 → a popup row; -1 → the closed field. Dark rows, gold-tinted hover.
			boolean hover = isSelected && index >= 0;
			row.setBackground(hover ? WIDGET_BG_HOVER : WIDGET_BG);
			name.setForeground(hover ? ColorScheme.BRAND_ORANGE : Color.WHITE);
			detail.setForeground(VALUE_COLOR);

			name.setText(value == null ? "" : plainText(value.label));
			// The closed field shows the name alone — a second line there would resize the header on
			// every refresh, and the detail is what you read while choosing, not after.
			boolean showDetail = index >= 0 && value != null && !value.detail.isEmpty();
			detail.setText(showDetail ? plainText(value.detail) : "");
			detail.setVisible(showDetail);
			return row;
		}
	}
}

package com.anvil;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * How a drop should be *talked about*: was it lucky, was it a long-overdue grind, or is it a rare
 * roll on something worthless?
 *
 * Rarity alone can't answer that. A 1/5000 roll on a player's second kill is a spoon; the same roll
 * at 20,000 kills is the opposite. So everything here is expressed against the kill count: with a
 * per-kill probability p, the share of players who would already hold the drop after kc kills is
 *
 *     P(at least one by now) = 1 - (1 - p)^kc
 *
 * A small share means you beat almost everyone to it (spooned); a large one means you were dry.
 *
 * Pure static logic with no RuneLite dependencies, so it's unit-tested directly (DropLuckTest).
 */
public final class DropLuck
{
	private DropLuck()
	{
	}

	/** Beat ~90% of players to it. */
	private static final double SPOONED_SHARE = 0.10;
	/** Ahead of the pack, but not absurd. */
	private static final double LUCKY_SHARE = 0.35;
	/** Most players already had it by this point — the grind was real. */
	private static final double DRY_SHARE = 0.85;

	/**
	 * A drop this rare that's worth less than this is a punchline, not a prize — the 1/10,000 roll
	 * that hands you a Dragon spear. Above it, it's simply a rare drop.
	 */
	public static final long TROLL_VALUE_CEILING = 250_000L;

	/**
	 * Awards you're GIVEN for finishing something, not rolled for: the cape you get for clearing the
	 * Inferno, the quiver for the Colosseum. Calling these "spooned" reads as an insult to the run,
	 * so the reaction lines are suppressed for them. Substring-matched, lowercased — the same style
	 * as the always-notify allowlist, so "Infernal cape (broken)" still matches.
	 */
	private static final List<String> EARNED_AWARDS = Arrays.asList(
		"infernal cape",
		"fire cape",
		"dizana's quiver",
		"champion's cape",
		"quest point cape",
		"music cape",
		"achievement diary cape",
		"max cape");

	public enum Verdict
	{
		/** Well ahead of the drop rate. */
		SPOONED,
		/** Ahead of the drop rate. */
		LUCKY,
		/** About when you'd expect it. */
		TYPICAL,
		/** Long past due. */
		DRY,
		/** No rate or no kill count — say nothing. */
		UNKNOWN
	}

	/** True when this item is handed out for completing content rather than rolled for. */
	public static boolean isEarnedAward(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return false;
		}
		String n = itemName.toLowerCase(Locale.ROOT);
		for (String award : EARNED_AWARDS)
		{
			if (n.contains(award))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Share of players (0..1) who would already hold a drop of probability {@code p} after
	 * {@code kc} kills. Computed as 1-(1-p)^kc, via expm1/log1p so tiny rates don't lose precision.
	 */
	public static double obtainedShare(double p, int kc)
	{
		if (p <= 0 || kc <= 0)
		{
			return 0;
		}
		if (p >= 1)
		{
			return 1;
		}
		// 1 - exp(kc * ln(1-p)); log1p/expm1 keep this accurate for p in the 1e-5 range.
		return -Math.expm1(kc * Math.log1p(-p));
	}

	/** Where this drop sits against the grind. UNKNOWN when either input is missing. */
	public static Verdict classify(Double dropRate, Integer killCount)
	{
		if (dropRate == null || dropRate <= 0 || killCount == null || killCount <= 0)
		{
			return Verdict.UNKNOWN;
		}
		double share = obtainedShare(dropRate, killCount);
		if (share < SPOONED_SHARE)
		{
			return Verdict.SPOONED;
		}
		if (share < LUCKY_SHARE)
		{
			return Verdict.LUCKY;
		}
		if (share >= DRY_SHARE)
		{
			return Verdict.DRY;
		}
		return Verdict.TYPICAL;
	}

	/**
	 * The "Luck" field value, e.g. {@code "Top 8%"} or {@code "Dry — 93% had it by now"}. Null for a
	 * typical or unknown result, which is the common case and shouldn't add a field.
	 */
	public static String luckLabel(Double dropRate, Integer killCount)
	{
		Verdict verdict = classify(dropRate, killCount);
		if (verdict == Verdict.UNKNOWN || verdict == Verdict.TYPICAL)
		{
			return null;
		}
		int pct = (int) Math.max(1, Math.round(obtainedShare(dropRate, killCount) * 100));
		switch (verdict)
		{
			case SPOONED:
				return "Top " + pct + "% — spooned";
			case LUCKY:
				return "Top " + pct + "%";
			case DRY:
				return "Dry — " + pct + "% had it by now";
			default:
				return null;
		}
	}

	/**
	 * A "troll": rare enough to trip the rarity gate, but worth almost nothing. Worth calling out as
	 * a joke rather than dressing up as treasure.
	 *
	 * @param dropRate     per-kill probability, or null when the drop qualified on value alone
	 * @param value        the drop's gp value
	 * @param rarityFloor  1-in-N the drop must beat to count as troll-rare (the clan's rarity floor)
	 */
	public static boolean isTrollDrop(Double dropRate, long value, int rarityFloor)
	{
		if (dropRate == null || dropRate <= 0 || rarityFloor <= 0)
		{
			return false;
		}
		if (value >= TROLL_VALUE_CEILING)
		{
			return false;
		}
		return MathUtils.lessThanOrEqual(dropRate, 1.0 / rarityFloor);
	}

	/**
	 * Whether to append a lucky-drop reaction line. Earned awards never qualify (see
	 * {@link #EARNED_AWARDS}); otherwise it's a genuine spoon against the kill count, or a drop
	 * valuable enough to be a moment regardless of how long it took.
	 */
	public static boolean deservesSpoonLine(String itemName, long value, Double dropRate, Integer killCount, long bigValue)
	{
		if (isEarnedAward(itemName))
		{
			return false;
		}
		if (classify(dropRate, killCount) == Verdict.SPOONED)
		{
			return true;
		}
		// No kill count to judge against (untracked NPC, or the clan hides KC): fall back to value.
		return value >= bigValue;
	}
}

package com.anvil;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.function.Consumer;

/**
 * Minimal obs-websocket v5 client — connects to OBS, saves the replay buffer on demand, and reports
 * the saved file path back via {@code onClipSaved} so the plugin can post it. Independent of the
 * "Save Replay Buffer for OBS" plugin (we run our own connection because we need the saved path,
 * which that plugin never exposes). All callbacks fire off the client thread.
 *
 * <p>Protocol: Hello(0) → Identify(1) [with SHA-256 auth if OBS requires it] → Identified(2). We
 * subscribe to the Outputs event category so we receive the {@code ReplayBufferSaved} event.
 */
@Slf4j
public class ObsReplayClient extends WebSocketListener
{
	// EventSubscription::Outputs (1 << 6) — the category that contains ReplayBufferSaved.
	private static final int EVENT_SUB_OUTPUTS = 1 << 6;

	private final OkHttpClient http;
	private final Gson gson;
	private final String url;
	private final String password;
	private final Consumer<String> onClipSaved; // savedReplayPath
	private final Runnable onConnected;
	private final Consumer<String> onError;
	private final java.util.function.IntSupplier clipSeconds;
	private final java.util.function.Supplier<String> clipFormat; // OBS RecFormat value, or null to leave as-is
	// When true, also act on ReplayBufferSaved events we didn't trigger (OBS's own hotkey/triggers).
	private final java.util.function.BooleanSupplier postExternalSaves;
	// Where the plugin wants OBS to write clips — its own folder, the only place it may read them
	// from without asking. Null/empty leaves the user's recording path alone.
	private final java.util.function.Supplier<String> managedClipDir;
	// Reports the folder OBS is recording to, as OBS itself sees it. Needed to put back what we
	// changed, and to name the folder in the chooser when we are NOT managing it.
	private final Consumer<String> onRecordDirectory;

	private WebSocket webSocket;
	private volatile boolean connected;
	// Where OBS says it is recording, as of the last GetRecordDirectory. Compared against the folder
	// we want so a buffer that is already running with the wrong path can be cycled onto the right one.
	private volatile String recordDir;
	// True between our own SaveReplayBuffer request and the matching ReplayBufferSaved event. OBS
	// broadcasts ReplayBufferSaved to EVERY connected obs-websocket client, so without this guard a
	// second RuneLite client sharing the same OBS would also upload a clip it never triggered.
	private volatile boolean awaitingSave;

	public ObsReplayClient(OkHttpClient http, Gson gson, String host, int port, String password,
		Consumer<String> onClipSaved, Runnable onConnected, Consumer<String> onError,
		java.util.function.IntSupplier clipSeconds, java.util.function.Supplier<String> clipFormat,
		java.util.function.BooleanSupplier postExternalSaves,
		java.util.function.Supplier<String> managedClipDir, Consumer<String> onRecordDirectory)
	{
		this.http = http;
		this.gson = gson;
		this.url = "ws://" + host + ":" + port;
		this.password = password == null ? "" : password;
		this.onClipSaved = onClipSaved;
		this.onConnected = onConnected;
		this.onError = onError;
		this.clipSeconds = clipSeconds;
		this.clipFormat = clipFormat;
		this.postExternalSaves = postExternalSaves;
		this.managedClipDir = managedClipDir;
		this.onRecordDirectory = onRecordDirectory;
	}

	public void connect()
	{
		log.debug("Anvil OBS: connecting to {}", url);
		webSocket = http.newWebSocket(new Request.Builder().url(url).build(), this);
	}

	public void disconnect()
	{
		connected = false;
		if (webSocket != null)
		{
			webSocket.close(1000, "Normal Shutdown");
			webSocket = null;
		}
	}

	public boolean isConnected()
	{
		return connected;
	}

	/** Ask OBS to flush the replay buffer to disk. The path comes back via the ReplayBufferSaved event. */
	public void saveReplayBuffer()
	{
		if (!connected)
		{
			return;
		}
		// Mark that the next ReplayBufferSaved broadcast is ours to act on.
		awaitingSave = true;
		sendRequest("SaveReplayBuffer", "anvil-clip");
	}

	/**
	 * Change the replay-buffer length/format. RecRBTime only applies when the buffer (re)starts, so we
	 * stop it and let the StopReplayBuffer *response* trigger a restart (see the op-7 handler). Doing
	 * Stop+Start back-to-back is racy — OBS rejects a Start while the output is still stopping — which
	 * is exactly what left the buffer dead before. Safe whether or not it's currently running.
	 */
	public void applyClipLength()
	{
		if (!connected)
		{
			return;
		}
		sendRequest("StopReplayBuffer", "anvil-rb-stop");
	}

	/**
	 * Write the configured replay-buffer length + recording format into the active profile. These only
	 * take effect when the buffer (re)starts, so we always call this immediately before a start. Set
	 * across both Simple and Advanced output modes (the inapplicable one no-ops).
	 */
	private void applyParams()
	{
		String format = clipFormat == null ? null : clipFormat.get();
		if (format != null && !format.isEmpty())
		{
			setProfileParameter("SimpleOutput", "RecFormat2", format);
			setProfileParameter("SimpleOutput", "RecFormat", format);
			setProfileParameter("AdvOut", "RecFormat2", format);
			setProfileParameter("AdvOut", "RecFormat", format);
		}
		// The recording path is read when the buffer STARTS, never at save time, so this is the only
		// moment it can be changed — and it is why the plugin cannot repoint OBS per clip.
		String managed = managedClipDir == null ? null : managedClipDir.get();
		if (managed != null && !managed.isEmpty())
		{
			setRecordDirectory(managed);
		}
		if (clipSeconds != null)
		{
			int secs = Math.max(5, Math.min(600, clipSeconds.getAsInt()));
			setProfileParameter("SimpleOutput", "RecRBTime", Integer.toString(secs));
			setProfileParameter("AdvOut", "RecRBTime", Integer.toString(secs));
		}
	}

	/** True when clips are meant to land in our folder but OBS is currently writing somewhere else. */
	private boolean wantsRedirect()
	{
		String managed = managedClipDir == null ? null : managedClipDir.get();
		return managed != null && !managed.isEmpty() && !managed.equalsIgnoreCase(recordDir);
	}

	/** Apply params, then start. Only call when the buffer is known stopped (status check / post-stop). */
	private void startBuffer()
	{
		applyParams();
		sendRequest("StartReplayBuffer", "anvil-rb-start");
	}

	/**
	 * Point OBS's recording path somewhere. Written through SetProfileParameter rather than
	 * SetRecordDirectory: the dedicated request only arrived in obs-websocket 5.3, and this writes the
	 * same two profile keys that request writes (AdvOut/RecFilePath + SimpleOutput/FilePath), so it
	 * works back to 5.0. Used both to claim the folder and to give the user's own back.
	 */
	public void setRecordDirectory(String dir)
	{
		if (dir == null || dir.isEmpty())
		{
			return;
		}
		setProfileParameter("SimpleOutput", "FilePath", dir);
		setProfileParameter("AdvOut", "RecFilePath", dir);
	}

	private void setProfileParameter(String category, String name, String value)
	{
		JsonObject data = new JsonObject();
		data.addProperty("parameterCategory", category);
		data.addProperty("parameterName", name);
		data.addProperty("parameterValue", value);
		sendRequest("SetProfileParameter", "anvil-rbtime", data);
	}

	private void sendRequest(String requestType, String requestId)
	{
		sendRequest(requestType, requestId, null);
	}

	private void sendRequest(String requestType, String requestId, JsonObject requestData)
	{
		if (webSocket == null)
		{
			return;
		}
		JsonObject d = new JsonObject();
		d.addProperty("requestType", requestType);
		d.addProperty("requestId", requestId);
		if (requestData != null)
		{
			d.add("requestData", requestData);
		}
		JsonObject req = new JsonObject();
		req.addProperty("op", 6);
		req.add("d", d);
		webSocket.send(gson.toJson(req));
	}

	@Override
	public void onMessage(WebSocket ws, String text)
	{
		final JsonObject msg;
		try
		{
			msg = gson.fromJson(text, JsonObject.class);
		}
		catch (Exception e)
		{
			return;
		}
		if (msg == null || !msg.has("op"))
		{
			return;
		}
		int op = msg.get("op").getAsInt();
		JsonObject d = msg.has("d") && msg.get("d").isJsonObject() ? msg.getAsJsonObject("d") : null;

		switch (op)
		{
			case 0: // Hello → Identify
			{
				JsonObject id = new JsonObject();
				id.addProperty("rpcVersion", 1);
				id.addProperty("eventSubscriptions", EVENT_SUB_OUTPUTS);
				// authentication is only present when OBS has auth enabled.
				if (d != null && d.has("authentication") && d.get("authentication").isJsonObject())
				{
					JsonObject auth = d.getAsJsonObject("authentication");
					id.addProperty("authentication",
						computeAuth(auth.get("salt").getAsString(), auth.get("challenge").getAsString()));
				}
				JsonObject identify = new JsonObject();
				identify.addProperty("op", 1);
				identify.add("d", id);
				ws.send(gson.toJson(identify));
				break;
			}
			case 2: // Identified
				connected = true;
				log.info("Anvil OBS: identified — checking replay-buffer status");
				if (onConnected != null)
				{
					onConnected.run();
				}
				// THE DIRECTORY COMES FIRST, and the buffer check waits for its answer. Starting the
				// buffer is what applies a recording path, so asking afterwards would read back OUR
				// folder and save that as "the user's setting" — then restore it to us on shutdown.
				sendRequest("GetRecordDirectory", "anvil-recdir");
				break;
			case 5: // Event
				if (d != null && "ReplayBufferSaved".equals(optString(d, "eventType")))
				{
					// OBS broadcasts this to ALL connected clients. By default only act on a save WE asked
					// for; otherwise another client (e.g. a second RuneLite on the same OBS) triggering it
					// would double-post. When the player opts in to OBS-triggered clips (they rely on OBS or
					// the "Save Replay Buffer for OBS" plugin to auto-save), also act on saves we didn't
					// trigger. self=true means it was our own SaveReplayBuffer.
					boolean self = awaitingSave;
					awaitingSave = false;
					boolean postExternal = postExternalSaves != null && postExternalSaves.getAsBoolean();
					if (!self && !postExternal)
					{
						log.debug("Anvil OBS: ignoring ReplayBufferSaved we didn't trigger");
						break;
					}
					JsonObject ed = d.has("eventData") && d.get("eventData").isJsonObject() ? d.getAsJsonObject("eventData") : null;
					String path = ed == null ? null : optString(ed, "savedReplayPath");
					log.info("Anvil OBS: ReplayBufferSaved → {}", path);
					if (path != null && onClipSaved != null)
					{
						onClipSaved.accept(path);
					}
				}
				break;
			case 7: // RequestResponse
			{
				String rt = optString(d, "requestType");
				JsonObject status = d != null && d.has("requestStatus") && d.get("requestStatus").isJsonObject()
					? d.getAsJsonObject("requestStatus") : null;
				boolean ok = status != null && status.has("result") && status.get("result").getAsBoolean();
				String comment = status != null && status.has("comment") && !status.get("comment").isJsonNull()
					? status.get("comment").getAsString() : "";
				if ("SaveReplayBuffer".equals(rt))
				{
					log.info("Anvil OBS: SaveReplayBuffer result={} {}", ok, comment);
					if (!ok)
					{
						// Our save failed, so no ReplayBufferSaved event will follow. Clear the guard
						// now, otherwise it would wrongly consume the next client's broadcast.
						awaitingSave = false;
						if (onError != null)
						{
							onError.accept("OBS could not save the clip — is the Replay Buffer started?");
						}
					}
				}
				else if ("GetRecordDirectory".equals(rt))
				{
					JsonObject rd = d != null && d.has("responseData") && d.get("responseData").isJsonObject()
						? d.getAsJsonObject("responseData") : null;
					String dir = rd == null ? null : optString(rd, "recordDirectory");
					recordDir = dir;
					log.debug("Anvil OBS: record directory is {}", dir);
					if (onRecordDirectory != null)
					{
						onRecordDirectory.accept(dir);
					}
					// Now it is safe to start the buffer: whatever we apply next can be undone.
					sendRequest("GetReplayBufferStatus", "anvil-rb-status");
				}
				else if ("GetReplayBufferStatus".equals(rt))
				{
					JsonObject rd = d != null && d.has("responseData") && d.get("responseData").isJsonObject()
						? d.getAsJsonObject("responseData") : null;
					boolean active = rd != null && rd.has("outputActive") && rd.get("outputActive").getAsBoolean();
					log.info("Anvil OBS: replay buffer active={}", active);
					if (!active)
					{
						startBuffer();
					}
					else if (wantsRedirect())
					{
						// ALREADY RUNNING, AND WRITING SOMEWHERE WE CANNOT READ. The recording path is
						// read when the buffer starts, so a buffer started before us keeps the old one
						// for as long as it runs — every clip would land out of reach and have to be
						// pasted by hand. Cycle it now, at RuneLite startup, where the few seconds of
						// footage being discarded are seconds of the login screen.
						log.info("Anvil OBS: buffer is running on another folder — restarting it on ours");
						sendRequest("StopReplayBuffer", "anvil-rb-stop");
					}
				}
				else if ("StopReplayBuffer".equals(rt))
				{
					// We stopped it (to apply a new length) — now restart with params applied.
					log.info("Anvil OBS: stop done (result={}) — restarting buffer", ok);
					startBuffer();
				}
				else if ("StartReplayBuffer".equals(rt))
				{
					log.info("Anvil OBS: StartReplayBuffer result={} {}", ok, comment);
				}
				break;
			}
			default:
				break;
		}
	}

	@Override
	public void onClosing(WebSocket ws, int code, String reason)
	{
		connected = false;
	}

	@Override
	public void onFailure(WebSocket ws, Throwable t, Response response)
	{
		// Quiet on purpose — connection problems are reported when the user actually presses the
		// clip hotkey (captureClip says "OBS isn't connected"). Chatting on every reconnect attempt
		// (e.g. OBS simply not running at login) would spam the game chat. onError is reserved for
		// per-save failures (the op-7 path) so the player learns *why* a save they triggered failed.
		connected = false;
		log.debug("Anvil OBS: connection failed: {}", t == null ? "?" : t.getMessage());
	}

	private static String optString(JsonObject o, String key)
	{
		return o.has(key) && !o.get(key).isJsonNull() ? o.get(key).getAsString() : null;
	}

	// obs-websocket v5 auth: base64(sha256( base64(sha256(password + salt)) + challenge )).
	private String computeAuth(String salt, String challenge)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] secretHash = digest.digest((password + salt).getBytes(StandardCharsets.UTF_8));
			String encodedSecret = Base64.getEncoder().encodeToString(secretHash);
			byte[] resultHash = digest.digest((encodedSecret + challenge).getBytes(StandardCharsets.UTF_8));
			return Base64.getEncoder().encodeToString(resultHash);
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 unavailable", e);
		}
	}
}

