    /**
     * Credits diary bingo tiles whose selector list matches this completion.
     * Selectors are "&lt;Area&gt; &lt;Tier&gt;" with "Any" as a wildcard on
     * either side ("Any Elite", "Wilderness Any"); area matching is
     * contains-based so "Lumbridge Any" matches the "Lumbridge &amp; Draynor"
     * area. One completion == amount 1 through the shared proof pipeline
     * (banner + screenshot + retry store).
     */
    private void creditDiaryTiles(String area, String tier) {
        String gate = trackingGateReason();
        if (gate != null || pluginConfig.trackedDiaries == null) {
            if (gate != null) {
                logTrackingSuppressed(gate);
            }
            return;
        }
        String areaLower = area.toLowerCase();
        String tierLower = tier.toLowerCase();
        for (PluginConfigResponse.TrackedDiary d : pluginConfig.trackedDiaries) {
            if (d == null || d.diaries == null || d.currentAmount >= d.requiredAmount) {
                continue;
            }
            boolean matches = false;
            for (String sel : d.diaries) {
                if (sel == null) {
                    continue;
                }
                String s = sel.trim();
                int cut = s.lastIndexOf(' ');
                if (cut <= 0) {
                    continue;
                }
                String selArea = s.substring(0, cut).trim().toLowerCase();
                String selTier = s.substring(cut + 1).trim().toLowerCase();
                boolean areaOk = selArea.equals("any") || areaLower.equals(selArea) || areaLower.contains(selArea);
                boolean tierOk = selTier.equals("any") || tierLower.equals(selTier);
                if (areaOk && tierOk) {
                    matches = true;
                    break;
                }
            }
            if (!matches) {
                continue;
            }
            d.currentAmount += 1;
            final PluginConfigResponse.TrackedDiary fd = d;
            log.info("Tracked diary completion: {} {} → tile '{}' ({}/{})",
                    area, tier, d.label, d.currentAmount, d.requiredAmount);
            captureAndSubmitProof(d.tileId, d.label, 1, null,
                    "DIARY COMPLETE", area + " " + tier + " Diary",
                    "[Auto] " + area + " " + tier + " diary completed — detected by RuneLite plugin",
                    () -> fd.currentAmount = Math.max(0, fd.currentAmount - 1));
        }
    }

    /**
     * Credits Combat Achievement bingo tiles whose selector list matches this completion.
     * Selectors are exact task names ("Whack-a-Mole") or "Any &lt;Tier&gt;" wildcards
     * ("Any Master"), matched case-insensitively. One completion == amount 1 through the
     * shared proof pipeline (banner + screenshot + retry store). A given task credits a
     * given tile at most once per session (creditedCaTaskTiles), so re-meeting the same
     * task's conditions repeatedly can't farm a multi-count wildcard tile.
     */
    private void creditCombatTaskTiles(CombatAchievementTier tier, String task) {
        String gate = trackingGateReason();
        if (gate != null || pluginConfig.trackedCombatTasks == null) {
            if (gate != null) {
                logTrackingSuppressed(gate);
            }
            return;
        }
        String taskLower = task.toLowerCase();
        String anyTier = "any " + tier.getDisplayName().toLowerCase();
        for (PluginConfigResponse.TrackedCombatTask t : pluginConfig.trackedCombatTasks) {
            if (t == null || t.tasks == null || t.currentAmount >= t.requiredAmount) {
                continue;
            }
            boolean matches = false;
            for (String sel : t.tasks) {
                if (sel == null) {
                    continue;
                }
                String s = sel.trim().toLowerCase();
                if (s.equals(taskLower) || s.equals(anyTier)) {
                    matches = true;
                    break;
                }
            }
            final String dedupKey = t.tileId + "|" + taskLower;
            if (!matches) {
                continue;
            }
            if (!creditedCaTaskTiles.add(dedupKey)) {
                log.debug("Combat task '{}' already credited tile '{}' this session — skipping repeat", task, t.label);
                continue;
            }
            t.currentAmount += 1;
            final PluginConfigResponse.TrackedCombatTask ft = t;
            log.info("Tracked combat task: {} '{}' → tile '{}' ({}/{})",
                    tier.getDisplayName(), task, t.label, t.currentAmount, t.requiredAmount);
            captureAndSubmitProof(t.tileId, t.label, 1, null,
                    "COMBAT TASK", tier.getDisplayName() + ": " + task,
                    "[Auto] " + tier.getDisplayName() + " combat task \"" + task + "\" completed — detected by RuneLite plugin",
                    () -> {
                        ft.currentAmount = Math.max(0, ft.currentAmount - 1);
                        // Un-remember the pair so a failed capture can credit on a later re-fire.
                        creditedCaTaskTiles.remove(dedupKey);
                    });
        }
    }

    /**
     * Does this board have tiles that can only credit off the in-game drop-notification line?
     *
     * <p>Drop and value tiles both do, for the corpse-looted bosses whose loot bypasses every loot
     * event the client raises (see {@link #creditDropFromChat}). The rest of the board does not care,
     * but the plugin cannot tell in advance which boss a tile's drop will come from, and the cost of
     * asking is one chat line against a silent 50m fang.</p>
     */
    static boolean eventNeedsDropLines(PluginConfigResponse cfg) {
        if (cfg == null || !AnvilOverlay.isEventActive(cfg.event)) {
            return false;
        }
        return (cfg.trackedDrops != null && !cfg.trackedDrops.isEmpty())
                || (cfg.trackedValues != null && !cfg.trackedValues.isEmpty());
    }

    /**
     * One-time (per session) reminder to enable the in-game "Repeat completion" Combat
     * Achievement setting when the active event has incomplete CA tiles — without it, tasks
     * the player already owns never re-fire the completion line, so those tiles can never
     * track for them. Reads the setting's varbit, so the check runs on the client thread.
     */
    private void maybeNudgeCaRepeatSetting() {
        if (caRepeatNudgeSent || pluginConfig == null || pluginConfig.trackedCombatTasks == null
                || pluginConfig.trackedCombatTasks.isEmpty() || !AnvilOverlay.isEventActive(pluginConfig.event)) {
            return;
        }
        boolean anyIncomplete = false;
        for (PluginConfigResponse.TrackedCombatTask t : pluginConfig.trackedCombatTasks) {
            if (t != null && t.currentAmount < t.requiredAmount) {
                anyIncomplete = true;
                break;
            }
        }
        if (!anyIncomplete) {
            return;
        }
        clientThread.invokeLater(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) {
                return;
            }
            if (client.getVarbitValue(VarbitID.CA_TASK_RECOMPLETION_NOTIFICATIONS) == 1) {
                return; // setting already on — nothing to remind about
            }
            caRepeatNudgeSent = true;
            sendChatMessage("This event has Combat Achievement tiles — enable Settings > Combat Achievements"
                    + " > \"Repeat completion\" so tasks you've already done can still count.");
        });
    }

    /**
     * One-time (per session) reminder to enable the in-game loot drop notifications when clan
     * rare-drop posts are on. The "&lt;player&gt; received a drop: …" chat line those posts key
     * off for corpse-boss spill loot (Maggot King uniques — see creditDropFromChat) is Jagex's
     * opt-in loot notification: with the setting off, or its value threshold above the drop's
     * price, the line never prints and the plugin has nothing to parse — a 50m fang can pass
     * completely silently. Varbit read requires the client thread.
     */
    /**
     * The in-game collection-log notification, which is what prints the line the plugin reads.
     *
     * <p>With it off, an unlock is invisible here: no achievements post, no tile credit, no
     * kill-count stamp. The clan broadcast covers it for anyone in a clan that announces slots —
     * that is the fallback in {@link #handleClogUnlock} — but a solo player, or a clan that doesn't
     * broadcast them, has nothing at all. Worth one line per account, since the cost of not saying
     * it is a log that silently never fills in.</p>
     *
     * <p>Only when the setting is OFF outright. The option has more than two values and the others
     * are not worth guessing at: a nudge that fires for a correctly-configured client is the kind
     * that teaches people to ignore the next one.</p>
     */
    private void maybeNudgeClogNotifications() {
        if (clogNotifyNudgeSent || !config.notifyClogSlots() || !notifyEnabled("collectionLog")) {
            return;
        }
        clientThread.invokeLater(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) {
                return;
            }
            if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 0) {
                return;
            }
            clogNotifyNudgeSent = true;
            sendChatMessage("Your collection log notifications are off in game (Settings > All settings > Chat"
                    + " > \"Collection log - New addition notification\") — new slots won't post to the clan"
                    + " unless your clan broadcasts them.");
        });
    }

    private void maybeNudgeLootNotifications() {
        if (lootNotifyNudgeSent) {
            return;
        }
        // TWO REASONS TO CARE, and only one of them used to be asked about. Clan rare-drop posts
        // need the line, and so does a BOARD with drop or value tiles on it: the same corpse-boss
        // loot that never posts also never credits (creditDropFromChat is what feeds both). Gating
        // the reminder on the clan-post toggle meant a member who had turned posts off — or whose
        // clan doesn't run them — played a bingo whose spill-loot tiles could not fire, and was
        // never told why.
        boolean forPosts = config.notifyRareDrops() && notifyEnabled("rareDrops");
        boolean forTiles = eventNeedsDropLines(pluginConfig);
        if (!forPosts && !forTiles) {
            return;
        }
        clientThread.invokeLater(() -> {
            if (client.getGameState() != GameState.LOGGED_IN) {
                return;
            }
            boolean settingOn = client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_ON) == 1;
            // The plugin's own posting floor (enforced minimum 1m) — an in-game threshold above
            // it would swallow lines for drops the clan channel wants to see.
            long plugFloor = Math.max(1_000_000, Math.max(0, config.rareDropMinValue()));
            long gameThreshold = client.getVarbitValue(VarbitID.OPTION_LOOTNOTIFICATION_VALUE);
            // The threshold half is a CLAN-POST concern only: it is measured against the posting
            // floor, and there is no equivalent number for a tile — a tile wants whatever the drop
            // happens to be worth. So a board-driven reminder ends at "the setting is off".
            if (settingOn && (!forPosts || gameThreshold <= plugFloor)) {
                return; // configured fine — the attribution line will fire for qualifying drops
            }
            lootNotifyNudgeSent = true;
            if (!settingOn) {
                sendChatMessage(forTiles
                        ? "Enable Settings > Chat > \"Loot drop notifications\" — this board has drop tiles, and"
                        + " bosses that spill their loot (Maggot King, Araxxor) only announce it on that line."
                        : "Enable Settings > Chat > \"Loot drop notifications\" — clan rare-drop posts for corpse-boss"
                        + " loot (Maggot King uniques) rely on that chat line.");
            } else {
                sendChatMessage("Your in-game loot notification threshold is above the clan rare-drop floor — lower it"
                        + " (Settings > Chat > Loot drop notifications) or drops like Maggot King uniques won't post.");
            }
        });
    }

    /**
     * Reads the quest-completed scroll and posts the completion, gated by the
     * configured difficulty threshold (default Master &amp; up). Runs a tick
     * after the widget loads so the text child is populated; retries a couple
     * of ticks if the text lands late.
     */
    private void scheduleQuestScrollRead(int attemptsLeft) {
        clientThread.invokeLater(() -> {
            net.runelite.api.widgets.Widget text = client.getWidget(QUEST_COMPLETED_GROUP_ID, QUEST_COMPLETED_TEXT_CHILD);
            String raw = text != null ? text.getText() : null;
            if (raw == null || raw.isEmpty()) {
                if (attemptsLeft > 0) {
                    scheduleQuestScrollRead(attemptsLeft - 1);
                }
                return;
            }
            // A widget, so the angle-bracket form is what appears here — but it costs nothing to
            // take the @ codes too, and the quest scroll is styled by the same game.
            String plain = CHAT_TAG.matcher(raw).replaceAll(" ").replaceAll("\\s+", " ").trim();
            String quest = parseQuestScroll(plain);
            if (quest == null || quest.contains("partial completion")) {
                return; // unparseable, or Hazeel Cult's "kind of completed" — not a completion
            }
            if (!announcedQuests.add(quest.toLowerCase())) {
                return; // widget re-loaded for a quest already posted this session
            }
            postQuestCompletion(quest);
        });
    }

    /**
     * Parses the quest-completed scroll text into the quest name. Ported from
     * RuneLite's ScreenshotPlugin (BSD-2) so all the scroll's text variants
     * resolve correctly — RFD subquests become "Recipe for Disaster - X",
     * "completely completed Rag and Bone Man" becomes "Rag and Bone Man II",
     * and names genuinely containing "Quest" (Legends' Quest, Doric's Quest)
     * keep the word. Returns null when nothing matches. Package-private for
     * the unit test.
     */
    static String parseQuestScroll(String text) {
        java.util.regex.Matcher m1 = QUEST_PATTERN_1.matcher(text);
        java.util.regex.Matcher m2 = QUEST_PATTERN_2.matcher(text);
        java.util.regex.Matcher m = m1.matches() ? m1 : m2;
        if (!m.matches()) {
            return null;
        }
        String quest = m.group("quest");
        String verb = m.group("verb") != null ? m.group("verb") : "";
        if (verb.contains("kind of")) {
            quest += " partial completion";
        } else if (verb.contains("completely")) {
            quest += " II";
        }
        final String questAndVerb = quest + verb;
        if (RFD_TAGS.stream().anyMatch(questAndVerb::contains)) {
            quest = "Recipe for Disaster - " + quest;
        }
        final String questName = quest;
        if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(questName::contains)) {
            quest += " Quest";
        }
        return quest;
    }

    /**
     * Posts a quest completion to the clan achievements channel. Tier comes
     * from the baked name sets; a quest in neither set counts as below Master,
     * so only the "All quests" setting posts it. Message-only, like CA posts.
     */
    private void postQuestCompletion(String questName) {
        QuestAnnounceTier setting = config.questAnnounce();
        if (setting == QuestAnnounceTier.OFF || !notifyEnabled("quests")) {
            return;
        }
        String key = questName.toLowerCase();
        boolean gm = GRANDMASTER_QUESTS.contains(key);
        boolean master = MASTER_QUESTS.contains(key);
        if (setting == QuestAnnounceTier.GRANDMASTER && !gm) {
            return;
        }
        if (setting == QuestAnnounceTier.MASTER && !gm && !master) {
            return;
        }
        String rsn = getLocalPlayerName();
        String tierTag = gm ? " (Grandmaster)" : master ? " (Master)" : "";
        com.google.gson.JsonObject embed = new com.google.gson.JsonObject();
        embed.addProperty("title", "🗺️ Quest complete!");
        embed.addProperty("description",
                (rsn != null ? rsn : "A clan member") + " just completed **" + questName + "**" + tierTag + "!");
        embed.addProperty("color", CA_EMBED_COLOR);
        apiClient.postNotification("quests", null, embed, null, null);
    }

    /**
     * True when the current world's stats aren't the player's real main-game progression, so level-up
     * and total-level milestones must be suppressed. PvP Arena hands out a preset max-stat account;
     * Leagues (SEASONAL) / Deadman / Tournament / Beta / Fresh Start / Quest Speedrunning / LMS / no-save
     * worlds are separate saves or preset loadouts. Hopping onto one otherwise spams "level 99!" for
     * stats the player never trained.
     */
    private boolean statsAreArtificial() {
        java.util.Set<WorldType> w = client.getWorldType();
        return w != null && (
               w.contains(WorldType.PVP_ARENA)
            || w.contains(WorldType.SEASONAL)
            || w.contains(WorldType.DEADMAN)
            || w.contains(WorldType.TOURNAMENT_WORLD)
            || w.contains(WorldType.BETA_WORLD)
            || w.contains(WorldType.FRESH_START_WORLD)
            || w.contains(WorldType.QUEST_SPEEDRUNNING)
            || w.contains(WorldType.LAST_MAN_STANDING)
            || w.contains(WorldType.NOSAVE_MODE));
    }

    private void handleLevelMilestone(String skill) {
        // A 99 happens once per skill per account, so when one does not reach Discord there has to be
        // something in the log saying which step dropped it. Every gate below this used to be silent,
        // and postNotification's own failure paths are log.debug — invisible at RuneLite's default
        // level — which left "it just didn't post" as the entire diagnosis.
        if (!notifyEnabled("levels")) {
            log.info("Anvil: 99 {} not announced — this clan has no channel for level posts.", skill);
            return;
        }
        if (statsAreArtificial()) {
            log.info("Anvil: 99 {} not announced — levels on this world aren't real progression.", skill);
            return;
        }
        // Post a given skill's 99 once per session — the same 99 can arrive from StatChanged and the
        // level-up chat line, and StatChanged pre-seeds skills already 99 at login.
        if (skill == null || !notified99.add(skill.toLowerCase())) {
            return; // already announced this session, or already 99 when the session started
        }
        log.info("Anvil: announcing 99 {}.", skill);
        String rsn = getLocalPlayerName();
        com.google.gson.JsonObject embed = new com.google.gson.JsonObject();
        embed.addProperty("title", "🎉 Level 99!");
        embed.addProperty("description",
                (rsn != null ? rsn : "A clan member") + " just reached **level 99 " + skill + "**!");
        embed.addProperty("color", CA_EMBED_COLOR);
        // How far along they are. A 99 post is about skills rather than total, so it counts those —
        // and a build not chasing max still gets it, because "12 of 23 skills at 99" is a fact about
        // what they have done rather than a distance from somebody else's goal.
        embed.add("fields", oneField("Progress", ninetyNineProgressLine()));
        postAchievement(embed);
    }

    /**
     * Called on every skill level-up. Announces a high-total milestone (every
     * {@code STEP} at or above {@code FLOOR}) or maxing, posting to the clan
     * achievements channel. Uses the baselined total so we only fire on genuine
     * crossings, and skips the round-100 post when this gain maxed.
     */
    private void handleTotalMilestone() {
        // NOT gated on the Discord channel here. The gate moved down to the post itself, because this
        // method also advances lastTotalLevel and feeds the clan's highlight feed — returning early
        // for want of a webhook froze the baseline and lost the milestone from both.
        if (statsAreArtificial()) {
            return;
        }
        int total = client.getTotalLevel();
        if (!totalLevelInitialized) {
            // Login baseline missed (e.g. levelled before the first tick settled) — seed and skip.
            lastTotalLevel = total;
            totalLevelInitialized = true;
            return;
        }
        if (total <= lastTotalLevel) {
            return;
        }
        int prev = lastTotalLevel;
        lastTotalLevel = total;

        int max = maxTotalLevel();
        if (prev < max && max <= total) {
            recordLevelMoment(null, total, "max");
            postTotalMilestone(total, true);
            return; // maxing is the headline — don't also post the round-100 it passed
        }
        // Highest round-STEP value this gain reached, at/above the floor.
        int milestone = (total / TOTAL_MILESTONE_STEP) * TOTAL_MILESTONE_STEP;
        if (milestone >= TOTAL_MILESTONE_FLOOR && prev < milestone) {
            recordLevelMoment(null, milestone, "total");
            postTotalMilestone(milestone, false);
        }
    }

    /**
     * Maximum possible total level, summed from the live Skill enum (adapts as
     * skills are added).
     */
    private int maxTotalLevel() {
        int max = 0;
        for (Skill s : Skill.values()) {
            if (s != Skill.OVERALL) {
                max += 99;
            }
        }
        return max;
    }

    /**
     * Is this account plainly not chasing 2277?
     *
     * THERE IS NO "PURE" ACCOUNT TYPE. RuneLite's AccountType knows Normal and the Ironman variants
     * and nothing else, because a pure is a BUILD rather than a flag — the game does not record the
     * intention, only the stats it produced. So this asks the one question the stats answer without
     * ambiguity: Defence 1. Nobody arrives at 99 Strength with Defence 1 by accident, and a level-3
     * skiller is the same answer for the same reason.
     *
     * It is used only to SUPPRESS a line, never to claim anything. Telling somebody who has chosen a
     * build that they are "435 levels from max" measures them against a goal they rejected, and the
     * cost of guessing wrong is a missing line rather than a wrong one.
     */
    private boolean buildIsNotChasingMax() {
        return client.getRealSkillLevel(Skill.DEFENCE) == 1;
    }

    /** "1,842 / 2,277 — 435 to go", or null when the number would not mean anything. */
    private String maxProgressLine(int total) {
        if (buildIsNotChasingMax()) {
            return null;
        }
        int max = maxTotalLevel();
        int left = max - total;
        if (left <= 0) {
            return null; // already there; the Maxed! post is the whole message
        }
        return String.format(java.util.Locale.ROOT, "%,d / %,d — %,d to go", total, max, left);
    }

    /** "12 of 23 skills at 99", the progress a 99 post is actually about. */
    private String ninetyNineProgressLine() {
        int at99 = 0;
        int of = 0;
        for (Skill sk : Skill.values()) {
            if (sk == Skill.OVERALL) {
                continue;
            }
            of++;
            if (client.getRealSkillLevel(sk) >= 99) {
                at99++;
            }
        }
        return at99 + " of " + of + " skills at 99";
    }

    private void postTotalMilestone(int total, boolean maxed) {
        if (!notifyEnabled("levels")) {
            log.info("Anvil: total-level milestone {} not announced — no channel for level posts.", total);
            return;
        }
        String rsn = getLocalPlayerName();
        String who = rsn != null ? rsn : "A clan member";
        com.google.gson.JsonObject embed = new com.google.gson.JsonObject();
        embed.addProperty("title", maxed ? "🏆 Maxed!" : "📈 Total level milestone!");
        embed.addProperty("description", maxed
                ? who + " just **maxed** with a total level of **" + total + "**!"
                : who + " just reached **" + total + " total level**!");
        embed.addProperty("color", CA_EMBED_COLOR);
        // Where this leaves them — from the LIVE total, not the milestone above.
        //
        // `total` is the rounded figure the post announces (1800), which is right in the sentence and
        // wrong in the progress: somebody who crossed 1800 on a level that took them to 1803 is 474
        // from max, not 477. The headline is the milestone; the progress is where they actually are.
        //
        // Omitted on a max — "0 to go" under "Maxed!" is noise — and on a build not chasing one.
        String progress = maxed ? null : maxProgressLine(client.getTotalLevel());
        if (progress != null) {
            embed.add("fields", oneField("Progress to max", progress));
        }
        postAchievement(embed);
    }

    /** A one-entry Discord `fields` array, inline so it sits beside the description rather than under it. */
    private static com.google.gson.JsonArray oneField(String name, String value) {
        com.google.gson.JsonObject field = new com.google.gson.JsonObject();
        field.addProperty("name", name);
        field.addProperty("value", value);
        field.addProperty("inline", true);
        com.google.gson.JsonArray fields = new com.google.gson.JsonArray();
        fields.add(field);
        return fields;
    }

    private com.google.gson.JsonObject buildDropEmbed(String title, String description,
            String itemName, int qty, long value, Double dropRate, Integer killCount, String shotName) {
        return buildDropEmbed(title, description, itemName, -1, qty, value, dropRate, killCount, shotName);
    }

    private com.google.gson.JsonObject buildDropEmbed(String title, String description,
            String itemName, int itemId, int qty, long value, Double dropRate, Integer killCount, String shotName) {
        return buildDropEmbed(title, description, itemName, itemId, qty, value, dropRate, killCount, shotName,
                "KC", false);
    }

    /**
     * The drop embed. {@code itemId} (or -1 when unknown) adds the item's own sprite as the
     * thumbnail — the same image the game draws, so a channel skim reads as icons rather than text.
     * Numeric fields are wrapped in backticks so Discord boxes them; see the site's
     * lib/discordEmbeds for the house style this matches.
     */
    private com.google.gson.JsonObject buildDropEmbed(String title, String description,
            String itemName, int itemId, int qty, long value, Double dropRate, Integer killCount, String shotName,
            String countLabel, boolean guaranteed) {
        com.google.gson.JsonObject embed = new com.google.gson.JsonObject();
        String rsn = getLocalPlayerName();
        if (rsn != null && !rsn.isEmpty()) {
            com.google.gson.JsonObject author = new com.google.gson.JsonObject();
            author.addProperty("name", rsn);
            embed.add("author", author);
        }
        embed.addProperty("title", title);
        embed.addProperty("description", description);
        embed.addProperty("color", RARE_EMBED_COLOR);

        com.google.gson.JsonArray fields = new com.google.gson.JsonArray();
        fields.add(statField("Item", qty > 1 ? itemName + " ×" + qty : itemName));
        if (value > 0) {
            fields.add(statField("Value", String.format("%,d gp", value)));
        }
        // A guaranteed drop has no rate worth printing and no luck to speak of: "1/1" and "Top 100%"
        // are both true and both noise. Say what it is instead, so the post still explains itself.
        if (guaranteed) {
            fields.add(statField("Drop rate", "Guaranteed"));
        } else if (dropRate != null && dropRate > 0) {
            long oneIn = Math.round(1.0 / dropRate);
            fields.add(statField("Drop rate", "1/" + String.format("%,d", oneIn)));
        }
        if (killCount != null && killCount > 0) {
            // Keys opened and caskets are not kills; calling either KC invites a comparison against
            // a drop rate that has nothing to do with it (DropSource.countLabel).
            fields.add(statField(countLabel == null || countLabel.isEmpty() ? "KC" : countLabel,
                    String.format("%,d", killCount)));
        }
        // Luck reads the rate against the kill count — silent unless the result is worth a remark.
        String luck = guaranteed ? null : DropLuck.luckLabel(dropRate, killCount);
        if (luck != null) {
            fields.add(statField("Luck", luck));
        }
        embed.add("fields", fields);

        // Wiki link (OSRS wiki uses underscores for spaces).
        embed.addProperty("url", "https://oldschool.runescape.wiki/w/" + itemName.replace(' ', '_'));

        if (itemId > 0) {
            com.google.gson.JsonObject thumb = new com.google.gson.JsonObject();
            thumb.addProperty("url", itemIconUrl(itemId));
            embed.add("thumbnail", thumb);
        }

        com.google.gson.JsonObject image = new com.google.gson.JsonObject();
        image.addProperty("url", "attachment://" + shotName);
        embed.add("image", image);
        return embed;
    }

    /**
     * RuneLite's static export of the game cache — the exact sprite the client renders, on a public
     * CDN Discord can fetch. Mirrors the site's lib/tileIcons.itemIconUrl.
     */
    private static String itemIconUrl(int itemId) {
        return "https://static.runelite.net/cache/item/icon/" + itemId + ".png";
    }

    private static com.google.gson.JsonObject embedField(String name, String value, boolean inline) {
        com.google.gson.JsonObject f = new com.google.gson.JsonObject();
        f.addProperty("name", name);
        f.addProperty("value", value);
        f.addProperty("inline", inline);
        return f;
    }

    /** An inline field whose value is a number or short token — boxed with backticks. */
    private static com.google.gson.JsonObject statField(String name, String value) {
        return embedField(name, "`" + value.replace("`", "") + "`", true);
    }

    /**
     * Higher of GE price and high-alch value for a single item. Safe to call on
     * the client thread.
     */
    private long itemUnitValue(int itemId) {
        long ge = 0;
        long ha = 0;
        try {
            ge = Math.max(0, itemManager.getItemPrice(itemId));
        } catch (Exception ignored) {
        }
        try {
            ItemComposition comp = itemManager.getItemComposition(itemId);
            if (comp != null) {
                ha = Math.max(0, comp.getHaPrice());
            }
        } catch (Exception ignored) {
        }
        return Math.max(ge, ha);
    }

    /**
     * Builds the death message: a 1/100 chance of a random fun line
     * (server-served pool, with a baked-in fallback), otherwise the player's
     * own configured message. {name} → RSN.
     */
    private String buildDeathMessage(String rsn) {
        String name = (rsn == null || rsn.isEmpty()) ? "Someone" : rsn;
        String base;
        boolean fun = ThreadLocalRandom.current().nextInt(100) == 0;
        if (fun) {
            List<String> pool = FUN_DEATHS_FALLBACK;
            PluginConfigResponse cfg = pluginConfig;
            if (cfg != null && cfg.funDeathMessages != null && !cfg.funDeathMessages.isEmpty()) {
                pool = cfg.funDeathMessages;
            }
            base = pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
        } else {
            base = config.deathMessage();
            if (base == null || base.isEmpty()) {
                base = "{name} just died!";
            }
        }
        base = base.replace("{name}", name);
        // Funny lines are always on — a cheeky reaction line on every death.
        base += "\n" + randomDeathTaunt();
        return base;
    }

    private static String randomLine(List<String> pool) {
        return pool.get(ThreadLocalRandom.current().nextInt(pool.size()));
    }

    /**
     * A death reaction line — the server pool when the clan has set one, else
     * the baked-in list.
     */
    private String randomDeathTaunt() {
        PluginConfigResponse cfg = pluginConfig;
        List<String> pool = (cfg != null && cfg.deathTaunts != null && !cfg.deathTaunts.isEmpty())
                ? cfg.deathTaunts : DEATH_TAUNTS;
        return randomLine(pool);
    }

    /**
     * A lucky-drop reaction line — the server pool when set, else the baked-in
     * list.
     */
    private String randomSpoonLine() {
        PluginConfigResponse cfg = pluginConfig;
        List<String> pool = (cfg != null && cfg.spoonTaunts != null && !cfg.spoonTaunts.isEmpty())
                ? cfg.spoonTaunts : SPOON_TAUNTS;
        return randomLine(pool);
    }

    /**
     * Whether a clan notification channel ("deaths", "pvpKills", "rareDrops",
     * "combatAchievements") has a Discord webhook configured on the site. The
     * flags are fetched on launch as part of the plugin config and refreshed
     * periodically. When true, the plugin posts the notification to its own
     * server (/api/plugin/notify), which forwards it to Discord — the plugin
     * never sees the webhook URL itself.
     */
    /**
     * Whether the clan has somewhere to put this kind of post.
     *
     * <p>Five kinds -- pets, levels, quests, diaries, collection-log slots -- used to be announced
     * under the name of the channel they shared. Each has its own name now, and a site that predates
     * that split sends no flag for it; a boxed null there means "ask the channel it came from"
     * rather than "off", so an older site keeps posting 99s exactly where it always did.</p>
     *
     * <p>Unknown names return false. The old default arm answered {@code rareDrops} for anything it
     * didn't recognise, which would have quietly routed every new channel through the drop flag.</p>
     */
    private boolean notifyEnabled(String channel) {
        PluginConfigResponse cfg = pluginConfig;
        if (cfg == null || cfg.notify == null) {
            return false;
        }
        return channelEnabled(cfg.notify, channel);
    }

    /** The resolution itself, free of plugin state so the inheritance can be tested directly. */
    static boolean channelEnabled(PluginConfigResponse.NotifyChannels n, String channel) {
        if (n == null) {
            return false;
        }
        switch (channel) {
            case "rareDrops":
                return n.rareDrops;
            case "deaths":
                return n.deaths;
            case "combatAchievements":
                return n.combatAchievements;
            case "pvpKills":
                return n.pvpKills;
            case "pets":
                return n.pets != null ? n.pets : n.rareDrops;
            case "levels":
                return n.levels != null ? n.levels : n.combatAchievements;
            case "quests":
                return n.quests != null ? n.quests : n.combatAchievements;
            case "diaries":
                return n.diaries != null ? n.diaries : n.combatAchievements;
            case "collectionLog":
                return n.collectionLog != null ? n.collectionLog : n.combatAchievements;
            default:
                return false;
        }
    }

    // ---- OBS clip capture ----
    private void connectObs() {
        synchronized (obsLock) {
            disconnectObs();
            obsClip = new ObsReplayClient(
                    okHttpClient,
                    gson,
                    config.obsHost(),
                    config.obsPort(),
                    config.obsPassword(),
                    this::onClipSaved,
                    () -> {
                        // OBS is usually still starting when RuneLite reaches the login screen, so the
                        // ask there finds no connection and skips. This is the second chance, and it
                        // only fires while nothing is happening on screen.
                        if (client.getGameState() == GameState.LOGIN_SCREEN) {
                            maybeAskForClipFolder();
                        }
                    },
                    // Per-save failures (e.g. the Replay Buffer isn't started) — tell the player why.
                    this::sendChatMessage,
                    config::clipLengthSeconds,
                    () -> config.clipMp4() ? "mp4" : null,
                    config::postObsTriggeredClips,
                    // Only when the player asked us to manage it; otherwise null leaves their path alone.
                    () -> config.manageObsFolder() ? clipFolder.managedPath() : null,
                    this::onObsRecordDirectory
            );
            obsClip.connect();
        }
    }

    /**
     * Reconnect tick (runs on the 30s executor loop). OBS often isn't up yet
     * when RuneLite launches, so the one-shot connect at startup can miss.
     * Retrying here means the buffer gets started as soon as OBS becomes
     * reachable — without it, clips only worked after toggling the config
     * off/on.
     */
    private void maybeReconnectObs() {
        if (config.clipsEnabled()) {
            final ObsReplayClient c = obsClip;
            if (c == null || !c.isConnected()) {
                connectObs();
            }
        } else {
            disconnectObs();
        }
    }

    private void disconnectObs() {
        synchronized (obsLock) {
            if (obsClip != null) {
                obsClip.disconnect();
                obsClip = null;
            }
        }
    }

    /**
     * Hotkey handler — ask OBS to flush the replay buffer.
     */
    private void captureClip() {
        if (!config.clipsEnabled()) {
            return;
        }
        if (obsClip == null || !obsClip.isConnected()) {
            sendChatMessage("Clip capture: OBS isn't connected. Make sure OBS is running with the WebSocket server + Replay Buffer enabled.");
            // Opportunistic reconnect so the next press can work.
            connectObs();
            return;
        }
        // Snapshot the caption inputs NOW — the footage ends here, whatever time the file arrives.
        synchronized (pendingClips) {
            while (pendingClips.size() >= MAX_PENDING_CLIPS) {
                pendingClips.removeFirst();
            }
            pendingClips.addLast(new PendingClip(System.currentTimeMillis(), lastCombatTarget, lastCombatTargetAt));
        }
        sendChatMessage("Saving clip...");
        obsClip.saveReplayBuffer();
    }

    /**
     * Fires (off the client thread) once OBS has written the clip to disk.
     * Posts it to the clan clips channel when it's small enough for Discord;
     * otherwise just a quiet in-game notice.
     */
    private void onClipSaved(String path) {
        if (path == null || path.isEmpty()) {
            return;
        }
        // What the clip actually caught — drops, kills, completions, deaths and missions the plugin
        // saw inside the buffer's own window. Null when nothing notable happened, in which case the
        // post falls back to naming the event.
        int clipSeconds = Math.max(1, config.clipLengthSeconds());
        // The request this file answers, oldest first. Absent when OBS saved a clip we didn't ask
        // for (someone pressed OBS's own hotkey), in which case "now" is the best we know.
        PendingClip pending;
        synchronized (pendingClips) {
            pending = pendingClips.pollFirst();
        }
        long clipEndedAt = pending != null ? pending.requestedAt : System.currentTimeMillis();
        String moment = clipMoments.summarize(clipEndedAt, clipSeconds, 3);
        // Nothing notable landed in the window — but if we were mid-fight, say who with. "Fighting
        // Vorkath" is a caption; "Clipped during Test missions bingo" is a timestamp with extra
        // steps. Only counts a target we actually hit inside the footage.
        //
        // Read from the snapshot, not the live field: by the time a slow save lands, `lastCombatTarget`
        // is whatever they wandered into since, and it would caption the clip with a boss that isn't
        // in it. That is the bug this whole path exists to avoid.
        if (moment == null) {
            String target = pending != null ? pending.combatTarget : lastCombatTarget;
            long targetAt = pending != null ? pending.combatTargetAt : lastCombatTargetAt;
            long since = clipEndedAt - targetAt;
            if (target != null && since >= 0 && since <= clipSeconds * 1000L + 5000L) {
                moment = "⚔️ Fighting " + target;
            }
        }

        submitClip(path, moment, clipSeconds);
    }

    /**
     * Post a clip — IF the plugin is allowed to open it.
     *
     * <p>OBS reports an absolute path, and a path is exactly what a plugin may not act on: a Filepath
     * cannot be built from a string. So the clip has to be somewhere we already hold — our own folder
     * (when the player let us point OBS at it) or the recordings folder they granted this session.
     * Anywhere else and it goes in the queue instead of being read.
     */
    private void submitClip(String path, String moment, int clipSeconds) {
        Filepath clip = clipFolder.locate(path);
        if (clip == null) {
            queueClip(path, moment, clipSeconds);
            return;
        }

        long size;
        byte[] data;
        try {
            size = clip.size();
            long maxBytes = (long) Math.max(1, config.clipMaxMb()) * 1024L * 1024L;
            if (size > maxBytes) {
                sendChatMessage("Clip saved locally (" + (size / (1024L * 1024L)) + "MB) — too big to auto-post to Discord.");
                return;
            }
            try (java.io.InputStream in = clip.openInputStream()) {
                data = in.readAllBytes();
            }
        } catch (IOException e) {
            log.debug("Anvil: couldn't read clip: {}", e.getMessage());
            sendChatMessage("Clip saved by OBS, but it couldn't be read to post.");
            return;
        }
        String fileName = clip.getFileName();

        // Preferred route: hand the clip to the clan's own site and let IT post to the clips channel.
        // That means members don't each have to paste a webhook URL, and it still isn't a URL handed
        // to us by a server response — it's the same configured base URL every other request uses.
        // Gated on the capability so older self-hosted sites (which have no such route) fall straight
        // through to the user's own webhook.
        PluginConfigResponse cfg = pluginConfig;
        boolean relayAvailable = cfg != null && cfg.serverSupports("clip-relay") && apiClient.isConfigured();
        if (relayAvailable) {
            sendChatMessage("Uploading clip to your clan's Discord...");
            // Only an event that is actually RUNNING. The config carries whatever board this
            // account is enrolled in, and enrolment starts when sign-ups open — so a clip taken
            // eight weeks before the first tile went up was captioned "Clipped during <that board>",
            // which is a claim about a competition that hasn't happened yet.
            boolean eventRunning = AnvilOverlay.isEventActive(cfg.event);
            String eventName = eventRunning ? cfg.event.name : null;
            // Their board position rides along: the footage can show the kill but not that it put
            // them top of the month.
            PluginConfigResponse.Standings standings = eventRunning ? cfg.event.monthlyStandings : null;
            BingoApiClient.ClipRelayResult result = apiClient.postClip(
                    data, fileName, moment, eventName, clipSeconds, contentTypeForClip(fileName),
                    standings != null ? standings.yourRank : 0,
                    standings != null ? standings.yourPoints : 0);
            switch (result) {
                case POSTED:
                    sendChatMessage("Clip posted to the clan Discord.");
                    discardIfOurs(clip);
                    return;
                case TOO_LARGE:
                    sendChatMessage("Clip saved locally — too big for Discord ("
                            + (size / (1024L * 1024L)) + "MB). Try a shorter clip length.");
                    return;
                case NO_CHANNEL:
                    // The clan hasn't set a clips channel. A personal webhook still works, so only
                    // stop here when there isn't one.
                    if (clipsWebhook().isEmpty()) {
                        sendChatMessage("Clip saved locally — your clan has no clips channel set up yet.");
                        return;
                    }
                    break;
                case UNSUPPORTED:
                case FAILED:
                default:
                    break; // fall through to the personal webhook below
            }
        }

        // Fallback: upload straight from the user's machine to a webhook THEY pasted into plugin
        // config. Blank = keep clips local.
        String webhook = clipsWebhook();
        if (webhook.isEmpty()) {
            sendChatMessage(relayAvailable
                    ? "Clip saved locally — couldn't reach your clan's Discord just now."
                    : "Clip saved locally — paste a Clips Discord webhook URL in the plugin config to auto-post.");
            return;
        }
        String rsn = getLocalPlayerName();
        String content = (rsn != null ? rsn : "A clan member") + " clipped 🎬"
                + (moment != null ? "\n" + moment : "");
        sendChatMessage("Uploading clip to Discord...");
        // Only claim success once Discord actually accepts it, so a 413/429/timeout reads as a
        // failure, not silence.
        discordClient.sendWithFile(webhook, content, data, fileName, contentTypeForClip(fileName), ok -> {
            if (ok) {
                sendChatMessage("Clip posted to Discord.");
                discardIfOurs(clip);
            } else {
                sendChatMessage("Clip saved locally, but Discord didn't accept the upload (too big, rate-limited, or timed out).");
            }
        });
    }

    /**
     * A clip we may not open — because OBS wrote it somewhere the plugin has no claim to.
     *
     * <p>Held, not dropped: the file stays where OBS put it, and granting the folder later in the
     * session posts it retroactively. Meanwhile chat just says OBS saved it.
     */
    private void queueClip(String path, String moment, int clipSeconds) {
        synchronized (heldClips) {
            if (heldClips.size() >= MAX_HELD_CLIPS) {
                heldClips.remove(0);
            }
            heldClips.add(() -> submitClip(path, moment, clipSeconds));
        }
        String caption = moment != null ? moment : "Clip saved";
        if (config.manageObsFolder()) {
            // Managing, yet the clip landed elsewhere: OBS was already running its buffer with the
            // old path when we connected. It will land in our folder from the next buffer start.
            sendChatMessage(caption + " — saved by OBS. Restart OBS's replay buffer so Anvil can post these for you.");
            return;
        }
        sendChatMessage(caption + " — saved by OBS. To post these automatically, point Anvil at your OBS folder at the login screen.");
    }

    /** Let go of clips we will never be able to read — they are in a folder that is not ours. */
    private void dropHeldClips() {
        synchronized (heldClips) {
            heldClips.clear();
        }
    }

    /** Post anything that arrived before we were allowed to read it. */
    private void flushPendingClips() {
        List<Runnable> queued;
        synchronized (heldClips) {
            if (heldClips.isEmpty()) {
                return;
            }
            queued = new ArrayList<>(heldClips);
            heldClips.clear();
        }
        for (Runnable r : queued) {
            try {
                r.run();
            } catch (Exception e) {
                log.debug("Anvil: queued clip failed: {}", e.getMessage());
            }
        }
    }

    /**
     * OBS has told us where it records. Two jobs, both of which must happen BEFORE the replay buffer
     * is started with our folder applied.
     *
     * <p>Remember it, so the chooser can name the folder the player is looking for. And, when we are
     * managing the path, keep a copy of THEIR value so shutdown can put it back. Only when it isn't
     * already ours: after a crash OBS still points at us, and overwriting the backup then would make
     * our own folder "the user's setting" and strand them there permanently.
     */
    private void onObsRecordDirectory(String dir) {
        if (dir == null || dir.isEmpty()) {
            return;
        }
        obsRecordDir = dir;
        String ours = clipFolder.managedPath();
        boolean isOurs = ours != null && ours.equalsIgnoreCase(dir);
        if (config.manageObsFolder()) {
            if (!isOurs) {
                configManager.setConfiguration("osrsbingo", OBS_PATH_BACKUP, dir);
            }
            return;
        }
        // Not managing any more, but OBS is still pointed at us — a toggle flipped while RuneLite was
        // closed, or a crash before shutdown could restore it. Give it back now.
        if (isOurs) {
            restoreObsRecordDirectory();
        }
    }

    /** Hand the player's recording folder back to them, and forget we ever held it. */
    private void restoreObsRecordDirectory() {
        restoreObsRecordDirectory(true);
    }

    private void restoreObsRecordDirectory(boolean cycle) {
        String backup = configManager.getConfiguration("osrsbingo", OBS_PATH_BACKUP);
        if (backup == null || backup.isEmpty()) {
            return;
        }
        ObsReplayClient obs;
        synchronized (obsLock) {
            obs = obsClip;
        }
        if (obs == null) {
            return;
        }
        obs.setRecordDirectory(backup);
        configManager.unsetConfiguration("osrsbingo", OBS_PATH_BACKUP);
        // A running buffer holds the folder it STARTED with, so the setting alone would leave their
        // next clips in ours. Cycling it makes the restore take effect now rather than whenever OBS
        // is next restarted. Skipped on the way out: the restart is driven by the stop's reply, and
        // there is no socket left to carry it.
        if (cycle && obs.isConnected()) {
            obs.applyClipLength();
        }
        log.debug("Anvil: OBS recording folder restored");
    }

    /**
     * Ask for the OBS recordings folder — at the login screen, and nowhere else.
     *
     * <p>A clip is saved at the one moment the player is busiest, so prompting there would throw a
     * modal dialog over a kill. The login screen is the opposite: nothing is happening, and a grant
     * made now covers the whole session. Dismissing it is final for the session; clips fall back to
     * the clipboard.
     *
     * <p>Runs off the client thread — the dialog blocks until answered.
     */
    private void maybeAskForClipFolder() {
        if (!config.clipsEnabled() || config.manageObsFolder() || clipFolder.asked()) {
            return;
        }
        // No OBS, no question: asking someone who isn't running it to pick a recordings folder is a
        // dialog about a feature they aren't using yet.
        synchronized (obsLock) {
            if (obsClip == null || !obsClip.isConnected()) {
                return;
            }
        }
        ScheduledExecutorService ex = executor;
        if (ex == null) {
            return;
        }
        ex.execute(() -> {
            switch (clipFolder.ask(client, obsRecordDir)) {
                case MANAGE:
                    // Permanent, and it takes effect on the next buffer start — which onConfigChanged
                    // triggers. Clips already taken stay where OBS put them: unreachable, and already
                    // on the clipboard, so say so once rather than failing them one by one.
                    configManager.setConfiguration("osrsbingo", "manageObsFolder", true);
                    dropHeldClips();
                    sendChatMessage("Anvil will save clips to its own folder and post them for you. "
                            + "Your OBS recording folder goes back when RuneLite closes.");
                    break;
                case GRANTED:
                    sendChatMessage("Anvil will post your clips to Discord for this session.");
                    flushPendingClips();
                    break;
                case DISMISSED:
                default:
                    break;
            }
        });
    }

    /** Clean up after ourselves — but only in our OWN folder. The player's recordings stay put. */
    private void discardIfOurs(Filepath clip) {
        if (!clipFolder.isOurs(clip)) {
            return;
        }
        try {
            clip.deleteIfExists();
        } catch (IOException e) {
            log.debug("Anvil: couldn't remove sent clip: {}", e.getMessage());
        }
    }

    /** The user's own clips webhook, trimmed; empty when unset. */
    private String clipsWebhook() {
        String webhook = config.clipsWebhookUrl();
        return webhook == null ? "" : webhook.trim();
    }

    private static String contentTypeForClip(String name) {
        String lower = name.toLowerCase();
        if (lower.endsWith(".mp4")) {
            return "video/mp4";
        }
        if (lower.endsWith(".mkv")) {
            return "video/x-matroska";
        }
        if (lower.endsWith(".mov")) {
            return "video/quicktime";
        }
        if (lower.endsWith(".webm")) {
            return "video/webm";
        }
        return "application/octet-stream";
    }

    // A stalled capture must not stall the notification: frames normally arrive within ~50ms,
    // so a few seconds of grace is already generous before posting without the screenshot.
    private static final long FRAME_CAPTURE_TIMEOUT_MS = 4000;

    /**
     * Captures the next rendered frame and hands the PNG bytes to
     * {@code consumer} OFF the client thread. The frame listener fires on the
     * client/AWT thread, so we immediately defer encoding to the executor; the
     * consumer then sends via OkHttp async. The game loop never waits on
     * either.
     *
     * <p>The consumer is guaranteed to run exactly once — with {@code null} when no frame
     * arrives in time (a minimized client can stop rendering, and the next-frame listener
     * then never fires) or the PNG encode fails. Callers post without the screenshot in
     * that case; before this guarantee, a stalled capture silently dropped the whole
     * notification (a Maggot King fang post vanished this way).
     */
    private void captureFrameAsync(Consumer<byte[]> consumer) {
        java.util.concurrent.atomic.AtomicBoolean delivered = new java.util.concurrent.atomic.AtomicBoolean(false);
        drawManager.requestNextFrameListener(image -> {
            if (executor == null || executor.isShutdown()) {
                return;
            }
            executor.submit(() -> {
                byte[] png = null;
                try {
                    BufferedImage buffered = (BufferedImage) image;
                    ByteArrayOutputStream baos = new ByteArrayOutputStream();
                    ImageIO.write(buffered, "png", baos);
                    png = baos.toByteArray();
                } catch (Exception e) {
                    log.debug("Anvil frame capture failed: {}", e.getMessage());
                }
                if (delivered.compareAndSet(false, true)) {
                    consumer.accept(png);
                }
            });
        });
        if (executor != null && !executor.isShutdown()) {
            executor.schedule(() -> {
                if (delivered.compareAndSet(false, true)) {
                    log.info("Anvil: no frame within {}ms — notifying without a screenshot", FRAME_CAPTURE_TIMEOUT_MS);
                    consumer.accept(null);
                }
            }, FRAME_CAPTURE_TIMEOUT_MS, TimeUnit.MILLISECONDS);
        }
    }

    /**
     * Captures a frame and posts a rareDrops embed; a failed or stalled capture posts the
     * embed without its image (stripping the attachment reference so Discord renders clean)
     * instead of not posting at all.
     */
    /**
     * Post an achievement embed, with a screenshot when the member wants one.
     *
     * A 99 and a max are the most screenshotted moments in the game, and both went out as text. The
     * comment that made it so said "matching combat-achievement posts" — which was simply untrue: CA
     * posts have taken a screenshot since `caScreenshot` existed, so the 99 was out of step with the
     * very thing it cited. Same shape as that path now, down to removing the image reference when the
     * capture fails, so a dropped frame degrades to the text post rather than an embed with a hole.
     */
    private void postAchievement(com.google.gson.JsonObject embed) {
        String shotName = "anvil-achievement.png";
        com.google.gson.JsonObject image = new com.google.gson.JsonObject();
        image.addProperty("url", "attachment://" + shotName);
        embed.add("image", image);
        Runnable capture = () -> captureFrameAsync(png -> {
            if (png == null) {
                embed.remove("image");
            }
            apiClient.postNotification("levels", null, embed, png, shotName);
        });

        // Let the room react before the shutter.
        //
        // The instant a 99 lands the screen holds the fireworks and nothing else; the congratulations
        // that make the screenshot worth keeping are still being typed. A beat's pause catches the
        // clan chat with the moment instead of an empty chatbox beneath it.
        //
        // Scheduled, never slept: a sleep here would park a shared RuneLite worker for a second and a
        // half, and the hub rejects Thread.sleep on sight. Without a usable executor -- shutting down
        // mid-level-up -- we capture now, because a slightly emptier screenshot beats none.
        if (executor == null || executor.isShutdown()) {
            capture.run();
            return;
        }
        executor.schedule(capture, ACHIEVEMENT_SHOT_DELAY_MS, TimeUnit.MILLISECONDS);
    }

    /** Pause between the achievement and its screenshot, long enough for clanmates' replies. */
    private static final long ACHIEVEMENT_SHOT_DELAY_MS = 1500;

    /** Capture, then post to {@code channel}; a failed capture drops the image and posts anyway. */
    private void postWithScreenshot(String channel, com.google.gson.JsonObject embed, String shotName) {
        captureFrameAsync(png -> {
            if (png == null) {
                embed.remove("image");
            }
            apiClient.postNotification(channel, null, embed, png, shotName);
        });
    }

    // Gold prefix flags the line as Anvil; white body stays readable on any background (OSRS text
    // has a built-in shadow). Brand orange on the tan chat was too low-contrast.
    private static final String CHAT_PREFIX_COLOR = "ffd700";
    private static final String CHAT_BODY_COLOR = "ffffff";

    private void sendChatMessage(String message) {
        // A raw '|' in a chat line gets mangled by the chat pipeline (an event named
        // "The AFK Spot | July Bingo" printed as a bare "July Bingo."). Interpolated names are
        // admin-authored, so swap in the visually-identical broken bar instead.
        String safe = message.replace('|', '\u00A6');
        String line = "<col=" + CHAT_PREFIX_COLOR + ">[Anvil]</col> <col=" + CHAT_BODY_COLOR + ">" + safe + "</col>";
        clientThread.invokeLater(()
                -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", line, null)
        );
    }

    // -- Profile sync: collection log + personal bests ---------------------------------------
    // Both are the player's OWN data going to the player's OWN clan site -- the pattern the hub
    // accepts (nothing here reads or reports anybody else). Everything is opt-out in config, and
    // nothing is read at all while the toggles are off.

    /**
     * Whether the clan site can store profile data at all.
     *
     * <p>Gated on the capability rather than discovered by 404ing: a site that predates these
     * endpoints would otherwise be asked every 30 seconds, forever, by every member of the clan.
     * Sites advertise it once they have somewhere to put it; until then the plugin does no reading,
     * no batching and no requests.
     */
    /**
     * The sidebar's "Sync clan roster" button.
     *
     * <p>Same work as the in-game one, with its own in-flight guard so a double click is one push,
     * and the result reported in chat where the player is looking. Refused outright when the clan
     * channel isn't readable — the roster is scraped from it, so there is nothing to send.
     */
    public void syncClanRosterFromPanel() {
        if (!isAdmin) {
            sendChatMessage("Only clan admins can sync the roster.");
            return;
        }
        // Cached, because this is called from the side panel on the EDT — reading the clan channel
        // from there is the same thread violation that swallowed the profile button's message.
        if (!clanRosterReadable) {
            sendChatMessage("Join your clan channel first — the roster is read from it.");
            return;
        }
        if (panelRosterSyncRunning) {
            sendChatMessage("Already syncing the roster.");
            return;
        }
        panelRosterSyncRunning = true;
        sendChatMessage("Syncing the clan roster...");
        syncClanRoster((ok, msg) -> {
            panelRosterSyncRunning = false;
            if (sidebarPanel != null) {
                sidebarPanel.refresh();
            }
        });
    }

    /** Does this clan's site take profile data? Drives the in-tab "Sync profile" row. */
    public boolean supportsProfileSync() {
        return config.syncClog() && apiClient.isConfigured() && serverSupportsProfileSync();
    }

    private boolean serverSupportsProfileSync() {
        PluginConfigResponse cfg = pluginConfig;
        return cfg != null && cfg.serverSupports("profile-sync");
    }

    /**
     * Point the profile-sync state at the account that just logged in.
     *
     * <p>State is per-RSN, so switching characters swaps it rather than merging two logs. A no-op
     * when the same account logs back in, which is the common case.
     */
    private void loadProfileSyncState(String rsn) {
        String key = rsn == null ? "" : rsn.trim().toLowerCase(java.util.Locale.ROOT);
        if (key.isEmpty() || key.equals(profileSyncRsn)) {
            return;
        }
        profileSyncRsn = key;
        clogSync.reset();
        personalBests.reset();
        // A different character doesn't inherit this one's unsent highlights — the site files them
        // against whoever the request authenticates as, which would now be the wrong person.
        moments.reset();
        clogSync.restoreState(configManager.getConfiguration("osrsbingo", CFG_CLOG_STATE + ":" + key));
        // The whole-log fingerprint survives a restart: opening the collection log re-transmits
        // everything every time, and without this each session's first open re-sent a log the site
        // already had, byte for byte.
        lastClogFingerprint = parseLongOrZero(configManager.getConfiguration("osrsbingo", CFG_CLOG_FINGERPRINT + ":" + key));
        personalBests.restoreState(configManager.getConfiguration("osrsbingo", CFG_PB_STATE + ":" + key));
        importRuneLitePersonalBests(key);
    }

    /**
     * Copy the personal bests RuneLite's own chat-commands plugin has already recorded, once.
     *
     * <p>Local config only -- the same store the player's own client wrote, on the same machine, for
     * the account they're logged into. Nothing is read about anyone else. Without it a profile
     * starts empty and fills in over months; with it, a player who has been playing for years sees
     * their real times the first time they open their clan profile.
     *
     * <p>Runs once per account per activity list (a flag in our own config), and does nothing when
     * chat-commands has never run -- then the live capture builds the set from the next kill onward.
     * The flag stores a signature of the names we asked for, so when the site adds an activity --
     * the awakened DT2 bosses, say -- everyone re-probes once for the new names. Re-running is safe:
     * a seeded time only ever replaces a slower one.
     */
    private void importRuneLitePersonalBests(String rsnKey) {
        if (!config.importRuneLitePbs() || !config.syncPersonalBests()) {
            return;
        }
        if (configManager.getRSProfileKey() == null || configManager.getRSProfileKey().isEmpty()) {
            return; // No RS profile yet -- try again next login rather than marking it done.
        }
        // The names to ask for. Without them there is nothing to probe, so we leave the flag unset
        // and try again once the site's config has landed.
        PluginConfigResponse cfg = pluginConfig;
        List<String> activities = cfg != null ? cfg.pbActivities : null;
        if (activities == null || activities.isEmpty()) {
            return;
        }
        // String.hashCode is specified, so the same list gives the same signature on every client
        // and every release. An older flag ("1", or an earlier list) simply doesn't match.
        String signature = Integer.toString(activities.hashCode());
        String done = configManager.getConfiguration("osrsbingo", CFG_PB_IMPORTED + ":" + rsnKey);
        if (signature.equals(done)) {
            return;
        }

        // ASK, don't list. RuneLite stores these under the RS-profile scope, and its only key-listing
        // API reads the main profile — so the obvious loop over getConfigurationKeys() silently found
        // nothing at all, whatever prefix it was given. getRSProfileConfiguration reads the right
        // store, one key at a time, which is why the names have to come from somewhere.
        Map<String, Integer> imported = new HashMap<>();
        for (String base : activities) {
            if (base == null || base.isEmpty()) {
                continue;
            }
            probeRuneLitePb(base, imported);
            // Every scale RuneLite files a raid under. Its own pattern is
            // "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)", so a solo run is the WORD solo — not
            // "1 players" — and a big team is a bucket rather than an exact count. Probing only
            // "N players" therefore missed every solo raid time anyone had.
            probeRuneLitePb(base + " solo", imported);
            for (int size = 1; size <= MAX_PB_TEAM_SIZE; size++) {
                probeRuneLitePb(base + " " + size + " players", imported);
            }
            for (String bucket : PB_TEAM_BUCKETS) {
                probeRuneLitePb(base + " " + bucket, imported);
            }
        }

        int adopted = personalBests.seed(imported, System.currentTimeMillis());
        configManager.setConfiguration("osrsbingo", CFG_PB_IMPORTED + ":" + rsnKey, signature);
        log.info("Anvil: imported {} existing personal best(s) from RuneLite ({} probed)",
                adopted, imported.size());
        if (adopted > 0) {
            sendChatMessage("Imported " + adopted + " personal best" + (adopted == 1 ? "" : "s")
                    + " from RuneLite.");
        }
    }

    /**
     * Try the personal-best import again on the periodic tick.
     *
     * <p>It needs three things that don't arrive together: an account (login), an RS profile key
     * (login), and the site's activity list (the first config fetch). Running it only at login meant
     * the config usually hadn't landed yet and the import quietly did nothing. The once-per-account
     * flag makes every call after a successful one free.
     */
    private void retryPersonalBestImport() {
        String rsn = profileSyncRsn;
        if (rsn != null && !rsn.isEmpty()) {
            importRuneLitePersonalBests(rsn);
        }
    }

    /** Config values are text; a missing or corrupt one just means "no fingerprint yet". */
    private static long parseLongOrZero(String raw) {
        if (raw == null || raw.isEmpty()) {
            return 0L;
        }
        try {
            return Long.parseLong(raw.trim());
        } catch (NumberFormatException e) {
            return 0L;
        }
    }

    /** Read one stored best, if RuneLite has it for this account. Times are seconds; ours centis. */
    private void probeRuneLitePb(String activity, Map<String, Integer> into) {
        String raw = configManager.getRSProfileConfiguration(RUNELITE_PB_GROUP, activity);
        if (raw == null || raw.trim().isEmpty()) {
            return;
        }
        try {
            int centis = (int) Math.round(Double.parseDouble(raw.trim()) * 100.0);
            if (centis > 0) {
                into.put(activity, centis);
            }
        } catch (NumberFormatException e) {
            // Not a time -- skip the key rather than the import.
        }
    }

    /**
     * Send any collection-log pages that have changed. Runs on the shared executor's 30s tick --
     * no thread of our own, and nothing on the client thread.
     */
    private void flushClogSync() {
        if (!config.syncClog() || !apiClient.isConfigured() || profileSyncRsn == null
                || !serverSupportsProfileSync()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (!clogSync.isDue(now) || !clogBackoff.ready(now)) {
            return;
        }
        java.util.List<ClogPage> batch = clogSync.nextBatch();
        try {
            apiClient.submitClogPages(batch, clogSync.syncedPages());
        } catch (BingoApiClient.RateLimitedException e) {
            // Background sync: nothing to tell the player, just wait as long as the site asked.
            clogPushAllowedAt = System.currentTimeMillis() + Math.max(e.retryAfterMs, 1_000L);
            log.debug("Collection log pages rate-limited for {}ms", e.retryAfterMs);
            return;
        } catch (BingoApiClient.PermanentSubmissionException e) {
            // Refused outright (a malformed page, a site that doesn't take these): dropping the batch
            // is the only way out of an otherwise permanent 30-second retry loop.
            log.info("Collection log pages refused, dropping the batch: {}", e.getMessage());
            clogSync.onSent(batch);
            return;
        } catch (Exception e) {
            // Left queued: we retry after the backoff. A clan site being down must not lose a sync.
            clogBackoff.onFailure(now);
            log.debug("Collection log push failed, retrying in {}s: {}",
                    clogBackoff.secondsUntilReady(now), e.getMessage());
            return;
        }
        clogBackoff.onSuccess();
        clogSync.onSent(batch);
        configManager.setConfiguration("osrsbingo", CFG_CLOG_STATE + ":" + profileSyncRsn,
                clogSync.serializeState());
    }

    /**
     * Push a settled whole-log transmit (see {@link ClogFullSync}). Runs on the same 30s tick as the
     * page sync; the two are complementary — this carries every obtained item, the page route carries
     * the kill-count lines that only appear on a drawn page.
     */
    private void flushFullClogSync() {
        if (!config.syncClog() || !apiClient.isConfigured() || profileSyncRsn == null
                || !serverSupportsProfileSync()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (!clogFullSync.isDue(now) || !clogFullBackoff.ready(now)) {
            return;
        }
        // The site's own rate limit, respected before the request rather than discovered by it.
        if (now < clogPushAllowedAt) {
            return;
        }
        boolean manual = clogFullSync.isManual();
        int count = clogFullSync.size();
        // Opening the log re-transmits everything, and most opens change nothing. Pushing an
        // identical log would burn the server's cooldown and rewrite 1,700 rows to say the same
        // thing. A deliberate press still goes, so "sync now" always means something happened.
        long fingerprint = clogFullSync.fingerprint();
        if (!manual && fingerprint == lastClogFingerprint) {
            log.debug("Collection log unchanged since the last sync — nothing to push");
            clogFullSync.onSent();
            // Nothing to send. Said once a login — proof the sync ran and agreed with the site —
            // and then not again: the log is re-transmitted on every open, and a line each time
            // saying nothing happened is worse than saying nothing at all.
            if (!autoClogReportedThisLogin) {
                autoClogReportedThisLogin = true;
                sendChatMessage("Collection log checked — your profile is up to date.");
            }
            return;
        }
        BingoApiClient.ClogPushResult result;
        try {
            result = apiClient.submitClogItems(clogFullSync.snapshot());
        } catch (BingoApiClient.RateLimitedException e) {
            // It said when. Wait exactly that long instead of doubling blindly, and keep the batch.
            clogPushAllowedAt = now + Math.max(e.retryAfterMs, 1_000L);
            clogFullSync.onSendFailed(now);
            manualSyncStartedAt = 0;
            log.debug("Collection log push rate-limited for {}ms", e.retryAfterMs);
            if (manual) {
                sendChatMessage("Synced very recently — the site allows one sync a minute. Try again in "
                        + Math.max(1, (e.retryAfterMs + 999) / 1000) + "s.");
            }
            return;
        } catch (BingoApiClient.PermanentSubmissionException e) {
            // The site said no and will keep saying no — most often because it predates whole-log
            // pushes and wants pages instead. Retrying that forever is just noise on their server.
            log.info("Whole-log push refused, dropping it: {}", e.getMessage());
            manualSyncStartedAt = 0;
            clogFullSync.onSent();
            if (manual) {
                sendChatMessage("Couldn't sync your profile: " + e.getMessage() + ".");
            }
            return;
        } catch (Exception e) {
            // Kept for the next attempt: a site that's down mustn't cost them the transmit.
            clogFullBackoff.onFailure(now);
            log.debug("Whole-log push failed, retrying in {}s: {}",
                    clogFullBackoff.secondsUntilReady(now), e.getMessage());
            clogFullSync.onSendFailed(now);
            manualSyncStartedAt = 0;
            if (manual) {
                sendChatMessage("Couldn't sync your profile: " + e.getMessage() + ". It'll retry on its own.");
            }
            return;
        }
        clogFullBackoff.onSuccess();
        manualSyncStartedAt = 0; // it landed — nothing for the watchdog to complain about
        clogPushAllowedAt = now + SERVER_CLOG_COOLDOWN_MS;
        lastClogFingerprint = fingerprint;
        if (profileSyncRsn != null) {
            configManager.setConfiguration("osrsbingo", CFG_CLOG_FINGERPRINT + ":" + profileSyncRsn,
                    Long.toString(fingerprint));
        }
        clogFullSync.onSent();
        log.info("Collection log synced: {} items", count);
        if (manual) {
            sendChatMessage("Profile synced — " + count + " collection log slots.");
        } else if (result.added > 0) {
            // New slots are news: always said.
            autoClogReportedThisLogin = true;
            sendChatMessage("Collection log synced — " + result.added + " new slot"
                    + (result.added == 1 ? "" : "s") + ".");
        } else if (!autoClogReportedThisLogin) {
            // A push that added nothing still proves the round trip worked — once a login.
            autoClogReportedThisLogin = true;
            sendChatMessage("Collection log synced — nothing new.");
        }
    }

    /** Same contract for best times. */
    private void flushPersonalBests() {
        if (!config.syncPersonalBests() || !apiClient.isConfigured() || profileSyncRsn == null
                || !serverSupportsProfileSync()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (!personalBests.isDue(now) || !pbBackoff.ready(now)) {
            return;
        }
        Map<String, Integer> batch = personalBests.nextBatch();
        try {
            apiClient.submitPersonalBests(batch);
        } catch (BingoApiClient.RateLimitedException e) {
            // Bests ride the same limiter; the batch stays dirty and goes up when it clears.
            pbBackoff.onFailure(System.currentTimeMillis());
            log.debug("Personal bests rate-limited for {}ms", e.retryAfterMs);
            return;
        } catch (BingoApiClient.PermanentSubmissionException e) {
            log.info("Personal bests refused, dropping the batch: {}", e.getMessage());
            personalBests.onSent(batch);
            return;
        } catch (Exception e) {
            pbBackoff.onFailure(now);
            log.debug("Personal best push failed, retrying in {}s: {}",
                    pbBackoff.secondsUntilReady(now), e.getMessage());
            return;
        }
        pbBackoff.onSuccess();
        personalBests.onSent(batch);
        configManager.setConfiguration("osrsbingo", CFG_PB_STATE + ":" + profileSyncRsn,
                personalBests.serializeState());
    }

    /**
     * The clan channel loaded (or changed) — the moment the in-game roster becomes readable.
     *
     * <p>Rosters used to drift until an admin remembered to press "Sync clan roster": someone joins,
     * the site doesn't know, and their drops land as a guest. The data is right here at login, so
     * take it. Admin-only (the site refuses anyone else's push anyway), at most once every half hour
     * per session, and silent — an automatic sync that announced itself in chat every login would be
     * worse than the drift.
     */
    @Subscribe
    public void onClanChannelChanged(ClanChannelChanged event) {
        if (event.isGuest() || !config.autoSyncClanRoster()) {
            return;
        }
        if (executor == null || executor.isShutdown()) {
            return;
        }
        // The member list arrives just after the channel; a delay is cheaper than polling for it.
        executor.schedule(() -> safely("autoRosterSync", this::autoSyncClanRoster),
                AUTO_ROSTER_DELAY_MS, TimeUnit.MILLISECONDS);
    }

    /**
     * Push the in-game roster if we're allowed to and haven't recently. Every guard here is a reason
     * NOT to send: not an admin, no token, roster not loaded yet, one already running, or one ran
     * within the last half hour.
     */
    private void autoSyncClanRoster() {
        if (autoRosterSyncRunning || !isAdmin) {
            return;
        }
        String token = config.playerToken();
        if (token == null || token.isEmpty() || !apiClient.isConfigured()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (lastAutoRosterSyncAt != 0 && now - lastAutoRosterSyncAt < AUTO_ROSTER_MIN_GAP_MS) {
            return;
        }
        autoRosterSyncRunning = true;
        lastAutoRosterSyncAt = now;
        autoRosterAnnounce = true;
        syncClanRoster((ok, msg) -> {
            autoRosterSyncRunning = false;
            if (ok) {
                log.debug("Clan roster auto-synced: {}", msg);
            } else {
                // Most likely "roster not loaded yet" — let the next channel change try again.
                lastAutoRosterSyncAt = 0;
                log.debug("Clan roster auto-sync skipped: {}", msg);
            }
        });
    }
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;

/**
 * Reads the collection-log page the game is currently showing.
 *
 * <p>The client only ever holds ONE page — the log is drawn on demand, so an unopened page has no
 * items anywhere in memory. That's why a full sync means the player paging through their log once,
 * and why this is a read-what's-on-screen routine rather than a dump.
 *
 * <p><b>Self-verifying.</b> The header prints "Obtained: 5/9"; we count the items we believe are
 * obtained and only return a page when the two agree. A game update that changes how unobtained
 * items are drawn therefore makes this return null — the sync stalls and says so — instead of
 * quietly reporting that everybody lost half their collection log.
 *
 * <p>Runs on the client thread (its only caller is the COLLECTION_DRAW_LIST script hook), so it
 * allocates nothing beyond the page it returns and never blocks.
 */
final class ClogPageReader
{
	private ClogPageReader() {}

	/** "Obtained: 5/9" — the log's own progress line, and our correctness check. */
	private static final Pattern OBTAINED = Pattern.compile("obtained:\\s*(\\d+)\\s*/\\s*(\\d+)");
	/** "Abyssal Sire kills: 1,204" / "Chest openings: 87" — label and value, commas stripped. */
	private static final Pattern COUNT_LINE = Pattern.compile("^(.+?):\\s*([\\d,]+)$");
	/** Widget tags: the log wraps names in colour tags we don't want in the payload. */
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	/**
	 * The page on screen, or null when it isn't readable yet (mid-draw, empty, or the obtained
	 * count disagrees with what we read — see the class note).
	 */
	static ClogPage read(Client client)
	{
		Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		Widget items = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (header == null || items == null)
		{
			return null;
		}

		String name = null;
		int obtained = -1;
		int total = -1;
		// Allocated only if the page actually prints counters — most don't, and this runs on every
		// redraw of every page the player scrolls past.
		Map<String, Integer> counts = null;

		Widget[] lines = header.getStaticChildren();
		if (lines == null)
		{
			return null;
		}
		for (Widget line : lines)
		{
			if (line == null)
			{
				continue;
			}
			String text = strip(line.getText());
			if (text.isEmpty())
			{
				continue;
			}
			// First non-empty line is the entry title; the rest are progress and counters.
			if (name == null)
			{
				name = text;
				continue;
			}
			Matcher progress = OBTAINED.matcher(text.toLowerCase());
			if (progress.find())
			{
				obtained = parseInt(progress.group(1));
				total = parseInt(progress.group(2));
				continue;
			}
			Matcher count = COUNT_LINE.matcher(text);
			if (count.matches())
			{
				int value = parseInt(count.group(2).replace(",", ""));
				if (value >= 0)
				{
					if (counts == null)
					{
						counts = new LinkedHashMap<>(4);
					}
					counts.put(count.group(1).trim(), value);
				}
			}
		}

		if (name == null || name.isEmpty() || obtained < 0 || total <= 0)
		{
			return null;
		}

		Widget[] cells = items.getDynamicChildren();
		if (cells == null)
		{
			return null;
		}

		// Two passes so the arrays are exactly sized — a page is at most a few dozen items, and this
		// avoids both an ArrayList's boxing and a grow-and-copy on every redraw.
		int found = 0;
		for (Widget cell : cells)
		{
			if (isObtained(cell))
			{
				found++;
			}
		}
		// The log's own count is the authority. Disagreeing means we misread the page (or Jagex
		// changed the drawing); either way, committing it would corrupt a synced log.
		if (found != obtained)
		{
			return null;
		}

		int[] ids = new int[found];
		int[] quantities = new int[found];
		int i = 0;
		for (Widget cell : cells)
		{
			if (!isObtained(cell))
			{
				continue;
			}
			ids[i] = cell.getItemId();
			// A quantity of 0 on an obtained item means "one, uncounted" for the handful of log
			// entries that predate stack tracking; storing 0 would read as "you don't have it".
			quantities[i] = Math.max(1, cell.getItemQuantity());
			i++;
		}

		return new ClogPage(name, ids, quantities, obtained, total, counts);
	}

	/**
	 * Whether a cell is an item the account has.
	 *
	 * <p>The log draws unobtained items dimmed (non-zero opacity) with no quantity; obtained ones are
	 * fully opaque and carry their count. Either signal alone has an edge case, so both are accepted
	 * and the header's "Obtained: N" arbitrates — see {@link #read}.
	 */
	private static boolean isObtained(Widget cell)
	{
		if (cell == null || cell.getItemId() <= 0)
		{
			return false;
		}
		return cell.getOpacity() == 0 || cell.getItemQuantity() > 0;
	}

	private static String strip(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		// The regex is the expensive part and most lines carry no tags at all — one scan for '<'
		// saves building a Matcher on every header line of every redraw.
		if (raw.indexOf('<') < 0)
		{
			return raw.trim();
		}
		return TAGS.matcher(raw).replaceAll("").trim();
	}

	private static int parseInt(String raw)
	{
		try
		{
			return Integer.parseInt(raw);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.anvil;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import lombok.extern.slf4j.Slf4j;

/**
 * Putting a path on the clipboard, which is as far as a hub plugin may go toward "open this folder".
 *
 * <p>RuneLite's LinkBrowser::open — the sanctioned way to hand a local path to the OS — is a
 * restricted API for plugin-hub releases, so the folder buttons can't launch a file manager. Copying
 * the path is the honest substitute: one paste into a file manager or a terminal, and nothing about
 * the plugin reaches outside its own directory.
 */
@Slf4j
final class Clipboards
{
	private Clipboards()
	{
	}

	/** True when the text made it onto the clipboard, so a caller can say so rather than assume. */
	static boolean copy(String value)
	{
		if (value == null || value.isEmpty())
		{
			return false;
		}
		return set(new StringSelection(value));
	}

	private static boolean set(Transferable contents)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(contents, null);
			return true;
		}
		catch (Exception e)
		{
			// A headless or locked-down desktop has no clipboard; the path still gets said out loud.
			log.debug("Anvil: clipboard copy skipped: {}", e.getMessage());
			return false;
		}
	}
}

package com.anvil;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Quest points, combat-achievement points and tier, and achievement diaries — the account progress
 * the hiscores never publish (site: lib/memberProgress).
 *
 * <p>The plugin already SEES all of it: it parses every quest, diary and combat-task completion line
 * to credit tiles and post to Discord. It just spent each one and forgot it, so the site could never
 * answer "how many quest points does this member have" — a thing the game knows exactly.
 *
 * <p>Reads varbits, so it must run on the client thread. What it produces is a small map of key →
 * value; the caller diffs it against what it last sent and pushes only the difference, which is
 * usually nothing.
 */
final class AccountProgress
{
	/** Diary completion varbits, region by region, in tier order: easy, medium, hard, elite. */
	private static final int[][] DIARY_VARBITS = {
		{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
	};

	/**
	 * Karamja is the odd one out: only its ELITE tier has a completion varbit. Easy, medium and hard
	 * are tracked as task COUNTS whose totals we would have to hardcode — and would then be wrong
	 * about after any update that adds a task — so they are left out rather than guessed at. The site
	 * says as much next to the number.
	 */
	private static final int KARAMJA_ELITE = VarbitID.KARAMJA_DIARY_ELITE_COMPLETE;

	private static final String[] DIARY_KEYS = {"diaryEasy", "diaryMedium", "diaryHard", "diaryElite"};

	/**
	 * The key each region's tier mask is stored under, in the same order as {@link #DIARY_VARBITS},
	 * with Karamja last — it only contributes its elite bit. Matches DIARY_REGIONS on the site.
	 */
	private static final String[] DIARY_REGION_KEYS = {
		"diaryArdougne", "diaryDesert", "diaryFalador", "diaryFremennik", "diaryKandarin",
		"diaryKourend", "diaryLumbridge", "diaryMorytania", "diaryVarrock", "diaryWestern",
		"diaryWilderness",
	};

	private static final String KARAMJA_KEY = "diaryKaramja";

	private AccountProgress()
	{
	}

	/**
	 * Sample everything, right now. Client thread only.
	 *
	 * <p>Returns an empty map when the varbits read as an empty account — a few ticks after login the
	 * client has the values zeroed, and sending that would be a push claiming somebody lost their
	 * quest cape. The server max-merges as a second line of defence, but not sending nonsense is the
	 * first one.
	 */
	static Map<String, Integer> sample(Client client)
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		if (client == null)
		{
			return out;
		}

		int questPoints = client.getVarpValue(VarPlayerID.QP);
		int caPoints = client.getVarbitValue(VarbitID.CA_POINTS);

		// Everything zero is what an unpopulated client looks like, not what an account looks like:
		// even a fresh account has quest points from the tutorial's first quest soon enough, and a
		// real one never has all of these at zero at once.
		int[] diaries = countDiaries(client);
		int diaryTotal = diaries[0] + diaries[1] + diaries[2] + diaries[3];
		if (questPoints <= 0 && caPoints <= 0 && diaryTotal <= 0)
		{
			return out;
		}

		out.put("questPoints", questPoints);
		out.put("questsCompleted", countQuests(client));
		out.put("caPoints", caPoints);
		out.put("caTier", highestTier(client, caPoints));
		// Every tier cleared rather than only the highest, so a profile can light them cumulatively.
		out.put("caTiers", tierMask(client, caPoints));
		for (int tier = 0; tier < DIARY_KEYS.length; tier++)
		{
			out.put(DIARY_KEYS[tier], diaries[tier]);
		}
		// Per region as well as per tier: the counts say how many, these say which.
		for (int region = 0; region < DIARY_VARBITS.length; region++)
		{
			out.put(DIARY_REGION_KEYS[region], regionMask(client, DIARY_VARBITS[region]));
		}
		out.put(KARAMJA_KEY, client.getVarbitValue(KARAMJA_ELITE) > 0 ? DIARY_ELITE_BIT : 0);
		return out;
	}

	/** Tier bits inside a region mask — the same numbering the site uses. */
	private static final int DIARY_EASY_BIT = 1;
	private static final int DIARY_MEDIUM_BIT = 2;
	private static final int DIARY_HARD_BIT = 4;
	private static final int DIARY_ELITE_BIT = 8;

	/** One region's four tiers, as a mask. */
	private static int regionMask(Client client, int[] region)
	{
		int mask = 0;
		int[] bits = {DIARY_EASY_BIT, DIARY_MEDIUM_BIT, DIARY_HARD_BIT, DIARY_ELITE_BIT};
		for (int tier = 0; tier < region.length; tier++)
		{
			if (client.getVarbitValue(region[tier]) > 0)
			{
				mask |= bits[tier];
			}
		}
		return mask;
	}

	/**
	 * Quests finished, out of everything this client build knows about.
	 *
	 * <p>An enum walk of ~200 quests, each a varp read — cheap enough for the half-minute tick that
	 * calls it, and the only way to the number: the game keeps no "quests completed" counter, only
	 * quest points, and those weight quests differently.
	 */
	private static int countQuests(Client client)
	{
		int done = 0;
		for (Quest quest : Quest.values())
		{
			if (quest.getState(client) == QuestState.FINISHED)
			{
				done++;
			}
		}
		return done;
	}

	/**
	 * The raw combat-achievement varps, exactly as the game holds them.
	 *
	 * <p>Completion is bit-packed across these: task `i` is bit `i % 32` of the `i / 32`-th varp in
	 * the order the site sent. Which bit is which task is the site's business — it has the task
	 * catalogue — so this reads integers and understands none of them, and a game update that adds a
	 * varp costs a data change there rather than a release here.
	 *
	 * <p>Client thread.
	 */
	static java.util.Map<Integer, Integer> combatVarps(Client client, java.util.List<Integer> varps)
	{
		java.util.Map<Integer, Integer> out = new LinkedHashMap<>();
		if (client == null || varps == null)
		{
			return out;
		}
		for (Integer varpId : varps)
		{
			if (varpId == null || varpId <= 0)
			{
				continue;
			}
			out.put(varpId, client.getVarpValue(varpId));
		}
		return out;
	}

	/** One quest, as the site lists it: the game's own id and name, and which of the three states. */
	static final class Item
	{
		final int id;
		final String name;
		final int state;

		Item(int id, String name, int state)
		{
			this.id = id;
			this.name = name;
			this.state = state;
		}
	}

	/**
	 * EVERY quest with its state, not just the finished ones.
	 *
	 * <p>"Which of these haven't I done" is the question a quest list gets opened for, and a list of
	 * completions can't answer it. Names travel with the ids so the site never needs a quest dataset
	 * of its own — one released next month lists itself.
	 *
	 * <p>Client thread, like everything else here.
	 */
	static java.util.List<Item> quests(Client client)
	{
		java.util.List<Item> out = new java.util.ArrayList<>();
		if (client == null)
		{
			return out;
		}
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			int code = state == QuestState.FINISHED ? 2 : state == QuestState.IN_PROGRESS ? 1 : 0;
			out.add(new Item(quest.getId(), quest.getName(), code));
		}
		return out;
	}

	/** Bit per combat-achievement tier cleared: bit 0 Easy … bit 5 Grandmaster. */
	private static int tierMask(Client client, int caPoints)
	{
		int mask = 0;
		int index = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values())
		{
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && caPoints >= threshold)
			{
				mask |= 1 << index;
			}
			index++;
		}
		return mask;
	}

	/** Regions complete at each tier: easy, medium, hard, elite. */
	private static int[] countDiaries(Client client)
	{
		int[] counts = new int[4];
		for (int[] region : DIARY_VARBITS)
		{
			for (int tier = 0; tier < region.length; tier++)
			{
				if (client.getVarbitValue(region[tier]) > 0)
				{
					counts[tier]++;
				}
			}
		}
		if (client.getVarbitValue(KARAMJA_ELITE) > 0)
		{
			counts[3]++;
		}
		return counts;
	}

	/**
	 * The highest combat-achievement tier this account has cleared, 0 (none) through 6 (Grandmaster).
	 *
	 * <p>Read from POINTS against each tier's threshold varbit rather than from the tier-status
	 * varbits: the thresholds are what the game itself compares, they're the same numbers the
	 * completion post already uses, and a tier the player cleared but never claimed the reward for
	 * still counts as cleared.
	 */
	private static int highestTier(Client client, int caPoints)
	{
		int highest = 0;
		int tier = 0;
		for (CombatAchievementTier t : CombatAchievementTier.values())
		{
			tier++;
			int threshold = client.getVarbitValue(t.getThresholdVarbitId());
			if (threshold > 0 && caPoints >= threshold)
			{
				highest = tier;
			}
		}
		return highest;
	}
}

package com.anvil;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Where an account sits in a boss's vestige rotation.
 *
 * <p>The DT2 bosses don't hand out their vestige at random: rolls of the unique table go
 * non-vestige, non-vestige, VESTIGE. So counting uniques since the last vestige tells a player
 * something they can act on — "that's roll 2, the next unique is the vestige" — which is worth far
 * more than another "you got a Virtus mask" line. The roll tables themselves (which items count,
 * which one is the vestige, how long the cycle is) come from the server, so a game change is an
 * edit there rather than a plugin release.
 *
 * <p>Honesty about what we can know: the cycle is account state on Jagex's side, and this plugin
 * only sees drops it was running for. A count is therefore ESTIMATED until a vestige is actually
 * observed — after that the cycle is anchored and the count is EXACT. The estimate is still worth
 * showing (it's right whenever the player has been running the plugin), it just says so.
 *
 * <p>RuneLite-free so it can be unit-tested; {@link AnvilPlugin} owns persistence.
 */
final class VestigeRolls
{
	/** One boss's cycle state. */
	static final class State
	{
		/** Rolls seen since the last vestige — 0 means "a vestige is 3 rolls away". */
		final int rolls;
		/** True once a vestige has been observed, which anchors the cycle. */
		final boolean exact;

		State(int rolls, boolean exact)
		{
			this.rolls = rolls;
			this.exact = exact;
		}
	}

	/** What a drop did to the cycle, and what to say about it. */
	static final class Result
	{
		final State state;
		/** True when this drop WAS the vestige. */
		final boolean vestige;
		/** True when the next unique from this boss is guaranteed to be the vestige. */
		final boolean vestigeNext;
		/** One line for chat and the drop post, or null when there's nothing worth saying. */
		final String line;

		Result(State state, boolean vestige, boolean vestigeNext, String line)
		{
			this.state = state;
			this.vestige = vestige;
			this.vestigeNext = vestigeNext;
			this.line = line;
		}
	}

	private final Map<String, State> byBoss = new HashMap<>();

	static String key(String boss)
	{
		return boss == null ? "" : boss.trim().toLowerCase(Locale.ROOT);
	}

	State get(String boss)
	{
		return byBoss.getOrDefault(key(boss), new State(0, false));
	}

	void put(String boss, State state)
	{
		byBoss.put(key(boss), state);
	}

	/**
	 * Fold one unique-table drop into the boss's cycle. Returns null when the item isn't part of
	 * this boss's roll table (nothing to count) or the table is unusable.
	 */
	Result record(PluginConfigResponse.RollTable table, int itemId)
	{
		if (table == null || table.rollItemIds == null || !table.rollItemIds.contains(itemId))
		{
			return null;
		}
		int cycle = Math.max(2, table.rollsPerVestige);
		State was = get(table.boss);
		Result r = advance(was, itemId == table.vestigeItemId, cycle, table.vestigeName);
		put(table.boss, r.state);
		return r;
	}

	/**
	 * The rule, in one place: a vestige resets the cycle and anchors it; anything else advances it.
	 * A non-vestige arriving where the vestige was due means our count was off (drops taken while
	 * the plugin wasn't watching) — start the cycle over from this drop and stop claiming exact.
	 */
	static Result advance(State was, boolean isVestige, int rollsPerVestige, String vestigeName)
	{
		String vestige = vestigeName == null || vestigeName.isEmpty() ? "vestige" : vestigeName;
		if (isVestige)
		{
			return new Result(new State(0, true), true, false,
				vestige + "! The cycle resets — the next one is " + rollsPerVestige + " rolls away.");
		}

		int next = was.rolls + 1;
		if (next >= rollsPerVestige)
		{
			// We thought the vestige was due and it wasn't: the count was wrong, not the game.
			return new Result(new State(1, false), false, false,
				"Roll 1 of " + rollsPerVestige + " (estimated — the count was off, re-anchoring)");
		}

		boolean vestigeNext = next == rollsPerVestige - 1;
		String line = "Roll " + next + " of " + rollsPerVestige
			+ (vestigeNext ? " — the next unique is the " + vestige + "!" : "")
			+ (was.exact ? "" : " (estimated)");
		return new Result(new State(next, was.exact), false, vestigeNext, line);
	}

	/** Serialised as "boss=rolls:exact;…" for the RuneLite config, so the cycle survives a restart. */
	String serialise()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, State> e : byBoss.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append('=').append(e.getValue().rolls).append(':').append(e.getValue().exact ? 1 : 0);
		}
		return sb.toString();
	}

	static VestigeRolls parse(String raw)
	{
		VestigeRolls out = new VestigeRolls();
		if (raw == null || raw.trim().isEmpty())
		{
			return out;
		}
		for (String part : raw.split(";"))
		{
			String[] kv = part.split("=", 2);
			if (kv.length != 2)
			{
				continue;
			}
			String[] v = kv[1].split(":", 2);
			try
			{
				int rolls = Integer.parseInt(v[0].trim());
				boolean exact = v.length > 1 && "1".equals(v[1].trim());
				out.byBoss.put(key(kv[0]), new State(Math.max(0, rolls), exact));
			}
			catch (NumberFormatException ignored)
			{
				// A corrupted entry just loses that boss's count — it re-estimates from the next drop.
			}
		}
		return out;
	}
}

package com.anvil;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Where a drop came from, said in a way a reader can act on.
 *
 * RuneLite hands us a loot event and a bare source string, and those two together are not the same
 * question. "Loot Chest" is what the client calls an opened Wilderness loot key, so a post built
 * straight off the string says a haul came "from Loot Chest" — which names no content, hides that
 * the items were taken off a player, and reads like a PvM drop to everyone in the channel. A player
 * kill has the mirror problem: the source is the victim's RSN, so the post reads as though a monster
 * called <i>Zezima</i> dropped a whip.
 *
 * <p>The kind is already classified correctly upstream (loot keys are re-typed to "pvp" in
 * onLootReceived so PvM drop tiles reject their contents) — this is only about saying it out loud.
 *
 * <p>Also the reader for the server's {@code dropFacts}: which monster a pet is really from, and
 * whether an item was ever a roll at all. Both are the server's to know (a new boss is a dataset
 * regen there, a release here), so everything below degrades to the old behaviour on a null.
 *
 * <p>Pure and RuneLite-free, so it is unit-tested directly (DropSourceTest).
 */
final class DropSource
{
	private DropSource()
	{
	}

	/** The client's name for an opened Wilderness loot key. Not a chest, and not our wording. */
	static boolean isLootKey(String source)
	{
		if (source == null)
		{
			return false;
		}
		String s = source.toLowerCase(Locale.ROOT);
		return s.equals("loot chest") || s.contains("loot key");
	}

	/**
	 * The trailing phrase for a drop post: {@code " from Vorkath"}, {@code " from a loot key"},
	 * {@code " from a player kill (Zezima)"}, or {@code ""} when there is nothing true to say.
	 *
	 * <p>Returned with its leading space so a caller can append it unconditionally, the way the
	 * source string was appended before.
	 */
	static String fromPhrase(String source, String sourceKind)
	{
		String label = label(source, sourceKind);
		return label == null ? "" : " from " + label;
	}

	/**
	 * How to name this source, or null when it can't be named.
	 *
	 * <p>A loot key never names its victim — the key is opened long after and somewhere else, and
	 * the client does not carry who it came from — so it is named as itself rather than dressed up
	 * as content. A player kill does know, and naming them is the whole story of the drop.
	 */
	static String label(String source, String sourceKind)
	{
		if (isLootKey(source))
		{
			return "a loot key";
		}
		boolean named = source != null && !source.trim().isEmpty();
		if ("pvp".equals(sourceKind))
		{
			return named ? "a player kill (" + source.trim() + ")" : "a player kill";
		}
		if (!named)
		{
			return null;
		}
		if ("pickpocket".equals(sourceKind))
		{
			return "pickpocketing " + source.trim();
		}
		return source.trim();
	}

	/**
	 * What the count against this source is called.
	 *
	 * <p>A loot key's "kill count" is keys opened and a clue casket's is caskets, and labelling
	 * either of those KC invites the reader to compare it against a drop rate that has nothing to do
	 * with it. Everything else is a kill count, which is what "KC" has always meant here.
	 */
	static String countLabel(String source, String sourceKind)
	{
		if (isLootKey(source))
		{
			return "Keys opened";
		}
		if (source != null && source.toLowerCase(Locale.ROOT).startsWith("clue scroll"))
		{
			return "Caskets";
		}
		return "KC";
	}

	/**
	 * True when {@code source} hands {@code itemName} over on every kill, per the server's facts.
	 *
	 * <p>Guaranteed drops are the one case where a reaction line actively misfires: an ornament kit
	 * the boss owes you is nobody's spoon, and saying someone drier deserved it reads as a bot that
	 * doesn't know the game. Unknown facts (an older site, an item nothing has an opinion about)
	 * answer false, which is exactly today's behaviour.
	 *
	 * <p>A {@code "*"} source in the list means "wherever it drops" — what a clan override without
	 * named sources stores, and the only sane reading of one.
	 */
	static boolean isGuaranteed(PluginConfigResponse.DropFacts facts, String itemName, String source)
	{
		if (facts == null || facts.guaranteed == null || itemName == null)
		{
			return false;
		}
		List<String> sources = facts.guaranteed.get(itemName.toLowerCase(Locale.ROOT).trim());
		if (sources == null || sources.isEmpty())
		{
			return false;
		}
		if (sources.contains("*"))
		{
			return true;
		}
		if (source == null)
		{
			return false;
		}
		String key = source.toLowerCase(Locale.ROOT).trim();
		return sources.contains(key);
	}

	/** The server's entry for a pet, or null when it has nothing to say about it. */
	static PluginConfigResponse.DropFacts.Pet petEntry(PluginConfigResponse.DropFacts facts, String petName)
	{
		if (facts == null || facts.pets == null || petName == null)
		{
			return null;
		}
		return facts.pets.get(petName.toLowerCase(Locale.ROOT).trim());
	}

	/**
	 * Which monster this pet actually came from.
	 *
	 * <p>A pet fires no loot event, so the only thing the client can offer is whatever loot it
	 * happened to see last — a minion, a stray kill, the chest rather than the raid. The pet's name
	 * is the reliable key, and the server holds the map from it. The rules, in order:
	 *
	 * <ol>
	 *   <li>if the loot the client saw IS one of the pet's real sources, that one — it is the most
	 *       specific answer available and disambiguates a pet with several (Vet'ion / Calvar'ion);
	 *   <li>if the pet has exactly one source, that one, whatever the client thought;
	 *   <li>otherwise the source the player has the most kills at, which is the likeliest of them;
	 *   <li>failing all of that, the pet's first listed source, and if there are none, null — a
	 *       skilling pet has no monster and a made-up one is worse than a shorter post.
	 * </ol>
	 *
	 * @param observed  the loot source the client saw around the drop; may be null
	 * @param killCount source name -> the player's kill count there, for the tie-break; may be null
	 */
	static String resolvePetSource(PluginConfigResponse.DropFacts facts, String petName, String observed,
								   Map<String, Integer> killCount)
	{
		PluginConfigResponse.DropFacts.Pet pet = petEntry(facts, petName);
		if (pet == null || pet.sources == null || pet.sources.isEmpty())
		{
			// Nothing known about this pet: an older site, or a pet the catalogue has not placed.
			// The observed source is then the best guess there is, which is where we started.
			return pet == null ? observed : null;
		}
		List<String> sources = pet.sources;
		if (observed != null && !observed.trim().isEmpty())
		{
			for (String candidate : sources)
			{
				if (candidate.equalsIgnoreCase(observed.trim()))
				{
					return candidate;
				}
			}
		}
		if (sources.size() == 1)
		{
			return sources.get(0);
		}
		String best = null;
		int bestKc = -1;
		Map<String, Integer> counts = killCount == null ? Collections.emptyMap() : killCount;
		for (String candidate : sources)
		{
			Integer kc = counts.get(candidate.toLowerCase(Locale.ROOT));
			int value = kc == null ? -1 : kc;
			if (value > bestKc)
			{
				bestKc = value;
				best = candidate;
			}
		}
		return best != null ? best : sources.get(0);
	}
}

package com.anvil;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/**
 * Pure (client-free) adapter that turns the plugin's tracked drops + stats into a single,
 * sortable, filterable list of task rows for the Anvil side panel.
 *
 * Deliberately has no RuneLite dependencies so it is fully unit-testable. The
 * {@link AnvilSidebarPanel} renders {@link TaskRow}s;
 * this class owns only the data shaping (status derivation, filtering, sorting).
 */
public final class ClogTaskModel
{
	private ClogTaskModel() {}

	/** Coarse data shape — drives only the icon fallback (DROP → item icon, STAT → sprite). */
	public enum Type { DROP, STAT }

	/**
	 * Fine-grained tile mechanic, mirroring the web admin's kind filter (standard / skill /
	 * boss / drop / collection / kill / timed / diary / lms / value). Drives the in-clog Type
	 * filter. STANDARD never originates from the plugin config today (manual tiles aren't
	 * synced) but is kept for parity with the web so the cycle order matches.
	 */
	public enum Kind { STANDARD, SKILL, BOSS, DROP, COLLECTION, KILL, PVP, TIMED, DIARY, COMBAT_TASK, LMS, VALUE, GAIN, DEATHLESS }

	public enum Status
	{
		// Order matters: used as the primary sort key so incomplete tasks surface first.
		IN_PROGRESS,
		NOT_STARTED,
		COMPLETED
	}

	/** Status filter options exposed by the in-clog filter bar (Phase 4). */
	public enum StatusFilter { ALL, COMPLETED, IN_PROGRESS, NOT_STARTED }

	/**
	 * Type filter options — ALL plus the seven {@link Kind}s, in the same order the web admin
	 * cycles them. Cycling steps through these on the in-clog "Type" chip.
	 */
	public enum TypeFilter { ALL, STANDARD, SKILL, BOSS, DROP, COLLECTION, KILL, PVP, TIMED, DIARY, COMBAT_TASK, LMS, VALUE, GAIN, DEATHLESS }

	/**
	 * Difficulty-tier bands are no longer hardcoded — the server sends them (admin-configurable) in
	 * the config/board payload. The Tier filter is the selected band's key, or "" for all tiers.
	 * {@link #defaultTierBands()} is the baked-in fallback for older/offline servers.
	 */
	public static List<PluginConfigResponse.TierBand> defaultTierBands()
	{
		List<PluginConfigResponse.TierBand> bands = new ArrayList<>();
		bands.add(tierBand("troll", "Troll", 0));
		bands.add(tierBand("easy", "Easy", 11));
		bands.add(tierBand("medium", "Medium", 100));
		bands.add(tierBand("hard", "Hard", 350));
		bands.add(tierBand("ultra", "Ultra", 700));
		return bands;
	}

	private static PluginConfigResponse.TierBand tierBand(String key, String label, int min)
	{
		PluginConfigResponse.TierBand b = new PluginConfigResponse.TierBand();
		b.key = key;
		b.label = label;
		b.min = min;
		return b;
	}

	/** Served bands with blanks dropped, falling back to the baked-in defaults when empty/null. */
	public static List<PluginConfigResponse.TierBand> tierBandsOrDefault(List<PluginConfigResponse.TierBand> bands)
	{
		if (bands == null)
		{
			return defaultTierBands();
		}
		List<PluginConfigResponse.TierBand> clean = new ArrayList<>();
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b != null && b.key != null && !b.key.isEmpty())
			{
				clean.add(b);
			}
		}
		return clean.isEmpty() ? defaultTierBands() : clean;
	}

	/**
	 * The key of the band a point value falls into — the highest band whose {@code min} it meets,
	 * with the lowest band as the floor. Returns null only when there are no bands.
	 */
	public static String tierKeyOf(int points, List<PluginConfigResponse.TierBand> bands)
	{
		if (bands == null || bands.isEmpty())
		{
			return null;
		}
		PluginConfigResponse.TierBand chosen = null;
		PluginConfigResponse.TierBand lowest = null;
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b == null)
			{
				continue;
			}
			if (lowest == null || b.min < lowest.min)
			{
				lowest = b;
			}
			if (points >= b.min && (chosen == null || b.min >= chosen.min))
			{
				chosen = b;
			}
		}
		if (chosen == null)
		{
			chosen = lowest; // points below every band's min → fall back to the lowest band
		}
		return chosen == null ? null : chosen.key;
	}

	/** Human label for a band key (falls back to "" when not found). */
	public static String tierLabel(String key, List<PluginConfigResponse.TierBand> bands)
	{
		if (key == null || key.isEmpty() || bands == null)
		{
			return "";
		}
		for (PluginConfigResponse.TierBand b : bands)
		{
			if (b != null && key.equalsIgnoreCase(b.key))
			{
				return b.label != null ? b.label : b.key;
			}
		}
		return "";
	}

	/** The coarse {@link Type} implied by a {@link Kind} — DROP-family kinds show an item icon. */
	private static Type typeOf(Kind kind)
	{
		return (kind == Kind.DROP || kind == Kind.COLLECTION || kind == Kind.VALUE || kind == Kind.GAIN) ? Type.DROP : Type.STAT;
	}

	/** Default {@link Kind} for the legacy constructors (board previews / tests) that only know Type. */
	private static Kind kindOf(Type type)
	{
		return type == Type.DROP ? Kind.DROP : Kind.SKILL;
	}

	/**
	 * A single renderable task. Immutable. {@code itemId < 0} means "no item icon" (stat tiles);
	 * {@code points} is the tile's Leagues-style reward value (0 when the event isn't points-scored
	 * or the value isn't known to the plugin yet).
	 */
	public static final class TaskRow
	{
		public final int tileId;
		public final String label;
		public final Type type;
		public final Kind kind;
		public final int current;
		public final int goal;
		public final int itemId;
		public final int points;
		public final String description;
		public final String category; // free-text grouping (boss/skill); "" = uncategorised
		public final String skillName; // hiscores skill for SKILL tiles ("mining"); null otherwise
		// Pre-formatted "current/goal" for tiles whose progress isn't a plain count — a cumulative
		// value tile is measured in gp, and "12500000/50000000" is a number nobody reads. Null on
		// every other kind, which means the renderer prints current/goal itself.
		public final String progressText;
		public final Status status;
		// Board position — the within-status-group sort key, so the in-game list mirrors the
		// site's tile order (difficulty sort, shuffle). Set after construction (0 on old
		// servers, where the sort falls through to the label tiebreak — the old behavior).
		public int position;

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId)
		{
			this(tileId, label, type, current, goal, itemId, 0, null, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points)
		{
			this(tileId, label, type, current, goal, itemId, points, null, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description)
		{
			this(tileId, label, type, current, goal, itemId, points, description, null);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description, String category)
		{
			this(tileId, label, type, current, goal, itemId, points, description, category, false);
		}

		public TaskRow(int tileId, String label, Type type, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted)
		{
			// Legacy entry point (board previews / tests): infer the fine-grained kind from Type.
			this(tileId, label, kindOf(type), current, goal, itemId, points, description, category, forceCompleted);
		}

		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted)
		{
			this(tileId, label, kind, current, goal, itemId, points, description, category, forceCompleted, null);
		}

		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted, String skillName)
		{
			this(tileId, label, kind, current, goal, itemId, points, description, category, forceCompleted,
				skillName, null);
		}

		/** Canonical constructor — callers that know the precise {@link Kind} (e.g. {@link #build}) use this. */
		public TaskRow(int tileId, String label, Kind kind, int current, int goal, int itemId, int points,
			String description, String category, boolean forceCompleted, String skillName, String progressText)
		{
			this.progressText = progressText;
			this.tileId = tileId;
			this.label = label == null ? "" : label;
			this.kind = kind == null ? Kind.STANDARD : kind;
			this.type = typeOf(this.kind);
			this.current = current;
			this.goal = goal;
			this.itemId = itemId;
			this.points = points;
			this.description = description == null ? "" : description;
			this.category = category == null ? "" : category.trim();
			this.skillName = skillName;
			// A team-level completion (any member / manual) is authoritative even when this client's
			// own current < goal — e.g. an individual-mode tile a teammate finished first.
			this.status = forceCompleted ? Status.COMPLETED : statusOf(current, goal);
		}

		public boolean isCompleted()
		{
			return status == Status.COMPLETED;
		}
	}

	/**
	 * Derive completion status from progress. A goal of {@code <= 0} (an untargeted tile)
	 * counts as completed the moment there's any progress, otherwise not-started.
	 */
	public static Status statusOf(int current, int goal)
	{
		if (goal > 0)
		{
			if (current >= goal)
			{
				return Status.COMPLETED;
			}
			return current > 0 ? Status.IN_PROGRESS : Status.NOT_STARTED;
		}
		return current > 0 ? Status.COMPLETED : Status.NOT_STARTED;
	}

	/** Build the full task list from the plugin config (drops + stats). Null-safe. */
	public static List<TaskRow> build(PluginConfigResponse cfg)
	{
		List<TaskRow> rows = new ArrayList<>();
		if (cfg == null)
		{
			return rows;
		}

		java.util.Set<Integer> completed = new java.util.HashSet<>();
		if (cfg.completedTiles != null)
		{
			for (PluginConfigResponse.CompletedTile c : cfg.completedTiles)
			{
				if (c != null)
				{
					completed.add(c.tileId);
				}
			}
		}

		if (cfg.trackedDrops != null)
		{
			for (PluginConfigResponse.TrackedDrop d : cfg.trackedDrops)
			{
				if (d == null)
				{
					continue;
				}
				// A per-item requirement list means "collect each of these" → a COLLECTION tile;
				// otherwise it's a simple drop pool. Mirrors the web's drop-vs-collection split.
				Kind kind = (d.itemRequirements != null && !d.itemRequirements.isEmpty())
					? Kind.COLLECTION : Kind.DROP;
				int current = d.currentAmount;
				int goal = d.requiredAmount;
				boolean done = completed.contains(d.tileId);
				if (kind == Kind.COLLECTION)
				{
					// A collection completes when its SETS are satisfied — not when the summed submission
					// count reaches requiredAmount (the server stores that as a shortest-path total, often
					// 1, so a 3-of-4 rings set read as 3/1 = done). Drive progress off the per-item
					// requirements, their sets, and how the tile says those sets combine.
					int[] pg = collectionProgress(d.itemRequirements, d.groupMode);
					current = pg[0];
					goal = pg[1];
					done = done || pg[2] == 1;
				}
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, kind, current, goal,
					representativeItemId(d), d.points, d.description, d.category, done));
			}
		}

		if (cfg.trackedStats != null)
		{
			for (PluginConfigResponse.TrackedStat s : cfg.trackedStats)
			{
				if (s == null)
				{
					continue;
				}
				// Stat tiles have no inventory item to show; the controller substitutes a
				// skill/boss sprite. -1 signals "no item icon". Category falls back to the stat
				// name (e.g. "zulrah", "mining") so stat tiles group sensibly even without one set.
				String statCategory = (s.category != null && !s.category.trim().isEmpty())
					? s.category : s.statName;
				boolean isBoss = "boss".equalsIgnoreCase(s.statType) || "kc".equalsIgnoreCase(s.statType);
				// statName doubles as the skill identifier ("mining") for the renderer's skill
				// icon; boss tiles carry the server-picked representative item instead.
				addAt(rows, s.position, new TaskRow(s.tileId, s.label, isBoss ? Kind.BOSS : Kind.SKILL, s.currentAmount,
					s.goalAmount, isBoss ? s.itemId : -1, s.points, s.description, statCategory,
					completed.contains(s.tileId), isBoss ? null : s.statName));
			}
		}

		if (cfg.trackedKills != null)
		{
			for (PluginConfigResponse.TrackedKill k : cfg.trackedKills)
			{
				if (k == null)
				{
					continue;
				}
				// No inventory icon for a kill-count tile; the controller shows the stat sprite.
				addAt(rows, k.position, new TaskRow(k.tileId, k.label, Kind.KILL, k.currentAmount, k.requiredAmount, -1,
					k.points, k.description, k.category, completed.contains(k.tileId)));
			}
		}

		if (cfg.trackedPvp != null)
		{
			for (PluginConfigResponse.TrackedPvp p : cfg.trackedPvp)
			{
				if (p == null)
				{
					continue;
				}
				// No inventory icon for a PvP-kill tile; the controller shows the stat sprite.
				addAt(rows, p.position, new TaskRow(p.tileId, p.label, Kind.PVP, p.currentAmount, p.requiredAmount, -1,
					p.points, p.description, p.category, completed.contains(p.tileId)));
			}
		}

		if (cfg.trackedDiaries != null)
		{
			for (PluginConfigResponse.TrackedDiary d : cfg.trackedDiaries)
			{
				if (d == null)
				{
					continue;
				}
				// Diary tiles count completions exactly like kills; no inventory icon.
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, Kind.DIARY, d.currentAmount, d.requiredAmount, -1,
					d.points, d.description, d.category, completed.contains(d.tileId)));
			}
		}

		if (cfg.trackedCombatTasks != null)
		{
			for (PluginConfigResponse.TrackedCombatTask t : cfg.trackedCombatTasks)
			{
				if (t == null)
				{
					continue;
				}
				// Combat Achievement tiles count completions exactly like diaries; no inventory icon.
				addAt(rows, t.position, new TaskRow(t.tileId, t.label, Kind.COMBAT_TASK, t.currentAmount, t.requiredAmount, -1,
					t.points, t.description, t.category, completed.contains(t.tileId)));
			}
		}

		if (cfg.trackedTimed != null)
		{
			for (PluginConfigResponse.TrackedTimed t : cfg.trackedTimed)
			{
				if (t == null)
				{
					continue;
				}
				// Timed tiles are pass/fail (no running count): completed flag drives status; goal 1.
				// The server sends the activity's signature reward as the icon (quiver, capes…).
				boolean done = t.completed || completed.contains(t.tileId);
				addAt(rows, t.position, new TaskRow(t.tileId, t.label, Kind.TIMED, done ? 1 : 0, 1, t.itemId,
					t.points, t.description, t.category, done));
			}
		}

		if (cfg.trackedLms != null)
		{
			for (PluginConfigResponse.TrackedLms l : cfg.trackedLms)
			{
				if (l == null)
				{
					continue;
				}
				// LMS tiles count qualifying games toward requiredAmount, exactly like kills.
				addAt(rows, l.position, new TaskRow(l.tileId, l.label, Kind.LMS, l.currentAmount,
					Math.max(1, l.requiredAmount), -1, l.points, l.description, l.category,
					completed.contains(l.tileId)));
			}
		}

		if (cfg.trackedValues != null)
		{
			for (PluginConfigResponse.TrackedValue v : cfg.trackedValues)
			{
				if (v == null)
				{
					continue;
				}
				// Coins as the icon — a gp-threshold tile has no single representative item.
				boolean done = v.completed || completed.contains(v.tileId);
				if (isTotalValue(v))
				{
					// A cumulative tile ("bank 50m between you") has real progress the server already
					// tracks, and showing it as pass/fail threw that away — the one tile on the board
					// that could say how far along the team was, saying only "not yet". Bars are drawn
					// from current/goal, so those carry the gp (clamped, since a target can exceed an
					// int) while the label gets the readable form.
					int goal = clampGp(v.thresholdGp);
					int current = Math.min(clampGp(v.currentGp), goal);
					addAt(rows, v.position, new TaskRow(v.tileId, v.label, Kind.VALUE, current, goal, COINS_ITEM_ID,
						v.points, v.description, v.category, done, null,
						formatGp(v.currentGp) + "/" + formatGp(v.thresholdGp)));
				}
				else
				{
					// Single-haul tiles are genuinely pass/fail — one qualifying drop or nothing — so
					// there's no partial progress to show and the completed flag drives status.
					addAt(rows, v.position, new TaskRow(v.tileId, v.label, Kind.VALUE, done ? 1 : 0, 1, COINS_ITEM_ID,
						v.points, v.description, v.category, done));
				}
			}
		}

		if (cfg.trackedGains != null)
		{
			for (PluginConfigResponse.TrackedGain g : cfg.trackedGains)
			{
				if (g == null)
				{
					continue;
				}
				// Gain tiles count like kills; the first pool item doubles as the icon.
				int icon = (g.itemIds != null && !g.itemIds.isEmpty() && g.itemIds.get(0) != null)
					? g.itemIds.get(0) : -1;
				addAt(rows, g.position, new TaskRow(g.tileId, g.label, Kind.GAIN, g.currentAmount,
					Math.max(1, g.requiredAmount), icon, g.points, g.description, g.category,
					completed.contains(g.tileId)));
			}
		}

		if (cfg.trackedDeathless != null)
		{
			for (PluginConfigResponse.TrackedDeathless d : cfg.trackedDeathless)
			{
				if (d == null)
				{
					continue;
				}
				// Deathless runs count like kills; the server sends the raid's signature reward icon.
				addAt(rows, d.position, new TaskRow(d.tileId, d.label, Kind.DEATHLESS, d.currentAmount,
					Math.max(1, d.requiredAmount), d.itemId, d.points, d.description, d.category,
					completed.contains(d.tileId)));
			}
		}

		return rows;
	}

	/**
	 * True when a value tile accumulates toward its target rather than needing one qualifying haul.
	 * An older server sends no mode at all, which means single — the only behaviour it had.
	 */
	static boolean isTotalValue(PluginConfigResponse.TrackedValue v)
	{
		return v != null && "total".equalsIgnoreCase(v.mode);
	}

	/**
	 * Squeeze a gp amount into the int the progress bar is drawn from. A gp target is a long because
	 * a clan-wide one can pass 2.1b; the bar only needs the ratio, and both ends clamp together so a
	 * clamped tile still fills at the right rate rather than looking finished early.
	 */
	private static int clampGp(long gp)
	{
		if (gp <= 0)
		{
			return 0;
		}
		return gp > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) gp;
	}

	/**
	 * Short gp for a progress line: 999, 12.5K, 3.4M, 2.15B. Trailing ".0" is dropped so a round
	 * number reads "50M" rather than "50.0M", and the unit is only attached once — this sits in
	 * "12.5M/50M", where repeating it on both sides is noise.
	 */
	static String formatGp(long gp)
	{
		long v = Math.max(0, gp);
		if (v < 1_000)
		{
			return Long.toString(v);
		}
		String unit;
		double scaled;
		if (v < 1_000_000)
		{
			unit = "K";
			scaled = v / 1_000d;
		}
		else if (v < 1_000_000_000L)
		{
			unit = "M";
			scaled = v / 1_000_000d;
		}
		else
		{
			unit = "B";
			scaled = v / 1_000_000_000d;
		}
		// One decimal, but only when it says something — truncated rather than rounded so a tile
		// never reads as finished ("50M/50M") while the server still counts it short.
		double truncated = Math.floor(scaled * 10) / 10d;
		if (truncated == Math.floor(truncated))
		{
			return (long) truncated + unit;
		}
		return String.format(java.util.Locale.ROOT, "%.1f%s", truncated, unit);
	}

	/** Adds the row with its board position stamped — the within-status-group sort key. */
	private static void addAt(List<TaskRow> rows, int position, TaskRow row)
	{
		row.position = position;
		rows.add(row);
	}

	/** Inventory item id for coins — the stand-in icon for loot-value (gp threshold) tiles. */
	static final int COINS_ITEM_ID = 995;

	/**
	 * Pick the icon to show for a drop tile: the first per-item requirement if present,
	 * else the first raw tracked item id, else -1.
	 */
	private static int representativeItemId(PluginConfigResponse.TrackedDrop d)
	{
		if (d.itemRequirements != null && !d.itemRequirements.isEmpty()
			&& d.itemRequirements.get(0) != null)
		{
			return d.itemRequirements.get(0).itemId;
		}
		if (d.itemIds != null && !d.itemIds.isEmpty() && d.itemIds.get(0) != null)
		{
			return d.itemIds.get(0);
		}
		return -1;
	}

	/**
	 * Set-aware collection progress, mirroring the site's lib/collectionSets (which owns the rule and
	 * decides completion server-side — this is the in-game read of the same tile).
	 *
	 * <p>Ungrouped requirements are ALWAYS required. Items sharing a {@code group} form one set, and a
	 * set counts as satisfied once {@code groupRequire} distinct items in it are obtained (0 = all of
	 * them, a full set). {@code groupMode} decides how the sets combine:
	 *
	 * <ul>
	 *   <li>{@code "any"} (default) — the sets are alternatives; satisfying ONE completes the tile.
	 *       Progress reports the set the player is CLOSEST to finishing, so a two-set tile shows real
	 *       progress toward one set instead of the inflated sum across every set.</li>
	 *   <li>{@code "all"} — every set must be satisfied. Progress sums what each set needs, so
	 *       "a unique from each of 4 bosses" reads 2/4 rather than pretending one boss finished it.</li>
	 * </ul>
	 *
	 * <p>Returns {current, goal, done}. An older server sends no groupMode/groupRequire, which lands
	 * on exactly the previous behaviour: OR-ed full sets.
	 */
	static int[] collectionProgress(List<PluginConfigResponse.ItemRequirement> reqs)
	{
		return collectionProgress(reqs, null);
	}

	static int[] collectionProgress(List<PluginConfigResponse.ItemRequirement> reqs, String groupMode)
	{
		List<PluginConfigResponse.ItemRequirement> ungrouped = new ArrayList<>();
		java.util.LinkedHashMap<String, List<PluginConfigResponse.ItemRequirement>> groups = new java.util.LinkedHashMap<>();
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r == null)
			{
				continue;
			}
			String g = r.group == null ? "" : r.group.trim();
			if (g.isEmpty())
			{
				ungrouped.add(r);
			}
			else
			{
				// Case-insensitive, like the server's grouping — "Duke" and "duke" are one set.
				groups.computeIfAbsent(g.toLowerCase(java.util.Locale.ROOT), k -> new ArrayList<>()).add(r);
			}
		}

		int ungroupedSat = satisfied(ungrouped);
		int ungroupedSize = ungrouped.size();
		if (groups.isEmpty())
		{
			int goal = Math.max(1, ungroupedSize);
			return new int[]{ ungroupedSat, goal, ungroupedSat >= ungroupedSize && ungroupedSize > 0 ? 1 : 0 };
		}

		if ("all".equalsIgnoreCase(groupMode))
		{
			// Every set must be satisfied: the tile's goal is the always-required items plus each set's
			// own requirement, and progress is what's been met toward that, capped per set so a fifth
			// Duke unique can't paper over a missing Leviathan one.
			int sat = ungroupedSat;
			int goal = ungroupedSize;
			boolean allSetsDone = true;
			for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
			{
				int need = requireCount(grp);
				int met = Math.min(satisfied(grp), need);
				sat += met;
				goal += need;
				if (met < need)
				{
					allSetsDone = false;
				}
			}
			return new int[]{ sat, Math.max(1, goal), allSetsDone && ungroupedSat >= ungroupedSize ? 1 : 0 };
		}

		// "any": each set, combined with the always-required items, is one alternative.
		int bestSat = 0;
		int bestGoal = 1;
		int bestRemaining = Integer.MAX_VALUE;
		for (List<PluginConfigResponse.ItemRequirement> grp : groups.values())
		{
			int need = requireCount(grp);
			int sat = ungroupedSat + Math.min(satisfied(grp), need);
			int size = ungroupedSize + need;
			if (size <= 0)
			{
				continue;
			}
			if (sat >= size)
			{
				return new int[]{ size, size, 1 }; // this set is satisfied — the tile is complete
			}
			int remaining = size - sat;
			if (remaining < bestRemaining || (remaining == bestRemaining && sat > bestSat))
			{
				bestRemaining = remaining;
				bestSat = sat;
				bestGoal = size;
			}
		}
		return new int[]{ bestSat, Math.max(1, bestGoal), 0 };
	}

	/** How many of these requirements the player has met. */
	private static int satisfied(List<PluginConfigResponse.ItemRequirement> reqs)
	{
		int n = 0;
		for (PluginConfigResponse.ItemRequirement r : reqs)
		{
			if (r.currentAmount >= Math.max(1, r.requiredAmount))
			{
				n++;
			}
		}
		return n;
	}

	/**
	 * How many distinct items a set needs. Rows of a set should agree; if they don't (hand-edited
	 * config) the strictest wins, clamped to the set's size so a stale "any 4 of" on a set that has
	 * since shrunk to 3 items stays satisfiable. Same resolution as the server's.
	 */
	private static int requireCount(List<PluginConfigResponse.ItemRequirement> grp)
	{
		int declared = 0;
		for (PluginConfigResponse.ItemRequirement r : grp)
		{
			if (r.groupRequire > declared)
			{
				declared = r.groupRequire;
			}
		}
		if (declared <= 0)
		{
			declared = grp.size();
		}
		return Math.min(Math.max(1, declared), grp.size());
	}

	/**
	 * Apply the active filters and return a new list (incomplete-first, then by label).
	 * {@code search} is a case-insensitive substring match on the label; null/blank = no
	 * text filter.
	 */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search)
	{
		return filter(rows, statusFilter, typeFilter, search, null, "", null);
	}

	/** As {@link #filter} but also restricts to a category ({@code null}/blank = all categories). */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search, String category)
	{
		return filter(rows, statusFilter, typeFilter, search, category, "", null);
	}

	/**
	 * As {@link #filter} but also restricts to a difficulty tier — {@code tierKey} blank = every
	 * tier; otherwise a tile matches when its points-derived band (per {@code tierBands}) equals it.
	 */
	public static List<TaskRow> filter(List<TaskRow> rows, StatusFilter statusFilter,
		TypeFilter typeFilter, String search, String category, String tierKey,
		List<PluginConfigResponse.TierBand> tierBands)
	{
		final String needle = search == null ? "" : search.trim().toLowerCase(Locale.ROOT);
		final StatusFilter sf = statusFilter == null ? StatusFilter.ALL : statusFilter;
		final TypeFilter tf = typeFilter == null ? TypeFilter.ALL : typeFilter;
		final String tier = tierKey == null ? "" : tierKey.trim();
		final String cat = category == null ? "" : category.trim();

		List<TaskRow> out = new ArrayList<>();
		for (TaskRow r : rows)
		{
			if (!matchesStatus(r, sf) || !matchesType(r, tf) || !matchesTier(r, tier, tierBands))
			{
				continue;
			}
			if (!cat.isEmpty() && !hasCategory(r, cat))
			{
				continue;
			}
			if (!needle.isEmpty() && !r.label.toLowerCase(Locale.ROOT).contains(needle))
			{
				continue;
			}
			out.add(r);
		}

		// Actionable first (in progress → not started → completed), then the site's board
		// order within each group — matching however the host sorted or shuffled the board.
		out.sort(Comparator
			.comparingInt((TaskRow r) -> r.status.ordinal())
			.thenComparingInt(r -> r.position)
			.thenComparing(r -> r.label, String.CASE_INSENSITIVE_ORDER));
		return out;
	}

	private static boolean matchesStatus(TaskRow r, StatusFilter sf)
	{
		switch (sf)
		{
			case COMPLETED:
				return r.status == Status.COMPLETED;
			case IN_PROGRESS:
				return r.status == Status.IN_PROGRESS;
			case NOT_STARTED:
				return r.status == Status.NOT_STARTED;
			case ALL:
			default:
				return true;
		}
	}

	private static boolean matchesType(TaskRow r, TypeFilter tf)
	{
		switch (tf)
		{
			case STANDARD:
				return r.kind == Kind.STANDARD;
			case SKILL:
				return r.kind == Kind.SKILL;
			case BOSS:
				return r.kind == Kind.BOSS;
			case DROP:
				return r.kind == Kind.DROP;
			case COLLECTION:
				return r.kind == Kind.COLLECTION;
			case KILL:
				return r.kind == Kind.KILL;
			case PVP:
				return r.kind == Kind.PVP;
			case TIMED:
				return r.kind == Kind.TIMED;
			case DIARY:
				return r.kind == Kind.DIARY;
			case COMBAT_TASK:
				return r.kind == Kind.COMBAT_TASK;
			case LMS:
				return r.kind == Kind.LMS;
			case VALUE:
				return r.kind == Kind.VALUE;
			case GAIN:
				return r.kind == Kind.GAIN;
			case DEATHLESS:
				return r.kind == Kind.DEATHLESS;
			case ALL:
			default:
				return true;
		}
	}

	private static boolean matchesTier(TaskRow r, String tierKey, List<PluginConfigResponse.TierBand> bands)
	{
		if (tierKey == null || tierKey.isEmpty())
		{
			return true;
		}
		return tierKey.equalsIgnoreCase(tierKeyOf(r.points, bands));
	}

	/**
	 * True when one of the row's comma-separated category tags equals {@code cat}
	 * (case-insensitive). A tile can carry several tags (e.g. "Inferno, PvM") and
	 * should surface under every one of them.
	 */
	private static boolean hasCategory(TaskRow r, String cat)
	{
		for (String part : r.category.split(","))
		{
			if (cat.equalsIgnoreCase(part.trim()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Distinct, case-insensitively-deduped category tags present (sorted); blanks excluded.
	 * Comma-separated multi-tag categories contribute each tag individually.
	 */
	public static List<String> categories(List<TaskRow> rows)
	{
		List<String> out = new ArrayList<>();
		for (TaskRow r : rows)
		{
			if (r.category == null || r.category.isEmpty())
			{
				continue;
			}
			for (String part : r.category.split(","))
			{
				String tag = part.trim();
				if (tag.isEmpty())
				{
					continue;
				}
				boolean seen = false;
				for (String c : out)
				{
					if (c.equalsIgnoreCase(tag))
					{
						seen = true;
						break;
					}
				}
				if (!seen)
				{
					out.add(tag);
				}
			}
		}
		out.sort(String.CASE_INSENSITIVE_ORDER);
		return out;
	}

	/** Count completed rows (for the header "{done}/{total}" summary). */
	public static int completedCount(List<TaskRow> rows)
	{
		return completedCount(rows, java.util.Collections.emptySet());
	}

	/** As {@link #completedCount(List)} but excluding optional tiles — they're bonus, off the score. */
	public static int completedCount(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int n = 0;
		for (TaskRow r : rows)
		{
			if (r.isCompleted() && !optionalTileIds.contains(r.tileId))
			{
				n++;
			}
		}
		return n;
	}

	/** Points earned so far (sum of points of completed rows) — the Leagues-style banner number. */
	public static int earnedPoints(List<TaskRow> rows)
	{
		return earnedPoints(rows, java.util.Collections.emptySet());
	}

	/** As {@link #earnedPoints(List)} but excluding optional tiles (bonus tiles don't add to the score). */
	public static int earnedPoints(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int p = 0;
		for (TaskRow r : rows)
		{
			if (r.isCompleted() && !optionalTileIds.contains(r.tileId))
			{
				p += r.points;
			}
		}
		return p;
	}

	/** Total points available across all rows. */
	public static int totalPoints(List<TaskRow> rows)
	{
		return totalPoints(rows, java.util.Collections.emptySet());
	}

	/** As {@link #totalPoints(List)} but excluding optional tiles — they're not part of the denominator. */
	public static int totalPoints(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int p = 0;
		for (TaskRow r : rows)
		{
			if (!optionalTileIds.contains(r.tileId))
			{
				p += r.points;
			}
		}
		return p;
	}

	/** Number of SCORED (non-optional) rows — the count-mode denominator (classic/race "x / y"). */
	public static int scoredCount(List<TaskRow> rows, java.util.Set<Integer> optionalTileIds)
	{
		int n = 0;
		for (TaskRow r : rows)
		{
			if (!optionalTileIds.contains(r.tileId))
			{
				n++;
			}
		}
		return n;
	}
}

package com.anvil;

/**
 * What the plugin says in chat about its own setup, and how often.
 *
 * <p>THE STATE THAT SAID NOTHING. The old check compared "has a Site URL" against "has a token" and
 * returned when they agreed — which covers the connected install, and covers the fresh one too. So
 * somebody who installed Anvil and never opened the side panel got complete silence forever: the
 * plugin's whole surface is a panel they have no reason to click, and nothing in the game ever
 * mentioned that there was a step left. A half-configured install got told; the one that had done
 * nothing at all did not.</p>
 *
 * <p>That mattered less when Anvil was something your clan admin set up for you and handed you a
 * token for. It is now a per-person account that works with no clan at all, so a fresh install is
 * the normal way in rather than a clan's leftover, and the thing it needs to know is where to go.</p>
 *
 * <p>NUDGE, NOT NAG. The first-run line is capped — {@link #FIRST_RUN_NUDGES} logins, counted in
 * config so the cap survives a restart — because somebody who has decided not to connect has
 * answered the question, and a message that repeats forever is how a plugin gets uninstalled. The
 * two half-configured lines are unchanged: those are a real misconfiguration, they are once per
 * client session, and they are what the member asked for by configuring half of it.</p>
 *
 * <p>Pure, and RuneLite-free, so the decision can be tested without a client: the plugin supplies
 * the two config values and the count, and gets back what to print.</p>
 */
public final class SetupNudge
{
	/** How many logins a never-configured install is told where to go before it stops asking. */
	static final int FIRST_RUN_NUDGES = 3;

	/** The site, as it reads in a chat line — one source of truth with the address Sign in writes. */
	static final String SITE_HOST = BingoApiClient.CANONICAL_SITE.replaceFirst("^https?://", "");

	public enum Kind
	{
		/** Connected, or done asking. Say nothing. */
		NONE,
		/** Nothing configured at all — the fresh install, and the only one of these that is not an error. */
		FIRST_RUN,
		/** Site URL set, no token: tracking cannot authenticate. */
		MISSING_TOKEN,
		/** Token set, no Site URL: tracking has nowhere to go. */
		MISSING_URL,
	}

	/**
	 * @param firstRunShown how many times the first-run line has already been printed on this install
	 */
	public static Kind decide(String apiUrl, String token, int firstRunShown)
	{
		boolean hasUrl = apiUrl != null && !apiUrl.trim().isEmpty();
		boolean hasToken = token != null && !token.trim().isEmpty();

		if (hasUrl && hasToken)
		{
			return Kind.NONE;
		}
		if (hasUrl)
		{
			return Kind.MISSING_TOKEN;
		}
		if (hasToken)
		{
			return Kind.MISSING_URL;
		}
		return firstRunShown < FIRST_RUN_NUDGES ? Kind.FIRST_RUN : Kind.NONE;
	}

	/**
	 * The chat lines for a decision, in order. Empty for {@link Kind#NONE}.
	 *
	 * <p>The first-run pair is two lines on purpose: the first is the instruction — one button, in a
	 * panel they are being told exists — and the second is the reason anyone would press it, which
	 * for a person with no clan is the part that is not obvious. Neither line is a request to go
	 * anywhere the plugin has not already been pointed: signing in is what writes the address.</p>
	 */
	public static String[] lines(Kind kind)
	{
		switch (kind)
		{
			case FIRST_RUN:
				return new String[]{
					"Not connected yet — open the Anvil panel (the anvil icon on the right) and press \"Sign in with Discord\".",
					"A free account on " + SITE_HOST + " tracks your collection log, personal bests and records. No clan needed — and starting one is free.",
				};
			case MISSING_URL:
				return new String[]{
					"Your Account Token is set but the Site URL is missing — add it in the Anvil plugin config so tracking can connect.",
				};
			case MISSING_TOKEN:
				return new String[]{
					"Your Site URL is set but the Account Token is missing — paste your token from the Anvil site into the plugin config.",
				};
			default:
				return new String[0];
		}
	}

	private SetupNudge()
	{
	}
}

package com.anvil;

/**
 * Binomial-probability helpers for multi-roll drop rarity.
 *
 * Adapted from Dink (pajlads/DinkPlugin), BSD-2-Clause — see THIRD_PARTY_NOTICES.md. Trimmed to the
 * methods the rarity service needs and rewritten to avoid the Guava dependency.
 */
final class MathUtils {
    static final double EPSILON = 0.00001;

    // Precomputed factorials 0..9 — max rolls in npc_drops.json is 9.
    private static final int[] FACTORIALS;

    static {
        int n = 10;
        int[] facts = new int[n];
        facts[0] = 1;
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }

    private MathUtils() {
    }

    static boolean lessThanOrEqual(double a, double b) {
        return a < b || Math.abs(a - b) <= EPSILON;
    }

    static double binomialProbability(double p, int nTrials, int kSuccess) {
        // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
        return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
    }

    private static int binomialCoefficient(int n, int k) {
        return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]);
    }
}

package com.anvil;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

@Slf4j
public class AnvilOverlay extends OverlayPanel {

    private static final DateTimeFormatter DATE_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'");

    private final AnvilPlugin plugin;
    private final AnvilConfig config;

    @Inject
    public AnvilOverlay(AnvilPlugin plugin, AnvilConfig config) {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showOverlay()) {
            return null;
        }

        PluginConfigResponse pluginConfig = plugin.getPluginConfig();
        if (pluginConfig == null || pluginConfig.event == null) {
            return null;
        }

        // Don't show overlay if event isn't active
        if (!isEventActive(pluginConfig.event)) {
            return null;
        }

        // Title
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Anvil")
                .color(new Color(255, 215, 0)) // Gold
                .build());

        // Team — the only proof we need on a screenshot. Team name + UTC date are
        // uniquely identifying for a submission. The previous codeword was redundant
        // since we never validated it server-side, and the aggregate "Drops: 1/3"
        // line was misleading when multiple tiles are progressing in parallel.
        if (pluginConfig.team != null && pluginConfig.team.name != null && !pluginConfig.team.name.isEmpty()) {
            Color teamColor = Color.WHITE;
            try {
                if (pluginConfig.team.color != null && pluginConfig.team.color.startsWith("#")) {
                    teamColor = Color.decode(pluginConfig.team.color);
                }
            } catch (NumberFormatException ignored) {
                /* fall back to white */ }
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Team:")
                    .right(pluginConfig.team.name)
                    .rightColor(teamColor)
                    .build());
        }

        // Date — UTC for unambiguous time-of-drop on the proof image.
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Date:")
                .right(ZonedDateTime.now(ZoneOffset.UTC).format(DATE_FMT))
                .build());

        return super.render(graphics);
    }

    static boolean isEventActive(PluginConfigResponse.EventInfo event) {
        if (event == null) {
            return false;
        }
        // Force-ended by admin
        if (event.forceEndedAt != null) {
            return false;
        }

        Instant now = Instant.now();

        if (event.startDate != null) {
            try {
                Instant start = Instant.parse(event.startDate);
                if (now.isBefore(start)) {
                    return false; // hasn't started
                }
            } catch (Exception e) {
                log.warn("Failed to parse event startDate '{}': {}", event.startDate, e.getMessage());
                return false; // treat as inactive on parse failure
            }
        }

        if (event.endDate != null) {
            try {
                Instant end = Instant.parse(event.endDate);
                if (now.isAfter(end)) {
                    return false; // already ended
                }
            } catch (Exception e) {
                log.warn("Failed to parse event endDate '{}': {}", event.endDate, e.getMessage());
                return false; // treat as inactive on parse failure
            }
        }

        return true;
    }
}

package com.anvil;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Collects a WHOLE collection log, as the server transmits it.
 *
 * <p>The client normally holds one page — whichever the player last drew — which is why the page
 * reader ({@link ClogPageReader}) can only ever report what someone has clicked through. But opening
 * the log and toggling its Search makes the server transmit EVERY entry, one script fire per item.
 * That's the whole log in one go, with no paging and nothing for the player to do but open the
 * interface. (The technique is WikiSync's; RuneProfile uses it too.)
 *
 * <p>This class is the accumulator and the "have they stopped arriving yet" policy. It is
 * RuneLite-free on purpose: the awkward parts are the quiet period and the guards against half a
 * transmit being sent as if it were a log, and both are worth testing without a client.
 *
 * <p>Item ids only — no page names. The site owns the catalogue (src/data/clog.json) and maps ids to
 * pages on the way in, so a game update that shuffles pages is a dataset rebuild rather than a
 * plugin release.
 */
final class ClogFullSync
{
	/**
	 * Items land over several ticks; wait this long after the last one before calling it complete.
	 * Two ticks and change — long enough that a transmit arriving in bursts isn't cut in half, short
	 * enough that a player who pressed a button isn't left watching an ellipsis.
	 */
	static final long QUIET_MS = 1_200;

	/**
	 * A transmit that yields fewer items than this is treated as noise rather than a log. The point
	 * is not to validate someone's collection — a genuinely empty log is possible — but to refuse to
	 * REPLACE a stored log with the tail end of an interrupted transmit (they closed the interface
	 * mid-flight, or another plugin's own search toggle fired one item).
	 */
	static final int MIN_ITEMS = 5;

	/** itemId -> quantity, in arrival order so a batch reads like the log does. */
	private final Map<Integer, Integer> items = new LinkedHashMap<>();

	private long lastItemAt;
	private boolean receiving;
	/** Set when the player asked for this explicitly, so a no-change sync still gets sent + reported. */
	private boolean manual;

	/** A transmit is starting (the log was opened / the button was pressed). Clears anything stale. */
	void begin(boolean manualRequest)
	{
		items.clear();
		receiving = true;
		manual = manual || manualRequest;
		lastItemAt = 0;
	}

	/** One item, straight off the transmit script. Ignored unless a transmit is actually in flight. */
	void onItem(int itemId, int quantity, long now)
	{
		if (!receiving || itemId <= 0)
		{
			return;
		}
		items.put(itemId, Math.max(1, quantity));
		lastItemAt = now;
	}

	/**
	 * Has a complete-looking transmit settled? True once nothing has arrived for {@link #QUIET_MS}
	 * and enough items landed to be a log rather than a fragment.
	 */
	boolean isDue(long now)
	{
		return receiving
			&& lastItemAt > 0
			&& items.size() >= MIN_ITEMS
			&& now - lastItemAt >= QUIET_MS;
	}

	/** True when the player pressed the button, so the caller can report the result in chat. */
	boolean isManual()
	{
		return manual;
	}

	/** Everything received, as an unmodifiable snapshot. Does not clear — see {@link #onSent}. */
	Map<Integer, Integer> snapshot()
	{
		return Collections.unmodifiableMap(new LinkedHashMap<>(items));
	}

	int size()
	{
		return items.size();
	}

	/**
	 * A cheap fingerprint of what was received, so an unchanged log isn't pushed twice.
	 *
	 * <p>The transmit re-sends everything every time the log is opened, and most opens change
	 * nothing. Order-independent (the game's transmit order is not ours to rely on) and includes
	 * quantities, so a second of the same item still counts as a change.
	 */
	synchronized long fingerprint()
	{
		long hash = items.size();
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			// Mixed per entry then XORed in: adding an item changes it, and reordering doesn't.
			long h = e.getKey() * 0x9E3779B97F4A7C15L + e.getValue();
			hash ^= h ^ (h >>> 29);
		}
		return hash;
	}

	/** The push landed: drop the batch and stand down until the next transmit. */
	void onSent()
	{
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}

	/**
	 * The push failed. Keeps the items so the next tick can retry, but stops the clock restarting —
	 * a site that is down must not cost the player their transmit.
	 */
	void onSendFailed(long now)
	{
		lastItemAt = now;
	}

	/** Account switch / logout: a half-received log belongs to nobody. */
	void reset()
	{
		items.clear();
		receiving = false;
		manual = false;
		lastItemAt = 0;
	}
}

package com.anvil;

import net.runelite.api.gameval.VarbitID;

/**
 * The six Combat Achievement tiers, with the point value awarded for a task at that tier and the
 * varbit holding the cumulative points needed to unlock the tier's rewards. Used to detect both
 * individual task completions (chat message gives the tier name) and tier unlocks (a task pushing
 * total points across a threshold).
 */
public enum CombatAchievementTier
{
	EASY("Easy", 1, VarbitID.CA_THRESHOLD_EASY),
	MEDIUM("Medium", 2, VarbitID.CA_THRESHOLD_MEDIUM),
	HARD("Hard", 3, VarbitID.CA_THRESHOLD_HARD),
	ELITE("Elite", 4, VarbitID.CA_THRESHOLD_ELITE),
	MASTER("Master", 5, VarbitID.CA_THRESHOLD_MASTER),
	GRANDMASTER("Grandmaster", 6, VarbitID.CA_THRESHOLD_GRANDMASTER);

	private final String displayName;
	private final int points;
	private final int thresholdVarbitId;

	CombatAchievementTier(String displayName, int points, int thresholdVarbitId)
	{
		this.displayName = displayName;
		this.points = points;
		this.thresholdVarbitId = thresholdVarbitId;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getPoints()
	{
		return points;
	}

	public int getThresholdVarbitId()
	{
		return thresholdVarbitId;
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	/** Resolves the tier from the word used in the completion message ("easy", "elite", …). */
	public static CombatAchievementTier byName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (CombatAchievementTier t : values())
		{
			if (t.displayName.equalsIgnoreCase(name) || t.name().equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}
}

