	private static <T> List<T> copyOrEmpty(List<T> src)
	{
		return src == null ? Collections.emptyList() : Collections.unmodifiableList(new ArrayList<>(src));
	}

	public boolean hasError()
	{
		return error != null && !error.isEmpty();
	}

	/** Board completion as 0..100, or 0 when the board has no tiles. Points-weighted for Leagues. */
	public int completionPercent()
	{
		return tilesTotal > 0 ? Math.min(100, (int) Math.round(tilesComplete * 100.0 / tilesTotal)) : 0;
	}

	/** The noun for {@link #tilesComplete}/{@link #tilesTotal}: "pts" for a points board, else "tiles". */
	public String unitNoun()
	{
		return pointsScored ? "pts" : "tiles";
	}

	/**
	 * One tile's progress ("nearest tiles" rows) — mirrors the {@code current}/{@code goal} pair used elsewhere
	 * ({@link ClogTaskModel.TaskRow}), so the future {@code /board} binding is a straight copy.
	 */
	public static final class TileProgressView
	{
		public final String name;
		public final int current;
		public final int target;
		public final boolean complete;

		public TileProgressView(String name, int current, int target, boolean complete)
		{
			this.name = name == null ? "" : name;
			this.current = Math.max(0, current);
			this.target = Math.max(0, target);
			// A team-level completion is authoritative even if current < target (a teammate finished it).
			this.complete = complete || (target > 0 && this.current >= target);
		}

		/** Progress as 0..100. An untargeted tile (target ≤ 0) is 100 when complete, else 0. */
		public int percent()
		{
			if (target > 0)
			{
				return Math.min(100, (int) Math.round(current * 100.0 / target));
			}
			return complete ? 100 : 0;
		}
	}

	/**
	 * One tile someone's actively working ("Active now") — the tile's progress ({@link ClogTaskModel.TaskRow})
	 * plus who's on it ({@code "You"} for the local player, teammates by RSN, deduped).
	 */
	public static final class ActiveTask
	{
		public final ClogTaskModel.TaskRow tile;
		/** Distinct workers, "You" first when the local player is among them. Never null/empty. */
		public final List<String> workers;
		public final boolean includesSelf;

		public ActiveTask(ClogTaskModel.TaskRow tile, List<String> workers, boolean includesSelf)
		{
			this.tile = tile;
			this.workers = copyOrEmpty(workers);
			this.includesSelf = includesSelf;
		}

		/** "You", "Kayle", or "You + Kayle" / "You + 2 others" for the row's byline. */
		public String workersLabel()
		{
			if (workers.isEmpty())
			{
				return "";
			}
			if (workers.size() == 1)
			{
				return workers.get(0);
			}
			if (workers.size() == 2)
			{
				return workers.get(0) + " + " + workers.get(1);
			}
			return workers.get(0) + " + " + (workers.size() - 1) + " others";
		}
	}

	/**
	 * One live weekly competition (Skill / Boss of the Week) as the sidebar shows it: the comp itself,
	 * the caller's standing, and the head of the leaderboard. Every display string is derived here so
	 * the panel just renders — and so the shaping is unit-testable without Swing.
	 */
	public static final class WeeklyView
	{
		public final int id;
		public final String title;
		/** {@code "skill"} | {@code "boss"} — picks the kind label and the gain's unit. */
		public final String type;
		/** Raw metric key as the site stores it ({@code "mining"}, {@code "chambers_of_xeric"}). */
		public final String metric;
		/** What the site calls that metric, when it sends one. Read through {@link #metricLabel()}. */
		private final String sentLabel;
		public final String startDate;
		public final String endDate;
		/** True for a comp that hasn't started yet — it has no standings, just a start time. */
		public final boolean upcoming;
		/** Caller's rank, or 0 when they aren't on the board (not enrolled / no gain yet / unknown). */
		public final int yourRank;
		public final long yourGained;
		/** Ranked participants, or 0 when the standings couldn't be read. */
		public final int participants;
		/** Head of the leaderboard, rank order, capped by the source. Never {@code null}. */
		public final List<Standing> top;
		/** The comp's page on the Anvil site ({@code <baseUrl>/weekly/<id>}), or {@code null} when unknown. */
		public final String url;

		public WeeklyView(int id, String title, String type, String metric, String startDate, String endDate,
			int yourRank, long yourGained, int participants, List<Standing> top, String url)
		{
			this(id, title, type, metric, startDate, endDate, false, yourRank, yourGained, participants, top, url);
		}

		public WeeklyView(int id, String title, String type, String metric, String startDate, String endDate,
			boolean upcoming, int yourRank, long yourGained, int participants, List<Standing> top, String url)
		{
			this(id, title, type, metric, null, startDate, endDate, upcoming, yourRank, yourGained,
				participants, top, url);
		}

		public WeeklyView(int id, String title, String type, String metric, String sentLabel, String startDate,
			String endDate, boolean upcoming, int yourRank, long yourGained, int participants,
			List<Standing> top, String url)
		{
			this.sentLabel = sentLabel;
			this.id = id;
			this.title = title == null || title.isEmpty() ? kindLabel(type) : title;
			this.type = type == null ? "" : type;
			this.metric = metric == null ? "" : metric;
			this.startDate = startDate;
			this.endDate = endDate;
			this.upcoming = upcoming;
			this.yourRank = Math.max(0, yourRank);
			this.yourGained = Math.max(0, yourGained);
			this.participants = Math.max(0, participants);
			this.top = copyOrEmpty(top);
			this.url = url;
		}

		/** True for an EHP/EHB comp — ranked by efficient hours, not one skill's XP or one boss's KC. */
		public boolean isEfficiency()
		{
			return "efficiency".equalsIgnoreCase(type);
		}

		/**
		 * "Skill of the Week" / "Boss of the Week" / "Efficiency of the Week" — the card's kind line and
		 * the list row's subtitle. Public so the callers that hold only a raw type string (the sidebar's
		 * leaderboard + schedule, the login greeting) name a comp the same way this card does.
		 */
		public String kindLabel()
		{
			return kindLabel(type);
		}

		public static String kindLabel(String type)
		{
			if ("skill".equalsIgnoreCase(type))
			{
				return "Skill of the Week";
			}
			// Efficiency comps are a THIRD type, not a fallback: matching only "skill" and letting
			// everything else read as boss labelled every EHP/EHB week "Boss of the Week".
			return "efficiency".equalsIgnoreCase(type) ? "Efficiency of the Week" : "Boss of the Week";
		}

		/** The tracked metric, spelled for a person: {@code "phosanisNightmare"} → "Phosani's Nightmare". */
		public String metricLabel()
		{
			return metricLabel(type, metric, sentLabel);
		}

		/**
		 * The site's own name for the metric, falling back to what the key can be made to look like.
		 *
		 * <p>Prefer what was sent, always. Boss keys are hiscores keys, and no amount of splitting
		 * "phosanisNightmare" recovers the apostrophe in "Phosani's Nightmare" or turns
		 * "chambersOfXericChallengeMode" into the clan's "CoX: CM". The fallback exists for sites
		 * older than the field, not as an equal option.
		 */
		public static String metricLabel(String type, String metric, String sentLabel)
		{
			if (sentLabel != null && !sentLabel.trim().isEmpty())
			{
				return sentLabel.trim();
			}
			return metricLabel(type, metric);
		}

		public static String metricLabel(String type, String metric)
		{
			// "ehp"/"ehb" are initialisms — humanise would title-case them to "Ehp".
			return "efficiency".equalsIgnoreCase(type)
				? (metric == null ? "" : metric.toUpperCase(java.util.Locale.ROOT))
				: humanise(metric);
		}

		/** What a gain counts in: XP for a skill comp, kills for a boss one, hours for EHP/EHB. */
		public String unitNoun()
		{
			return unitNoun(type);
		}

		public static String unitNoun(String type)
		{
			if ("efficiency".equalsIgnoreCase(type))
			{
				return "hrs";
			}
			return "skill".equalsIgnoreCase(type) ? "xp" : "kc";
		}

		/** A gain as the UI shows it — "1.2M xp", "184 kc", "12.40 hrs". */
		public String formatGain(long gained)
		{
			return formatGain(type, gained);
		}

		public static String formatGain(String type, long gained)
		{
			long safe = Math.max(0, gained);
			return formatGainValue(type, safe) + " " + unitNoun(type);
		}

		/** The number alone, for callers that place the unit themselves. */
		public static String formatGainValue(String type, long gained)
		{
			long safe = Math.max(0, gained);
			// Efficiency comps travel in MILLI-hours (the site's EFFICIENCY_SCALE): the weekly's
			// integer columns would round 12.4 EHB down to 12 and throw away most of a week's gain.
			// Rendered raw that arrives as "+12,400 kc".
			return "efficiency".equalsIgnoreCase(type)
				? String.format(java.util.Locale.ROOT, "%.2f", safe / EFFICIENCY_SCALE)
				: formatCount(safe);
		}

		/** Underscored/hyphenated metric keys → title case, keeping the small joining words lowercase. */
		static String humanise(String key)
		{
			if (key == null || key.isEmpty())
			{
				return "";
			}
			// Boss keys arrive camel-cased ("phosanisNightmare"), so a split on separators alone left
			// them as one word and title-case made it "PhosanisNightmare" — which is what the in-game
			// banner printed. A word boundary is also lower→upper (and letter→digit, for "theatreOfBlood2").
			String spaced = key.replace('_', ' ').replace('-', ' ')
				.replaceAll("(?<=[a-z0-9])(?=[A-Z])", " ")
				.replaceAll("(?<=[A-Za-z])(?=[0-9])", " ");
			String[] words = spaced.trim().split("\\s+");
			StringBuilder out = new StringBuilder();
			for (int i = 0; i < words.length; i++)
			{
				String w = words[i];
				if (w.isEmpty())
				{
					continue;
				}
				if (out.length() > 0)
				{
					out.append(' ');
				}
				// Case-insensitively, because the camel split hands these over capitalised ("Of").
				boolean small = i > 0 && ("of".equalsIgnoreCase(w) || "the".equalsIgnoreCase(w)
					|| "and".equalsIgnoreCase(w) || "at".equalsIgnoreCase(w));
				out.append(small ? w.toLowerCase(java.util.Locale.ROOT)
					: Character.toUpperCase(w.charAt(0)) + w.substring(1));
			}
			return out.toString();
		}
	}

	/**
	 * A bingo event on the clan's schedule that ISN'T the caller's own board — one starting soon, or a
	 * live one they aren't enrolled in. Read-only: there's no progress to show, so the card is the
	 * pitch (what, when, how big) plus a link to sign up on the site.
	 */
	public static final class ScheduledView
	{
		public final int id;
		public final String title;
		public final String startDate;
		public final String endDate;
		/** True when it's already running (the caller just isn't in it); false = still upcoming. */
		public final boolean live;
		/** Tiles configured, or 0 when the site didn't say. */
		public final int tileCount;
		/**
		 * The site's `boardSize`, whose MEANING depends on the format: N for a classic N×N grid, the
		 * tile COUNT for every list format (Leagues, tile race, ladder). See {@link #squareGrid()}.
		 */
		public final int boardSize;
		public final String format;
		public final String scoringMode;
		/** The event's page on the Anvil site, or {@code null} when the base URL is unknown. */
		public final String url;

		public ScheduledView(int id, String title, String startDate, String endDate, boolean live,
			int tileCount, int boardSize, String format, String scoringMode, String url)
		{
			this.id = id;
			this.title = title == null || title.isEmpty() ? "Bingo" : title;
			this.startDate = startDate;
			this.endDate = endDate;
			this.live = live;
			this.tileCount = Math.max(0, tileCount);
			this.boardSize = Math.max(0, boardSize);
			this.format = format;
			this.scoringMode = scoringMode;
			this.url = url;
		}

		/** "Bingo" / "Bingo (points)" / "Tile race" / "Ladder" — same wording as the in-game schedule. */
		public String kindLabel()
		{
			if (LadderMissions.isLadder(format))
			{
				return "Ladder";
			}
			if ("tilerace".equalsIgnoreCase(format))
			{
				return "Tile race";
			}
			return "points".equalsIgnoreCase(scoringMode) ? "Bingo (points)" : "Bingo";
		}

		/**
		 * Whether {@code boardSize} is a grid SIDE or a tile COUNT.
		 *
		 * <p>Only a classic bingo is square. Every other format — Leagues and its reveal-policy
		 * variants, tile race, ladder — is a task LIST whose boardSize is simply how many tiles it
		 * has, so treating it as a side length turns a 240-task Leagues board into a "240×240"
		 * claim about 57,600 tiles.
		 */
		private boolean squareGrid()
		{
			if (format != null && !format.isEmpty())
			{
				return "bingo".equalsIgnoreCase(format) && !"points".equalsIgnoreCase(scoringMode);
			}
			// A site too old to tell us. Believe the geometry instead: a square board's tile count is
			// its side squared, and anything that doesn't add up is a list.
			return tileCount > 0 && boardSize > 0 && boardSize * boardSize == tileCount;
		}

		/** "5×5 · 25 tiles" for a grid, "240 tiles" for a list, or "" when the site said nothing. */
		public String sizeLabel()
		{
			if (squareGrid())
			{
				// Deliberately NOT derived from boardSize² — a board that is still being authored has
				// fewer tiles than its grid has cells, and the honest thing is to say so.
				String tiles = tileCount > 0 ? tileCount + (tileCount == 1 ? " tile" : " tiles") : "";
				if (boardSize <= 0)
				{
					return tiles;
				}
				return tiles.isEmpty() ? boardSize + "×" + boardSize : boardSize + "×" + boardSize + " · " + tiles;
			}
			// A list: boardSize IS the tile count, so it stands in when the authored count is absent.
			int count = tileCount > 0 ? tileCount : boardSize;
			return count > 0 ? count + (count == 1 ? " tile" : " tiles") : "";
		}
	}

	/** One row of a weekly leaderboard, with the caller's own row flagged. */
	public static final class Standing
	{
		public final int rank;
		public final String rsn;
		public final long gained;
		public final boolean self;

		public Standing(int rank, String rsn, long gained, boolean self)
		{
			this.rank = Math.max(0, rank);
			this.rsn = rsn == null ? "" : rsn;
			this.gained = Math.max(0, gained);
			this.self = self;
		}
	}

	/**
	 * The ladder missions-board view-model for the sidebar card: the countdown target, the caller's
	 * rank (this month + all-time), and the currently-open missions. Display strings (live value,
	 * m:ss countdown) are computed at tick time from these raw values via {@link LadderMissions}.
	 */
	public static final class Ladder
	{
		/** ISO time of the next reveal — the per-second countdown target. Null when none is scheduled. */
		public final String nextRevealAtIso;
		public final int monthRank;      // caller's rank this month; 0 when unranked
		public final long monthPoints;   // caller's points this month
		public final int allTimeRank;    // caller's all-time rank; 0 when unranked
		/** The points ramp (may be null) — lets each mission show a live grow/decay value. */
		public final PluginConfigResponse.Decay decay;
		/** Currently-open missions (revealed, not yet claimed/expired), board order. Never null. */
		public final List<Mission> missions;
		/**
		 * True for a real ladder event, false for an ordinary bingo that merely carries missions.
		 *
		 * Both surface a mission strip — a bingo can drop hidden missions mid-event too, and those
		 * deserve the same countdown and live values rather than being left to show up as "New tile
		 * revealed" lines in the activity feed. Only a ladder REPLACES the board summary with this
		 * card and carries a personal rank; a bingo keeps its board summary and gets the strip
		 * underneath.
		 */
		public final boolean ladderFormat;

		public Ladder(String nextRevealAtIso, int monthRank, long monthPoints, int allTimeRank,
			PluginConfigResponse.Decay decay, List<Mission> missions, boolean ladderFormat)
		{
			this.nextRevealAtIso = nextRevealAtIso;
			this.monthRank = Math.max(0, monthRank);
			this.monthPoints = Math.max(0, monthPoints);
			this.allTimeRank = Math.max(0, allTimeRank);
			this.decay = decay;
			this.missions = copyOrEmpty(missions);
			this.ladderFormat = ladderFormat;
		}

		/** One open mission: its label, face value, and reveal time (for the live grow/decay value). */
		public static final class Mission
		{
			public final int tileId;
			public final String label;
			public final int face;
			public final String revealedAtIso;

			public Mission(int tileId, String label, int face, String revealedAtIso)
			{
				this.tileId = tileId;
				this.label = label == null ? "" : label;
				this.face = Math.max(0, face);
				this.revealedAtIso = revealedAtIso;
			}
		}
	}
}

package com.anvil;

import java.time.LocalDateTime;
import java.time.ZoneOffset;

/**
 * Pure, RuneLite-free helpers for the in-game "missions board" of a ladder / rotating event: the live
 * grow-or-decay value of a mission, the per-second countdown to the next reveal, and their display
 * strings. Kept side-effect-free so the Swing sidebar renders
 * one implementation and it's unit-testable. No threads, no I/O — just clock math.
 */
final class LadderMissions
{
	private LadderMissions()
	{
	}

	/** True for the ladder format (individual-primary random-task leaderboard). Null/other → false. */
	static boolean isLadder(String format)
	{
		return "ladder".equalsIgnoreCase(format);
	}

	/**
	 * A mission's live value = face scaled by the decay ramp: {@code face * (1 - (1 - target) * frac)},
	 * where {@code target = targetPct/100} and {@code frac} is the elapsed fraction of the ramp window
	 * (0 at reveal → 1 after {@code hours}). {@code targetPct < 100} decays, {@code > 100} grows. Returns
	 * the plain face when there's no decay rule or the reveal time is unknown/unparseable.
	 */
	static long liveValue(long face, String revealedAtIso, PluginConfigResponse.Decay decay, long nowMs)
	{
		if (decay == null || decay.hours <= 0)
		{
			return face;
		}
		long revealedAt = parseUtcMillis(revealedAtIso);
		if (revealedAt < 0)
		{
			return face;
		}
		double target = decay.targetPct / 100.0;
		double frac = Math.min(1.0, Math.max(0.0, (nowMs - revealedAt) / (decay.hours * 3_600_000.0)));
		double value = face * (1.0 - (1.0 - target) * frac);
		return Math.round(Math.max(0.0, value));
	}

	/** True when the live value differs enough from face to be worth showing the "face → current" form. */
	static boolean valueMoved(long face, long current)
	{
		return current != face;
	}

	/**
	 * "120 -> 90" (decay) / "120 -> 200" (grow) when the value has moved, else just "120". ASCII arrow:
	 * the OSRS chat + collection-log widget fonts don't carry Unicode arrows/emoji.
	 */
	static String valueLabel(long face, long current)
	{
		if (current == face)
		{
			return Long.toString(face);
		}
		return face + " -> " + current;
	}

	/**
	 * Per-second countdown to the next reveal: {@code "12:34"} (m:ss), {@code "1:02:03"} (h:mm:ss for
	 * long waits), {@code "now"} once due, or {@code null} when there's no scheduled reveal (e.g. a
	 * bounty board draws on claim, not a clock).
	 */
	static String countdown(String nextRevealAtIso, long nowMs)
	{
		if (nextRevealAtIso == null || nextRevealAtIso.isEmpty())
		{
			return null;
		}
		long at = parseUtcMillis(nextRevealAtIso);
		if (at < 0)
		{
			return null;
		}
		long secs = Math.max(0, (at - nowMs) / 1000);
		if (secs == 0)
		{
			return "now";
		}
		long h = secs / 3600;
		long m = (secs % 3600) / 60;
		long s = secs % 60;
		if (h > 0)
		{
			return h + ":" + two(m) + ":" + two(s);
		}
		return m + ":" + two(s);
	}

	private static String two(long v)
	{
		return v < 10 ? "0" + v : Long.toString(v);
	}

	/**
	 * Parse the server's UTC timestamp — either ISO ({@code 2026-07-29T12:00:00.000Z}) or the
	 * space-separated {@code yyyy-MM-dd HH:mm:ss} SQLite form — to epoch millis, or -1 if unparseable.
	 */
	static long parseUtcMillis(String ts)
	{
		if (ts == null || ts.isEmpty())
		{
			return -1;
		}
		String s = ts.trim().replace(' ', 'T');
		if (s.endsWith("Z"))
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			return LocalDateTime.parse(s).toInstant(ZoneOffset.UTC).toEpochMilli();
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}
}

package com.anvil;

/**
 * The client-side half of the STARTING SHOT rule (site lib/startProof).
 *
 * <p>Two things the site can ask for beyond the screenshot itself, both of which only this client can
 * answer, and both of which are far more useful checked BEFORE the frame is grabbed than filed and
 * argued about afterwards:
 *
 * <ul>
 *   <li><b>Where you are.</b> A drawn spot the host pinned on the map comes down as coordinates, so
 *       "go to Edgeville bank" stops being an instruction nobody can verify.</li>
 *   <li><b>How old this session is.</b> Hiscores only flush on LOGOUT, so a player who has been
 *       logged in since before the event started has a stale start baseline — every gain they made
 *       beforehand lands in the event's first sweep. Making them log out and back in right before
 *       the shot is what actually stops that, and the screenshot is just the receipt.</li>
 * </ul>
 *
 * <p>Pure and static so it unit-tests without a client: the plugin supplies the numbers.
 */
final class StartProofRules
{
	/** {@code sessionLoginAtMs} when we never saw the login — a plugin enabled mid-session. */
	static final long UNKNOWN_LOGIN = 0L;

	private StartProofRules()
	{
	}

	/**
	 * Squares from the drawn spot, the way OSRS measures "within N squares" — the longer axis, not
	 * the diagonal. -1 when there is nothing to measure (no pin, or no position to compare).
	 */
	static int distance(PluginConfigResponse.StartProof proof, Integer x, Integer y)
	{
		if (proof == null || proof.spot == null || x == null || y == null)
		{
			return -1;
		}
		return Math.max(Math.abs(x - proof.spot.x), Math.abs(y - proof.spot.y));
	}

	/**
	 * Why this shot can't be filed yet, as a sentence for chat — or null when it can.
	 *
	 * <p>Every check fails OPEN: an older site sends no spot and no window, an unpinned location has
	 * no coordinates, and a client that can't read its own position skips the distance test. The
	 * rule only ever blocks on something we positively know is wrong.
	 */
	static String blockReason(
		PluginConfigResponse.StartProof proof,
		long sessionLoginAtMs,
		long nowMs,
		Integer x,
		Integer y)
	{
		if (proof == null)
		{
			return null;
		}

		if (proof.maxSessionMinutes > 0)
		{
			if (sessionLoginAtMs == UNKNOWN_LOGIN)
			{
				// The plugin was switched on (or the client reconnected) mid-session, so we can't
				// vouch for the logout that flushed the hiscores. One relog settles it.
				return "Log out and back in before your starting shot — that's what saves your hiscores"
					+ " so your starting totals are right.";
			}
			long minutes = Math.max(0, (nowMs - sessionLoginAtMs) / 60_000L);
			if (minutes > proof.maxSessionMinutes)
			{
				return "You've been logged in for " + describeMinutes(minutes) + " — log out and back in,"
					+ " then take your starting shot within " + proof.maxSessionMinutes + " min."
					+ " Hiscores only save on logout, so this is what sets your starting totals.";
			}
		}

		int away = distance(proof, x, y);
		if (away >= 0 && away > proof.spot.radius)
		{
			return "You're " + away + " squares from " + (proof.location != null ? proof.location : "the start spot")
				+ " — go there, then take your starting shot.";
		}

		return null;
	}

	/**
	 * How long is left before the site stops asking for a shot, as a sentence fragment — or null
	 * when there is no deadline to quote (an older site that doesn't send one, or an unreadable
	 * stamp). The window closing is not a failure state: the ask simply expires, so this reads as a
	 * countdown rather than a threat.
	 */
	static String describeWindow(PluginConfigResponse.StartProof proof, long nowMs)
	{
		if (proof == null || proof.windowEndsAt == null || proof.windowEndsAt.isEmpty())
		{
			return null;
		}
		long endsMs;
		try
		{
			endsMs = java.time.Instant.parse(proof.windowEndsAt).toEpochMilli();
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
		long minutes = (endsMs - nowMs) / 60_000L;
		return minutes <= 0 ? null : describeMinutes(minutes);
	}

	/** "12 min" / "2h 05m" — a session age a player reads at a glance. */
	static String describeMinutes(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + " min";
		}
		return (minutes / 60) + "h " + String.format("%02dm", minutes % 60);
	}
}

package com.anvil;

import java.util.Locale;

/**
 * One way to fold an OSRS name into a comparison key — the SAME way the site does it.
 *
 * <p>Every use of this is the same shape: take a name the client read out of the game, take a name
 * the server sent, and decide whether they are the same account. That only works if both sides fold
 * identically. There were three of these in the plugin, agreeing with each other about half the
 * time and with the server never.</p>
 *
 * <p><b>The rule</b> is the server's ({@code Anvil.Site src/lib/auth.ts normalizeRsn}):
 * lower-case, and collapse every run of whitespace <em>or underscore</em> to one space.</p>
 *
 * <p><b>Underscores are the part that was missing.</b> OSRS treats space and underscore as the same
 * character in a name: the game renders "GIM Nisbro", while logins, hiscores lookups and
 * hand-entered roster rows carry "GIM_nisbro". The server folds them together deliberately —
 * without it a roster sync reports one member left and another joined for the same person. The
 * plugin did not, so any name holding an underscore on the site failed to match the account playing
 * it: no bounty credit, no drop attribution, no "that's you" in a standings list.</p>
 *
 * <p><b>Two places where Java quietly disagrees with JavaScript</b>, both of which this has to bridge
 * because the server is the JavaScript one:</p>
 * <ul>
 *   <li>{@code String.trim()} in Java strips only characters up to U+0020, so it leaves a
 *       non-breaking space where JS strips it. OSRS names are full of U+00A0 — that is how the game
 *       encodes their spaces so a name never wraps a line. Folded to a plain space first.</li>
 *   <li>Java's {@code \\s} does not match U+00A0 either; JS's does. Spelled out in the class.</li>
 * </ul>
 *
 * <p>{@link Locale#ROOT} rather than the default locale, and that is not pedantry: a Turkish client
 * lower-cases 'I' to 'ı', so "IRON MIKE" would fold to something the server has never seen and that
 * player would silently stop matching their own roster row.</p>
 */
public final class Rsn
{
	private Rsn()
	{
	}

	/** Whitespace-or-underscore runs. U+00A0 is named explicitly — Java's {@code \s} omits it. */
	private static final java.util.regex.Pattern FOLD =
		java.util.regex.Pattern.compile("[\\s\\u00a0_]+");

	/**
	 * The comparison key for a name, or "" when there is no name.
	 *
	 * <p>Never null, because every caller compares the result and a null check at each of them is a
	 * check somebody eventually forgets. An empty key never matches a real one — callers guard on
	 * {@code !me.isEmpty()} before comparing, so an unknown local name matches nobody rather than
	 * everybody.</p>
	 */
	public static String normalize(String rsn)
	{
		if (rsn == null)
		{
			return "";
		}
		// U+00A0 → space BEFORE trimming, so a name padded with them trims like it does on the server.
		String plain = rsn.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
		return FOLD.matcher(plain).replaceAll(" ").trim();
	}

	/** Do these two names denote the same account? Empty never matches, including empty itself. */
	public static boolean same(String a, String b)
	{
		String left = normalize(a);
		return !left.isEmpty() && left.equals(normalize(b));
	}
}

package com.anvil;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.io.IOException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Plays a clip when the bingo banner fires, and another when a mission drops. No clips ship with the
 * plugin — users supply their own WAV/PCM files (the only format stock Java decodes) through
 * {@link #importSounds}, which copies them into {@code sounds/banner/} or {@code sounds/mission/}.
 * The folder is what makes a clip a banner clip or a mission clip; there is no setting to keep in
 * step with it, and a mission folder left empty simply keeps the built-in chime. The old {@code .runelite/anvil-bingo-sounds}
 * folder is not readable from here and is not the one legacy directory the migration could carry, so
 * anyone who used it re-imports. Nothing plays until a file is added. Playback goes through RuneLite's {@link AudioPlayer} (plugin-hub policy requires
 * this over the raw Java Sound API).
 */
@Slf4j
@Singleton
public class BannerSoundService
{
	/**
	 * The plugin's own `sounds/` folder, handed over by AnvilPlugin at startUp.
	 *
	 * NOT MIGRATED, and deliberately so: the client moves exactly one legacy folder and that slot is
	 * spent on the pending queue, which holds screenshots of drops that cannot be taken again. A .wav
	 * is still wherever the user got it, and Add sounds re-imports it through the same picker they
	 * used the first time.
	 */
	private volatile Filepath root;

	private final AnvilConfig config;
	private final AudioPlayer audioPlayer;
	private final ExecutorService audioExecutor = Executors.newSingleThreadExecutor(r ->
	{
		Thread t = new Thread(r, "anvil-banner-sound");
		t.setDaemon(true);
		return t;
	});

	@Inject
	public BannerSoundService(AnvilConfig config, AudioPlayer audioPlayer)
	{
		this.config = config;
		this.audioPlayer = audioPlayer;
	}

	public void setRoot(Filepath dir)
	{
		this.root = dir;
		migrateLooseClips();
	}

	/**
	 * WHICH CLIP IS THIS? Answered by the folder it is in, not by a setting.
	 *
	 * <p>A mission dropping is the opposite kind of news from a tile being finished, so the two
	 * should not sound alike — but "different how?" used to be a toggle choosing between the banner
	 * clip and a built-in chime, with no way to supply a mission clip at all. A folder each answers
	 * it without asking anything: drop a .wav in {@code mission/} and missions play it, leave it
	 * empty and they keep the built-in chime.</p>
	 */
	public enum Kind
	{
		BANNER("banner"),
		MISSION("mission");

		private final String folder;

		Kind(String folder)
		{
			this.folder = folder;
		}
	}

	/** One kind's directory, created on demand, or null when there is nowhere to read or write. */
	private Filepath dir(Kind kind)
	{
		Filepath d = root;
		if (d == null)
		{
			return null;
		}
		try
		{
			Filepath sub = d.joinSegment(kind.folder);
			if (!sub.exists())
			{
				sub.createDirectories();
			}
			return sub;
		}
		catch (IOException e)
		{
			log.warn("Anvil: cannot create the {} sounds directory: {}", kind.folder, e.getMessage());
			return null;
		}
	}

	/**
	 * Clips added before the folders existed sat loose in {@code sounds/}, where nothing looks any
	 * more. They are banner clips — that is all there was — so they are moved once, quietly. Doing it
	 * here rather than asking means nobody's sounds stop working because the layout changed under
	 * them.
	 */
	private void migrateLooseClips()
	{
		Filepath d = root;
		if (d == null || !d.isDirectory())
		{
			return;
		}
		try (Stream<Filepath> walk = d.walk(1))
		{
			List<Filepath> loose = walk
				.filter(f -> f.isFile() && f.getFileName().toLowerCase().endsWith(".wav"))
				.collect(Collectors.toList());
			if (loose.isEmpty())
			{
				return;
			}
			Filepath banner = dir(Kind.BANNER);
			if (banner == null)
			{
				return;
			}
			for (Filepath f : loose)
			{
				try
				{
					f.moveTo(banner.joinSegment(f.getFileName()), StandardCopyOption.REPLACE_EXISTING);
				}
				catch (Exception e)
				{
					log.debug("Could not move {} into banner/: {}", f.getFileName(), e.getMessage());
				}
			}
			log.debug("Anvil: moved {} clip(s) into banner/", loose.size());
		}
		catch (IOException e)
		{
			log.debug("Could not migrate loose clips: {}", e.getMessage());
		}
	}

	/** Every .wav in one kind's folder. Depth 1 — a clip is a file in it, never deeper. */
	private List<Filepath> wavFiles(Kind kind)
	{
		Filepath dir = dir(kind);
		if (dir == null)
		{
			return new ArrayList<>();
		}
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk
				.filter(f -> f.isFile() && f.getFileName().toLowerCase().endsWith(".wav"))
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			log.debug("Could not list {} sounds: {}", kind.folder, e.getMessage());
			return new ArrayList<>();
		}
	}

	/** True if this kind has at least one .wav (i.e. it could play something of its own). */
	public boolean hasClips(Kind kind)
	{
		return !wavFiles(kind).isEmpty();
	}

	/** All .wav filenames for one kind, case-insensitively sorted (for the in-tab manager). */
	public List<String> listClips(Kind kind)
	{
		List<String> out = new ArrayList<>();
		for (Filepath f : wavFiles(kind))
		{
			out.add(f.getFileName());
		}
		out.sort(String.CASE_INSENSITIVE_ORDER);
		return out;
	}

	/**
	 * A clip filename as something to read: "odablock-we-won.wav" becomes "Odablock we won".
	 *
	 * <p>Clips arrive as downloaded files, so their names are slugs. Printed verbatim they made both
	 * the in-game list and the side panel look like a directory listing that had leaked into the
	 * interface. Lives here rather than in either panel because both of them show the same files.
	 */
	public static String displayName(String file)
	{
		String s = file == null ? "" : file.trim();
		int dot = s.lastIndexOf('.');
		if (dot > 0)
		{
			s = s.substring(0, dot);
		}
		s = s.replace('_', ' ').replace('-', ' ').replaceAll("\\s+", " ").trim();
		if (s.isEmpty())
		{
			return file == null ? "" : file;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/**
	 * True if {@code name} is in the play cycle. The cycle is the comma-separated allowlist in
	 * {@link AnvilConfig#bannerSoundClip()}; an empty allowlist means "every clip plays".
	 */
	public boolean isSelected(String name)
	{
		Set<String> sel = parseSelected(config.bannerSoundClip());
		return sel.isEmpty() || sel.contains(name.toLowerCase());
	}

	/** Parse the comma-separated clip allowlist into lowercased ".wav" filenames. Empty = play all. */
	static Set<String> parseSelected(String csv)
	{
		Set<String> out = new LinkedHashSet<>();
		if (csv == null)
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			String s = part.trim().toLowerCase();
			if (s.isEmpty())
			{
				continue;
			}
			if (!s.endsWith(".wav"))
			{
				s += ".wav";
			}
			out.add(s);
		}
		return out;
	}

	public void play(Kind kind)
	{
		if (!config.bannerSound())
		{
			return;
		}
		audioExecutor.submit(() -> playBlocking(kind));
	}

	private void playBlocking(Kind kind)
	{
		try
		{
			List<Filepath> files = wavFiles(kind);
			if (files.isEmpty())
			{
				return;
			}

			// The cycle is the allowlist (comma-separated filenames); empty = every clip is eligible.
			// Each banner plays one at random from the eligible set, so a multi-clip cycle varies.
			// Mission clips have no allowlist: the folder is already the choice of what plays.
			Set<String> selected = kind == Kind.BANNER ? parseSelected(config.bannerSoundClip()) : Collections.emptySet();
			List<Filepath> candidates = new ArrayList<>();
			for (Filepath f : files)
			{
				if (selected.isEmpty() || selected.contains(f.getFileName().toLowerCase()))
				{
					candidates.add(f);
				}
			}
			if (candidates.isEmpty())
			{
				return;
			}

			playFile(candidates.get(ThreadLocalRandom.current().nextInt(candidates.size())));
		}
		catch (Exception e)
		{
			log.debug("Banner sound skipped: {}", e.getMessage());
		}
	}

	private void playFile(Filepath file) throws Exception
	{
		// AudioPlayer takes a Filepath directly as of 1.12.39, so the clip never leaves the sandbox.
		audioPlayer.play(file, gainDb());
	}

	/**
	 * Convert the 0–100 volume config to a MASTER_GAIN decibel value AudioPlayer applies. 100 → 0 dB
	 * (unattenuated); lower volumes attenuate logarithmically; 0 → effectively silent. AudioPlayer
	 * clamps to the line's supported range.
	 */
	private float gainDb()
	{
		int vol = Math.max(0, Math.min(100, config.bannerSoundVolume()));
		return vol <= 0 ? -80f : (float) (20.0 * Math.log10(vol / 100.0));
	}

	/**
	 * Opens a file picker and copies the chosen WAV(s) into the user sounds folder. {@code onImported}
	 * (may be null) is invoked with the successfully-copied filenames so the caller can confirm in chat;
	 * it's skipped when the user cancels or nothing copied.
	 */
	public void importSounds(Kind kind, Consumer<List<String>> onImported)
	{
		SwingUtilities.invokeLater(() ->
		{
			// Filepath.Chooser rather than a bare JFileChooser: the user picking a file is how a
			// plugin is granted anything outside its own directory, and it is the same dialog they
			// were already looking at. Nothing else about this flow changes — the clips are copied
			// in, and playback still only ever reads our own folder.
			List<Filepath> chosen = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsFiles()
				.setMultiSelectionEnabled(true)
				.setDialogTitle(kind == Kind.MISSION ? "Add mission sounds" : "Add banner sounds")
				.addExtensionFilter("WAV audio", "wav")
				.showDialog((java.awt.Component) null);
			if (chosen == null || chosen.isEmpty())
			{
				return;
			}
			Filepath dir = dir(kind);
			if (dir == null)
			{
				return;
			}
			List<String> imported = new ArrayList<>();
			for (Filepath src : chosen)
			{
				String name = src.getFileName();
				try
				{
					src.copyTo(dir.joinSegment(name), StandardCopyOption.REPLACE_EXISTING);
					imported.add(name);
				}
				catch (Exception e)
				{
					log.warn("Could not import sound {}: {}", name, e.getMessage());
				}
			}
			if (onImported != null && !imported.isEmpty())
			{
				onImported.accept(imported);
			}
		});
	}

	/** Copies the user sounds folder's path — see Clipboards for why it can't be opened directly. */
	public void copyFolderPath()
	{
		Filepath dir = root;
		if (dir == null)
		{
			return;
		}
		// The PARENT, not one kind's folder: both `banner/` and `mission/` are inside it, so one
		// paste lands somewhere the player can see the whole arrangement and drag files between them.
		try
		{
			if (!dir.exists())
			{
				dir.createDirectories();
			}
		}
		catch (IOException e)
		{
			log.debug("Could not create the sounds folder: {}", e.getMessage());
			return;
		}
		// LinkBrowser::open is restricted for hub releases, so the path goes on the clipboard and the
		// player pastes it wherever they were going to open it.
		Clipboards.copy(dir.toString());
	}

	public void shutdown()
	{
		audioExecutor.shutdownNow();
	}
}

package com.anvil;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;

/**
 * The plugin's "Sign in with Discord" — the home-native device-code flow (site: /api/plugin/auth/*).
 * Start → open the home's /link-device page in the member's browser → poll until approved → hand the
 * account token to the caller to store. Asynchronous: every step runs on the scheduler (approval polls
 * paced by delayed rescheduling, never a sleeping thread) and BOTH callbacks arrive on that executor
 * thread — marshal to the EDT before touching Swing. {@code done} fires exactly once.
 *
 * <p><b>Security:</b> no local listener — completion is detected purely by polling the home. The
 * browser URL is pinned to the CONFIGURED home origin (the one host the member explicitly typed
 * into the plugin config) + the fixed {@code /link-device} path: same anti-phishing shape as the
 * federation broker pin, anchored to user intent instead of a hardcoded host, which is what lets
 * this work for hosted, self-hosted, and fully-standalone sites alike.</p>
 */
@Slf4j
public final class DeviceSignIn
{
	/** Fixed path of the approval page on the home site — the only page this flow will ever open. */
	static final String LINK_PATH = "/link-device";

	/** Fallback pacing/deadline when the server response omits them. */
	private static final int DEFAULT_INTERVAL_S = 5;
	private static final int DEFAULT_EXPIRES_S = 600;

	public enum Outcome
	{
		SIGNED_IN, DENIED, EXPIRED, UNAVAILABLE
	}

	/** Result: outcome + the account token when {@link Outcome#SIGNED_IN}. */
	public static final class Result
	{
		public final Outcome outcome;
		public final String token;

		Result(Outcome outcome, String token)
		{
			this.outcome = outcome;
			this.token = token;
		}
	}

	private final BingoApiClient apiClient;
	private final BrowserOpener browserOpener;
	private final PollScheduler scheduler;

	/** Production binding — real system browser + delayed steps on the shared client executor. */
	public DeviceSignIn(BingoApiClient apiClient, ScheduledExecutorService executor)
	{
		this(apiClient, DeviceSignIn::browse,
			(step, delayMs) -> executor.schedule(step, delayMs, TimeUnit.MILLISECONDS));
	}

	/** Test seam — injectable browser opener + scheduler so the flow runs offline and fast. */
	DeviceSignIn(BingoApiClient apiClient, BrowserOpener browserOpener,
		PollScheduler scheduler)
	{
		this.apiClient = apiClient;
		this.browserOpener = browserOpener;
		this.scheduler = scheduler;
	}

	/**
	 * Ask the desktop to open the sign-in page.
	 *
	 * <p>Returns whether we ASKED without throwing, which is all RuneLite lets us know:
	 * LinkBrowser.browse is void, so a browser that never appeared and one that opened fine are the
	 * same call from here. Everything downstream is written so that distinction doesn't matter — the
	 * address and the code go on screen either way.
	 */
	private static boolean browse(String url)
	{
		LinkBrowser.browse(url);
		return true;
	}

	/** Run the whole flow. {@code status} receives short human-readable progress lines for the UI;
	 * {@code done} the terminal {@link Result}. Both called on the executor thread. */
	public void run(Consumer<String> status, Consumer<Result> done)
	{
		// The first step runs on the executor too — authStart is network I/O, keep it off the EDT.
		schedule(() -> start(status, done), 0, status, done);
	}

	private void start(Consumer<String> status, Consumer<Result> done)
	{
		BingoApiClient.DeviceAuthStart start = apiClient.authStart();
		if (start == null || start.device_code == null || start.device_code.isEmpty())
		{
			status.accept("Couldn't reach the site — check the Site URL.");
			done.accept(new Result(Outcome.UNAVAILABLE, null));
			return;
		}

		String url = start.verification_url_complete != null && !start.verification_url_complete.isEmpty()
			? start.verification_url_complete : start.verification_url;
		if (!isConfiguredHomeUrl(apiClient.getApiUrl(), url))
		{
			// A response steering the browser anywhere but the member's own configured site is hostile.
			log.warn("refusing sign-in URL not on the configured home: {}", url);
			status.accept("Sign-in blocked — the site returned a suspicious login page.");
			done.accept(new Result(Outcome.UNAVAILABLE, null));
			return;
		}
		// The address is on screen whether or not the browser opened. We can't tell the difference
		// (see browse), and the failure mode of assuming success is a player staring at a code with
		// nowhere to type it — while the cost of saying both is one extra clause.
		if (!browserOpener.open(url))
		{
			status.accept("Couldn't open your browser — visit " + url + " and enter " + start.user_code + ".");
		}
		else
		{
			status.accept("Approve code " + start.user_code + " in your browser. If it didn't open: " + url);
		}

		long intervalMs = Math.max(1, start.interval > 0 ? start.interval : DEFAULT_INTERVAL_S) * 1000L;
		long deadline = System.currentTimeMillis()
			+ (start.expires_in > 0 ? start.expires_in : DEFAULT_EXPIRES_S) * 1000L;
		poll(status, done, start.device_code, intervalMs, deadline);
	}

	/** One scheduled approval poll; reschedules itself (server {@code slow_down} stretches the delay)
	 * until a terminal status or the deadline. */
	private void poll(Consumer<String> status, Consumer<Result> done, String deviceCode, long intervalMs, long deadline)
	{
		if (System.currentTimeMillis() >= deadline)
		{
			status.accept("The code expired — try again.");
			done.accept(new Result(Outcome.EXPIRED, null));
			return;
		}
		schedule(() ->
		{
			long nextIntervalMs = intervalMs;
			BingoApiClient.DeviceAuthPoll poll = apiClient.authPoll(deviceCode);
			if (poll != null && poll.status != null)
			{
				switch (poll.status)
				{
					case "complete":
						if (poll.token != null && !poll.token.isEmpty())
						{
							status.accept("Signed in.");
							done.accept(new Result(Outcome.SIGNED_IN, poll.token));
						}
						else
						{
							done.accept(new Result(Outcome.UNAVAILABLE, null));
						}
						return;
					case "denied":
						status.accept("Sign-in denied on the site.");
						done.accept(new Result(Outcome.DENIED, null));
						return;
					case "expired":
						status.accept("The code expired — try again.");
						done.accept(new Result(Outcome.EXPIRED, null));
						return;
					case "slow_down":
						nextIntervalMs = Math.max(intervalMs, Math.max(1, poll.interval) * 1000L);
						break;
					default: // pending (a null/blank poll is a transient blip — keep polling until the deadline)
						break;
				}
			}
			poll(status, done, deviceCode, nextIntervalMs, deadline);
		}, intervalMs, status, done);
	}

	/** Schedule a flow step; an escaped {@link RuntimeException} would otherwise vanish inside the
	 * executor, so surface it as the terminal failure. */
	private void schedule(Runnable step, long delayMs, Consumer<String> status, Consumer<Result> done)
	{
		scheduler.schedule(() ->
		{
			try
			{
				step.run();
			}
			catch (RuntimeException e)
			{
				log.debug("sign-in flow failed", e);
				status.accept("Sign-in failed — try again.");
				done.accept(new Result(Outcome.UNAVAILABLE, null));
			}
		}, delayMs);
	}

	/**
	 * True only for an HTTPS/HTTP URL on the EXACT configured home origin (scheme + host + port all
	 * matching the member-typed Site URL) with the fixed {@link #LINK_PATH} path. No credentials.
	 * HTTP is tolerated only when the configured home itself is HTTP (self-host dev setups).
	 */
	static boolean isConfiguredHomeUrl(String configuredApiUrl, String url)
	{
		if (configuredApiUrl == null || configuredApiUrl.isEmpty() || url == null || url.isEmpty())
		{
			return false;
		}
		final URI home;
		final URI target;
		try
		{
			home = new URI(configuredApiUrl);
			target = new URI(url);
		}
		catch (URISyntaxException e)
		{
			return false;
		}
		if (target.getScheme() == null || target.getHost() == null || target.getUserInfo() != null)
		{
			return false;
		}
		if (!target.getScheme().equalsIgnoreCase(home.getScheme()))
		{
			return false;
		}
		if (!target.getHost().equalsIgnoreCase(home.getHost()) || target.getPort() != home.getPort())
		{
			return false;
		}
		String path = target.getPath();
		return path != null && path.startsWith(LINK_PATH);
	}
}
